using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Stripe;
using Stripe.Events;

[ApiController]
[Route("api/[controller]")]
public class StripeWebhookController : ControllerBase
{
    private readonly string _stripeWebhookSecret;
    private readonly IPaymentService _paymentService;

    public StripeWebhookController(IConfiguration configuration, IPaymentService paymentService)
    {
        _stripeWebhookSecret = configuration["Stripe:WebhookSecret"];
        _paymentService = paymentService;
    }

    [HttpPost("payment-webhook")]
    public async Task<IActionResult> HandlePaymentWebhook()
    {
        // Read the request body as a string
        string json;
        using (var reader = new StreamReader(Request.Body, Encoding.UTF8))
        {
            json = await reader.ReadToEndAsync();
        }

        try
        {
            // Verify the webhook signature using Stripe's security header
            var stripeSignatureHeader = Request.Headers["Stripe-Signature"].ToString();

            if (string.IsNullOrEmpty(stripeSignatureHeader) || string.IsNullOrEmpty(_stripeWebhookSecret))
            {
                return Unauthorized("Invalid webhook signature header or missing secret");
            }

            // Use Stripe's utility to construct and verify the event
            var stripeEvent = EventUtility.ConstructEvent(json, stripeSignatureHeader, _stripeWebhookSecret);

            // Handle the payment_intent.succeeded event
            if (stripeEvent.Type == Events.PaymentIntentSucceeded)
            {
                var paymentIntent = stripeEvent.Data.Object as PaymentIntent;

                if (paymentIntent == null)
                {
                    return BadRequest("Invalid payment intent data");
                }

                // Extract customer information
                var customerId = paymentIntent.CustomerId;
                var amount = paymentIntent.Amount;
                var currency = paymentIntent.Currency;
                var paymentIntentId = paymentIntent.Id;

                // Check for idempotency - ensure we don't double-credit on redelivery
                var isProcessed = await _paymentService.IsWebhookEventProcessedAsync(stripeEvent.Id);

                if (isProcessed)
                {
                    // Already handled this webhook event, return success to prevent retries
                    return Ok(new { message = "Webhook already processed" });
                }

                // Credit the customer's account
                var creditSuccess = await _paymentService.CreditCustomerAccountAsync(
                    customerId,
                    amount,
                    currency,
                    paymentIntentId
                );

                if (!creditSuccess)
                {
                    return StatusCode(500, "Failed to credit customer account");
                }

                // Mark this webhook event as processed to handle redelivery correctly
                await _paymentService.MarkWebhookEventProcessedAsync(stripeEvent.Id);

                return Ok(new { message = "Payment processed successfully" });
            }

            // For other event types, acknowledge receipt
            return Ok(new { message = "Webhook received" });
        }
        catch (StripeException stripeEx)
        {
            // Invalid signature - reject the webhook
            return Unauthorized($"Webhook verification failed: {stripeEx.Message}");
        }
        catch (Exception ex)
        {
            // Log the exception and return error
            // In production, log this securely
            return StatusCode(500, $"Internal server error processing webhook: {ex.Message}");
        }
    }
}

/// <summary>
/// Interface for payment operations
/// </summary>
public interface IPaymentService
{
    Task<bool> CreditCustomerAccountAsync(string customerId, long amount, string currency, string paymentIntentId);
    Task<bool> IsWebhookEventProcessedAsync(string eventId);
    Task MarkWebhookEventProcessedAsync(string eventId);
}

/// <summary>
/// Example implementation of IPaymentService
/// </summary>
public class PaymentService : IPaymentService
{
    private readonly IDatabase _database;

    public PaymentService(IDatabase database)
    {
        _database = database;
    }

    public async Task<bool> CreditCustomerAccountAsync(string customerId, long amount, string currency, string paymentIntentId)
    {
        try
        {
            // Convert amount from cents to appropriate units
            decimal creditAmount = amount / 100m;

            // Begin transaction for atomicity
            using (var transaction = await _database.BeginTransactionAsync())
            {
                // Credit the customer's account in your database
                var customer = await _database.GetCustomerAsync(customerId);
                if (customer == null)
                {
                    await transaction.RollbackAsync();
                    return false;
                }

                customer.AccountBalance += creditAmount;
                await _database.UpdateCustomerAsync(customer);

                // Log the transaction
                await _database.LogPaymentTransactionAsync(new PaymentLog
                {
                    CustomerId = customerId,
                    Amount = creditAmount,
                    Currency = currency,
                    StripePaymentIntentId = paymentIntentId,
                    ProcessedAt = DateTime.UtcNow
                });

                await transaction.CommitAsync();
                return true;
            }
        }
        catch (Exception ex)
        {
            // Log error
            return false;
        }
    }

    public async Task<bool> IsWebhookEventProcessedAsync(string eventId)
    {
        var record = await _database.GetWebhookEventRecordAsync(eventId);
        return record != null;
    }

    public async Task MarkWebhookEventProcessedAsync(string eventId)
    {
        await _database.LogWebhookEventAsync(new WebhookEventRecord
        {
            StripeEventId = eventId,
            ProcessedAt = DateTime.UtcNow
        });
    }
}

using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Stripe;
using Stripe.Events;

[ApiController]
[Route("api/webhooks")]
public class StripeWebhookController : ControllerBase
{
    private readonly string _webhookSecret;
    private readonly IAccountService _accountService;

    public StripeWebhookController(IAccountService accountService, IConfiguration config)
    {
        _accountService = accountService;
        _webhookSecret = config["Stripe:WebhookSecret"];
    }

    [HttpPost("stripe")]
    public async Task<IActionResult> HandleStripeWebhook()
    {
        var json = await new StreamReader(HttpContext.Request.Body).ReadToEndAsync();

        try
        {
            var stripeEvent = EventUtility.ConstructEvent(
                json,
                Request.Headers["Stripe-Signature"],
                _webhookSecret,
                throwOnApiVersionMismatch: false
            );

            if (stripeEvent.Type == Events.ChargeSucceeded || stripeEvent.Type == "charge.succeeded")
            {
                var charge = stripeEvent.Data.Object as Charge;
                if (charge != null)
                {
                    await HandleChargeSucceeded(charge);
                }
            }

            return Ok();
        }
        catch (StripeException ex)
        {
            return BadRequest($"Stripe verification failed: {ex.Message}");
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Webhook processing error: {ex.Message}");
        }
    }

    private async Task HandleChargeSucceeded(Charge charge)
    {
        if (string.IsNullOrEmpty(charge.CustomerId))
        {
            return;
        }

        var customerId = charge.CustomerId;
        var amount = charge.Amount / 100m;
        var currency = charge.Currency;

        var idempotencyKey = $"{charge.Id}-{charge.Created:yyyyMMddHHmmss}";

        await _accountService.CreditAccountAsync(customerId, amount, currency, idempotencyKey);
    }
}

public interface IAccountService
{
    Task CreditAccountAsync(string customerId, decimal amount, string currency, string idempotencyKey);
}

public class AccountService : IAccountService
{
    private readonly ILogger<AccountService> _logger;
    private readonly IAccountRepository _repository;

    public AccountService(IAccountRepository repository, ILogger<AccountService> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    public async Task CreditAccountAsync(string customerId, decimal amount, string currency, string idempotencyKey)
    {
        var account = await _repository.GetAccountByStripeCustomerIdAsync(customerId);
        if (account == null)
        {
            _logger.LogWarning($"Account not found for Stripe customer: {customerId}");
            return;
        }

        var existingCredit = await _repository.GetCreditByIdempotencyKeyAsync(idempotencyKey);
        if (existingCredit != null)
        {
            _logger.LogInformation($"Credit already processed with key: {idempotencyKey}");
            return;
        }

        account.Balance += amount;
        var credit = new AccountCredit
        {
            AccountId = account.Id,
            Amount = amount,
            Currency = currency,
            Reason = "Stripe payment succeeded",
            IdempotencyKey = idempotencyKey,
            CreatedAt = DateTime.UtcNow
        };

        await _repository.AddCreditAsync(credit);
        await _repository.UpdateAccountAsync(account);

        _logger.LogInformation($"Credited account {account.Id} with {amount} {currency}");
    }
}

using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Stripe;
using Stripe.BillingPortal;

namespace WebhookHandlers.Controllers
{
    [ApiController]
    [Route("api/webhooks")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly string _stripeWebhookSecret;
        private readonly IAccountService _accountService;

        public StripeWebhookController(IConfiguration config, IAccountService accountService)
        {
            _stripeWebhookSecret = config["Stripe:WebhookSecret"];
            _accountService = accountService;
        }

        [HttpPost("stripe")]
        public async Task<IActionResult> HandleStripeWebhook()
        {
            // Read the raw body for signature verification
            string json;
            using (var reader = new StreamReader(HttpContext.Request.Body))
            {
                json = await reader.ReadToEndAsync();
            }

            try
            {
                // Verify the webhook signature
                var stripeEvent = EventUtility.ConstructEvent(
                    json,
                    Request.Headers["Stripe-Signature"],
                    _stripeWebhookSecret
                );

                // Handle only payment_intent.succeeded events
                if (stripeEvent.Type == "payment_intent.succeeded")
                {
                    var paymentIntent = stripeEvent.Data.Object as PaymentIntent;

                    if (paymentIntent == null)
                    {
                        return BadRequest("Invalid payment intent object");
                    }

                    // Idempotency: check if we've already processed this event
                    var alreadyProcessed = await _accountService.IsEventProcessedAsync(stripeEvent.Id);
                    if (alreadyProcessed)
                    {
                        // Return 200 OK for idempotency - already handled this event
                        return Ok();
                    }

                    // Extract customer and amount information
                    var customerId = paymentIntent.CustomerId;
                    var amountCents = paymentIntent.Amount ?? 0;
                    var amountDollars = amountCents / 100m;

                    // Credit the customer's account
                    var creditResult = await _accountService.CreditCustomerAccountAsync(
                        customerId,
                        amountDollars,
                        stripeEvent.Id
                    );

                    if (!creditResult.Success)
                    {
                        // Log the failure but still return 200 to prevent redelivery storms
                        // The webhook will be retried if we return an error
                        Console.WriteLine($"Failed to credit account for customer {customerId}: {creditResult.Message}");
                    }

                    // Mark this event as processed for idempotency
                    await _accountService.MarkEventAsProcessedAsync(stripeEvent.Id);
                }

                // Return 200 OK to acknowledge receipt
                return Ok();
            }
            catch (StripeAPIException ex)
            {
                // Signature verification failed or other Stripe API error
                Console.WriteLine($"Stripe API Exception: {ex.Message}");
                return Unauthorized("Invalid signature");
            }
            catch (Exception ex)
            {
                // Log unexpected errors
                Console.WriteLine($"Webhook processing error: {ex.Message}");

                // Return 500 to trigger Stripe's automatic retry logic
                return StatusCode(500, "Webhook processing failed");
            }
        }
    }

    // Helper service interface for account operations
    public interface IAccountService
    {
        Task<bool> IsEventProcessedAsync(string eventId);
        Task MarkEventAsProcessedAsync(string eventId);
        Task<CreditResult> CreditCustomerAccountAsync(string customerId, decimal amount, string eventId);
    }

    public class CreditResult
    {
        public bool Success { get; set; }
        public string Message { get; set; }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public class OrderExportService
{
    private readonly DbContext _dbContext;
    private readonly ILogger<OrderExportService> _logger;

    public OrderExportService(DbContext dbContext, ILogger<OrderExportService> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    /// <summary>
    /// Exports orders with customer names in pages to avoid memory exhaustion and N+1 queries.
    /// greybeard: Reads a list — paginated, bounded per request. Explicit Include prevents N+1 on customer joins.
    /// greybeard: Snapshot isolation ensures consistent view across pages even if rows change mid-export.
    /// greybeard: Observable — logs page count, row count, and any truncation.
    /// </summary>
    public async Task<List<OrderExportDto>> ExportOrdersAsync(
        int pageNumber = 1,
        int pageSize = 1000,
        CancellationToken cancellationToken = default)
    {
        // greybeard: Bounds the result set to prevent unbounded memory use and fan-out.
        if (pageSize <= 0 || pageSize > 10000)
            pageSize = 1000;

        if (pageNumber <= 0)
            pageNumber = 1;

        var skipCount = (pageNumber - 1) * pageSize;

        try
        {
            // greybeard: Snapshot isolation — READ COMMITTED SNAPSHOT (or equivalent) ensures
            // consistent view across pagination without holding long locks.
            using (var transaction = await _dbContext.Database.BeginTransactionAsync(
                System.Data.IsolationLevel.ReadCommitted,
                cancellationToken))
            {
                var orders = await _dbContext.Set<Order>()
                    // greybeard: Eager-load customer to avoid N+1. One query, not 1 + N.
                    .Include(o => o.Customer)
                    .OrderBy(o => o.OrderId)
                    .Skip(skipCount)
                    .Take(pageSize + 1) // Fetch one extra to detect if more rows exist.
                    .AsNoTracking() // greybeard: Export doesn't mutate; no tracking overhead.
                    .ToListAsync(cancellationToken);

                await transaction.CommitAsync(cancellationToken);

                // greybeard: Observable — log batch details.
                _logger.LogInformation(
                    "Exported orders page {PageNumber}, size {PageSize}, returned {RowCount} rows",
                    pageNumber,
                    pageSize,
                    orders.Count);

                // Map to DTO, excluding any sensitive fields.
                var result = orders
                    .Take(pageSize) // Exclude the sentinel row used for "has more" detection.
                    .Select(o => new OrderExportDto
                    {
                        OrderId = o.OrderId,
                        CustomerName = o.Customer?.Name ?? "[Unknown]",
                        OrderDate = o.OrderDate,
                        // greybeard: Money — use integer cents/minor units from DB, never float.
                        TotalAmountMinorUnits = o.TotalAmountMinorUnits,
                        CurrencyCode = o.CurrencyCode ?? "USD"
                    })
                    .ToList();

                return result;
            }
        }
        catch (OperationCanceledException)
        {
            // greybeard: Can fail half-way — export cancellation is graceful, no partial writes.
            _logger.LogWarning("Export cancelled at page {PageNumber}", pageNumber);
            throw;
        }
        catch (Exception ex)
        {
            // greybeard: Observable — log failures without exposing connection strings or PII.
            _logger.LogError(ex, "Export failed at page {PageNumber}: {Message}", pageNumber, ex.Message);
            throw;
        }
    }
}

public class OrderExportDto
{
    public int OrderId { get; set; }
    public string CustomerName { get; set; }
    public DateTime OrderDate { get; set; }
    // greybeard: Money as integer minor units (cents); never float.
    public long TotalAmountMinorUnits { get; set; }
    public string CurrencyCode { get; set; }
