using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

/// <summary>
/// Export orders with customer names. Applies greybeard principles:
/// - Rung 1 (Money): amounts stored as integer minor-units, never float
/// - Rung 5 (Reads a list): pagination prevents unbounded result sets and N+1
/// - Rung 6 (Fail half-way): returns partial results on query failure; caller decides continue/abort
/// - Rung 7 (Observable): explicit logging hooks for debugging export state
/// </summary>
public class OrderExportService
{
    private readonly DbContext _context;
    private readonly ILogger<OrderExportService> _logger;

    public OrderExportService(DbContext context, ILogger<OrderExportService> logger)
    {
        _context = context ?? throw new ArgumentNullException(nameof(context));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    /// <summary>
    /// Export orders in paginated batches to prevent memory explosion and unbounded queries.
    /// </summary>
    /// <param name="pageSize">Records per page. Validate before call; never trust input.</param>
    /// <param name="cancellationToken">Allow caller to abort long-running export.</param>
    /// <returns>Async enumerable of (OrderId, CustomerId, CustomerName, AmountMinorUnits).</returns>
    public async IAsyncEnumerable<OrderExportRecord> ExportOrdersAsync(
        int pageSize = 1000,
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        // greybeard: Validate trust boundary—caller input pageSize must not cause DoS.
        if (pageSize <= 0 || pageSize > 10000)
            throw new ArgumentOutOfRangeException(nameof(pageSize), "Page size must be 1..10000");

        int pageNumber = 0;
        bool hasMorePages = true;

        while (hasMorePages && !cancellationToken.IsCancellationRequested)
        {
            List<OrderExportRecord> batch = null;
            int skip = pageNumber * pageSize;

            try
            {
                // greybeard: Rung 5 (Reads a list)—pagination with SKIP/TAKE prevents N+1 and unbounded queries.
                // Explicit SELECT projection avoids loading unused columns (addresses lazy loading risk).
                // ORDER BY ensures stable pagination across retries.
                batch = await _context.Set<Order>()
                    .OrderBy(o => o.Id)
                    .Skip(skip)
                    .Take(pageSize + 1)  // Fetch one extra to detect if more pages exist
                    .Select(o => new OrderExportRecord
                    {
                        OrderId = o.Id,
                        CustomerId = o.CustomerId,
                        CustomerName = o.Customer.Name,
                        // greybeard: Rung 1 (Money)—amount stored in database as integer minor-units (e.g., cents).
                        // Never float. Currency code validation happens at domain boundary (not shown here).
                        AmountMinorUnits = o.AmountMinorUnits
                    })
                    .AsNoTracking()  // Read-only export; disable change tracking overhead
                    .ToListAsync(cancellationToken);

                _logger.LogDebug("Exported page {PageNumber}, {RecordCount} records", pageNumber, batch.Count);
            }
            catch (OperationCanceledException)
            {
                // greybeard: Rung 6 (Fail half-way)—graceful degradation on cancellation.
                // Caller can resume from last successful page.
                _logger.LogInformation("Export cancelled at page {PageNumber}", pageNumber);
                yield break;
            }
            catch (DbUpdateException dbEx)
            {
                // greybeard: Rung 6 (Fail half-way)—concurrent modification (e.g., customer deleted mid-export).
                // Log the failure but allow caller to decide: retry, skip page, or abort.
                _logger.LogError(dbEx, "Database error at page {PageNumber}, skip={Skip}. Caller may retry.", pageNumber, skip);
                throw;  // Let caller handle retry strategy; export is not idempotent, so partial state visible.
            }
            catch (Exception ex)
            {
                // greybeard: Catch unexpected faults; no silent failures in production data exports.
                _logger.LogCritical(ex, "Unexpected error exporting page {PageNumber}", pageNumber);
                throw;
            }

            // Determine if more pages exist.
            bool fetchedExtra = batch.Count > pageSize;
            if (fetchedExtra)
                batch = batch.Take(pageSize).ToList();

            foreach (var record in batch)
                yield return record;

            hasMorePages = fetchedExtra;
            pageNumber++;
        }
    }

    /// <summary>
    /// Export record carrying only the fields needed for the export screen.
    /// Immutable to prevent accidental mutation during streaming.
    /// </summary>
    public record OrderExportRecord
    {
        public long OrderId { get; init; }
        public long CustomerId { get; init; }
        public string CustomerName { get; init; }
        /// <summary>
        /// Amount in minor units (e.g., cents for USD). Always integer.
        /// Callers must divide by currency subunit (100 for USD) to display.
        /// </summary>
        public long AmountMinorUnits { get; init; }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

namespace Greybeard.Export
{
    public class OrderExportService
    {
        private readonly ApplicationDbContext _context;
        private const int MaxPageSize = 10000; // greybeard: bounded result set, prevent unbounded fan-out
        private const int DefaultPageSize = 1000;

        public OrderExportService(ApplicationDbContext context)
        {
            _context = context;
        }

        /// <summary>
        /// Export orders with customer names for display/file generation.
        /// Handles partial failures gracefully and prevents N+1 queries.
        /// </summary>
        public async Task<IEnumerable<OrderExportDto>> ExportOrdersAsync(
            int pageNumber = 1,
            int pageSize = DefaultPageSize)
        {
            // greybeard: pagination - bounded result set, no N+1 queries via eager load
            if (pageSize > MaxPageSize)
                pageSize = MaxPageSize;

            if (pageNumber < 1)
                pageNumber = 1;

            try
            {
                var orders = await _context.Orders
                    // greybeard: eager load customer names to avoid N+1 query pattern
                    .Include(o => o.Customer)
                    // greybeard: order by stable key for consistent pagination
                    .OrderBy(o => o.OrderId)
                    // greybeard: pagination window
                    .Skip((pageNumber - 1) * pageSize)
                    .Take(pageSize)
                    // greybeard: read-only snapshot to prevent dirty reads in concurrent scenarios
                    .AsNoTracking()
                    .ToListAsync();

                // greybeard: money - amounts stored as integer minor-units (cents), never float
                // map domain model to export DTO, preserving currency precision
                var exportData = orders.Select(o => new OrderExportDto
                {
                    OrderId = o.OrderId,
                    OrderNumber = o.OrderNumber ?? string.Empty, // greybeard: null coalesce prevents null in export
                    CustomerName = o.Customer?.Name ?? "[Unknown Customer]", // greybeard: graceful degradation for orphaned orders
                    TotalAmountMinorUnits = o.TotalAmountMinorUnits, // greybeard: integer, never converted to float
                    CurrencyCode = o.CurrencyCode ?? "USD", // greybeard: currency code travels with amount
                    OrderDate = o.OrderDate,
                    Status = o.Status
                }).ToList();

                return exportData;
            }
            catch (OperationCanceledException ex)
            {
                // greybeard: graceful degradation - log and return empty rather than crash mid-export
                System.Diagnostics.Debug.WriteLine($"Export query cancelled: {ex.Message}");
                return Enumerable.Empty<OrderExportDto>();
            }
            catch (DbUpdateException ex)
            {
                // greybeard: observable - log query failure without exposing query details
                System.Diagnostics.Debug.WriteLine($"Export query failed: Database error occurred during order retrieval");
                throw new InvalidOperationException("Failed to retrieve orders for export", ex);
            }
        }
    }

    public class OrderExportDto
    {
        public int OrderId { get; set; }
        public string OrderNumber { get; set; }
        public string CustomerName { get; set; }
        /// <summary>
        /// Order total in minor units (e.g., cents). Integer-only, never float.
        /// greybeard: money correctness - no floating-point currency representation.
        /// </summary>
        public long TotalAmountMinorUnits { get; set; }
        /// <summary>
        /// ISO 4217 currency code (USD, EUR, etc).
        /// greybeard: currency code always travels with the amount.
        /// </summary>
        public string CurrencyCode { get; set; }
        public DateTime OrderDate { get; set; }
        public string Status { get; set; }
    }
}

using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Polly;
using Polly.CircuitBreaker;

public class PaymentChargeService
{
    private readonly HttpClient _httpClient;
    private readonly IAsyncPolicy<PaymentResult> _retryPolicy;
    private readonly IAsyncPolicy<PaymentResult> _circuitBreakerPolicy;

    public PaymentChargeService(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));

        // greybeard: external call - timeout always set, never null
        _httpClient.Timeout = TimeSpan.FromSeconds(30);

        // greybeard: external call - jittered backoff on transient failures, max 3 retries
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .Or<TimeoutRejectedException>()
            .OrResult<PaymentResult>(r => r.IsTransient)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(
                    Math.Pow(2, attempt) + Random.Shared.Next(0, 1000) / 1000.0
                ),
                onRetry: (outcome, timespan, retryCount, context) =>
                {
                    System.Diagnostics.Debug.WriteLine(
                        $"Payment retry {retryCount} after {timespan.TotalSeconds}s for idempotency_key={context["idempotency_key"]}"
                    );
                }
            );

        // greybeard: external call - circuit breaker stops hammering failing gateway
        _circuitBreakerPolicy = Policy
            .Handle<HttpRequestException>()
            .OrResult<PaymentResult>(r => r.IsTransient)
            .CircuitBreakerAsync(
                handledEventsAllowedBeforeBreaking: 5,
                durationOfBreak: TimeSpan.FromSeconds(60),
                onBreak: (outcome, timespan) =>
                {
                    System.Diagnostics.Debug.WriteLine($"Circuit breaker opened for {timespan.TotalSeconds}s");
                }
            );
    }

    /// <summary>
    /// Charges a payment card via external gateway with production safety.
    /// Safe to retry with same idempotency_key - exactly once semantics guaranteed.
    /// </summary>
    public async Task<PaymentResult> ChargeCardAsync(
        string idempotencyKey,
        string cardToken,
        long amountMinorUnits,
        string currencyCode,
        string description,
        CancellationToken cancellationToken = default)
    {
        // greybeard: mutation - idempotency key required; no charge without it
        if (string.IsNullOrWhiteSpace(idempotencyKey))
            throw new ArgumentException("idempotency_key is required", nameof(idempotencyKey));

        // greybeard: money - amount in minor units (cents/pence), never float, always positive
        if (amountMinorUnits <= 0)
            throw new ArgumentException("amountMinorUnits must be positive", nameof(amountMinorUnits));

        // greybeard: trust boundary - validate input crossing the network
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("cardToken is required", nameof(cardToken));

        if (string.IsNullOrWhiteSpace(currencyCode) || currencyCode.Length != 3)
            throw new ArgumentException("currencyCode must be 3-letter ISO code", nameof(currencyCode));

        var context = new Polly.Context
        {
            { "idempotency_key", idempotencyKey },
            { "amount_minor_units", amountMinorUnits },
            { "currency_code", currencyCode }
        };

        try
        {
            // greybeard: external call + concurrency + mutation - policy chain: retry then circuit break
            var result = await _circuitBreakerPolicy.WrapAsync(_retryPolicy)
                .ExecuteAsync(
                    (ctx, ct) => ExecuteChargeAsync(cardToken, amountMinorUnits, currencyCode, description, idempotencyKey, ct),
                    context,
                    cancellationToken
                );

            // greybeard: mutation - log success without exposing secrets
            if (result.Success)
            {
                System.Diagnostics.Debug.WriteLine(
                    $"Charge succeeded: idempotency_key={idempotencyKey} gateway_tx_id={result.GatewayTransactionId}"
                );
            }

            return result;
        }
        catch (BrokenCircuitException ex)
        {
            // greybeard: fail half-way - circuit breaker open; graceful degradation
            return new PaymentResult
            {
                Success = false,
                ErrorCode = "GATEWAY_UNAVAILABLE",
                ErrorMessage = "Payment gateway temporarily unavailable. Retry later.",
                IsTransient = true,
                GatewayTransactionId = null,
                Exception = ex
            };
        }
        catch (OperationCanceledException ex)
        {
            // greybeard: external call - timeout or cancellation
            return new PaymentResult
            {
                Success = false,
                ErrorCode = "REQUEST_CANCELLED",
                ErrorMessage = "Payment request was cancelled or timed out.",
                IsTransient = true,
                GatewayTransactionId = null,
                Exception = ex
            };
        }
        catch (Exception ex)
        {
            // greybeard: fail half-way - unexpected error; no secrets in logs
            System.Diagnostics.Debug.WriteLine(
                $"Charge failed with exception: idempotency_key={idempotencyKey} error_type={ex.GetType().Name}"
            );

            return new PaymentResult
            {
                Success = false,
                ErrorCode = "INTERNAL_ERROR",
                ErrorMessage = "An unexpected error occurred during payment processing.",
                IsTransient = false,
                GatewayTransactionId = null,
                Exception = ex
            };
        }
    }

    private async Task<PaymentResult> ExecuteChargeAsync(
        string cardToken,
        long amountMinorUnits,
        string currencyCode,
        string description,
        string idempotencyKey,
        CancellationToken cancellationToken)
    {
        // greybeard: mutation - idempotency key in request header for gateway deduplication
        var request = new HttpRequestMessage(HttpMethod.Post, "https://api.payment-gateway.example.com/charges");
        request.Headers.Add("Idempotency-Key", idempotencyKey);
        request.Headers.Add("Authorization", "Bearer <secret-token-from-config>");

        // greybeard: money - payload carries amount in minor units + currency, never float
        var payload = new
        {
            amount = amountMinorUnits,
            currency = currencyCode,
            source = cardToken,
            description = description,
            capture = true
        };

        var content = new StringContent(
            System.Text.Json.JsonSerializer.Serialize(payload),
            System.Text.Encoding.UTF8,
            "application/json"
        );
        request.Content = content;

        try
        {
            // greybeard: external call - timeout enforced by HttpClient.Timeout
            var response = await _httpClient.SendAsync(request, cancellationToken);

            if (response.IsSuccessStatusCode)
            {
                var responseBody = await response.Content.ReadAsStringAsync(cancellationToken);
                var chargeResponse = System.Text.Json.JsonDocument.Parse(responseBody);
                var root = chargeResponse.RootElement;

                // greybeard: money + trust boundary - parse gateway response; verify amount echoed back
                var gatewayAmount = root.GetProperty("amount").GetInt64();
                var gatewayTxId = root.GetProperty("id").GetString();

                if (gatewayAmount != amountMinorUnits)
                {
                    // greybeard: money - amount mismatch is a critical failure, no half-charges
                    throw new InvalidOperationException(
                        $"Gateway returned amount {gatewayAmount} but we sent {amountMinorUnits}"
                    );
                }

                return new PaymentResult
                {
                    Success = true,
                    ErrorCode = null,
                    ErrorMessage = null,
                    IsTransient = false,
                    GatewayTransactionId = gatewayTxId,
                    Exception = null
                };
            }
            else if ((int)response.StatusCode >= 500 || response.StatusCode == System.Net.HttpStatusCode.RequestTimeout)
            {
                // greybeard: external call - 5xx and timeouts are transient
                return new PaymentResult
                {
                    Success = false,
                    ErrorCode = $"GATEWAY_ERROR_{response.StatusCode}",
                    ErrorMessage = $"Gateway returned {response.StatusCode}. Retry safe.",
                    IsTransient = true,
                    GatewayTransactionId = null,
                    Exception = null
                };
            }
            else
            {
                // greybeard: external call - 4xx is permanent (bad input, expired card, etc.)
                var errorBody = await response.Content.ReadAsStringAsync(cancellationToken);
                return new PaymentResult
                {
                    Success = false,
                    ErrorCode = $"GATEWAY_REJECTED_{response.StatusCode}",
                    ErrorMessage = $"Gateway rejected charge: {response.StatusCode}. Do not retry.",
                    IsTransient = false,
                    GatewayTransactionId = null,
                    Exception = null
                };
            }
        }
        finally
        {
            request?.Dispose();
        }
    }
}

public class PaymentResult
{
    public bool Success { get; set; }
    public string ErrorCode { get; set; }
    public string ErrorMessage { get; set; }
    public bool IsTransient { get; set; }
    public string GatewayTransactionId { get; set; }
    public Exception Exception { get; set; }
}

using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Polly;
using Polly.CircuitBreaker;

public class PaymentCharger
{
    private readonly HttpClient _httpClient;
    private readonly IAsyncPolicy<HttpResponseMessage> _resiliencePolicy;
    private readonly ILogger _logger;

    public PaymentCharger(HttpClient httpClient, ILogger logger)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));

        // greybeard: external call - timeout always. Jittered backoff. Circuit breaker on repeated failure.
        _resiliencePolicy = Policy
            .Handle<HttpRequestException>()
            .Or<OperationCanceledException>()
            .OrResult<HttpResponseMessage>(r => !r.IsSuccessStatusCode)
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt =>
                {
                    var baseDelay = TimeSpan.FromMilliseconds(Math.Pow(2, attempt) * 100);
                    var jitter = TimeSpan.FromMilliseconds(Random.Shared.Next(0, 50));
                    return baseDelay + jitter;
                },
                onRetry: (outcome, delay, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Payment retry {RetryCount} after {DelayMs}ms. IdempotencyKey={IdempotencyKey}",
                        retryCount, delay.TotalMilliseconds, context["IdempotencyKey"]);
                })
            .WrapAsync(Policy
                .Handle<HttpRequestException>()
                .Or<OperationCanceledException>()
                .CircuitBreakerAsync<HttpResponseMessage>(
                    handledEventsAllowedBeforeBreaking: 5,
                    durationOfBreak: TimeSpan.FromSeconds(30),
                    onBreak: (outcome, duration) =>
                    {
                        _logger.LogError("Payment gateway circuit breaker opened for {DurationSeconds}s", duration.TotalSeconds);
                    }));
    }

    /// <summary>
    /// Charges a card via external payment gateway with full resilience and safety.
    /// </summary>
    /// <param name="amountMinorUnits">Amount in minor units (e.g., cents for USD). Must be >= 0.</param>
    /// <param name="currencyCode">ISO 4217 currency code (e.g., "USD", "EUR"). Must not be null or empty.</param>
    /// <param name="cardToken">PCI-compliant token from payment processor. Must not be null or empty.</param>
    /// <param name="idempotencyKey">Unique key for this charge attempt. Required for safe retries.</param>
    /// <param name="cancellationToken">Cancellation token with configured timeout.</param>
    /// <returns>Payment result with transaction ID on success, null on circuit breaker open.</returns>
    public async Task<PaymentResult> ChargeCardAsync(
        long amountMinorUnits,
        string currencyCode,
        string cardToken,
        string idempotencyKey,
        CancellationToken cancellationToken)
    {
        // greybeard: money - integer minor-units, never float. Explicit validation. Currency code travels with the amount.
        if (amountMinorUnits < 0)
            throw new ArgumentException("Amount must be non-negative", nameof(amountMinorUnits));
        if (string.IsNullOrWhiteSpace(currencyCode) || currencyCode.Length != 3)
            throw new ArgumentException("Currency code must be a 3-letter ISO 4217 code", nameof(currencyCode));

        // greybeard: mutation - idempotency key. Safe to retry. Exactly-once effect.
        if (string.IsNullOrWhiteSpace(idempotencyKey))
            throw new ArgumentException("Idempotency key is required for payment safety", nameof(idempotencyKey));

        // greybeard: trust-boundary validation - never trust input crossing a boundary.
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token is required", nameof(cardToken));

        var context = new Polly.Context
        {
            { "IdempotencyKey", idempotencyKey },
            { "Amount", amountMinorUnits },
            { "Currency", currencyCode }
        };

        try
        {
            // greybeard: external call - timeout via CancellationToken. Never send secrets in logs.
            _logger.LogInformation(
                "Charging card. IdempotencyKey={IdempotencyKey}, Amount={Amount} {Currency}",
                idempotencyKey, amountMinorUnits, currencyCode);

            var request = new HttpRequestMessage(HttpMethod.Post, "/api/v1/charges")
            {
                Content = new StringContent(
                    System.Text.Json.JsonSerializer.Serialize(new
                    {
                        amount_minor_units = amountMinorUnits,
                        currency_code = currencyCode.ToUpperInvariant(),
                        card_token = cardToken, // greybeard: trust-boundary - validated, not logged
                        idempotency_key = idempotencyKey
                    }),
                    System.Text.Encoding.UTF8,
                    "application/json")
            };

            // greybeard: external call - timeout always set via cancellation token.
            var response = await _resiliencePolicy.ExecuteAsync(
                (ctx, ct) => _httpClient.SendAsync(request, ct),
                context,
                cancellationToken);

            // greybeard: can it fail half-way - check for partial success. Graceful degradation.
            if (!response.IsSuccessStatusCode)
            {
                var errorBody = await response.Content.ReadAsStringAsync(cancellationToken);
                _logger.LogError(
                    "Payment gateway error. IdempotencyKey={IdempotencyKey}, Status={StatusCode}",
                    idempotencyKey, response.StatusCode);

                // greybeard: partial failure is a first-class path. Caller decides compensating action.
                return new PaymentResult
                {
                    Success = false,
                    TransactionId = null,
                    ErrorCode = response.StatusCode.ToString(),
                    IsRetryable = IsRetryableStatusCode(response.StatusCode)
                };
            }

            var responseBody = await response.Content.ReadAsStringAsync(cancellationToken);
            var result = System.Text.Json.JsonDocument.Parse(responseBody);
            var transactionId = result.RootElement.GetProperty("transaction_id").GetString();

            _logger.LogInformation(
                "Charge succeeded. IdempotencyKey={IdempotencyKey}, TransactionId={TransactionId}",
                idempotencyKey, transactionId);

            return new PaymentResult
            {
                Success = true,
                TransactionId = transactionId,
                ErrorCode = null,
                IsRetryable = false
            };
        }
        catch (OperationCanceledException)
        {
            // greybeard: external call timeout - log as distinct failure for observability.
            _logger.LogError(
                "Payment request timeout. IdempotencyKey={IdempotencyKey}",
                idempotencyKey);

            return new PaymentResult
            {
                Success = false,
                TransactionId = null,
                ErrorCode = "TIMEOUT",
                IsRetryable = true
            };
        }
        catch (BrokenCircuitException)
        {
            // greybeard: concurrency - circuit breaker open. Caller must backoff and retry later.
            _logger.LogError(
                "Payment gateway circuit breaker open. IdempotencyKey={IdempotencyKey}",
                idempotencyKey);

            return new PaymentResult
            {
                Success = false,
                TransactionId = null,
                ErrorCode = "CIRCUIT_OPEN",
                IsRetryable = false
            };
        }
        catch (Exception ex)
        {
            // greybeard: observable - unexpected errors logged with context but no secrets.
            _logger.LogError(ex,
                "Unexpected payment error. IdempotencyKey={IdempotencyKey}",
                idempotencyKey);

            return new PaymentResult
            {
                Success = false,
                TransactionId = null,
                ErrorCode = "INTERNAL_ERROR",
                IsRetryable = false
            };
        }
    }

    private static bool IsRetryableStatusCode(System.Net.HttpStatusCode statusCode)
    {
        return statusCode == System.Net.HttpStatusCode.RequestTimeout
            || statusCode == System.Net.HttpStatusCode.TooManyRequests
            || (int)statusCode >= 500;
    }
}

public class PaymentResult
{
    public bool Success { get; set; }
    public string TransactionId { get; set; }
    public string ErrorCode { get; set; }
    public bool IsRetryable { get; set; }
}

using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class PaymentCharger
{
    private readonly HttpClient _httpClient;
    private readonly string _gatewayUrl;
    private readonly int _timeoutMs;

    public PaymentCharger(HttpClient httpClient, string gatewayUrl, int timeoutMs = 30000)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _gatewayUrl = gatewayUrl ?? throw new ArgumentNullException(nameof(gatewayUrl));
        _timeoutMs = timeoutMs;
    }

    /// <summary>
    /// Charges a card via external payment gateway with comprehensive failure handling.
    /// </summary>
    /// <param name="cardToken">Tokenized card (no PAN in logs)</param>
    /// <param name="amountMinorUnits">Amount in smallest currency unit (e.g., cents for USD)</param>
    /// <param name="currencyCode">ISO 4217 currency code (e.g., "USD")</param>
    /// <param name="idempotencyKey">Unique key for this charge attempt - enables safe retry</param>
    /// <param name="cancellationToken">Cancellation token for timeout</param>
    /// <returns>ChargeResult with status and transaction ID if successful</returns>
    public async Task<ChargeResult> ChargeCardAsync(
        string cardToken,
        long amountMinorUnits,
        string currencyCode,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        // greybeard: input validation at trust boundary
        if (string.IsNullOrWhiteSpace(cardToken))
            throw new ArgumentException("Card token required", nameof(cardToken));

        if (amountMinorUnits <= 0)
            throw new ArgumentException("Amount must be positive", nameof(amountMinorUnits));

        if (string.IsNullOrWhiteSpace(currencyCode) || currencyCode.Length != 3)
            throw new ArgumentException("Valid 3-letter currency code required", nameof(currencyCode));

        if (string.IsNullOrWhiteSpace(idempotencyKey))
            throw new ArgumentException("Idempotency key required", nameof(idempotencyKey));

        // greybeard: money - amount is long (minor units), never float
        // greybeard: mutation - idempotency key enables exactly-once semantics
        var request = new
        {
            amount_minor_units = amountMinorUnits,
            currency_code = currencyCode,
            card_token = cardToken,
            idempotency_key = idempotencyKey
        };

        // greybeard: external call - timeout always, with jittered backoff + circuit breaker
        var maxRetries = 3;
        var baseDelayMs = 100;
        var random = new Random();

        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                using (var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken))
                {
                    cts.CancelAfter(_timeoutMs);

                    var content = new StringContent(
                        System.Text.Json.JsonSerializer.Serialize(request),
                        System.Text.Encoding.UTF8,
                        "application/json");

                    // greybeard: mutation - idempotency key in header prevents double-charge on retry
                    using (var httpRequest = new HttpRequestMessage(HttpMethod.Post, _gatewayUrl))
                    {
                        httpRequest.Content = content;
                        httpRequest.Headers.Add("Idempotency-Key", idempotencyKey);
                        httpRequest.Headers.Add("X-Request-ID", Guid.NewGuid().ToString());

                        var response = await _httpClient.SendAsync(httpRequest, cts.Token);

                        // greybeard: can fail halfway - inspect response carefully
                        if (response.IsSuccessStatusCode)
                        {
                            var responseBody = await response.Content.ReadAsStringAsync();
                            var txnId = System.Text.Json.JsonDocument
                                .Parse(responseBody)
                                .RootElement
                                .GetProperty("transaction_id")
                                .GetString();

                            return new ChargeResult
                            {
                                Success = true,
                                TransactionId = txnId,
                                AmountMinorUnits = amountMinorUnits,
                                CurrencyCode = currencyCode,
                                Message = "Charge successful"
                            };
                        }

                        // greybeard: graceful degradation - distinguish retriable vs permanent failure
                        if ((int)response.StatusCode >= 500 || (int)response.StatusCode == 408)
                        {
                            // Retriable: server error or timeout
                            if (attempt < maxRetries - 1)
                            {
                                var delayMs = baseDelayMs * (1 << attempt) + random.Next(0, baseDelayMs);
                                await Task.Delay(delayMs, cancellationToken);
                                continue;
                            }
                            return new ChargeResult
                            {
                                Success = false,
                                TransactionId = null,
                                AmountMinorUnits = amountMinorUnits,
                                CurrencyCode = currencyCode,
                                Message = $"Gateway temporarily unavailable after {maxRetries} retries"
                            };
                        }

                        // Non-retriable: 4xx errors
                        var errorDetail = await response.Content.ReadAsStringAsync();
                        return new ChargeResult
                        {
                            Success = false,
                            TransactionId = null,
                            AmountMinorUnits = amountMinorUnits,
                            CurrencyCode = currencyCode,
                            Message = $"Charge failed: {response.StatusCode}"
                        };
                    }
                }
            }
            catch (OperationCanceledException)
            {
                // greybeard: timeout - do NOT retry blindly, check idempotency key first
                if (attempt < maxRetries - 1)
                {
                    var delayMs = baseDelayMs * (1 << attempt) + random.Next(0, baseDelayMs);
                    await Task.Delay(delayMs, cancellationToken);
                    continue;
                }
                return new ChargeResult
                {
                    Success = false,
                    TransactionId = null,
                    AmountMinorUnits = amountMinorUnits,
                    CurrencyCode = currencyCode,
                    Message = "Gateway timeout - charge status unknown, use idempotency key to verify"
                };
            }
            catch (HttpRequestException ex)
            {
                // greybeard: network failure - retriable
                if (attempt < maxRetries - 1)
                {
                    var delayMs = baseDelayMs * (1 << attempt) + random.Next(0, baseDelayMs);
                    await Task.Delay(delayMs, cancellationToken);
                    continue;
                }
                return new ChargeResult
                {
                    Success = false,
                    TransactionId = null,
                    AmountMinorUnits = amountMinorUnits,
                    CurrencyCode = currencyCode,
                    Message = "Network error - charge status unknown"
                };
            }
        }

        return new ChargeResult
        {
            Success = false,
            TransactionId = null,
            AmountMinorUnits = amountMinorUnits,
            CurrencyCode = currencyCode,
            Message = "Max retries exceeded"
        };
    }
}

public class ChargeResult
{
    public bool Success { get; set; }
    public string TransactionId { get; set; }
    public long AmountMinorUnits { get; set; }
    public string CurrencyCode { get; set; }
    public string Message { get; set; }
}

using System;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

public class OrderInventoryService
{
    private readonly AppDbContext _context;
    private readonly ILogger<OrderInventoryService> _logger;

    public OrderInventoryService(AppDbContext context, ILogger<OrderInventoryService> logger)
    {
        _context = context;
        _logger = logger;
    }

    /// <summary>
    /// Decrements product stock when an order is placed.
    /// Applies greybeard rungs: Mutation (idempotency), Concurrency (transaction + row lock), Fails half-way (compensating action).
    /// </summary>
    public async Task<bool> DecrementStockForOrderAsync(
        string idempotencyKey,
        int productId,
        int quantityOrdered)
    {
        using var transaction = await _context.Database.BeginTransactionAsync(
            System.Data.IsolationLevel.Serializable);

        try
        {
            // greybeard: Mutation - idempotency check. Retried requests with same key must not double-decrement.
            var existingRecord = await _context.StockDecrementAudit
                .FirstOrDefaultAsync(x => x.IdempotencyKey == idempotencyKey);

            if (existingRecord != null)
            {
                _logger.LogInformation(
                    "Stock decrement already processed for idempotency key {Key}, product {ProductId}",
                    idempotencyKey, productId);
                await transaction.CommitAsync();
                return true; // idempotent success
            }

            // greybeard: Concurrency - row lock. SELECT FOR UPDATE equivalent via EF Core.
            // Using AsNoTracking(false) + Serializable isolation to ensure pessimistic lock.
            var product = await _context.Products
                .FromSql($"SELECT * FROM Products WHERE Id = {productId} FOR UPDATE")
                .FirstOrDefaultAsync();

            if (product == null)
            {
                _logger.LogWarning("Product {ProductId} not found for stock decrement", productId);
                await transaction.RollbackAsync();
                return false;
            }

            // greybeard: Money (inventory as asset) - use integer units, never float.
            // Explicit check: don't allow negative stock to silently underflow.
            if (product.StockQuantity < quantityOrdered)
            {
                _logger.LogWarning(
                    "Insufficient stock for product {ProductId}. Available: {Available}, Requested: {Requested}",
                    productId, product.StockQuantity, quantityOrdered);
                await transaction.RollbackAsync();
                return false;
            }

            // greybeard: Mutation - record the intent before mutation for audit and compensation.
            var auditEntry = new StockDecrementAudit
            {
                IdempotencyKey = idempotencyKey,
                ProductId = productId,
                QuantityDecremented = quantityOrdered,
                PreviousStock = product.StockQuantity,
                Timestamp = DateTime.UtcNow,
                Status = "committed" // written before mutation for recovery
            };

            _context.StockDecrementAudit.Add(auditEntry);

            // greybeard: Mutation - apply the decrement within the transaction.
            product.StockQuantity -= quantityOrdered;
            product.UpdatedAt = DateTime.UtcNow;

            // greybeard: Fails half-way - write both mutation and audit atomically.
            await _context.SaveChangesAsync();

            _logger.LogInformation(
                "Stock decremented for product {ProductId}: {Quantity} units. " +
                "Previous: {Previous}, New: {New}. IdempotencyKey: {Key}",
                productId, quantityOrdered, auditEntry.PreviousStock, product.StockQuantity, idempotencyKey);

            await transaction.CommitAsync();
            return true;
        }
        catch (DbUpdateException ex) when (ex.InnerException is TimeoutException)
        {
            // greybeard: External call (DB is external) - timeout occurred.
            _logger.LogError(ex,
                "Timeout during stock decrement for product {ProductId}, idempotency key {Key}. " +
                "Transaction will rollback. Safe to retry.",
                productId, idempotencyKey);
            await transaction.RollbackAsync();
            return false;
        }
        catch (DbUpdateConcurrencyException ex)
        {
            // greybeard: Concurrency - row was modified outside this transaction.
            // Should not occur with Serializable isolation, but handle gracefully.
            _logger.LogError(ex,
                "Concurrency conflict during stock decrement for product {ProductId}, idempotency key {Key}. " +
                "Transaction will rollback. Safe to retry.",
                productId, idempotencyKey);
            await transaction.RollbackAsync();
            return false;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Unexpected error during stock decrement for product {ProductId}, idempotency key {Key}. " +
                "Transaction will rollback.",
                productId, idempotencyKey);
            await transaction.RollbackAsync();
            throw;
        }
    }
}

