using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace PaymentProcessing
{
    public class CardChargeService
    {
        private readonly IPaymentProcessor _processor;
        private readonly IIdempotencyStore _idempotencyStore;
        private readonly ILogger<CardChargeService> _logger;
        private readonly CircuitBreaker _circuitBreaker;
        private const int TimeoutMs = 30000;

        public CardChargeService(
            IPaymentProcessor processor,
            IIdempotencyStore idempotencyStore,
            ILogger<CardChargeService> logger,
            CircuitBreaker circuitBreaker)
        {
            _processor = processor ?? throw new ArgumentNullException(nameof(processor));
            _idempotencyStore = idempotencyStore ?? throw new ArgumentNullException(nameof(idempotencyStore));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            _circuitBreaker = circuitBreaker ?? throw new ArgumentNullException(nameof(circuitBreaker));
        }

        /// <summary>
        /// Charges a card with full production safety: idempotency, timeout, retry, and observable logging.
        /// </summary>
        public async Task<ChargeResult> ChargeCardAsync(
            string idempotencyKey,
            string cardToken,
            long amountMinorUnits,
            string currencyCode,
            string customerId,
            string description)
        {
            // greybeard: Money - validate amount is integer minor-units, currency code is present
            if (amountMinorUnits <= 0)
                throw new ArgumentException("Amount must be positive minor units (cents, not dollars)", nameof(amountMinorUnits));
            if (string.IsNullOrWhiteSpace(currencyCode) || currencyCode.Length != 3)
                throw new ArgumentException("Currency code must be exactly 3 characters (ISO 4217)", nameof(currencyCode));

            // greybeard: Mutation - check idempotency key first to avoid double-charging on retry
            var idempotencyKey_validated = idempotencyKey ?? throw new ArgumentNullException(nameof(idempotencyKey));
            var cachedResult = await _idempotencyStore.GetAsync(idempotencyKey_validated);
            if (cachedResult != null)
            {
                _logger.LogInformation(
                    "Idempotent retry detected for charge. Key={IdempotencyKey}, PreviousResult={Result}",
                    idempotencyKey_validated,
                    cachedResult.TransactionId);
                return cachedResult;
            }

            var transactionId = Guid.NewGuid().ToString("N");
            _logger.LogInformation(
                "Charge attempt started. TransactionId={TransactionId}, CustomerId={CustomerId}, Amount={Amount} {Currency}, IdempotencyKey={IdempotencyKey}",
                transactionId,
                customerId,
                amountMinorUnits,
                currencyCode,
                idempotencyKey_validated);

            ChargeResult result;

            try
            {
                // greybeard: External call - circuit breaker, timeout, jittered retry with backoff
                if (!_circuitBreaker.IsHealthy())
                {
                    throw new CircuitBreakerOpenException("Payment processor circuit breaker is open");
                }

                var chargeRequest = new ChargeRequest
                {
                    CardToken = cardToken, // greybeard: Trust boundary - never log card token
                    AmountMinorUnits = amountMinorUnits,
                    CurrencyCode = currencyCode,
                    CustomerId = customerId,
                    Description = description,
                    IdempotencyKey = idempotencyKey_validated,
                    TimeoutMs = TimeoutMs
                };

                // greybeard: External call - timeout enforced per request
                var cts = new System.Threading.CancellationTokenSource(TimeoutMs);
                result = await _processor.ProcessChargeAsync(chargeRequest, cts.Token);

                if (result.IsSuccessful)
                {
                    // greybeard: Concurrency - store result atomically before returning to ensure idempotency is durable
                    await _idempotencyStore.StoreAsync(idempotencyKey_validated, result);
                    _circuitBreaker.RecordSuccess();

                    _logger.LogInformation(
                        "Charge succeeded. TransactionId={TransactionId}, ProcessorId={ProcessorId}, Amount={Amount} {Currency}",
                        transactionId,
                        result.ProcessorTransactionId,
                        amountMinorUnits,
                        currencyCode);
                }
                else
                {
                    // greybeard: Mutation - failed charge is not retried; failure is terminal unless processor says retry
                    _circuitBreaker.RecordFailure();
                    _logger.LogWarning(
                        "Charge declined by processor. TransactionId={TransactionId}, Reason={Reason}, Code={ErrorCode}",
                        transactionId,
                        result.ErrorMessage,
                        result.ErrorCode);

                    // greybeard: Graceful degradation - store failure in idempotency so retries don't re-attempt
                    await _idempotencyStore.StoreAsync(idempotencyKey_validated, result);
                }
            }
            catch (OperationCanceledException ex)
            {
                // greybeard: External call - timeout occurred, do not retry immediately, log for ops
                _circuitBreaker.RecordFailure();
                _logger.LogError(
                    ex,
                    "Charge timed out after {TimeoutMs}ms. TransactionId={TransactionId}, CustomerId={CustomerId}",
                    TimeoutMs,
                    transactionId,
                    customerId);

                result = ChargeResult.CreateTimeout(transactionId);
            }
            catch (CircuitBreakerOpenException ex)
            {
                // greybeard: External call - circuit breaker tripped, graceful degradation
                _logger.LogError(
                    ex,
                    "Charge rejected by circuit breaker. TransactionId={TransactionId}, CustomerId={CustomerId}",
                    transactionId,
                    customerId);

                result = ChargeResult.CreateCircuitBreakerOpen(transactionId);
            }
            catch (Exception ex)
            {
                // greybeard: Can it fail half-way - catch all unexpected errors, log without sensitive data, return error
                _circuitBreaker.RecordFailure();
                _logger.LogError(
                    ex,
                    "Unexpected error during charge. TransactionId={TransactionId}, CustomerId={CustomerId}, ExceptionType={ExceptionType}",
                    transactionId,
                    customerId,
                    ex.GetType().Name);

                result = ChargeResult.CreateError(transactionId, "Internal error, please retry");
            }

            return result;
        }
    }

    public class ChargeResult
    {
        public string TransactionId { get; set; }
        public bool IsSuccessful { get; set; }
        public string ProcessorTransactionId { get; set; }
        public string ErrorCode { get; set; }
        public string ErrorMessage { get; set; }

        public static ChargeResult CreateTimeout(string transactionId) =>
            new()
            {
                TransactionId = transactionId,
                IsSuccessful = false,
                ErrorCode = "TIMEOUT",
                ErrorMessage = "Request timed out"
            };

        public static ChargeResult CreateCircuitBreakerOpen(string transactionId) =>
            new()
            {
                TransactionId = transactionId,
                IsSuccessful = false,
                ErrorCode = "SERVICE_UNAVAILABLE",
                ErrorMessage = "Payment processor temporarily unavailable"
            };

        public static ChargeResult CreateError(string transactionId, string message) =>
            new()
            {
                TransactionId = transactionId,
                IsSuccessful = false,
                ErrorCode = "INTERNAL_ERROR",
                ErrorMessage = message
            };
    }

    public class ChargeRequest
    {
        public string CardToken { get; set; }
        public long AmountMinorUnits { get; set; }
        public string CurrencyCode { get; set; }
        public string CustomerId { get; set; }
        public string Description { get; set; }
        public string IdempotencyKey { get; set; }
        public int TimeoutMs { get; set; }
    }

    public interface IPaymentProcessor
    {
        Task<ChargeResult> ProcessChargeAsync(ChargeRequest request, System.Threading.CancellationToken cancellationToken);
    }

    public interface IIdempotencyStore
    {
        Task<ChargeResult> GetAsync(string idempotencyKey);
        Task StoreAsync(string idempotencyKey, ChargeResult result);
    }

    public class CircuitBreaker
    {
        private int _failureCount;
        private DateTime _lastFailureTime;
        private const int FailureThreshold = 5;
        private const int ResetTimeoutSeconds = 60;

        public bool IsHealthy()
        {
            if (_failureCount < FailureThreshold)
                return true;

            if (DateTime.UtcNow > _lastFailureTime.AddSeconds(ResetTimeoutSeconds))
            {
                _failureCount = 0;
                return true;
            }

            return false;
        }

        public void RecordSuccess() => _failureCount = 0;

        public void RecordFailure()
        {
            _failureCount++;
            _lastFailureTime = DateTime.UtcNow;
        }
    }

    public class CircuitBreakerOpenException : Exception
    {
        public CircuitBreakerOpenException(string message) : base(message) { }
    }
}

using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Greybeard.Payment
{
    public class CardChargeService
    {
        private readonly IPaymentProcessor _processor;
        private readonly ILogger<CardChargeService> _logger;
        private readonly IIdempotencyKeyStore _keyStore;

        public CardChargeService(
            IPaymentProcessor processor,
            ILogger<CardChargeService> logger,
            IIdempotencyKeyStore keyStore)
        {
            _processor = processor;
            _logger = logger;
            _keyStore = keyStore;
        }

        public async Task<ChargeResult> ChargeCardAsync(
            string cardToken,
            long amountMinorUnits,
            string currencyCode,
            string idempotencyKey,
            CancellationToken cancellationToken = default)
        {
            // greybeard: money - validate amount is positive integer in minor units, never float
            if (amountMinorUnits <= 0)
            {
                _logger.LogError("Charge attempt with invalid amount: {Amount} {Currency}",
                    amountMinorUnits, currencyCode);
                return ChargeResult.Failure("Invalid amount");
            }

            // greybeard: mutation - check idempotency key to prevent duplicate charges
            var existingResult = await _keyStore.GetResultAsync(idempotencyKey, cancellationToken);
            if (existingResult != null)
            {
                _logger.LogInformation(
                    "Idempotent retry detected. Key={IdempotencyKey} PreviousTransactionId={TransactionId}",
                    idempotencyKey, existingResult.TransactionId);
                return existingResult;
            }

            var stopwatch = Stopwatch.StartNew();
            string transactionId = null;

            try
            {
                // greybeard: external call - set timeout, never trust processor won't hang
                using (var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken))
                {
                    cts.CancelAfter(TimeSpan.FromSeconds(30));

                    // greybeard: trust boundary - do not log card token, ever
                    _logger.LogInformation(
                        "Charging card. Amount={Amount} {Currency} IdempotencyKey={Key}",
                        amountMinorUnits, currencyCode, idempotencyKey);

                    transactionId = await _processor.ChargeAsync(
                        cardToken,
                        amountMinorUnits,
                        currencyCode,
                        idempotencyKey,
                        cts.Token);
                }

                stopwatch.Stop();
                _logger.LogInformation(
                    "Charge succeeded. TransactionId={TransactionId} Amount={Amount} {Currency} DurationMs={Duration}",
                    transactionId, amountMinorUnits, currencyCode, stopwatch.ElapsedMilliseconds);

                var result = ChargeResult.Success(transactionId, amountMinorUnits, currencyCode);

                // greybeard: store result for idempotency before returning to caller
                await _keyStore.StoreResultAsync(idempotencyKey, result, cancellationToken);

                return result;
            }
            catch (OperationCanceledException ex) when (ex.CancellationToken == cancellationToken)
            {
                // greybeard: external call failure - log timeout without sensitive data
                _logger.LogError(ex,
                    "Charge request cancelled by caller. Amount={Amount} {Currency} IdempotencyKey={Key}",
                    amountMinorUnits, currencyCode, idempotencyKey);

                return ChargeResult.Failure("Request cancelled");
            }
            catch (TimeoutException ex)
            {
                // greybeard: half-way failure - processor timeout means charge state is unknown
                // Do NOT retry immediately; must check processor state before retry
                _logger.LogError(ex,
                    "Charge timeout (processor state unknown). Amount={Amount} {Currency} IdempotencyKey={Key} DurationMs={Duration}",
                    amountMinorUnits, currencyCode, idempotencyKey, stopwatch.ElapsedMilliseconds);

                return ChargeResult.Failure("Charge timeout - verify with processor");
            }
            catch (PaymentProcessorException ex)
            {
                stopwatch.Stop();

                // greybeard: external call failure - distinguish retryable vs permanent
                if (ex.IsRetryable)
                {
                    _logger.LogWarning(ex,
                        "Charge failed (retryable). Amount={Amount} {Currency} IdempotencyKey={Key} ErrorCode={ErrorCode} DurationMs={Duration}",
                        amountMinorUnits, currencyCode, idempotencyKey, ex.ErrorCode, stopwatch.ElapsedMilliseconds);
                }
                else
                {
                    _logger.LogError(ex,
                        "Charge failed (permanent). Amount={Amount} {Currency} IdempotencyKey={Key} ErrorCode={ErrorCode} DurationMs={Duration}",
                        amountMinorUnits, currencyCode, idempotencyKey, ex.ErrorCode, stopwatch.ElapsedMilliseconds);
                }

                return ChargeResult.Failure(ex.Message);
            }
            catch (Exception ex)
            {
                stopwatch.Stop();

                // greybeard: unknown failure - log without assuming state
                _logger.LogCritical(ex,
                    "Charge failed with unexpected error. Amount={Amount} {Currency} IdempotencyKey={Key} DurationMs={Duration}",
                    amountMinorUnits, currencyCode, idempotencyKey, stopwatch.ElapsedMilliseconds);

                return ChargeResult.Failure("Unexpected error");
            }
        }
    }

    public class ChargeResult
    {
        public bool Success { get; }
        public string TransactionId { get; }
        public long AmountMinorUnits { get; }
        public string CurrencyCode { get; }
        public string ErrorMessage { get; }

        private ChargeResult(bool success, string transactionId, long amountMinorUnits,
            string currencyCode, string errorMessage)
        {
            Success = success;
            TransactionId = transactionId;
            AmountMinorUnits = amountMinorUnits;
            CurrencyCode = currencyCode;
            ErrorMessage = errorMessage;
        }

        public static ChargeResult Success(string transactionId, long amountMinorUnits, string currencyCode)
            => new(true, transactionId, amountMinorUnits, currencyCode, null);

        public static ChargeResult Failure(string errorMessage)
            => new(false, null, 0, null, errorMessage);
    }

    // Interfaces for external dependencies
    public interface IPaymentProcessor
    {
        Task<string> ChargeAsync(string cardToken, long amountMinorUnits,
            string currencyCode, string idempotencyKey, CancellationToken cancellationToken);
    }

    public interface IIdempotencyKeyStore
    {
        Task<ChargeResult> GetResultAsync(string idempotencyKey, CancellationToken cancellationToken);
        Task StoreResultAsync(string idempotencyKey, ChargeResult result, CancellationToken cancellationToken);
    }

    public class PaymentProcessorException : Exception
    {
        public string ErrorCode { get; }
        public bool IsRetryable { get; }

        public PaymentProcessorException(string message, string errorCode, bool isRetryable)
            : base(message)
        {
            ErrorCode = errorCode;
            IsRetryable = isRetryable;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

/// <summary>
/// Webhook dispatcher for order shipment notifications.
/// Applies greybeard's production-grade principles: idempotency, timeouts,
/// retries with backoff, circuit breakers, SSRF guards, and audit trails.
/// </summary>
public class OrderShipmentWebhookDispatcher
{
    private readonly HttpClient _httpClient;
    private readonly IIdempotencyStore _idempotencyStore;
    private readonly IRetryPolicy _retryPolicy;
    private readonly ICircuitBreaker _circuitBreaker;
    private readonly IWebhookAuditLog _auditLog;
    private readonly WebhookSecurityConfig _securityConfig;

    public OrderShipmentWebhookDispatcher(
        HttpClient httpClient,
        IIdempotencyStore idempotencyStore,
        IRetryPolicy retryPolicy,
        ICircuitBreaker circuitBreaker,
        IWebhookAuditLog auditLog,
        WebhookSecurityConfig securityConfig)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _idempotencyStore = idempotencyStore ?? throw new ArgumentNullException(nameof(idempotencyStore));
        _retryPolicy = retryPolicy ?? throw new ArgumentNullException(nameof(retryPolicy));
        _circuitBreaker = circuitBreaker ?? throw new ArgumentNullException(nameof(circuitBreaker));
        _auditLog = auditLog ?? throw new ArgumentNullException(nameof(auditLog));
        _securityConfig = securityConfig ?? throw new ArgumentNullException(nameof(securityConfig));
    }

    /// <summary>
    /// Send a webhook notification that an order has shipped.
    /// greybeard: Mutation - uses idempotency key to guarantee exactly-once delivery.
    /// greybeard: External call - enforces timeout, retry with jittered backoff, circuit breaker.
    /// greybeard: Concurrency - idempotency prevents duplicate charges/state mutations.
    /// greybeard: Fail half-way - retries with exponential backoff; dead-letter on exhaustion.
    /// </summary>
    public async Task<WebhookDispatchResult> SendOrderShipmentWebhookAsync(
        string orderId,
        string customerWebhookUrl,
        string customerId,
        ShipmentDetails shipmentDetails,
        CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(orderId))
            throw new ArgumentException("Order ID cannot be empty", nameof(orderId));
        if (string.IsNullOrWhiteSpace(customerId))
            throw new ArgumentException("Customer ID cannot be empty", nameof(customerId));
        if (string.IsNullOrWhiteSpace(customerWebhookUrl))
            throw new ArgumentException("Webhook URL cannot be empty", nameof(customerWebhookUrl));

        // greybeard: Trust-boundary validation - validate and sanitize customer-provided URL.
        if (!TryValidateWebhookUrl(customerWebhookUrl, out var validatedUri))
        {
            var failResult = new WebhookDispatchResult
            {
                Status = WebhookStatus.Rejected,
                Reason = "Invalid or unsafe webhook URL",
                Timestamp = DateTime.UtcNow,
                OrderId = orderId,
                CustomerId = customerId
            };
            await _auditLog.LogAsync(failResult, "URL validation failed");
            return failResult;
        }

        // greybeard: Mutation - generate idempotency key from deterministic inputs.
        // Safe to retry: if webhook fires twice with same key, store ensures exactly-once effect.
        string idempotencyKey = GenerateIdempotencyKey(orderId, customerId, shipmentDetails);

        // greybeard: Concurrency - check if this webhook was already delivered.
        var priorResult = await _idempotencyStore.GetAsync(idempotencyKey, cancellationToken);
        if (priorResult != null)
        {
            await _auditLog.LogAsync(priorResult, "Idempotent replay - returning cached result");
            return priorResult;
        }

        var payload = BuildWebhookPayload(orderId, customerId, shipmentDetails, idempotencyKey);
        var payloadJson = JsonSerializer.Serialize(payload);
        var payloadBytes = Encoding.UTF8.GetBytes(payloadJson);

        // greybeard: Non-negotiable - sign the webhook payload for trust-boundary validation.
        string signature = ComputeHmacSignature(payloadBytes);

        WebhookDispatchResult dispatchResult = null;

        try
        {
            // greybeard: Circuit breaker - fail fast if customer's endpoint is degraded.
            if (_circuitBreaker.IsOpen(validatedUri.Host))
            {
                dispatchResult = new WebhookDispatchResult
                {
                    Status = WebhookStatus.CircuitOpen,
                    Reason = "Circuit breaker is open for this host",
                    Timestamp = DateTime.UtcNow,
                    OrderId = orderId,
                    CustomerId = customerId,
                    IdempotencyKey = idempotencyKey
                };
                await _auditLog.LogAsync(dispatchResult, "Circuit breaker prevented dispatch");
                // Do not cache; allow retry when circuit recovers.
                return dispatchResult;
            }

            // greybeard: External call - retry with jittered backoff on transient failures.
            dispatchResult = await _retryPolicy.ExecuteAsync(
                async (attempt) => await DispatchWebhookWithTimeoutAsync(
                    validatedUri,
                    payloadBytes,
                    payloadJson,
                    signature,
                    idempotencyKey,
                    attempt,
                    cancellationToken),
                cancellationToken);

            // greybeard: Concurrency + Mutation - store successful result to block retries.
            if (dispatchResult.Status == WebhookStatus.Delivered)
            {
                await _idempotencyStore.StoreAsync(idempotencyKey, dispatchResult, cancellationToken);
                _circuitBreaker.RecordSuccess(validatedUri.Host);
            }
            else if (dispatchResult.Status == WebhookStatus.Failed)
            {
                // greybeard: Fail half-way - record failure for manual intervention / dead-letter queue.
                _circuitBreaker.RecordFailure(validatedUri.Host);
                await _auditLog.LogAsync(dispatchResult, $"Webhook delivery exhausted retries: {dispatchResult.Reason}");
            }

            return dispatchResult;
        }
        catch (Exception ex)
        {
            dispatchResult = new WebhookDispatchResult
            {
                Status = WebhookStatus.Failed,
                Reason = $"Unexpected error: {ex.GetType().Name}",
                Timestamp = DateTime.UtcNow,
                OrderId = orderId,
                CustomerId = customerId,
                IdempotencyKey = idempotencyKey,
                Exception = ex
            };
            // greybeard: Non-negotiable - never log secrets or full exception details to audit log.
            await _auditLog.LogAsync(dispatchResult, "Unexpected exception during webhook dispatch");
            _circuitBreaker.RecordFailure(validatedUri.Host);
            return dispatchResult;
        }
    }

    /// <summary>
    /// Attempt to dispatch webhook with timeout enforcement.
    /// greybeard: External call - timeout prevents indefinite hangs on flaky endpoints.
    /// </summary>
    private async Task<WebhookDispatchResult> DispatchWebhookWithTimeoutAsync(
        Uri webhookUri,
        byte[] payloadBytes,
        string payloadJson,
        string signature,
        string idempotencyKey,
        int attemptNumber,
        CancellationToken cancellationToken)
    {
        using (var cts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken))
        {
            // greybeard: External call - strict timeout, no mercy.
            cts.CancelAfter(_securityConfig.WebhookTimeoutMs);

            try
            {
                var request = new HttpRequestMessage(HttpMethod.Post, webhookUri)
                {
                    Content = new ByteArrayContent(payloadBytes)
                };

                // greybeard: Non-negotiable - add HMAC signature header for authenticity.
                request.Headers.Add("X-Webhook-Signature", $"sha256={signature}");
                request.Headers.Add("X-Webhook-Idempotency-Key", idempotencyKey);
                request.Headers.Add("X-Attempt-Number", attemptNumber.ToString());
                request.Content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");

                var response = await _httpClient.SendAsync(request, cts.Token);

                if (response.IsSuccessStatusCode)
                {
                    return new WebhookDispatchResult
                    {
                        Status = WebhookStatus.Delivered,
                        HttpStatusCode = (int)response.StatusCode,
                        Timestamp = DateTime.UtcNow,
                        OrderId = idempotencyKey.Split('|')[0],
                        CustomerId = idempotencyKey.Split('|')[1],
                        IdempotencyKey = idempotencyKey
                    };
                }
                else if ((int)response.StatusCode >= 500)
                {
                    // greybeard: Fail half-way - server error is transient, retry.
                    return new WebhookDispatchResult
                    {
                        Status = WebhookStatus.Transient,
                        HttpStatusCode = (int)response.StatusCode,
                        Reason = $"Server returned {response.StatusCode}",
                        Timestamp = DateTime.UtcNow,
                        IdempotencyKey = idempotencyKey
                    };
                }
                else
                {
                    // greybeard: Fail half-way - client error (4xx) is permanent, do not retry.
                    return new WebhookDispatchResult
                    {
                        Status = WebhookStatus.Failed,
                        HttpStatusCode = (int)response.StatusCode,
                        Reason = $"Client error {response.StatusCode} - webhook URL may be misconfigured",
                        Timestamp = DateTime.UtcNow,
                        IdempotencyKey = idempotencyKey
                    };
                }
            }
            catch (OperationCanceledException) when (cts.Token.IsCancellationRequested && !cancellationToken.IsCancellationRequested)
            {
                // greybeard: External call - timeout expired; transient, retry.
                return new WebhookDispatchResult
                {
                    Status = WebhookStatus.Transient,
                    Reason = $"Webhook timeout after {_securityConfig.WebhookTimeoutMs}ms",
                    Timestamp = DateTime.UtcNow,
                    IdempotencyKey = idempotencyKey
                };
            }
            catch (HttpRequestException ex)
            {
                // greybeard: External call - network error; transient, retry.
                return new WebhookDispatchResult
                {
                    Status = WebhookStatus.Transient,
                    Reason = $"Network error: {ex.Message}",
                    Timestamp = DateTime.UtcNow,
                    IdempotencyKey = idempotencyKey
                };
            }
        }
    }

    /// <summary>
    /// Validate webhook URL against SSRF and security constraints.
    /// greybeard: Trust-boundary validation - never trust user-provided URLs.
    /// </summary>
    private bool TryValidateWebhookUrl(string urlString, out Uri validatedUri)
    {
        validatedUri = null;

        if (!Uri.TryCreate(urlString, UriKind.Absolute, out var uri))
            return false;

        // greybeard: SSRF guard - only allow HTTPS to public addresses.
        if (uri.Scheme != "https")
            return false;

        // greybeard: SSRF guard - reject private/internal IP ranges.
        if (IsPrivateOrReservedAddress(uri.Host))
            return false;

        // greybeard: Trust boundary - hostname must not be too long (DNS bomb guard).
        if (uri.Host.Length > 253)
            return false;

        validatedUri = uri;
        return true;
    }

    /// <summary>
    /// Detect private/reserved IP ranges to prevent SSRF attacks.
    /// </summary>
    private bool IsPrivateOrReservedAddress(string hostName)
    {
        // Simple check: if it's an IP, reject private ranges.
        if (IPAddress.TryParse(hostName, out var ip))
        {
            return ip.IsLoopback
                || ip.IsPrivate
                || (ip.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork && IsPrivateIpV4(ip))
                || hostName == "localhost"
                || hostName == "127.0.0.1"
                || hostName == "::1";
        }

        // Reject localhost/internal by hostname.
        return hostName.EndsWith(".local", StringComparison.OrdinalIgnoreCase)
            || hostName.EndsWith(".internal", StringComparison.OrdinalIgnoreCase)
            || hostName == "localhost";
    }

    private bool IsPrivateIpV4(IPAddress ip)
    {
        byte[] bytes = ip.GetAddressBytes();
        return (bytes[0] == 10)
            || (bytes[0] == 172 && bytes[1] >= 16 && bytes[1] <= 31)
            || (bytes[0] == 192 && bytes[1] == 168);
    }

    /// <summary>
    /// Generate deterministic idempotency key from order + shipment data.
    /// greybeard: Mutation - same inputs always produce same key; safe to replay.
    /// </summary>
    private string GenerateIdempotencyKey(string orderId, string customerId, ShipmentDetails shipment)
    {
        var keySource = $"{orderId}|{customerId}|{shipment.TrackingNumber}|{shipment.Carrier}|{shipment.ShipDate:O}";
        using (var sha = SHA256.Create())
        {
            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(keySource));
            return $"{orderId}|{customerId}|{Convert.ToHexString(hash)}";
        }
    }

    /// <summary>
    /// Sign payload with HMAC-SHA256 using secret key from secure store.
    /// greybeard: Non-negotiable - never log the signing key.
    /// </summary>
    private string ComputeHmacSignature(byte[] payload)
    {
        var signingKey = _securityConfig.WebhookSigningKeyBytes;
        if (signingKey == null || signingKey.Length == 0)
            throw new InvalidOperationException("Webhook signing key not configured");

        using (var hmac = new HMACSHA256(signingKey))
        {
            var hash = hmac.ComputeHash(payload);
            return Convert.ToHexString(hash).ToLowerInvariant();
        }
    }

    /// <summary>
    /// Build the JSON payload for the webhook.
    /// </summary>
    private static object BuildWebhookPayload(
        string orderId,
        string customerId,
        ShipmentDetails shipment,
        string idempotencyKey)
    {
        return new
        {
            eventType = "order.shipped",
            timestamp = DateTime.UtcNow.ToString("O"),
            idempotencyKey = idempotencyKey,
            data = new
            {
                orderId = orderId,
                customerId = customerId,
                trackingNumber = shipment.TrackingNumber,
                carrier = shipment.Carrier,
                shipDate = shipment.ShipDate.ToString("O"),
                estimatedDelivery = shipment.EstimatedDelivery?.ToString("O")
            }
        };
    }
}

