using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Stripe;
using Stripe.Events;

namespace GreybeardPayments.Controllers
{
    [ApiController]
    [Route("api/webhooks")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly IStripeSignatureValidator _signatureValidator;
        private readonly IAccountCreditService _creditService;
        private readonly IWebhookDeliveryService _deliveryService;
        private readonly ILogger<StripeWebhookController> _logger;

        public StripeWebhookController(
            IStripeSignatureValidator signatureValidator,
            IAccountCreditService creditService,
            IWebhookDeliveryService deliveryService,
            ILogger<StripeWebhookController> logger)
        {
            _signatureValidator = signatureValidator;
            _creditService = creditService;
            _deliveryService = deliveryService;
            _logger = logger;
        }

        [HttpPost("stripe")]
        public async Task<IActionResult> HandleStripeWebhook()
        {
            string json;
            try
            {
                using (var reader = new System.IO.StreamReader(Request.Body))
                {
                    json = await reader.ReadToEndAsync();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to read webhook body");
                return BadRequest();
            }

            // greybeard: Trust boundary — verify Stripe signature before parsing JSON
            string signatureHeader = Request.Headers["Stripe-Signature"].ToString();
            if (!_signatureValidator.VerifySignature(json, signatureHeader))
            {
                _logger.LogWarning("Webhook signature validation failed");
                return Unauthorized();
            }

            Event stripeEvent;
            try
            {
                stripeEvent = EventUtility.ParseEvent(json);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to parse Stripe event");
                return BadRequest();
            }

            // greybeard: Mutation + Concurrency — check idempotency by event ID before proceeding
            // Ensures exactly-once semantics even if webhook is redelivered
            bool alreadyProcessed = await _deliveryService.HasEventBeenProcessedAsync(stripeEvent.Id);
            if (alreadyProcessed)
            {
                _logger.LogInformation("Webhook event {EventId} already processed, returning 200 OK", stripeEvent.Id);
                return Ok();
            }

            if (stripeEvent.Type != "payment_intent.succeeded")
            {
                // Not our event type; acknowledge but don't process
                return Ok();
            }

            PaymentIntent paymentIntent = stripeEvent.Data.Object as PaymentIntent;
            if (paymentIntent == null)
            {
                _logger.LogError("payment_intent.succeeded event missing PaymentIntent object");
                return BadRequest();
            }

            // greybeard: Mutation — idempotency key travels with the payment
            // Use PaymentIntent.Id as the idempotency key for credit operation
            string idempotencyKey = paymentIntent.Id;

            // greybeard: Trust boundary — validate payment amount came from Stripe, not client
            // Never trust amounts in headers or metadata; only the PaymentIntent amount
            if (paymentIntent.Amount <= 0)
            {
                _logger.LogError("PaymentIntent {PaymentId} has invalid amount: {Amount}", paymentIntent.Id, paymentIntent.Amount);
                return BadRequest();
            }

            // greybeard: Money — extract amount as integer minor units (cents for USD)
            // Currency code travels with the amount; validate it matches expected
            long amountMinorUnits = paymentIntent.Amount;
            string currency = paymentIntent.Currency;

            if (string.IsNullOrEmpty(currency) || currency.Length != 3)
            {
                _logger.LogError("PaymentIntent {PaymentId} has invalid currency: {Currency}", paymentIntent.Id, currency);
                return BadRequest();
            }

            // greybeard: Trust boundary — extract customer ID from PaymentIntent, not from webhook metadata
            string stripeCustomerId = paymentIntent.CustomerId;
            if (string.IsNullOrEmpty(stripeCustomerId))
            {
                _logger.LogError("PaymentIntent {PaymentId} missing customer ID", paymentIntent.Id);
                return BadRequest();
            }

            // greybeard: Concurrency — record delivery attempt before mutation to prevent double-processing
            // Mark this event as being processed atomically with the credit
            try
            {
                await _creditService.CreditAccountAsync(
                    stripeCustomerId,
                    amountMinorUnits,
                    currency,
                    idempotencyKey,
                    paymentIntent.Id
                );

                // greybeard: Mutation + Concurrency — mark event as successfully processed only after credit completes
                await _deliveryService.MarkEventProcessedAsync(stripeEvent.Id);

                _logger.LogInformation(
                    "Successfully credited customer {CustomerId} {Amount} {Currency} for PaymentIntent {PaymentId}",
                    stripeCustomerId,
                    amountMinorUnits,
                    currency,
                    paymentIntent.Id
                );

                return Ok();
            }
            catch (CreditAlreadyGrantedException ex)
            {
                // greybeard: Mutation — idempotent credit was already applied for this PaymentIntent
                _logger.LogInformation("Credit already granted for PaymentIntent {PaymentId}: {Message}", paymentIntent.Id, ex.Message);
                await _deliveryService.MarkEventProcessedAsync(stripeEvent.Id);
                return Ok();
            }
            catch (Exception ex)
            {
                // greybeard: Can it fail half-way? — credit operation failed; do not mark event processed
                // Webhook will be retried; customer account is not corrupted
                _logger.LogError(
                    ex,
                    "Failed to credit account for PaymentIntent {PaymentId}, customer {CustomerId}, amount {Amount} {Currency}. Webhook will be retried.",
                    paymentIntent.Id,
                    stripeCustomerId,
                    amountMinorUnits,
                    currency
                );
                return StatusCode(500);
            }
        }
    }

    // Supporting interfaces for dependency injection
    public interface IStripeSignatureValidator
    {
        bool VerifySignature(string json, string signatureHeader);
    }

    public interface IAccountCreditService
    {
        Task CreditAccountAsync(string stripeCustomerId, long amountMinorUnits, string currency, string idempotencyKey, string paymentIntentId);
    }

    public interface IWebhookDeliveryService
    {
        Task<bool> HasEventBeenProcessedAsync(string eventId);
        Task MarkEventProcessedAsync(string eventId);
    }

    public class CreditAlreadyGrantedException : Exception
    {
        public CreditAlreadyGrantedException(string message) : base(message) { }
    }
}

using Microsoft.AspNetCore.Mvc;
using Stripe;
using System;
using System.Threading.Tasks;

namespace PaymentWebhooks.Controllers
{
    [ApiController]
    [Route("webhooks")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly IStripeWebhookVerifier _webhookVerifier;
        private readonly IAccountService _accountService;
        private readonly IWebhookEventStore _eventStore;
        private readonly ILogger<StripeWebhookController> _logger;

        public StripeWebhookController(
            IStripeWebhookVerifier webhookVerifier,
            IAccountService accountService,
            IWebhookEventStore eventStore,
            ILogger<StripeWebhookController> logger)
        {
            _webhookVerifier = webhookVerifier;
            _accountService = accountService;
            _eventStore = eventStore;
            _logger = logger;
        }

        [HttpPost("stripe/payment")]
        public async Task<IActionResult> HandlePaymentSucceeded()
        {
            // greybeard: Trust boundary — verify webhook signature before processing
            var json = await new StreamReader(HttpContext.Request.Body).ReadToEndAsync();
            var stripeSignature = Request.Headers["Stripe-Signature"].ToString();

            if (string.IsNullOrEmpty(stripeSignature))
            {
                _logger.LogWarning("Webhook missing signature header");
                return Unauthorized();
            }

            if (!_webhookVerifier.VerifySignature(json, stripeSignature))
            {
                _logger.LogWarning("Webhook signature verification failed");
                return Unauthorized();
            }

            Event stripeEvent;
            try
            {
                // greybeard: Parse safely; never log raw event body (contains secrets)
                stripeEvent = EventUtility.ParseEvent(json);
            }
            catch (JsonException ex)
            {
                _logger.LogError("Webhook event parse failed: {ErrorType}", ex.GetType().Name);
                return BadRequest();
            }

            // greybeard: Idempotency — check if this event was already processed
            // Stripe can redeliver; we must not credit twice for the same payment_succeeded
            var alreadyProcessed = await _eventStore.EventProcessedAsync(stripeEvent.Id);
            if (alreadyProcessed)
            {
                _logger.LogInformation("Webhook event {EventId} already processed, skipping", stripeEvent.Id);
                return Ok(); // Return 200 to tell Stripe we handled it
            }

            // greybeard: Only handle payment_succeeded events
            if (stripeEvent.Type != "payment_intent.succeeded")
            {
                _logger.LogInformation("Webhook type {Type} ignored", stripeEvent.Type);
                return Ok();
            }

            var paymentIntent = stripeEvent.Data.Object as PaymentIntent;
            if (paymentIntent == null)
            {
                _logger.LogError("Webhook payload missing PaymentIntent object");
                return BadRequest();
            }

            // greybeard: Money — extract amount as integer minor units (cents), never float
            // Always validate currency code travels with amount
            if (string.IsNullOrEmpty(paymentIntent.Currency) || paymentIntent.Amount == null)
            {
                _logger.LogError("Webhook amount or currency missing");
                return BadRequest();
            }

            var amountMinorUnits = (long)paymentIntent.Amount; // Stripe delivers in minor units
            var currencyCode = paymentIntent.Currency.ToUpperInvariant();

            // greybeard: Extract customer ID; validate presence before lookup
            var customerId = paymentIntent.CustomerId;
            if (string.IsNullOrEmpty(customerId))
            {
                _logger.LogError("Webhook payment has no customer ID");
                return BadRequest();
            }

            // greybeard: Concurrency + Mutation — wrap in transaction with row lock
            // Exactly-once effect: idempotency key (Stripe event ID) ensures safe retry
            try
            {
                await _accountService.CreditAccountAsync(
                    customerId: customerId,
                    amountMinorUnits: amountMinorUnits,
                    currencyCode: currencyCode,
                    idempotencyKey: stripeEvent.Id,
                    sourceReference: paymentIntent.Id);

                // greybeard: Graceful degradation — record successful processing atomically
                // If this fails, we retry the entire webhook (Stripe will redeliver)
                await _eventStore.MarkEventProcessedAsync(stripeEvent.Id);

                _logger.LogInformation(
                    "Payment credited: customer={CustomerId}, amount={Amount}{Currency}, ref={Ref}",
                    customerId,
                    amountMinorUnits,
                    currencyCode,
                    paymentIntent.Id);

                return Ok();
            }
            catch (ConcurrencyException ex)
            {
                // greybeard: Idempotency — another request already credited this payment
                // Stripe will retry; we idempotently return success
                _logger.LogInformation("Payment already credited (race condition): {Message}", ex.Message);
                return Ok();
            }
            catch (CustomerNotFoundException ex)
            {
                // greybeard: Fail half-way — customer vanished but payment succeeded
                // Log loudly; return 400 to tell Stripe to redeliver (manual intervention needed)
                _logger.LogError("Customer not found after payment: {CustomerId}", customerId);
                return BadRequest("Customer not found");
            }
            catch (Exception ex)
            {
                // greybeard: Never expose internal errors to webhook (no stack traces)
                _logger.LogError(ex, "Webhook processing failed: {EventId}", stripeEvent.Id);
                // Return 500 to trigger Stripe retry
                return StatusCode(500);
            }
        }
    }

    // Supporting interfaces (implementation responsibility of caller)
    public interface IStripeWebhookVerifier
    {
        // greybeard: Verify signature using Stripe's public key; never trust raw event
        bool VerifySignature(string json, string signature);
    }

    public interface IAccountService
    {
        // greybeard: Idempotency key ensures exactly-once credit
        // Throws ConcurrencyException if amount already credited for this idempotency key
        Task CreditAccountAsync(
            string customerId,
            long amountMinorUnits,
            string currencyCode,
            string idempotencyKey,
            string sourceReference);
    }

    public interface IWebhookEventStore
    {
        // greybeard: Atomically track processed events to prevent double-processing
        Task<bool> EventProcessedAsync(string stripeEventId);
        Task MarkEventProcessedAsync(string stripeEventId);
    }

    public class ConcurrencyException : Exception
    {
        public ConcurrencyException(string message) : base(message) { }
    }

    public class CustomerNotFoundException : Exception
    {
        public CustomerNotFoundException(string message) : base(message) { }
    }
}

