using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Payments;

/// <summary>
/// Request payload sent to the external payment gateway.
/// </summary>
public sealed record ChargeRequest(
    string CardToken,
    long AmountMinorUnits,
    string Currency,
    string IdempotencyKey);

/// <summary>
/// Response returned by the external payment gateway.
/// </summary>
public sealed record ChargeResponse(
    string TransactionId,
    string Status,
    string? FailureReason);

/// <summary>
/// Result of attempting to charge a card.
/// </summary>
public sealed record ChargeResult(
    bool Succeeded,
    string? TransactionId,
    string? ErrorMessage);

public sealed class PaymentGatewayClient
{
    private readonly HttpClient _httpClient;

    // HttpClient should be injected (e.g. via IHttpClientFactory) and reused,
    // not created per-call, to avoid socket exhaustion.
    public PaymentGatewayClient(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    /// <summary>
    /// Charges a card by calling the external payment gateway over HTTP.
    /// </summary>
    /// <param name="request">The charge details, including a card token and idempotency key.</param>
    /// <param name="cancellationToken">Token used to cancel the outbound request.</param>
    /// <returns>A <see cref="ChargeResult"/> describing success or failure.</returns>
    public async Task<ChargeResult> ChargeCardAsync(
        ChargeRequest request,
        CancellationToken cancellationToken = default)
    {
        if (request is null)
            throw new ArgumentNullException(nameof(request));
        if (request.AmountMinorUnits <= 0)
            throw new ArgumentOutOfRangeException(nameof(request.AmountMinorUnits));
        if (string.IsNullOrWhiteSpace(request.CardToken))
            throw new ArgumentException("Card token is required.", nameof(request.CardToken));
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required.", nameof(request.IdempotencyKey));

        using var httpRequest = new HttpRequestMessage(HttpMethod.Post, "v1/charges")
        {
            Content = JsonContent.Create(request)
        };

        // Idempotency key lets the gateway dedupe retries so a card is never
        // charged twice for the same logical operation.
        httpRequest.Headers.Add("Idempotency-Key", request.IdempotencyKey);

        try
        {
            using var httpResponse = await _httpClient
                .SendAsync(httpRequest, cancellationToken)
                .ConfigureAwait(false);

            if (!httpResponse.IsSuccessStatusCode)
            {
                var body = await httpResponse.Content
                    .ReadAsStringAsync(cancellationToken)
                    .ConfigureAwait(false);

                return new ChargeResult(
                    Succeeded: false,
                    TransactionId: null,
                    ErrorMessage: $"Gateway returned {(int)httpResponse.StatusCode}: {body}");
            }

            var charge = await httpResponse.Content
                .ReadFromJsonAsync<ChargeResponse>(cancellationToken)
                .ConfigureAwait(false);

            if (charge is null)
            {
                return new ChargeResult(
                    Succeeded: false,
                    TransactionId: null,
                    ErrorMessage: "Gateway returned an empty or unparseable response.");
            }

            var approved = string.Equals(charge.Status, "succeeded", StringComparison.OrdinalIgnoreCase);

            return new ChargeResult(
                Succeeded: approved,
                TransactionId: charge.TransactionId,
                ErrorMessage: approved ? null : charge.FailureReason ?? "Charge was declined.");
        }
        catch (TaskCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            // SendAsync surfaces timeouts as TaskCanceledException when the caller
            // did not request cancellation.
            return new ChargeResult(
                Succeeded: false,
                TransactionId: null,
                ErrorMessage: "The payment gateway request timed out.");
        }
        catch (HttpRequestException ex)
        {
            return new ChargeResult(
                Succeeded: false,
                TransactionId: null,
                ErrorMessage: $"Failed to reach the payment gateway: {ex.Message}");
        }
    }
}

using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Payments
{
    /// <summary>
    /// Request payload sent to the external payment gateway.
    /// </summary>
    public sealed record ChargeRequest
    {
        public required string CardToken { get; init; }
        public required long AmountMinorUnits { get; init; }
        public required string Currency { get; init; }
        public string? Description { get; init; }
        public string? IdempotencyKey { get; init; }
    }

    /// <summary>
    /// Response returned by the external payment gateway.
    /// </summary>
    public sealed record ChargeResult
    {
        public required bool Success { get; init; }
        public string? TransactionId { get; init; }
        public string? Status { get; init; }
        public string? ErrorCode { get; init; }
        public string? ErrorMessage { get; init; }
    }

    public sealed class PaymentGatewayException : Exception
    {
        public PaymentGatewayException(string message, Exception? inner = null)
            : base(message, inner) { }
    }

    public sealed class PaymentGatewayClient
    {
        private readonly HttpClient _httpClient;

        // Reuse a single HttpClient instance (typically injected via IHttpClientFactory)
        // to avoid socket exhaustion.
        public PaymentGatewayClient(HttpClient httpClient)
        {
            _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        }

        /// <summary>
        /// Charges a card by calling the external payment gateway over HTTP.
        /// </summary>
        /// <param name="request">The charge details (tokenized card, amount, currency, etc.).</param>
        /// <param name="cancellationToken">Token used to cancel the in-flight request.</param>
        /// <returns>The result of the charge attempt.</returns>
        /// <exception cref="ArgumentNullException">Thrown when <paramref name="request"/> is null.</exception>
        /// <exception cref="ArgumentException">Thrown when the request is invalid.</exception>
        /// <exception cref="PaymentGatewayException">Thrown when the gateway call fails.</exception>
        public async Task<ChargeResult> ChargeCardAsync(
            ChargeRequest request,
            CancellationToken cancellationToken = default)
        {
            if (request is null)
                throw new ArgumentNullException(nameof(request));
            if (string.IsNullOrWhiteSpace(request.CardToken))
                throw new ArgumentException("Card token is required.", nameof(request));
            if (request.AmountMinorUnits <= 0)
                throw new ArgumentException("Amount must be positive.", nameof(request));
            if (string.IsNullOrWhiteSpace(request.Currency))
                throw new ArgumentException("Currency is required.", nameof(request));

            // An idempotency key prevents a retried request from charging the card twice.
            var idempotencyKey = string.IsNullOrWhiteSpace(request.IdempotencyKey)
                ? Guid.NewGuid().ToString("N")
                : request.IdempotencyKey;

            using var httpRequest = new HttpRequestMessage(HttpMethod.Post, "v1/charges")
            {
                Content = JsonContent.Create(new
                {
                    card_token = request.CardToken,
                    amount = request.AmountMinorUnits,
                    currency = request.Currency,
                    description = request.Description
                })
            };
            httpRequest.Headers.Add("Idempotency-Key", idempotencyKey);

            try
            {
                using HttpResponseMessage response =
                    await _httpClient.SendAsync(httpRequest, cancellationToken)
                                     .ConfigureAwait(false);

                if (!response.IsSuccessStatusCode)
                {
                    // Try to read a structured error body; fall back to status code.
                    var failure = await TryReadResultAsync(response, cancellationToken)
                                        .ConfigureAwait(false);

                    return failure ?? new ChargeResult
                    {
                        Success = false,
                        Status = "failed",
                        ErrorCode = ((int)response.StatusCode).ToString(),
                        ErrorMessage = $"Gateway returned HTTP {(int)response.StatusCode} ({response.ReasonPhrase})."
                    };
                }

                var result = await response.Content
                    .ReadFromJsonAsync<ChargeResult>(cancellationToken: cancellationToken)
                    .ConfigureAwait(false);

                return result ?? throw new PaymentGatewayException(
                    "Gateway returned an empty or unparseable success response.");
            }
            catch (TaskCanceledException) when (!cancellationToken.IsCancellationRequested)
            {
                // TaskCanceledException without caller cancellation indicates a timeout.
                throw new PaymentGatewayException("The payment gateway request timed out.");
            }
            catch (HttpRequestException ex)
            {
                throw new PaymentGatewayException(
                    "A network error occurred while contacting the payment gateway.", ex);
            }
        }

        private static async Task<ChargeResult?> TryReadResultAsync(
            HttpResponseMessage response,
            CancellationToken cancellationToken)
        {
            try
            {
                return await response.Content
                    .ReadFromJsonAsync<ChargeResult>(cancellationToken: cancellationToken)
                    .ConfigureAwait(false);
            }
            catch
            {
                return null;
            }
        }
    }
}

using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Payments;

/// <summary>
/// Request payload sent to the payment gateway.
/// </summary>
public sealed record ChargeRequest(
    string CardToken,
    long AmountMinorUnits,
    string Currency,
    string IdempotencyKey,
    string? Description = null);

/// <summary>
/// Response returned by the payment gateway after a charge attempt.
/// </summary>
public sealed record ChargeResponse(
    string TransactionId,
    string Status,
    long AmountMinorUnits,
    string Currency);

/// <summary>
/// Result wrapper so callers can branch on success/failure without exceptions
/// for expected decline scenarios.
/// </summary>
public sealed record ChargeResult(
    bool Succeeded,
    ChargeResponse? Response,
    string? ErrorCode,
    string? ErrorMessage)
{
    public static ChargeResult Ok(ChargeResponse response) =>
        new(true, response, null, null);

    public static ChargeResult Failed(string code, string message) =>
        new(false, null, code, message);
}

/// <summary>
/// Thrown when the gateway call fails in a way that is not a normal decline
/// (e.g. network failure, 5xx, timeout, or malformed response).
/// </summary>
public sealed class PaymentGatewayException : Exception
{
    public PaymentGatewayException(string message, Exception? inner = null)
        : base(message, inner) { }
}

public sealed class PaymentGatewayClient
{
    private readonly HttpClient _httpClient;

    /// <summary>
    /// The <see cref="HttpClient"/> should be supplied by the caller, ideally
    /// via IHttpClientFactory, with BaseAddress and the Authorization header
    /// (gateway API key/secret) already configured. This keeps secrets out of
    /// this method and lets the platform manage connection pooling and resilience.
    /// </summary>
    public PaymentGatewayClient(HttpClient httpClient)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
    }

    /// <summary>
    /// Charges a card by calling the external payment gateway over HTTP.
    /// </summary>
    /// <param name="request">The charge details. Pass a stable
    /// <see cref="ChargeRequest.IdempotencyKey"/> so that retries do not
    /// double-charge the customer.</param>
    /// <param name="cancellationToken">Token to cancel the request.</param>
    /// <returns>A <see cref="ChargeResult"/> describing success or a decline.</returns>
    /// <exception cref="PaymentGatewayException">
    /// Thrown for transport-level or unexpected gateway errors.
    /// </exception>
    public async Task<ChargeResult> ChargeAsync(
        ChargeRequest request,
        CancellationToken cancellationToken = default)
    {
        // Validate input before spending a network round-trip on it.
        ArgumentNullException.ThrowIfNull(request);

        if (string.IsNullOrWhiteSpace(request.CardToken))
            throw new ArgumentException("Card token is required.", nameof(request));

        if (request.AmountMinorUnits <= 0)
            throw new ArgumentException("Amount must be greater than zero.", nameof(request));

        if (string.IsNullOrWhiteSpace(request.Currency))
            throw new ArgumentException("Currency is required.", nameof(request));

        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required.", nameof(request));

        // Build the request explicitly so we can attach the idempotency header,
        // which the gateway uses to deduplicate retried charges.
        using var httpRequest = new HttpRequestMessage(HttpMethod.Post, "v1/charges")
        {
            Content = JsonContent.Create(request)
        };
        httpRequest.Headers.Add("Idempotency-Key", request.IdempotencyKey);

        HttpResponseMessage httpResponse;
        try
        {
            httpResponse = await _httpClient
                .SendAsync(httpRequest, HttpCompletionOption.ResponseHeadersRead, cancellationToken)
                .ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Caller-initiated cancellation: let it propagate as cancellation.
            throw;
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            // Network failure or timeout. Because the charge may or may not have
            // been applied on the gateway side, callers should retry with the
            // SAME idempotency key rather than issuing a fresh charge.
            throw new PaymentGatewayException(
                "Failed to reach the payment gateway. Retry with the same idempotency key.", ex);
        }

        using (httpResponse)
        {
            // A successful HTTP status means the gateway processed the request.
            if (httpResponse.IsSuccessStatusCode)
            {
                var charge = await httpResponse.Content
                    .ReadFromJsonAsync<ChargeResponse>(cancellationToken)
                    .ConfigureAwait(false);

                if (charge is null)
                    throw new PaymentGatewayException("Gateway returned an empty response body.");

                return ChargeResult.Ok(charge);
            }

            // 4xx (other than 402) typically indicates a bad request on our side.
            // 402 Payment Required is the conventional "card declined" signal.
            var status = (int)httpResponse.StatusCode;
            var body = await httpResponse.Content
                .ReadAsStringAsync(cancellationToken)
                .ConfigureAwait(false);

            if (status == 402 || (status >= 400 && status < 500))
            {
                // Expected, non-transient outcome (declined / invalid request).
                // Return a result instead of throwing so callers can handle it
                // as normal control flow. Avoid logging the raw body verbatim if
                // it can contain sensitive data; this is left to the caller.
                return ChargeResult.Failed(
                    code: httpResponse.StatusCode.ToString(),
                    message: $"Charge was not completed (HTTP {status}).");
            }

            // 5xx or anything else unexpected: treat as a transport-level failure.
            throw new PaymentGatewayException(
                $"Payment gateway returned an unexpected status {status}. Body: {body}");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

namespace Shop.Inventory;

/// <summary>
/// Represents a single line of an order: which product and how many units.
/// </summary>
public sealed record OrderLine(int ProductId, int Quantity);

/// <summary>
/// Thrown when an order cannot be fulfilled because one or more products
/// do not have enough stock on hand.
/// </summary>
public sealed class InsufficientStockException : Exception
{
    public InsufficientStockException(int productId, int requested, int available)
        : base($"Insufficient stock for product {productId}: requested {requested}, available {available}.")
    {
        ProductId = productId;
        Requested = requested;
        Available = available;
    }

    public int ProductId { get; }
    public int Requested { get; }
    public int Available { get; }
}

public sealed class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public int StockOnHand { get; set; }

    /// <summary>
    /// Concurrency token. EF Core uses this to detect competing updates so two
    /// simultaneous orders cannot both decrement from the same starting value.
    /// </summary>
    public byte[] RowVersion { get; set; } = Array.Empty<byte>();
}

public sealed class ShopDbContext : DbContext
{
    public ShopDbContext(DbContextOptions<ShopDbContext> options) : base(options) { }

    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(b =>
        {
            b.HasKey(p => p.Id);
            b.Property(p => p.Name).IsRequired();
            b.Property(p => p.StockOnHand).IsRequired();
            b.Property(p => p.RowVersion).IsRowVersion();
        });
    }
}

public sealed class StockService
{
    private readonly ShopDbContext _db;

    public StockService(ShopDbContext db) => _db = db;

    /// <summary>
    /// Atomically decrements stock for every line of an order.
    ///
    /// The whole operation runs inside a single transaction: either every line
    /// is decremented or none are. A row-version concurrency token guards against
    /// two orders racing on the same product, and an optimistic-concurrency retry
    /// loop re-reads and re-validates if a conflict is detected.
    /// </summary>
    /// <exception cref="ArgumentException">An order line has a non-positive quantity, or there are no lines.</exception>
    /// <exception cref="KeyNotFoundException">A referenced product does not exist.</exception>
    /// <exception cref="InsufficientStockException">A product does not have enough stock.</exception>
    public async Task DecrementStockForOrderAsync(
        IReadOnlyCollection<OrderLine> lines,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(lines);

        if (lines.Count == 0)
            throw new ArgumentException("An order must contain at least one line.", nameof(lines));

        // Collapse duplicate product lines so each product is touched exactly once.
        var demand = lines
            .GroupBy(l => l.ProductId)
            .Select(g => new
            {
                ProductId = g.Key,
                Quantity = g.Sum(l => l.Quantity),
            })
            .ToList();

        foreach (var d in demand)
        {
            if (d.Quantity <= 0)
                throw new ArgumentException(
                    $"Quantity for product {d.ProductId} must be positive.", nameof(lines));
        }

        var productIds = demand.Select(d => d.ProductId).ToList();

        const int maxRetries = 3;
        for (var attempt = 0; ; attempt++)
        {
            await using var transaction =
                await _db.Database.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);

            try
            {
                var products = await _db.Products
                    .Where(p => productIds.Contains(p.Id))
                    .ToDictionaryAsync(p => p.Id, cancellationToken)
                    .ConfigureAwait(false);

                foreach (var d in demand)
                {
                    if (!products.TryGetValue(d.ProductId, out var product))
                        throw new KeyNotFoundException($"Product {d.ProductId} was not found.");

                    if (product.StockOnHand < d.Quantity)
                        throw new InsufficientStockException(
                            d.ProductId, d.Quantity, product.StockOnHand);

                    product.StockOnHand -= d.Quantity;
                }

                await _db.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
                await transaction.CommitAsync(cancellationToken).ConfigureAwait(false);
                return;
            }
            catch (DbUpdateConcurrencyException) when (attempt < maxRetries)
            {
                // Another order updated one of these products first. Roll back,
                // drop the now-stale tracked entities, and retry with fresh data.
                await transaction.RollbackAsync(cancellationToken).ConfigureAwait(false);

                foreach (var entry in _db.ChangeTracker.Entries<Product>().ToList())
                    entry.State = EntityState.Detached;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

namespace Shop.Inventory
{
    // Domain entities
    public class Product
    {
        public int Id { get; set; }
        public string Name { get; set; } = string.Empty;

        // Quantity currently available to sell.
        public int StockQuantity { get; set; }

        // Optional concurrency token. When mapped as a row version (e.g.
        // .IsRowVersion() in OnModelCreating), EF Core will throw a
        // DbUpdateConcurrencyException if two transactions race to decrement
        // the same product, which prevents overselling.
        public byte[]? RowVersion { get; set; }
    }

    public class OrderLine
    {
        public int ProductId { get; set; }
        public int Quantity { get; set; }
    }

    public class ShopDbContext : DbContext
    {
        public ShopDbContext(DbContextOptions<ShopDbContext> options)
            : base(options)
        {
        }

        public DbSet<Product> Products => Set<Product>();

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<Product>(entity =>
            {
                entity.HasKey(p => p.Id);
                entity.Property(p => p.RowVersion).IsRowVersion();
            });
        }
    }

    /// <summary>
    /// Thrown when an order cannot be fulfilled because one or more products
    /// do not have enough stock on hand.
    /// </summary>
    public class InsufficientStockException : Exception
    {
        public int ProductId { get; }
        public int Requested { get; }
        public int Available { get; }

        public InsufficientStockException(int productId, int requested, int available)
            : base($"Insufficient stock for product {productId}: requested {requested}, available {available}.")
        {
            ProductId = productId;
            Requested = requested;
            Available = available;
        }
    }

    public class InventoryService
    {
        private readonly ShopDbContext _db;

        public InventoryService(ShopDbContext db)
        {
            _db = db ?? throw new ArgumentNullException(nameof(db));
        }

        /// <summary>
        /// Decrements stock for every line in an order atomically.
        /// Either all lines succeed or the whole operation is rolled back.
        /// </summary>
        /// <param name="lines">The order lines (product id + quantity).</param>
        /// <param name="cancellationToken">Cancellation token.</param>
        /// <exception cref="ArgumentNullException">If <paramref name="lines"/> is null.</exception>
        /// <exception cref="ArgumentException">If any line has a non-positive quantity.</exception>
        /// <exception cref="KeyNotFoundException">If a referenced product does not exist.</exception>
        /// <exception cref="InsufficientStockException">If a product lacks sufficient stock.</exception>
        /// <exception cref="DbUpdateConcurrencyException">If a concurrent update wins the race.</exception>
        public async Task DecrementStockForOrderAsync(
            IEnumerable<OrderLine> lines,
            CancellationToken cancellationToken = default)
        {
            if (lines is null)
            {
                throw new ArgumentNullException(nameof(lines));
            }

            // Collapse duplicate product references into a single quantity so a
            // product appearing twice in one order is handled correctly.
            var requested = lines
                .GroupBy(l => l.ProductId)
                .ToDictionary(g => g.Key, g => g.Sum(l => l.Quantity));

            if (requested.Count == 0)
            {
                return;
            }

            foreach (var (productId, quantity) in requested)
            {
                if (quantity <= 0)
                {
                    throw new ArgumentException(
                        $"Order line quantity for product {productId} must be positive.",
                        nameof(lines));
                }
            }

            var productIds = requested.Keys.ToList();

            // Wrap in an explicit transaction so the read-check-write across
            // multiple products is all-or-nothing.
            await using var transaction =
                await _db.Database.BeginTransactionAsync(cancellationToken);

            // Load all required products in a single query and track them so
            // changes are persisted on SaveChanges.
            var products = await _db.Products
                .Where(p => productIds.Contains(p.Id))
                .ToDictionaryAsync(p => p.Id, cancellationToken);

            foreach (var (productId, quantity) in requested)
            {
                if (!products.TryGetValue(productId, out var product))
                {
                    throw new KeyNotFoundException($"Product {productId} was not found.");
                }

                if (product.StockQuantity < quantity)
                {
                    throw new InsufficientStockException(
                        productId, quantity, product.StockQuantity);
                }

                product.StockQuantity -= quantity;
            }

            // RowVersion concurrency tokens cause SaveChanges to fail if another
            // transaction modified the same product concurrently, so we never
            // oversell under load.
            await _db.SaveChangesAsync(cancellationToken);
            await transaction.CommitAsync(cancellationToken);
        }
    }
}

