using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Webhooks
{
    /// <summary>
    /// Configuration for the Stripe webhook endpoint.
    /// </summary>
    public sealed class StripeWebhookOptions
    {
        /// <summary>
        /// The signing secret for this endpoint (starts with "whsec_").
        /// Obtain it from the Stripe Dashboard / API per-endpoint. Never hard-code it.
        /// </summary>
        public string SigningSecret { get; set; } = string.Empty;
    }

    /// <summary>
    /// Records which Stripe events have already been processed, so that
    /// Stripe's at-least-once redelivery does not double-credit accounts.
    /// </summary>
    public interface IProcessedEventStore
    {
        /// <summary>
        /// Atomically marks the event id as seen. Returns <c>true</c> if this call
        /// is the first to claim the id (i.e. we should process it), or <c>false</c>
        /// if it had already been recorded (a redelivery / duplicate).
        /// Implementations MUST be atomic (e.g. an INSERT with a unique constraint
        /// on the event id, treating a duplicate-key violation as "already seen").
        /// </summary>
        Task<bool> TryMarkProcessedAsync(string eventId, CancellationToken cancellationToken);

        /// <summary>
        /// Removes the record for an event id. Used to roll back the claim if the
        /// business operation throws, so Stripe's retry can be processed cleanly.
        /// </summary>
        Task UnmarkAsync(string eventId, CancellationToken cancellationToken);
    }

    /// <summary>
    /// Applies account credits. Implementations should themselves be idempotent
    /// where possible (e.g. keyed on the PaymentIntent / Charge id) as defence in depth.
    /// </summary>
    public interface IAccountCreditService
    {
        Task CreditAsync(
            string customerId,
            long amountInMinorUnits,
            string currency,
            string paymentIntentId,
            CancellationToken cancellationToken);
    }

    [ApiController]
    [Route("api/webhooks/stripe")]
    public sealed class StripeWebhookController : ControllerBase
    {
        private readonly string _signingSecret;
        private readonly IProcessedEventStore _processedEvents;
        private readonly IAccountCreditService _credits;
        private readonly ILogger<StripeWebhookController> _logger;

        public StripeWebhookController(
            IOptions<StripeWebhookOptions> options,
            IProcessedEventStore processedEvents,
            IAccountCreditService credits,
            ILogger<StripeWebhookController> logger)
        {
            _signingSecret = options?.Value?.SigningSecret
                ?? throw new ArgumentNullException(nameof(options));
            _processedEvents = processedEvents ?? throw new ArgumentNullException(nameof(processedEvents));
            _credits = credits ?? throw new ArgumentNullException(nameof(credits));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        [HttpPost]
        public async Task<IActionResult> Handle(CancellationToken cancellationToken)
        {
            // 1) Read the RAW request body. Signature verification is computed over
            //    the exact bytes Stripe sent, so we must not use a model-bound DTO.
            string payload;
            using (var reader = new StreamReader(Request.Body))
            {
                payload = await reader.ReadToEndAsync().ConfigureAwait(false);
            }

            // 2) Verify the signature. This authenticates the payload AND, because
            //    ConstructEvent enforces the timestamp tolerance (default 300s),
            //    protects against replay of captured requests.
            Event stripeEvent;
            try
            {
                stripeEvent = EventUtility.ConstructEvent(
                    payload,
                    Request.Headers["Stripe-Signature"],
                    _signingSecret,
                    throwOnApiVersionMismatch: false);
            }
            catch (StripeException ex)
            {
                // Signature invalid / missing header / outside tolerance.
                // Do NOT 500 here: a 400 tells Stripe the request is bad and not
                // worth retrying. Never log the secret or the raw signature.
                _logger.LogWarning(ex, "Rejected Stripe webhook: signature verification failed.");
                return BadRequest();
            }

            // 3) Only act on the event type we care about. Acknowledge everything
            //    else with 200 so Stripe stops retrying events we ignore.
            if (stripeEvent.Type != Events.PaymentIntentSucceeded)
            {
                _logger.LogDebug("Ignoring Stripe event {EventId} of type {EventType}.",
                    stripeEvent.Id, stripeEvent.Type);
                return Ok();
            }

            // 4) Idempotency: Stripe guarantees at-least-once delivery, so the same
            //    event id can arrive multiple times (retries / dashboard redelivery).
            //    Claim the id atomically; if someone already claimed it, ack and stop.
            if (!await _processedEvents.TryMarkProcessedAsync(stripeEvent.Id, cancellationToken)
                    .ConfigureAwait(false))
            {
                _logger.LogInformation("Duplicate Stripe event {EventId} ignored.", stripeEvent.Id);
                return Ok();
            }

            try
            {
                if (stripeEvent.Data.Object is not PaymentIntent intent)
                {
                    _logger.LogError("Stripe event {EventId} had no PaymentIntent payload.", stripeEvent.Id);
                    // Malformed payload that we can't action. Drop our claim and
                    // return 200 so Stripe doesn't hammer us; this needs human review.
                    await _processedEvents.UnmarkAsync(stripeEvent.Id, cancellationToken).ConfigureAwait(false);
                    return Ok();
                }

                if (string.IsNullOrEmpty(intent.CustomerId))
                {
                    _logger.LogWarning(
                        "PaymentIntent {PaymentIntentId} (event {EventId}) has no customer; nothing to credit.",
                        intent.Id, stripeEvent.Id);
                    return Ok();
                }

                // Use the amount Stripe actually received, in the smallest currency unit.
                await _credits.CreditAsync(
                    intent.CustomerId,
                    intent.AmountReceived,
                    intent.Currency,
                    intent.Id,
                    cancellationToken).ConfigureAwait(false);

                _logger.LogInformation(
                    "Credited customer {CustomerId} with {Amount} {Currency} for PaymentIntent {PaymentIntentId} (event {EventId}).",
                    intent.CustomerId, intent.AmountReceived, intent.Currency, intent.Id, stripeEvent.Id);

                return Ok();
            }
            catch (Exception ex)
            {
                // The business operation failed. Roll back the idempotency claim so
                // Stripe's automatic retry can re-attempt cleanly, and return 500 so
                // Stripe knows to redeliver.
                _logger.LogError(ex, "Failed to process Stripe event {EventId}; rolling back claim for retry.",
                    stripeEvent.Id);

                try
                {
                    await _processedEvents.UnmarkAsync(stripeEvent.Id, cancellationToken).ConfigureAwait(false);
                }
                catch (Exception rollbackEx)
                {
                    _logger.LogError(rollbackEx,
                        "Failed to roll back idempotency claim for event {EventId}.", stripeEvent.Id);
                }

                return StatusCode(StatusCodes.Status500InternalServerError);
            }
        }
    }
}

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Webhooks;

/// <summary>
/// Strongly-typed options bound from configuration / secret store.
/// The webhook signing secret (whsec_...) is NOT the same as your API key.
/// Get it from the Stripe Dashboard for the specific endpoint, or from the
/// `stripe listen` CLI output during local development.
/// </summary>
public sealed class StripeWebhookOptions
{
    public string SigningSecret { get; set; } = string.Empty;
}

/// <summary>
/// Persists which Stripe event ids have already been processed so that
/// redeliveries (Stripe retries with the SAME event id) are idempotent.
/// Back this with a real durable store (SQL/Redis) in production. The
/// "claim" should be atomic — e.g. an INSERT on a UNIQUE event-id column,
/// or a Redis SET NX — so two concurrent deliveries can't both win.
/// </summary>
public interface IProcessedEventStore
{
    /// <summary>
    /// Atomically records the event id as "in progress / done".
    /// Returns true if THIS call claimed it (first time we've seen it),
    /// false if it was already claimed (i.e. a redelivery / duplicate).
    /// </summary>
    Task<bool> TryClaimAsync(string eventId, CancellationToken ct);
}

/// <summary>Applies account credits. Implementation must itself be idempotent-safe.</summary>
public interface IAccountCreditService
{
    /// <summary>
    /// Credits the customer's account for a successful payment.
    /// Keyed on the PaymentIntent id so that even if the idempotency
    /// guard is bypassed, double-crediting is prevented at the data layer.
    /// </summary>
    Task CreditAsync(string customerId, string paymentIntentId, long amount, string currency, CancellationToken ct);
}

[ApiController]
[Route("api/webhooks/stripe")]
public sealed class StripeWebhookController : ControllerBase
{
    private readonly string _signingSecret;
    private readonly IProcessedEventStore _processedEvents;
    private readonly IAccountCreditService _credits;
    private readonly ILogger<StripeWebhookController> _logger;

    public StripeWebhookController(
        IOptions<StripeWebhookOptions> options,
        IProcessedEventStore processedEvents,
        IAccountCreditService credits,
        ILogger<StripeWebhookController> logger)
    {
        _signingSecret = options.Value.SigningSecret;
        _processedEvents = processedEvents;
        _credits = credits;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> Handle(CancellationToken ct)
    {
        // 1. Read the RAW request body. Signature verification is computed over
        //    the exact bytes Stripe sent; never deserialize-then-reserialize,
        //    that would change the payload and break verification.
        //    (Ensure no upstream middleware has consumed/buffered the body in a
        //    way that mutates it; EnableBuffering or a raw read is fine.)
        string json;
        using (var reader = new StreamReader(Request.Body))
        {
            json = await reader.ReadToEndAsync(ct);
        }

        var signatureHeader = Request.Headers["Stripe-Signature"];

        Event stripeEvent;
        try
        {
            // 2. Verify the signature AND the timestamp tolerance (default 5 min).
            //    This both authenticates the sender (HMAC with the signing secret)
            //    and rejects replayed/stale payloads. throwOnApiVersionMismatch is
            //    left default so a dashboard version bump doesn't drop events.
            stripeEvent = EventUtility.ConstructEvent(
                json,
                signatureHeader,
                _signingSecret);
        }
        catch (StripeException ex)
        {
            // Invalid signature, malformed payload, or expired timestamp.
            // Return 400 so Stripe marks the delivery as failed (do NOT retry
            // a forged request into a 200). Don't leak details to the caller.
            _logger.LogWarning(ex, "Rejected Stripe webhook: signature verification failed.");
            return BadRequest();
        }

        // 3. Filter to the event type we actually handle. Stripe may send other
        //    enabled event types to this endpoint; acknowledge them with 200 so
        //    Stripe stops retrying, but do no work.
        if (stripeEvent.Type != EventTypes.PaymentIntentSucceeded)
        {
            _logger.LogInformation("Ignoring unhandled Stripe event type {Type} ({Id}).",
                stripeEvent.Type, stripeEvent.Id);
            return Ok();
        }

        // 4. Idempotency / redelivery guard. Stripe guarantees at-least-once
        //    delivery and retries on any non-2xx or timeout, reusing the SAME
        //    event id. Claim it atomically; if we've seen it, ack and stop.
        if (!await _processedEvents.TryClaimAsync(stripeEvent.Id, ct))
        {
            _logger.LogInformation("Duplicate Stripe event {Id} ignored (already processed).", stripeEvent.Id);
            return Ok();
        }

        var paymentIntent = stripeEvent.Data.Object as PaymentIntent;
        if (paymentIntent is null)
        {
            // Shape we didn't expect for this event type. Ack to avoid an
            // infinite retry loop, but record it for investigation.
            _logger.LogError("payment_intent.succeeded event {Id} had no PaymentIntent payload.", stripeEvent.Id);
            return Ok();
        }

        // Defense in depth: trust the verified payload's status field.
        if (paymentIntent.Status != "succeeded")
        {
            _logger.LogWarning("PaymentIntent {Pi} in event {Id} not in succeeded state ({Status}); skipping credit.",
                paymentIntent.Id, stripeEvent.Id, paymentIntent.Status);
            return Ok();
        }

        try
        {
            // 5. Do the actual side effect. Keyed on the PaymentIntent id so the
            //    credit layer can also dedupe defensively. Amounts come from the
            //    signed payload — never from anything the client could influence.
            await _credits.CreditAsync(
                customerId: paymentIntent.CustomerId,
                paymentIntentId: paymentIntent.Id,
                amount: paymentIntent.AmountReceived,   // smallest currency unit (e.g. cents)
                currency: paymentIntent.Currency,
                ct: ct);
        }
        catch (Exception ex)
        {
            // Transient failure crediting the account. Return 500 so Stripe
            // RETRIES delivery later (with the same event id, caught by our
            // idempotency guard). Surfacing the error keeps the money correct.
            _logger.LogError(ex, "Failed to credit account for PaymentIntent {Pi} (event {Id}).",
                paymentIntent.Id, stripeEvent.Id);
            return StatusCode(StatusCodes.Status500InternalServerError);
        }

        _logger.LogInformation("Credited account for PaymentIntent {Pi} (event {Id}).",
            paymentIntent.Id, stripeEvent.Id);

        // 6. 200 OK -> Stripe marks the event delivered and stops retrying.
        return Ok();
    }
}

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Webhooks;

/// <summary>
/// Configuration bound from app settings / secrets store.
/// The signing secret is the per-endpoint secret shown in the Stripe Dashboard
/// (starts with "whsec_"). Never hard-code it.
/// </summary>
public sealed class StripeWebhookOptions
{
    public string SigningSecret { get; init; } = string.Empty;
}

/// <summary>
/// Abstraction over the account-crediting logic so the controller stays thin
/// and the credit operation can be made idempotent at the data layer.
/// </summary>
public interface IAccountCreditingService
{
    /// <summary>
    /// Credits the customer's account for a succeeded payment.
    ///
    /// MUST be idempotent: Stripe guarantees *at-least-once* delivery, so the
    /// same event can arrive multiple times (network retries, redeliveries from
    /// the Dashboard, etc.). Use <paramref name="eventId"/> (the Stripe Event ID,
    /// which is stable across redeliveries) as the idempotency key — typically a
    /// unique constraint on a "processed_events" table inside the same DB
    /// transaction that performs the credit.
    /// </summary>
    /// <returns>
    /// true  if the credit was applied for the first time;
    /// false if this event was already processed (duplicate / redelivery).
    /// </returns>
    Task<bool> CreditAccountAsync(
        string eventId,
        string customerId,
        string paymentIntentId,
        long amountReceived,
        string currency,
        CancellationToken cancellationToken);
}

[ApiController]
[Route("api/webhooks/stripe")]
public sealed class StripeWebhookController : ControllerBase
{
    private readonly string _signingSecret;
    private readonly IAccountCreditingService _crediting;
    private readonly ILogger<StripeWebhookController> _logger;

    public StripeWebhookController(
        IOptions<StripeWebhookOptions> options,
        IAccountCreditingService crediting,
        ILogger<StripeWebhookController> logger)
    {
        _signingSecret = options.Value.SigningSecret;
        _crediting = crediting;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> Handle(CancellationToken cancellationToken)
    {
        // 1. Read the RAW body. Signature verification is computed over the exact
        //    bytes Stripe sent; never use a model-bound/deserialized payload here.
        string payload;
        using (var reader = new StreamReader(Request.Body))
        {
            payload = await reader.ReadToEndAsync(cancellationToken);
        }

        var signatureHeader = Request.Headers["Stripe-Signature"].ToString();
        if (string.IsNullOrEmpty(signatureHeader))
        {
            _logger.LogWarning("Stripe webhook received with no Stripe-Signature header.");
            return BadRequest();
        }

        // 2. Verify the signature. This authenticates the request AND, because
        //    Stripe includes a timestamp in the signed payload, rejects replayed
        //    requests outside the default tolerance (300s). Constructing the event
        //    via the library also re-parses the trusted payload — we deliberately
        //    do NOT trust any client-supplied JSON before this point.
        Event stripeEvent;
        try
        {
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                signatureHeader,
                _signingSecret,
                throwOnApiVersionMismatch: false);
        }
        catch (StripeException ex)
        {
            // Bad signature, tampered payload, or stale timestamp.
            // Return 400 so Stripe marks delivery as failed (and will retry).
            _logger.LogWarning(ex, "Stripe webhook signature verification failed.");
            return BadRequest();
        }

        // 3. Dispatch by event type. We only act on payment_intent.succeeded
        //    here; everything else is acknowledged so Stripe stops retrying it.
        if (stripeEvent.Type != EventTypes.PaymentIntentSucceeded)
        {
            // Acknowledge unhandled event types with 200 to avoid pointless retries.
            return Ok();
        }

        if (stripeEvent.Data.Object is not PaymentIntent paymentIntent)
        {
            _logger.LogWarning(
                "Event {EventId} typed as payment_intent.succeeded but payload was not a PaymentIntent.",
                stripeEvent.Id);
            return BadRequest();
        }

        // Defensive: the event type says succeeded, but confirm the status too.
        if (paymentIntent.Status != "succeeded")
        {
            _logger.LogWarning(
                "PaymentIntent {PaymentIntentId} in event {EventId} has status {Status}; ignoring.",
                paymentIntent.Id, stripeEvent.Id, paymentIntent.Status);
            return Ok();
        }

        var customerId = paymentIntent.CustomerId;
        if (string.IsNullOrEmpty(customerId))
        {
            // No customer to credit — log and acknowledge so Stripe doesn't retry.
            _logger.LogWarning(
                "PaymentIntent {PaymentIntentId} (event {EventId}) has no associated customer; nothing to credit.",
                paymentIntent.Id, stripeEvent.Id);
            return Ok();
        }

        try
        {
            // 4. Credit idempotently, keyed on the stable Stripe Event ID.
            //    AmountReceived is the amount actually captured, in the currency's
            //    smallest unit (e.g. cents). Pass it straight through; do not trust
            //    any amount that might have come from the client.
            bool applied = await _crediting.CreditAccountAsync(
                eventId: stripeEvent.Id,
                customerId: customerId,
                paymentIntentId: paymentIntent.Id,
                amountReceived: paymentIntent.AmountReceived,
                currency: paymentIntent.Currency,
                cancellationToken: cancellationToken);

            if (applied)
            {
                _logger.LogInformation(
                    "Credited customer {CustomerId} for {Amount} {Currency} (PaymentIntent {PaymentIntentId}, event {EventId}).",
                    customerId, paymentIntent.AmountReceived, paymentIntent.Currency,
                    paymentIntent.Id, stripeEvent.Id);
            }
            else
            {
                // Duplicate delivery / redelivery — already handled. Still 200.
                _logger.LogInformation(
                    "Event {EventId} already processed; skipping duplicate credit for customer {CustomerId}.",
                    stripeEvent.Id, customerId);
            }
        }
        catch (Exception ex)
        {
            // Transient failure (DB down, etc.). Return 500 WITHOUT having
            // committed a partial credit, so Stripe retries delivery later.
            // Idempotency above guarantees the retry won't double-credit.
            _logger.LogError(ex,
                "Failed to credit customer {CustomerId} for event {EventId}; returning 500 so Stripe retries.",
                customerId, stripeEvent.Id);
            return StatusCode(500);
        }

        // 5. Acknowledge fast. Heavy/slow work should be enqueued, not done inline,
        //    because Stripe times out webhook deliveries.
        return Ok();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

// greybeard ladder for this task:
//   Rung 5 (reads a list)  -> keyset pagination, bounded page size, single projected
//                             query so the customer join does NOT become an N+1.
//   Rung 1 (money)         -> order total returned as integer minor units + currency code;
//                             no float ever crosses this boundary.
//   Rung 7 (minimum + observable) -> trust-boundary validation on paging params,
//                             AsNoTracking read, deterministic ordering.
// Rungs 2/3/4/6 do not apply: this is a read-only, in-process query. Skipped silently.

namespace Exports;

/// <summary>One row of the export screen. Money stays integer minor-units + currency.</summary>
public sealed record OrderExportRow(
    long OrderId,
    string CustomerName,
    long TotalMinorUnits,   // greybeard: integer minor units (e.g. cents), never a float currency value
    string Currency,        // greybeard: currency code travels WITH the amount, always
    DateTime CreatedUtc);

/// <summary>A bounded page of export rows plus the cursor to fetch the next page.</summary>
public sealed record OrderExportPage(
    IReadOnlyList<OrderExportRow> Rows,
    long? NextCursor);       // null => no more rows. Caller loops until null.

public static class OrderExportQueries
{
    // greybeard: hard upper bound on page size so a hostile/buggy caller can't ask for
    //            "all rows" and fan out an unbounded result set / OOM the export host.
    private const int MaxPageSize = 500;
    private const int DefaultPageSize = 100;

    /// <summary>
    /// Returns one bounded page of orders, each joined to its customer's name, for the
    /// export screen. Pages via a stable keyset cursor on OrderId (ascending).
    /// </summary>
    /// <param name="db">The EF Core context.</param>
    /// <param name="afterOrderId">
    /// Exclusive cursor: return orders with Id greater than this. Null for the first page.
    /// </param>
    /// <param name="pageSize">Requested rows per page; clamped to [1, MaxPageSize].</param>
    public static async Task<OrderExportPage> GetOrderExportPageAsync(
        AppDbContext db,
        long? afterOrderId,
        int pageSize,
        CancellationToken ct = default)
    {
        // greybeard: validate input crossing the trust boundary BEFORE it hits the DB.
        // Clamp rather than throw so an aggressive page size degrades to MaxPageSize
        // instead of failing the export; a non-positive size falls back to the default.
        if (pageSize <= 0)
        {
            pageSize = DefaultPageSize;
        }
        else if (pageSize > MaxPageSize)
        {
            pageSize = MaxPageSize;
        }

        // greybeard: cursor must reference a real, ordered key. Reject a negative cursor
        // (it can only come from a corrupted/forged token) rather than silently treating
        // it as "from the start".
        if (afterOrderId is < 0)
        {
            throw new ArgumentOutOfRangeException(
                nameof(afterOrderId), "Cursor must be non-negative.");
        }

        long cursor = afterOrderId ?? long.MinValue;

        // greybeard: ONE projected query.
        //   - Server-side join to Customer => the name comes back with each order,
        //     no per-order lazy load (kills the N+1 the veteran asks about).
        //   - AsNoTracking: read-only export, no change tracker overhead.
        //   - OrderBy(Id) + Id > cursor: keyset pagination. Stable and index-friendly,
        //     unlike Skip/Take which drifts and degrades on deep pages.
        //   - Take(pageSize + 1): one probe row tells us if a next page exists without
        //     a second COUNT round trip.
        var fetchSize = pageSize + 1;

        var fetched = await db.Orders
            .AsNoTracking()
            .Where(o => o.Id > cursor)
            .OrderBy(o => o.Id) // greybeard: deterministic order => stable, repeatable export
            .Select(o => new OrderExportRow(
                o.Id,
                // greybeard: null-safe so an order with a missing/deleted customer still
                // exports a row instead of throwing and aborting the whole batch.
                o.Customer != null ? o.Customer.Name : "(unknown)",
                o.TotalMinorUnits,
                o.Currency,
                o.CreatedUtc))
            .Take(fetchSize)
            .ToListAsync(ct)
            .ConfigureAwait(false);

        long? nextCursor = null;
        if (fetched.Count == fetchSize)
        {
            // We pulled the probe row => there is at least one more page.
            // Next cursor is the last row WE return (the probe is dropped).
            nextCursor = fetched[pageSize - 1].OrderId;
            fetched.RemoveAt(fetched.Count - 1);
        }

        return new OrderExportPage(fetched, nextCursor);
    }
}

