using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Payments;

// greybeard: rungs that apply here -> 1 Money (charging a card), 2 Mutation (a charge
// must have exactly-once effect under retry), 3 External call (HTTP to the gateway).
// Rungs 4/5/6 do not apply: no local row contention, no list read, no multi-step saga
// inside this single call -- so no machinery is added for them.

// greybeard: rung 1 -- amount is integer minor units (cents), currency travels with it.
// Never a float/decimal-as-money-over-the-wire-without-context. No silent rounding here:
// the caller already rounded explicitly when it produced minor units.
public readonly record struct Money(long MinorUnits, string Currency)
{
    public static Money Of(long minorUnits, string currency)
    {
        if (minorUnits < 0)
            throw new ArgumentOutOfRangeException(nameof(minorUnits), "Charge amount cannot be negative.");
        if (string.IsNullOrWhiteSpace(currency) || currency.Length != 3)
            throw new ArgumentException("Currency must be a 3-letter ISO-4217 code.", nameof(currency));
        return new Money(minorUnits, currency.ToUpperInvariant());
    }
}

public sealed record ChargeRequest(
    Money Amount,
    string CardToken,        // greybeard: trust boundary -- a vault token, never a raw PAN. Never logged.
    string IdempotencyKey);  // greybeard: rung 2 -- stable, caller-supplied, survives retries.

public enum ChargeStatus { Succeeded, Declined, Failed }

public sealed record ChargeResult(ChargeStatus Status, string? GatewayChargeId, string? DeclineReason);

public sealed class CardCharger
{
    private readonly HttpClient _http;
    private readonly ILogger<CardCharger> _log;

    // greybeard: rung 3 -- a circuit breaker shared across calls. Once the gateway is
    // failing hard, we stop hammering it and fail fast until it recovers.
    private readonly CircuitBreaker _breaker;

    private const int MaxAttempts = 3;
    private static readonly TimeSpan PerCallTimeout = TimeSpan.FromSeconds(5);

    public CardCharger(HttpClient http, ILogger<CardCharger> log, CircuitBreaker breaker)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        _log = log ?? throw new ArgumentNullException(nameof(log));
        _breaker = breaker ?? throw new ArgumentNullException(nameof(breaker));
    }

    public async Task<ChargeResult> ChargeAsync(ChargeRequest req, CancellationToken ct)
    {
        // greybeard: trust-boundary validation -- never trust input crossing into a money mutation.
        ArgumentNullException.ThrowIfNull(req);
        if (req.Amount.MinorUnits <= 0)
            throw new ArgumentException("Charge amount must be positive.", nameof(req));
        if (string.IsNullOrWhiteSpace(req.CardToken))
            throw new ArgumentException("Card token is required.", nameof(req));
        if (string.IsNullOrWhiteSpace(req.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required for a charge.", nameof(req));

        // greybeard: rung 3 -- circuit breaker. If open, fail fast; do not pile load on a sick gateway.
        if (!_breaker.AllowRequest())
        {
            _log.LogWarning("Charge short-circuited: gateway circuit is open. idemKey={IdempotencyKey}", req.IdempotencyKey);
            return new ChargeResult(ChargeStatus.Failed, null, "gateway_unavailable_circuit_open");
        }

        var wire = new GatewayChargeBody
        {
            // greybeard: rung 1 -- minor units + currency cross the wire together, no float anywhere.
            AmountMinor = req.Amount.MinorUnits,
            Currency = req.Amount.Currency,
            Source = req.CardToken,
        };

        Exception? lastTransient = null;

        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            ct.ThrowIfCancellationRequested();

            // greybeard: rung 3 -- ALWAYS a timeout. A hung gateway socket must not hang us forever.
            using var attemptCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            attemptCts.CancelAfter(PerCallTimeout);

            using var httpReq = new HttpRequestMessage(HttpMethod.Post, "charges")
            {
                Content = JsonContent.Create(wire),
            };
            // greybeard: rung 2 -- the idempotency key rides on EVERY attempt and every retry.
            // The gateway dedupes on it, so a retried/timed-out request produces exactly-once charge.
            httpReq.Headers.Add("Idempotency-Key", req.IdempotencyKey);

            try
            {
                using var resp = await _http.SendAsync(httpReq, HttpCompletionOption.ResponseHeadersRead, attemptCts.Token)
                    .ConfigureAwait(false);

                // 2xx -> definitive success. Charge happened exactly once (idem key guaranteed it).
                if (resp.IsSuccessStatusCode)
                {
                    var ok = await resp.Content.ReadFromJsonAsync<GatewayChargeResponse>(attemptCts.Token).ConfigureAwait(false);
                    _breaker.RecordSuccess();
                    // greybeard: rung 7 -- observable. We log the gateway charge id, the idem key, and
                    // attempt count. We NEVER log the card token, amount-as-secret, or response body raw.
                    _log.LogInformation(
                        "Charge succeeded. chargeId={ChargeId} idemKey={IdempotencyKey} attempt={Attempt}",
                        ok?.Id, req.IdempotencyKey, attempt);
                    return new ChargeResult(ChargeStatus.Succeeded, ok?.Id, null);
                }

                // greybeard: a decline (402) is a DEFINITIVE business answer, not a transient fault.
                // Retrying would not change it and could confuse the gateway -- stop here.
                if (resp.StatusCode == HttpStatusCode.PaymentRequired)
                {
                    var declined = await resp.Content.ReadFromJsonAsync<GatewayChargeResponse>(attemptCts.Token).ConfigureAwait(false);
                    _breaker.RecordSuccess(); // gateway is healthy; the *card* was declined.
                    _log.LogInformation(
                        "Charge declined. reason={Reason} idemKey={IdempotencyKey}",
                        declined?.DeclineCode ?? "unknown", req.IdempotencyKey);
                    return new ChargeResult(ChargeStatus.Declined, null, declined?.DeclineCode ?? "declined");
                }

                // 4xx (other than 402) -> our request is wrong. Retrying repeats the same mistake.
                if ((int)resp.StatusCode >= 400 && (int)resp.StatusCode < 500)
                {
                    _breaker.RecordSuccess(); // gateway responded fine; the bug is ours.
                    _log.LogError(
                        "Charge rejected by gateway as a client error. status={Status} idemKey={IdempotencyKey}",
                        (int)resp.StatusCode, req.IdempotencyKey);
                    return new ChargeResult(ChargeStatus.Failed, null, $"client_error_{(int)resp.StatusCode}");
                }

                // 5xx -> transient. Safe to retry BECAUSE the idempotency key makes it non-duplicating.
                _breaker.RecordFailure();
                lastTransient = new HttpRequestException($"Gateway returned {(int)resp.StatusCode}.");
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                throw; // caller cancelled -- honor it, don't swallow.
            }
            catch (OperationCanceledException) // our per-attempt timeout fired
            {
                _breaker.RecordFailure();
                lastTransient = new TimeoutException($"Charge attempt {attempt} timed out after {PerCallTimeout.TotalSeconds}s.");
                _log.LogWarning("Charge attempt timed out. idemKey={IdempotencyKey} attempt={Attempt}", req.IdempotencyKey, attempt);
            }
            catch (HttpRequestException ex) // connection-level transient
            {
                _breaker.RecordFailure();
                lastTransient = ex;
                // greybeard: no secrets in logs -- we log the exception message, not request content/headers.
                _log.LogWarning("Charge attempt failed transiently. idemKey={IdempotencyKey} attempt={Attempt} error={Error}",
                    req.IdempotencyKey, attempt, ex.Message);
            }

            // greybeard: rung 3 -- jittered exponential backoff between retries. Bounded, never the last attempt.
            if (attempt < MaxAttempts)
            {
                var backoff = JitteredBackoff(attempt);
                try
                {
                    await Task.Delay(backoff, ct).ConfigureAwait(false);
                }
                catch (OperationCanceledException) when (ct.IsCancellationRequested)
                {
                    throw;
                }
            }
        }

        // greybeard: exhausted retries on a TRANSIENT fault. We return Failed -- crucially NOT Declined.
        // The charge state is now genuinely UNKNOWN: it may or may not have landed at the gateway.
        // The caller must reconcile by querying the gateway with the SAME idempotency key before
        // ever re-charging. Returning a wrong "success" or a wrong "decline" here loses money.
        _log.LogError(lastTransient,
            "Charge unresolved after {Attempts} attempts -- state UNKNOWN, requires reconciliation. idemKey={IdempotencyKey}",
            MaxAttempts, req.IdempotencyKey);
        return new ChargeResult(ChargeStatus.Failed, null, "unresolved_requires_reconciliation");
    }

    private static TimeSpan JitteredBackoff(int attempt)
    {
        // base 200ms * 2^(attempt-1), plus full jitter, capped at 2s.
        var baseMs = Math.Min(200d * Math.Pow(2, attempt - 1), 2000d);
        var jittered = Random.Shared.NextDouble() * baseMs;
        return TimeSpan.FromMilliseconds(jittered);
    }
}

// --- wire contracts (kept minimal and explicit) ---

internal sealed class GatewayChargeBody
{
    [JsonPropertyName("amount_minor")] public long AmountMinor { get; init; }
    [JsonPropertyName("currency")] public string Currency { get; init; } = "";
    [JsonPropertyName("source")] public string Source { get; init; } = "";
}

internal sealed class GatewayChargeResponse
{
    [JsonPropertyName("id")] public string? Id { get; init; }
    [JsonPropertyName("decline_code")] public string? DeclineCode { get; init; }
}

// --- minimal circuit breaker (thread-safe, no external deps) ---

public sealed class CircuitBreaker
{
    private readonly int _failureThreshold;
    private readonly TimeSpan _openDuration;
    private readonly object _gate = new();

    private int _consecutiveFailures;
    private DateTimeOffset _openedUntil = DateTimeOffset.MinValue;

    public CircuitBreaker(int failureThreshold = 5, TimeSpan? openDuration = null)
    {
        _failureThreshold = failureThreshold;
        _openDuration = openDuration ?? TimeSpan.FromSeconds(30);
    }

    public bool AllowRequest()
    {
        lock (_gate)
        {
            if (_openedUntil > DateTimeOffset.UtcNow) return false; // open -> fail fast
            return true; // closed or half-open -> let one through
        }
    }

    public void RecordSuccess()
    {
        lock (_gate)
        {
            _consecutiveFailures = 0;
            _openedUntil = DateTimeOffset.MinValue;
        }
    }

    public void RecordFailure()
    {
        lock (_gate)
        {
            _consecutiveFailures++;
            if (_consecutiveFailures >= _failureThreshold)
                _openedUntil = DateTimeOffset.UtcNow.Add(_openDuration);
        }
    }
}

using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

// greybeard rungs that apply here:
//   1. Money?            -> amount is integer minor units + ISO currency; never float.
//   2. Mutation?         -> idempotency key sent to gateway so a retry never double-charges.
//   3. External call?    -> hard timeout always; jittered backoff retry; circuit breaker on repeated failure.
//   6. Fail half-way?    -> timeout/5xx => outcome UNKNOWN, not "failed". Caller must reconcile, never silently re-charge.
//   7. Minimum correct + observable.

namespace Payments;

// greybeard (rung 1): money is integer minor units (e.g. cents), currency travels with it. No float anywhere.
public readonly record struct Money(long MinorUnits, string CurrencyCode)
{
    public Money
    {
        if (MinorUnits < 0) throw new ArgumentOutOfRangeException(nameof(MinorUnits), "amount must be non-negative");
        if (string.IsNullOrWhiteSpace(CurrencyCode) || CurrencyCode.Length != 3)
            throw new ArgumentException("currency must be a 3-letter ISO 4217 code", nameof(CurrencyCode));
    }
}

public enum ChargeStatus
{
    Succeeded,
    Declined,
    // greybeard (rung 6): the gateway may have charged the card even though we never got a clean answer.
    // This is NOT "failed" — surfacing it as failure invites a double-charge on retry.
    Unknown
}

public sealed record ChargeResult(ChargeStatus Status, string? GatewayChargeId, string? DeclineReason);

public sealed class CardChargeService
{
    private readonly HttpClient _http;
    private readonly ILogger<CardChargeService> _log;

    // greybeard (rung 3): bounded retries + jittered backoff. Don't hammer a struggling gateway.
    private const int MaxAttempts = 3;
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(8);

    // greybeard (rung 3): minimal circuit breaker — after enough consecutive failures, fail fast
    // instead of piling load onto a downstream that is clearly down.
    private const int BreakerThreshold = 5;
    private static readonly TimeSpan BreakerCooldown = TimeSpan.FromSeconds(30);
    private int _consecutiveFailures;
    private long _breakerOpenUntilTicks; // UTC ticks; 0 = closed

    public CardChargeService(HttpClient http, ILogger<CardChargeService> log)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        _log = log ?? throw new ArgumentNullException(nameof(log));
    }

    /// <summary>
    /// Charges a card via the external gateway.
    /// </summary>
    /// <param name="amount">Money in integer minor units + ISO currency.</param>
    /// <param name="cardToken">A gateway card token — NEVER a raw PAN (PCI scope + secrets-in-logs).</param>
    /// <param name="idempotencyKey">
    /// Stable, caller-owned key for THIS logical charge (e.g. the order/payment-attempt id).
    /// Must be identical across retries so the gateway dedupes and never double-charges.
    /// </param>
    public async Task<ChargeResult> ChargeAsync(
        Money amount,
        string cardToken,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        // greybeard: validate at the trust boundary before any side effect.
        if (string.IsNullOrWhiteSpace(cardToken)) throw new ArgumentException("cardToken required", nameof(cardToken));
        if (string.IsNullOrWhiteSpace(idempotencyKey)) throw new ArgumentException("idempotencyKey required", nameof(idempotencyKey));

        // greybeard (rung 3): circuit breaker open => fail fast, treat as UNKNOWN (we did not even ask).
        if (Volatile.Read(ref _breakerOpenUntilTicks) > DateTime.UtcNow.Ticks)
        {
            _log.LogWarning("Charge skipped: circuit breaker open. idempotencyKey={IdempotencyKey}", idempotencyKey);
            return new ChargeResult(ChargeStatus.Unknown, null, "circuit_open");
        }

        var payload = new
        {
            amount_minor = amount.MinorUnits,   // greybeard (rung 1): integer minor units on the wire, never a decimal/float.
            currency = amount.CurrencyCode,
            source = cardToken
            // greybeard: idempotency key goes in the header below, not the body, per gateway contract.
        };

        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            // greybeard (rung 3): per-attempt hard timeout, ALWAYS. Linked so caller cancellation still wins.
            using var timeoutCts = new CancellationTokenSource(RequestTimeout);
            using var linkedCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, timeoutCts.Token);

            using var request = new HttpRequestMessage(HttpMethod.Post, "v1/charges")
            {
                Content = JsonContent.Create(payload)
            };
            // greybeard (rung 2): same idempotency key on every attempt => gateway collapses retries into one charge.
            request.Headers.Add("Idempotency-Key", idempotencyKey);

            try
            {
                using var response = await _http.SendAsync(request, linkedCts.Token).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    var ok = await response.Content
                        .ReadFromJsonAsync<GatewayChargeResponse>(linkedCts.Token).ConfigureAwait(false);

                    RecordSuccess();
                    // greybeard: log the gateway charge id, never the token/amount-as-secret. No PAN, no secrets.
                    _log.LogInformation("Charge succeeded. idempotencyKey={IdempotencyKey} chargeId={ChargeId}",
                        idempotencyKey, ok?.Id);
                    return new ChargeResult(ChargeStatus.Succeeded, ok?.Id, null);
                }

                // greybeard: a clean 4xx decline is a definitive answer — do NOT retry, do NOT mark UNKNOWN.
                if (response.StatusCode is HttpStatusCode.PaymentRequired or HttpStatusCode.UnprocessableEntity
                    || ((int)response.StatusCode is >= 400 and < 500 && response.StatusCode != HttpStatusCode.TooManyRequests))
                {
                    var declined = await response.Content
                        .ReadFromJsonAsync<GatewayChargeResponse>(linkedCts.Token).ConfigureAwait(false);
                    RecordSuccess(); // gateway answered cleanly; it is not "down".
                    _log.LogInformation("Charge declined. idempotencyKey={IdempotencyKey} reason={Reason}",
                        idempotencyKey, declined?.DeclineCode);
                    return new ChargeResult(ChargeStatus.Declined, null, declined?.DeclineCode ?? "declined");
                }

                // 429 / 5xx => transient. Retry (idempotency key keeps us safe).
                RecordFailure();
                _log.LogWarning("Charge transient gateway error {Status} on attempt {Attempt}. idempotencyKey={IdempotencyKey}",
                    (int)response.StatusCode, attempt, idempotencyKey);
            }
            catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException or OperationCanceledException
                                       && !cancellationToken.IsCancellationRequested)
            {
                // greybeard (rung 6): timeout / connection drop. The charge MIGHT have gone through.
                // Retrying is safe ONLY because of the idempotency key. After last attempt => UNKNOWN, never silent-fail.
                RecordFailure();
                _log.LogWarning(ex, "Charge attempt {Attempt} failed (network/timeout). idempotencyKey={IdempotencyKey}",
                    attempt, idempotencyKey);
            }

            if (attempt < MaxAttempts)
            {
                // greybeard (rung 3): exponential backoff with full jitter to avoid retry stampedes.
                var backoffMs = (int)(Math.Pow(2, attempt) * 100);
                var jitterMs = Random.Shared.Next(0, backoffMs);
                await Task.Delay(backoffMs + jitterMs, cancellationToken).ConfigureAwait(false);
            }
        }

        // greybeard (rung 6): exhausted retries without a definitive answer. The card may or may not be charged.
        // Return UNKNOWN so the caller reconciles against the gateway (by idempotency key) instead of re-charging blind.
        _log.LogError("Charge outcome UNKNOWN after {Attempts} attempts — needs reconciliation. idempotencyKey={IdempotencyKey}",
            MaxAttempts, idempotencyKey);
        return new ChargeResult(ChargeStatus.Unknown, null, "no_definitive_answer");
    }

    private void RecordSuccess()
    {
        Interlocked.Exchange(ref _consecutiveFailures, 0);
        Volatile.Write(ref _breakerOpenUntilTicks, 0);
    }

    private void RecordFailure()
    {
        if (Interlocked.Increment(ref _consecutiveFailures) >= BreakerThreshold)
        {
            Volatile.Write(ref _breakerOpenUntilTicks, DateTime.UtcNow.Add(BreakerCooldown).Ticks);
        }
    }

    // greybeard: only the fields we trust/need. Never deserialize secrets back into logs.
    private sealed record GatewayChargeResponse(string? Id, string? DeclineCode);
}

using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

// greybeard: rungs that apply here ->
//   1. Money?       charge amount is integer minor-units + currency code travels with it.
//   2. Mutation?    charging a card is a state mutation; caller-supplied idempotency key makes retries exactly-once.
//   3. External call? HTTP to the gateway: hard timeout, jittered backoff retry, circuit breaker on repeated failure.
//   7. Minimum correct code, observable: structured logs, no PAN/secrets in logs.
// Rungs 4 (concurrency), 5 (list), 6 (half-way saga) do not apply to a single synchronous charge -> skipped.

namespace Payments;

/// <summary>Amount carried as integer minor units (cents) with its currency. Never a float.</summary>
public readonly record struct Money(long MinorUnits, string Currency)
{
    // greybeard: rung 1 -- validate at the trust boundary; reject the nonsensical before it reaches the gateway.
    public void Validate()
    {
        if (MinorUnits <= 0)
            throw new ArgumentOutOfRangeException(nameof(MinorUnits), "Charge amount must be positive minor units.");
        if (string.IsNullOrWhiteSpace(Currency) || Currency.Length != 3)
            throw new ArgumentException("Currency must be a 3-letter ISO-4217 code.", nameof(Currency));
    }
}

public sealed record ChargeRequest(
    string CardToken,        // greybeard: a gateway token, NEVER a raw PAN. Raw card data never enters this process.
    Money Amount,
    string IdempotencyKey);  // greybeard: rung 2 -- caller owns this; same key => same charge, never a double-charge.

public enum ChargeOutcome { Succeeded, Declined, GatewayUnavailable }

public sealed record ChargeResult(ChargeOutcome Outcome, string? GatewayChargeId, string? DeclineReason);

/// <summary>Minimal circuit breaker: opens after N consecutive failures, half-opens after a cooldown.</summary>
public sealed class CircuitBreaker
{
    private readonly int _threshold;
    private readonly TimeSpan _cooldown;
    private int _consecutiveFailures;
    private DateTimeOffset _openedAt = DateTimeOffset.MinValue;
    private readonly object _gate = new();

    public CircuitBreaker(int threshold = 5, TimeSpan? cooldown = null)
    {
        _threshold = threshold;
        _cooldown = cooldown ?? TimeSpan.FromSeconds(30);
    }

    public bool IsOpen
    {
        get
        {
            lock (_gate)
            {
                if (_consecutiveFailures < _threshold) return false;
                // greybeard: rung 3 -- half-open after cooldown so we don't hammer a dying gateway, but we do recover.
                if (DateTimeOffset.UtcNow - _openedAt >= _cooldown)
                {
                    _consecutiveFailures = _threshold - 1; // allow one trial request.
                    return false;
                }
                return true;
            }
        }
    }

    public void RecordSuccess()
    {
        lock (_gate) { _consecutiveFailures = 0; }
    }

    public void RecordFailure()
    {
        lock (_gate)
        {
            _consecutiveFailures++;
            if (_consecutiveFailures >= _threshold) _openedAt = DateTimeOffset.UtcNow;
        }
    }
}

public sealed class PaymentGatewayClient
{
    private const int MaxAttempts = 3;
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(10);

    private readonly HttpClient _http;
    private readonly CircuitBreaker _breaker;
    private readonly ILogger<PaymentGatewayClient> _log;

    public PaymentGatewayClient(HttpClient http, CircuitBreaker breaker, ILogger<PaymentGatewayClient> log)
    {
        _http = http;
        _breaker = breaker;
        _log = log;
    }

    /// <summary>
    /// Charges a card via the external gateway. Safe to retry with the same IdempotencyKey.
    /// Returns a result for the expected outcomes (success/decline/unavailable);
    /// throws only on programmer error (invalid input).
    /// </summary>
    public async Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct = default)
    {
        // greybeard: rung 1 + trust boundary -- validate before we spend a network round-trip or a dollar.
        if (request is null) throw new ArgumentNullException(nameof(request));
        request.Amount.Validate();
        if (string.IsNullOrWhiteSpace(request.CardToken))
            throw new ArgumentException("CardToken is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("IdempotencyKey is required to make this charge retry-safe.", nameof(request));

        // greybeard: rung 3 -- if the breaker is open, fail fast. Don't queue work onto a gateway that's down.
        if (_breaker.IsOpen)
        {
            _log.LogWarning("Charge short-circuited; gateway circuit is open. idempotencyKey={Key}", request.IdempotencyKey);
            return new ChargeResult(ChargeOutcome.GatewayUnavailable, null, "circuit_open");
        }

        Exception? lastTransient = null;

        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            // greybeard: rung 3 -- per-attempt hard timeout, linked to the caller's cancellation. No unbounded hang.
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            timeoutCts.CancelAfter(RequestTimeout);

            try
            {
                using var httpRequest = new HttpRequestMessage(HttpMethod.Post, "/v1/charges")
                {
                    // greybeard: rung 2 -- the idempotency key rides as a header; the gateway dedupes the retry.
                    Content = JsonContent.Create(new
                    {
                        amount = request.Amount.MinorUnits,   // greybeard: rung 1 -- integer minor units on the wire.
                        currency = request.Amount.Currency,    // greybeard: rung 1 -- currency travels with the amount.
                        source = request.CardToken,
                    }),
                };
                httpRequest.Headers.Add("Idempotency-Key", request.IdempotencyKey);

                using var response = await _http.SendAsync(httpRequest, timeoutCts.Token).ConfigureAwait(false);

                // 2xx -> charge accepted by the gateway.
                if (response.IsSuccessStatusCode)
                {
                    _breaker.RecordSuccess();
                    var ok = await response.Content
                        .ReadFromJsonAsync<GatewayChargeResponse>(cancellationToken: ct)
                        .ConfigureAwait(false);
                    // greybeard: observability -- log the gateway charge id, never the card token or amount-in-the-clear secrets.
                    _log.LogInformation("Charge succeeded. chargeId={ChargeId} idempotencyKey={Key} attempt={Attempt}",
                        ok?.Id, request.IdempotencyKey, attempt);
                    return new ChargeResult(ChargeOutcome.Succeeded, ok?.Id, null);
                }

                // 402/422 -> a *business* decline (insufficient funds, etc.). Deterministic; retrying won't help.
                if (response.StatusCode is HttpStatusCode.PaymentRequired or HttpStatusCode.UnprocessableEntity)
                {
                    _breaker.RecordSuccess(); // the gateway is healthy; it just said no.
                    var declined = await response.Content
                        .ReadFromJsonAsync<GatewayChargeResponse>(cancellationToken: ct)
                        .ConfigureAwait(false);
                    _log.LogInformation("Charge declined. reason={Reason} idempotencyKey={Key}",
                        declined?.DeclineCode, request.IdempotencyKey);
                    return new ChargeResult(ChargeOutcome.Declined, null, declined?.DeclineCode ?? "declined");
                }

                // 4xx (other than the above) -> our request is malformed; retrying is pointless and hides bugs.
                if ((int)response.StatusCode is >= 400 and < 500)
                {
                    _breaker.RecordSuccess();
                    _log.LogError("Charge rejected by gateway as a client error. status={Status} idempotencyKey={Key}",
                        (int)response.StatusCode, request.IdempotencyKey);
                    return new ChargeResult(ChargeOutcome.GatewayUnavailable, null, $"client_error_{(int)response.StatusCode}");
                }

                // 5xx / 429 -> transient; fall through to retry.
                _breaker.RecordFailure();
                lastTransient = new HttpRequestException($"Gateway returned {(int)response.StatusCode}.");
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                throw; // caller asked to cancel -- honor it, don't swallow.
            }
            catch (OperationCanceledException)
            {
                // greybeard: rung 3 -- our own timeout fired. Transient: the charge may or may not have landed,
                // but the SAME idempotency key on the next attempt makes a retry safe (no double-charge).
                _breaker.RecordFailure();
                lastTransient = new TimeoutException($"Gateway timed out after {RequestTimeout.TotalSeconds}s.");
            }
            catch (HttpRequestException ex)
            {
                _breaker.RecordFailure();
                lastTransient = ex; // connection reset, DNS, etc. -- transient.
            }

            if (attempt < MaxAttempts)
            {
                // greybeard: rung 3 -- exponential backoff with full jitter; avoids retry storms / thundering herd.
                var backoffMs = (int)(Math.Pow(2, attempt) * 100);
                var jitterMs = Random.Shared.Next(0, backoffMs);
                _log.LogWarning("Charge attempt {Attempt} failed transiently; retrying. idempotencyKey={Key}",
                    attempt, request.IdempotencyKey);
                await Task.Delay(backoffMs + jitterMs, ct).ConfigureAwait(false);
            }
        }

        // greybeard: exhausted retries. We DO NOT know if the money moved. Return Unavailable so the caller
        // can reconcile (re-query the gateway by idempotency key) rather than assuming failure and re-charging blindly.
        _log.LogError(lastTransient,
            "Charge failed after {Attempts} attempts; outcome unknown -- reconciliation required. idempotencyKey={Key}",
            MaxAttempts, request.IdempotencyKey);
        return new ChargeResult(ChargeOutcome.GatewayUnavailable, null, "gateway_unavailable");
    }

    private sealed record GatewayChargeResponse(
        [property: JsonPropertyName("id")] string Id,
        [property: JsonPropertyName("decline_code")] string? DeclineCode);
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

// greybeard ladder applied to "decrement stock when an order is placed":
//   Rung 2 (Mutation)     -> idempotency key on the order so a retried request never double-decrements.
//   Rung 4 (Concurrency)  -> explicit transaction + optimistic concurrency token (RowVersion) so two
//                            simultaneous orders on the same product row can't lose an update / oversell.
//   Rung 6 (Half-way)     -> conditional UPDATE + retry loop; on insufficient stock we fail cleanly with a
//                            domain result, no partial mutation left behind.
//   Rung 1 (Money) n/a    -> stock is a count, modeled as an integer (units), never a float regardless.
//   Rung 3 (External) n/a -> no external call here.
//   Rung 5 (List) n/a     -> single-row write, no unbounded read.

namespace Inventory
{
    // --- Domain model -------------------------------------------------------

    public class Product
    {
        public Guid Id { get; set; }

        // greybeard: stock is a discrete count of units -> integer, never float. Cannot go negative.
        public int StockUnits { get; set; }

        // greybeard (Rung 4): optimistic concurrency token. EF Core throws DbUpdateConcurrencyException
        // if another transaction changed this row between our read and write -> no lost updates / oversell.
        public byte[] RowVersion { get; set; } = Array.Empty<byte>();
    }

    // greybeard (Rung 2): records that a given order has already consumed stock. The unique OrderId is the
    // idempotency key; the unique index makes a duplicate insert fail rather than decrement a second time.
    public class StockReservation
    {
        public Guid Id { get; set; }
        public Guid OrderId { get; set; }
        public Guid ProductId { get; set; }
        public int Units { get; set; }
        public DateTimeOffset CreatedAtUtc { get; set; }
    }

    public class InventoryDbContext : DbContext
    {
        public InventoryDbContext(DbContextOptions<InventoryDbContext> options) : base(options) { }

        public DbSet<Product> Products => Set<Product>();
        public DbSet<StockReservation> StockReservations => Set<StockReservation>();

        protected override void OnModelCreating(ModelBuilder b)
        {
            b.Entity<Product>(e =>
            {
                e.HasKey(p => p.Id);
                // greybeard (Rung 4): mark RowVersion as the concurrency token.
                e.Property(p => p.RowVersion).IsRowVersion();
            });

            b.Entity<StockReservation>(e =>
            {
                e.HasKey(r => r.Id);
                // greybeard (Rung 2): enforce exactly-once at the database level, not just in app code.
                e.HasIndex(r => r.OrderId).IsUnique();
            });
        }
    }

    // --- Result type: partial failure is a first-class return value, not an exception to swallow ---

    public enum DecrementOutcome
    {
        Decremented,        // we consumed stock this call
        AlreadyApplied,     // idempotent replay -> stock already consumed for this order, no-op
        InsufficientStock   // not enough units -> caller must not fulfill the order
    }

    public readonly record struct DecrementResult(DecrementOutcome Outcome, int RemainingUnits);

    // --- The operation ------------------------------------------------------

    public class StockService
    {
        private readonly InventoryDbContext _db;
        private const int MaxConcurrencyRetries = 3;

        public StockService(InventoryDbContext db) => _db = db;

        /// <summary>
        /// Decrements <paramref name="units"/> of <paramref name="productId"/> on behalf of
        /// <paramref name="orderId"/>. Safe to call more than once for the same order: the effect is
        /// exactly-once even under at-least-once delivery (retried request, redelivered message).
        /// </summary>
        public async Task<DecrementResult> DecrementForOrderAsync(
            Guid orderId,
            Guid productId,
            int units,
            CancellationToken ct = default)
        {
            // greybeard: validate input crossing the boundary before it touches the database.
            if (orderId == Guid.Empty) throw new ArgumentException("orderId required.", nameof(orderId));
            if (productId == Guid.Empty) throw new ArgumentException("productId required.", nameof(productId));
            if (units <= 0) throw new ArgumentOutOfRangeException(nameof(units), "Units must be positive.");

            // greybeard (Rung 4): retry the whole transaction on a concurrency clash. Each retry re-reads
            // the current RowVersion, so we converge instead of clobbering a concurrent decrement.
            for (var attempt = 1; ; attempt++)
            {
                try
                {
                    return await TryDecrementOnceAsync(orderId, productId, units, ct);
                }
                catch (DbUpdateConcurrencyException) when (attempt < MaxConcurrencyRetries)
                {
                    // Another order mutated the row first. Detach stale entities and retry with fresh data.
                    _db.ChangeTracker.Clear();
                }
            }
        }

        private async Task<DecrementResult> TryDecrementOnceAsync(
            Guid orderId, Guid productId, int units, CancellationToken ct)
        {
            // greybeard (Rung 4): explicit transaction boundary so the reservation insert and the stock
            // decrement commit together or not at all -- no half-applied state.
            await using var tx = await _db.Database.BeginTransactionAsync(ct);

            // greybeard (Rung 2): idempotency check. If this order already reserved stock, this is a replay;
            // return without touching the count. Reads inside the transaction for a consistent snapshot.
            var alreadyReserved = await _db.StockReservations
                .AsNoTracking()
                .AnyAsync(r => r.OrderId == orderId, ct);

            if (alreadyReserved)
            {
                var current = await _db.Products
                    .AsNoTracking()
                    .Where(p => p.Id == productId)
                    .Select(p => (int?)p.StockUnits)
                    .SingleOrDefaultAsync(ct);

                await tx.CommitAsync(ct);
                return new DecrementResult(DecrementOutcome.AlreadyApplied, current ?? 0);
            }

            var product = await _db.Products.SingleOrDefaultAsync(p => p.Id == productId, ct)
                ?? throw new InvalidOperationException($"Product {productId} not found.");

            // greybeard (Rung 6): insufficient stock is an expected outcome, not a crash. Roll back so no
            // reservation row leaks, and tell the caller the order cannot be fulfilled.
            if (product.StockUnits < units)
            {
                await tx.RollbackAsync(ct);
                return new DecrementResult(DecrementOutcome.InsufficientStock, product.StockUnits);
            }

            product.StockUnits -= units; // integer math, guarded above -> never negative.

            _db.StockReservations.Add(new StockReservation
            {
                Id = Guid.NewGuid(),
                OrderId = orderId,
                ProductId = productId,
                Units = units,
                CreatedAtUtc = DateTimeOffset.UtcNow
            });

            try
            {
                // greybeard (Rung 4): SaveChanges checks RowVersion. A concurrent decrement bumps the token
                // and forces DbUpdateConcurrencyException -> caught and retried by the caller above.
                await _db.SaveChangesAsync(ct);
            }
            catch (DbUpdateException ex) when (IsUniqueViolation(ex))
            {
                // greybeard (Rung 2): two concurrent calls for the *same* order raced past the idempotency
                // check; the unique index on OrderId rejected the second insert. Treat as already-applied.
                await tx.RollbackAsync(ct);
                _db.ChangeTracker.Clear();
                var remaining = await _db.Products
                    .AsNoTracking()
                    .Where(p => p.Id == productId)
                    .Select(p => p.StockUnits)
                    .SingleAsync(ct);
                return new DecrementResult(DecrementOutcome.AlreadyApplied, remaining);
            }

            await tx.CommitAsync(ct);

            // greybeard (Rung 7): observable -- caller logs outcome + remaining at INFO. No secrets here:
            // only ids and counts cross the log boundary, never tokens or PII.
            return new DecrementResult(DecrementOutcome.Decremented, product.StockUnits);
        }

        // Provider-agnostic-ish unique-violation detection. Replace the SQLSTATE/error-number check with
        // your provider's (e.g. Npgsql 23505, SqlException 2601/2627) for precision.
        private static bool IsUniqueViolation(DbUpdateException ex)
        {
            var msg = ex.InnerException?.Message ?? ex.Message;
            return msg.Contains("unique", StringComparison.OrdinalIgnoreCase)
                || msg.Contains("duplicate", StringComparison.OrdinalIgnoreCase);
        }
    }
}

// 3am re-read: "What still breaks?"
//  - Oversell under concurrency? No -> RowVersion token + transaction; a lost update throws and we retry.
//  - Retried/redelivered order double-decrements? No -> idempotency key (OrderId) + unique index, even
//    under a same-order race (handled via the unique-violation branch).
//  - Negative stock? No -> guarded integer subtraction; insufficient stock returns cleanly, no mutation.
//  - Partial write on failure? No -> single transaction commits both rows or neither.
//  - Float drift on the count? N/A -> integer units throughout.
//  Flagged for the operator: IsUniqueViolation uses string matching; swap in your provider's error code.
//  Flagged: retries are bounded at 3 -- under pathological contention the call surfaces the concurrency
//  exception to the caller rather than spinning forever (intentional: fail loud, let upstream back off).

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace Inventory;

// greybeard ladder applied to "decrement stock on order placed":
//   1. Money?            -> N/A. We move integer *units* of stock, not currency. (no float anywhere)
//   2. Mutation?         -> YES. This is a state mutation triggered by an order. Idempotent on OrderId
//                           so a retried request / duplicate webhook does not double-decrement.
//   3. External call?    -> N/A. Pure DB work.
//   4. Concurrency?      -> YES. Two orders racing for the last unit must not oversell. Optimistic
//                           concurrency via [Timestamp]/RowVersion + bounded retry, all inside one tx.
//   5. Reads a list?     -> Bounded: we read only the exact products in this order, in one batched query (no N+1).
//   6. Can it fail half-way? -> YES. A multi-line order is all-or-nothing. One transaction; any
//                           insufficient-stock line aborts the whole decrement. No partial commit.
//   7. Minimum correct code, made observable.

public sealed class InsufficientStockException : Exception
{
    public int ProductId { get; }
    public int Requested { get; }
    public int Available { get; }

    public InsufficientStockException(int productId, int requested, int available)
        : base($"Insufficient stock for product {productId}: requested {requested}, available {available}.")
    {
        ProductId = productId;
        Requested = requested;
        Available = available;
    }
}

public sealed record OrderLine(int ProductId, int Quantity);

public sealed class StockService
{
    private readonly InventoryDbContext _db;
    private readonly ILogger<StockService> _logger;

    // greybeard: small bounded retry budget for the optimistic-concurrency race. Never unbounded.
    private const int MaxConcurrencyRetries = 3;

    public StockService(InventoryDbContext db, ILogger<StockService> logger)
    {
        _db = db;
        _logger = logger;
    }

    /// <summary>
    /// Decrements product stock for the given order. Atomic across all lines, idempotent per orderId,
    /// and safe against concurrent orders competing for the same stock.
    /// </summary>
    public async Task DecrementStockForOrderAsync(
        Guid orderId,
        IReadOnlyCollection<OrderLine> lines,
        CancellationToken ct = default)
    {
        // greybeard: trust-boundary validation. Reject malformed input before touching any row.
        if (orderId == Guid.Empty)
            throw new ArgumentException("orderId is required.", nameof(orderId));
        if (lines is null || lines.Count == 0)
            throw new ArgumentException("Order must contain at least one line.", nameof(lines));
        foreach (var line in lines)
        {
            if (line.Quantity <= 0)
                throw new ArgumentException(
                    $"Quantity for product {line.ProductId} must be positive (got {line.Quantity}).",
                    nameof(lines));
        }

        // greybeard: coalesce duplicate product lines so we lock/decrement each row exactly once.
        // Integer units only — no float math anywhere in stock accounting.
        var requested = lines
            .GroupBy(l => l.ProductId)
            .ToDictionary(g => g.Key, g => g.Sum(l => (long)l.Quantity));

        for (var attempt = 1; ; attempt++)
        {
            try
            {
                await TryDecrementOnceAsync(orderId, requested, ct).ConfigureAwait(false);
                return;
            }
            catch (DbUpdateConcurrencyException) when (attempt < MaxConcurrencyRetries)
            {
                // greybeard: lost-update guard fired — another order changed a row first.
                // Reset tracked state and re-read fresh stock, then retry within budget.
                _logger.LogWarning(
                    "Stock decrement for order {OrderId} hit a concurrency conflict (attempt {Attempt}/{Max}); retrying.",
                    orderId, attempt, MaxConcurrencyRetries);

                foreach (var entry in _db.ChangeTracker.Entries().ToList())
                    entry.State = EntityState.Detached;
            }
        }
    }

    private async Task TryDecrementOnceAsync(
        Guid orderId,
        IReadOnlyDictionary<int, long> requested,
        CancellationToken ct)
    {
        // greybeard: explicit transaction boundary — the whole order's decrement commits or none of it does.
        await using var tx = await _db.Database
            .BeginTransactionAsync(System.Data.IsolationLevel.ReadCommitted, ct)
            .ConfigureAwait(false);

        // greybeard: idempotency. If we already recorded this order's reservation, this call is a
        // retry/duplicate — do nothing and return success. Exactly-once effect, at-least-once delivery.
        var alreadyApplied = await _db.StockReservations
            .AsNoTracking()
            .AnyAsync(r => r.OrderId == orderId, ct)
            .ConfigureAwait(false);
        if (alreadyApplied)
        {
            _logger.LogInformation("Order {OrderId} stock already decremented; treating as idempotent no-op.", orderId);
            await tx.CommitAsync(ct).ConfigureAwait(false);
            return;
        }

        // greybeard: bounded batched read — only the products in THIS order, one round trip, no N+1.
        var productIds = requested.Keys.ToArray();
        var products = await _db.Products
            .Where(p => productIds.Contains(p.Id))
            .ToDictionaryAsync(p => p.Id, ct)
            .ConfigureAwait(false);

        // greybeard: fail-closed on unknown product — never silently skip a line.
        foreach (var id in productIds)
        {
            if (!products.ContainsKey(id))
                throw new KeyNotFoundException($"Product {id} does not exist.");
        }

        // greybeard: validate sufficiency for EVERY line before mutating any, so a partial order
        // never half-commits. Stock is an integer; check is exact, no rounding.
        foreach (var (productId, qty) in requested)
        {
            var product = products[productId];
            if (product.StockOnHand < qty)
                throw new InsufficientStockException(productId, checked((int)qty), product.StockOnHand);
        }

        foreach (var (productId, qty) in requested)
            products[productId].StockOnHand -= checked((int)qty);

        // greybeard: the reservation row IS the idempotency record AND the recovery breadcrumb.
        // A unique constraint on OrderId is the last line of defense if two retries race past the read.
        _db.StockReservations.Add(new StockReservation
        {
            OrderId = orderId,
            CreatedAtUtc = DateTime.UtcNow,
        });

        // greybeard: SaveChanges enforces RowVersion optimistic concurrency; a stale row throws
        // DbUpdateConcurrencyException and is retried by the caller. No lost updates, no oversell.
        await _db.SaveChangesAsync(ct).ConfigureAwait(false);
        await tx.CommitAsync(ct).ConfigureAwait(false);

        _logger.LogInformation(
            "Decremented stock for order {OrderId} across {LineCount} product(s).",
            orderId, requested.Count);
    }
}

public sealed class Product
{
    public int Id { get; set; }

    // greybeard: integer units. Stock is never a floating-point quantity.
    public int StockOnHand { get; set; }

    // greybeard: optimistic-concurrency token. EF bumps/checks this on every UPDATE -> lost-update safe.
    [Microsoft.EntityFrameworkCore.Timestamp]
    public byte[] RowVersion { get; set; } = Array.Empty<byte>();
}

// greybeard: idempotency + audit record. Unique index on OrderId makes double-application impossible
// even under a perfect race; also serves as the recovery trail for reconciliation.
public sealed class StockReservation
{
    public long Id { get; set; }
    public Guid OrderId { get; set; }
    public DateTime CreatedAtUtc { get; set; }
}

public class InventoryDbContext : DbContext
{
    public InventoryDbContext(DbContextOptions<InventoryDbContext> options) : base(options) { }

    public DbSet<Product> Products => Set<Product>();
    public DbSet<StockReservation> StockReservations => Set<StockReservation>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // greybeard: enforce idempotency at the database, not just in app logic.
        modelBuilder.Entity<StockReservation>()
            .HasIndex(r => r.OrderId)
            .IsUnique();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

// greybeard ladder for "decrement stock when an order is placed":
//   1. Money?      -> no money moves here (stock counts are integers already; pricing lives elsewhere). Skip.
//   2. Mutation?   -> YES. Placing an order is a state mutation that will be retried (network blips, at-least-once
//                     queues, double-clicks). We take an idempotency key and make the effect exactly-once.
//   3. External?   -> no outbound call in this method. Skip.
//   4. Concurrency?-> YES. Two orders can hit the same product row at once -> lost update / overselling.
//                     We guard with a conditional UPDATE (atomic compare-and-decrement) so the database, not the
//                     app, enforces "never go below zero". Optimistic concurrency token catches concurrent writes.
//   5. Reads list? -> we read N order lines (bounded by the order itself). We batch-load to avoid N+1.
//   6. Half-way?   -> YES. If line 3 of 5 oversells, the whole order must fail and nothing is decremented.
//                     One transaction = all-or-nothing. No compensating saga needed because it is one local DB.
//   7. Minimum correct code, observable (structured logs, no secrets, no PII).

namespace Inventory
{
    public sealed class OrderLine
    {
        public Guid ProductId { get; init; }
        public int Quantity { get; init; }
    }

    public sealed class Product
    {
        public Guid Id { get; set; }
        public int StockOnHand { get; set; }

        // greybeard (rung 4): optimistic-concurrency token. EF maps this as [Timestamp]/rowversion so two
        // concurrent decrements on the same row cannot silently clobber each other -> DbUpdateConcurrencyException.
        public byte[] RowVersion { get; set; } = Array.Empty<byte>();
    }

    /// <summary>
    /// Records that we have already processed a given idempotency key, so a retried order placement is a no-op.
    /// greybeard (rung 2): exactly-once effect, at-least-once delivery. Unique index on IdempotencyKey.
    /// </summary>
    public sealed class ProcessedOrder
    {
        public long Id { get; set; }
        public string IdempotencyKey { get; set; } = string.Empty;
        public Guid OrderId { get; set; }
        public DateTimeOffset ProcessedAtUtc { get; set; }
    }

    public sealed class InventoryDbContext : DbContext
    {
        public InventoryDbContext(DbContextOptions<InventoryDbContext> options) : base(options) { }

        public DbSet<Product> Products => Set<Product>();
        public DbSet<ProcessedOrder> ProcessedOrders => Set<ProcessedOrder>();

        protected override void OnModelCreating(ModelBuilder b)
        {
            b.Entity<Product>(e =>
            {
                e.HasKey(p => p.Id);
                // greybeard (rung 4): rowversion concurrency token.
                e.Property(p => p.RowVersion).IsRowVersion();
                // greybeard (rung 4): DB-level invariant so overselling is impossible even outside this method.
                e.ToTable(t => t.HasCheckConstraint("ck_products_stock_nonneg", "[StockOnHand] >= 0"));
            });

            b.Entity<ProcessedOrder>(e =>
            {
                e.HasKey(p => p.Id);
                // greybeard (rung 2): unique idempotency key -> the dedupe is enforced by the database,
                // not by a check-then-act race in application code.
                e.HasIndex(p => p.IdempotencyKey).IsUnique();
                e.Property(p => p.IdempotencyKey).HasMaxLength(200).IsRequired();
            });
        }
    }

    public enum DecrementOutcome
    {
        /// <summary>Stock decremented and order recorded for the first time.</summary>
        Applied,
        /// <summary>This idempotency key was already processed; this call was a safe no-op.</summary>
        AlreadyProcessed,
    }

    public sealed class InsufficientStockException : Exception
    {
        public Guid ProductId { get; }
        public int Requested { get; }
        public int Available { get; }

        public InsufficientStockException(Guid productId, int requested, int available)
            : base($"Insufficient stock for product {productId}: requested {requested}, available {available}.")
        {
            ProductId = productId;
            Requested = requested;
            Available = available;
        }
    }

    public sealed class InventoryService
    {
        private readonly InventoryDbContext _db;
        private readonly ILogger<InventoryService> _log;

        public InventoryService(InventoryDbContext db, ILogger<InventoryService> log)
        {
            _db = db ?? throw new ArgumentNullException(nameof(db));
            _log = log ?? throw new ArgumentNullException(nameof(log));
        }

        /// <summary>
        /// Decrements stock for every line of an order, atomically. Either every line is decremented or none is.
        /// Safe to call more than once with the same <paramref name="idempotencyKey"/>.
        /// </summary>
        /// <param name="orderId">The order being placed (for traceability).</param>
        /// <param name="lines">The order lines. Each (ProductId, Quantity) is validated and aggregated.</param>
        /// <param name="idempotencyKey">Stable per-order key so retried placements do not double-decrement.</param>
        public async Task<DecrementOutcome> DecrementStockForOrderAsync(
            Guid orderId,
            IReadOnlyCollection<OrderLine> lines,
            string idempotencyKey,
            CancellationToken ct = default)
        {
            // greybeard (trust boundary): validate everything crossing in. Do not trust the caller's happy path.
            if (orderId == Guid.Empty)
                throw new ArgumentException("orderId is required.", nameof(orderId));
            if (string.IsNullOrWhiteSpace(idempotencyKey))
                throw new ArgumentException("idempotencyKey is required.", nameof(idempotencyKey));
            if (lines is null || lines.Count == 0)
                throw new ArgumentException("Order must contain at least one line.", nameof(lines));

            // greybeard (rung 4/6): collapse duplicate product lines and reject non-positive quantities up front,
            // so the same product is decremented exactly once and we never "decrement by zero/negative".
            var demand = new Dictionary<Guid, int>();
            foreach (var line in lines)
            {
                if (line.ProductId == Guid.Empty)
                    throw new ArgumentException("Order line has empty ProductId.", nameof(lines));
                if (line.Quantity <= 0)
                    throw new ArgumentException(
                        $"Order line quantity must be positive (product {line.ProductId}).", nameof(lines));

                demand[line.ProductId] = demand.TryGetValue(line.ProductId, out var q)
                    ? checked(q + line.Quantity) // greybeard: checked -> overflow on a hostile/huge order surfaces, not wraps.
                    : line.Quantity;
            }

            // greybeard (rung 2): short-circuit known-processed keys before opening a transaction. This is a fast path;
            // the authoritative dedupe is the unique-index insert inside the transaction below (handles the race).
            var seen = await _db.ProcessedOrders
                .AsNoTracking()
                .AnyAsync(p => p.IdempotencyKey == idempotencyKey, ct);
            if (seen)
            {
                _log.LogInformation(
                    "Order {OrderId} idempotency key already processed; no-op. (KeyHash {KeyHash})",
                    orderId, HashForLog(idempotencyKey)); // greybeard (no secrets): log a hash, not the raw key.
                return DecrementOutcome.AlreadyProcessed;
            }

            // greybeard (rung 6): one transaction = all-or-nothing. A half-decremented order is never observable.
            await using var tx = await _db.Database.BeginTransactionAsync(
                System.Data.IsolationLevel.ReadCommitted, ct);

            try
            {
                // greybeard (rung 5/N+1): batch-load all needed products in one query, then process in a stable order.
                var productIds = demand.Keys.ToArray();
                var products = await _db.Products
                    .Where(p => productIds.Contains(p.Id))
                    .ToDictionaryAsync(p => p.Id, ct);

                // greybeard (trust boundary): a referenced product that does not exist is a hard error, not a skip.
                foreach (var id in productIds)
                {
                    if (!products.ContainsKey(id))
                        throw new InvalidOperationException($"Product {id} not found.");
                }

                // greybeard (rung 4): process in deterministic ProductId order to avoid deadlocks under concurrency
                // (all callers acquire row locks in the same sequence).
                foreach (var id in productIds.OrderBy(x => x))
                {
                    var qty = demand[id];
                    var product = products[id];

                    // greybeard (rung 4): atomic compare-and-decrement at the database. We do NOT read-modify-write
                    // in memory (that is the classic lost-update / oversell). The WHERE clause makes the DB reject
                    // the update if stock would go negative; affected-rows == 0 means lose-the-race or not-enough.
                    var affected = await _db.Products
                        .Where(p => p.Id == id && p.StockOnHand >= qty)
                        .ExecuteUpdateAsync(
                            s => s.SetProperty(p => p.StockOnHand, p => p.StockOnHand - qty),
                            ct);

                    if (affected == 0)
                    {
                        // Re-read the live value purely for an honest error message; the transaction will roll back.
                        var available = await _db.Products
                            .Where(p => p.Id == id)
                            .Select(p => p.StockOnHand)
                            .SingleAsync(ct);

                        _log.LogWarning(
                            "Order {OrderId} rejected: insufficient stock for product {ProductId} " +
                            "(requested {Requested}, available {Available}).",
                            orderId, id, qty, available);

                        // greybeard (rung 6): throwing rolls back every prior decrement in this order. No partial commit.
                        throw new InsufficientStockException(id, qty, available);
                    }
                }

                // greybeard (rung 2): record the idempotency key INSIDE the transaction. The unique index turns a
                // concurrent duplicate placement into a DbUpdateException -> we treat it as AlreadyProcessed, so the
                // effect is exactly-once even when two retries race past the fast-path check above.
                _db.ProcessedOrders.Add(new ProcessedOrder
                {
                    IdempotencyKey = idempotencyKey,
                    OrderId = orderId,
                    ProcessedAtUtc = DateTimeOffset.UtcNow,
                });

                await _db.SaveChangesAsync(ct);
                await tx.CommitAsync(ct);

                _log.LogInformation(
                    "Order {OrderId} decremented stock for {LineCount} product(s).",
                    orderId, productIds.Length);

                return DecrementOutcome.Applied;
            }
            catch (DbUpdateException ex) when (IsUniqueKeyViolation(ex))
            {
                // greybeard (rung 2): lost the idempotency race to a concurrent identical placement.
                // The other transaction already applied the decrement; ours rolls back. Net effect: exactly-once.
                await tx.RollbackAsync(CancellationToken.None);
                _log.LogInformation(
                    "Order {OrderId} idempotency key won by a concurrent request; treating as already processed.",
                    orderId);
                return DecrementOutcome.AlreadyProcessed;
            }
            catch
            {
                // greybeard (data-loss safety): any failure rolls the whole order back. The DB returns to its prior
                // state and the caller may safely retry with the same idempotency key.
                await tx.RollbackAsync(CancellationToken.None);
                throw;
            }
        }

        // greybeard (no secrets in logs): never log the raw idempotency key; emit a short, non-reversible fingerprint.
        private static string HashForLog(string value)
        {
            var bytes = System.Security.Cryptography.SHA256.HashData(
                System.Text.Encoding.UTF8.GetBytes(value));
            return Convert.ToHexString(bytes, 0, 4); // first 4 bytes is enough to correlate, not enough to reconstruct.
        }

        // greybeard: provider-agnostic-ish detection of unique-constraint violation. In real code, narrow this to your
        // provider's error number (e.g. SqlException 2601/2627, Postgres 23505) rather than string-sniffing.
        private static bool IsUniqueKeyViolation(DbUpdateException ex)
        {
            var msg = ex.InnerException?.Message ?? ex.Message;
            return msg.Contains("unique", StringComparison.OrdinalIgnoreCase)
                || msg.Contains("duplicate", StringComparison.OrdinalIgnoreCase);
        }
    }
}

// greybeard re-read at 3am — "what still breaks?":
//  - Oversell under load: prevented. The atomic `WHERE StockOnHand >= qty` + check constraint makes negative stock
//    unrepresentable; the app cannot win a TOCTOU race it never performs.
//  - Double-charge / double-decrement on retry: prevented. Idempotency key is inserted in the same transaction,
//    guarded by a unique index; concurrent duplicates resolve to AlreadyProcessed.
//  - Partial order: prevented. Single transaction; any failing line rolls back all prior lines.
//  - Deadlocks: mitigated by touching rows in sorted ProductId order.
//  - Secrets/PII in logs: idempotency key is hashed; no amounts or customer data logged.
//  - Cancellation: ct threaded through; rollback on the failure path uses CancellationToken.None so cleanup is not
//    itself cancelled mid-flight.
//  Open flags for the reviewer: IsUniqueKeyViolation should be tightened to the concrete DB provider's error code.

using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

// greybeard: rungs that apply -> 1 (money), 2 (mutation/idempotency), 3 (external call),
//            6 (half-way failure: charge may succeed at the bank but the response never reaches us).
//            Rungs 4 (concurrency) and 5 (list) do not apply here, skipped silently.

namespace Payments;

// greybeard: rung 1 -> money is an integer minor-units amount with its currency code attached.
//            No float anywhere near a balance.
public readonly record struct Money(long MinorUnits, string CurrencyCode)
{
    public override string ToString() => $"{MinorUnits} {CurrencyCode}"; // safe to log: no PAN here.
}

public enum ChargeOutcome
{
    Succeeded,
    Declined,    // definitive: bank said no. Safe to surface.
    Failed,      // definitive: our side / validation. No charge happened.
    Unknown      // greybeard: rung 6 -> we never learned the outcome. Money may have moved. Do NOT retry blindly.
}

public sealed record ChargeRequest(
    Money Amount,
    string PaymentMethodToken, // a vault token, never a raw PAN/CVV crossing this boundary.
    string IdempotencyKey);    // greybeard: rung 2 -> caller-supplied; identical key == identical charge.

public sealed record ChargeResult(
    ChargeOutcome Outcome,
    string? ProcessorChargeId,
    string? DeclineReason);

public interface ICardProcessor
{
    // Implementation is expected to forward the idempotency key to the upstream gateway.
    Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct);
}

public sealed class CardCharger
{
    private const int MaxAttempts = 3;
    private static readonly TimeSpan PerCallTimeout = TimeSpan.FromSeconds(8);

    private readonly ICardProcessor _processor;
    private readonly ILogger<CardCharger> _log;

    public CardCharger(ICardProcessor processor, ILogger<CardCharger> log)
    {
        _processor = processor ?? throw new ArgumentNullException(nameof(processor));
        _log = log ?? throw new ArgumentNullException(nameof(log));
    }

    public async Task<ChargeResult> ChargeCardAsync(ChargeRequest request, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(request);

        // greybeard: trust-boundary validation -> reject garbage before we touch the network.
        if (request.Amount.MinorUnits <= 0)
            throw new ArgumentException("Amount must be positive minor-units.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.Amount.CurrencyCode) || request.Amount.CurrencyCode.Length != 3)
            throw new ArgumentException("Currency must be an ISO-4217 3-letter code.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.PaymentMethodToken))
            throw new ArgumentException("Payment method token is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required.", nameof(request));

        // greybeard: no secrets in logs -> we log the idempotency key + amount, never the token, PAN, or CVV.
        //            IdempotencyKey is structured so failures are searchable later.
        using var scope = _log.BeginScope(new Dictionary<string, object>
        {
            ["idempotency_key"] = request.IdempotencyKey,
            ["amount"] = request.Amount.ToString(),
        });

        var rng = Random.Shared;
        ChargeResult? lastResult = null;

        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            // greybeard: rung 6 -> log the attempt BEFORE the call. If the process dies mid-charge,
            //            this line is the breadcrumb proving we may have moved money.
            _log.LogInformation("Charge attempt {Attempt}/{Max} starting", attempt, MaxAttempts);

            // greybeard: rung 3 -> hard timeout on every external call, always.
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            timeoutCts.CancelAfter(PerCallTimeout);

            try
            {
                var result = await _processor
                    .ChargeAsync(request, timeoutCts.Token)
                    .ConfigureAwait(false);

                lastResult = result;

                // greybeard: rung 6 -> a decline is a definitive answer, not a transient fault. Stop, don't retry.
                if (result.Outcome is ChargeOutcome.Succeeded or ChargeOutcome.Declined or ChargeOutcome.Failed)
                {
                    _log.LogInformation(
                        "Charge attempt {Attempt} resolved: {Outcome} (processorChargeId={ChargeId}, declineReason={Reason})",
                        attempt, result.Outcome, result.ProcessorChargeId, result.DeclineReason);
                    return result;
                }

                _log.LogWarning("Charge attempt {Attempt} returned Unknown outcome", attempt);
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                // Caller cancelled (not our timeout). The charge may be in-flight at the bank.
                _log.LogWarning("Charge cancelled by caller during attempt {Attempt}", attempt);
                throw;
            }
            catch (OperationCanceledException)
            {
                // greybeard: rung 3 + 6 -> our timeout fired. Outcome is UNKNOWN: the bank may have charged.
                //            The shared idempotency key makes a retry safe (exactly-once effect upstream).
                _log.LogWarning("Charge attempt {Attempt} timed out after {Timeout}s; outcome unknown",
                    attempt, PerCallTimeout.TotalSeconds);
                lastResult = new ChargeResult(ChargeOutcome.Unknown, null, "timeout");
            }
            catch (HttpRequestException ex)
            {
                // greybeard: no secrets in logs -> log the exception message/type, never the request body.
                _log.LogWarning(ex, "Charge attempt {Attempt} failed with transport error; outcome unknown", attempt);
                lastResult = new ChargeResult(ChargeOutcome.Unknown, null, "transport_error");
            }

            // greybeard: rung 3 -> retry only the Unknown/transient path, with jittered exponential backoff.
            //            Because we resend the SAME idempotency key, at-least-once delivery yields exactly-once effect.
            if (attempt < MaxAttempts)
            {
                var backoffMs = (int)(Math.Pow(2, attempt) * 100);
                var jitterMs = rng.Next(0, 100);
                var delay = TimeSpan.FromMilliseconds(backoffMs + jitterMs);
                _log.LogInformation("Backing off {Delay}ms before retry", delay.TotalMilliseconds);
                await Task.Delay(delay, ct).ConfigureAwait(false);
            }
        }

        // greybeard: rung 6 -> exhausted retries with no definitive answer. Return Unknown, do NOT pretend success.
        //            Downstream reconciliation must resolve this against the processor using the idempotency key.
        var unresolved = lastResult ?? new ChargeResult(ChargeOutcome.Unknown, null, "exhausted_retries");
        _log.LogError(
            "Charge unresolved after {Max} attempts; outcome={Outcome}. Reconcile against processor by idempotency key.",
            MaxAttempts, unresolved.Outcome);
        return unresolved with { Outcome = ChargeOutcome.Unknown };
    }
}

using System;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Payments;

// Rungs that apply to "charge a card and log the attempt":
//   1. Money       -> amount is integer minor units + currency code, never float/decimal-as-dollars.
//   2. Mutation    -> idempotency key so a retried charge does not double-bill.
//   3. External    -> timeout always, jittered backoff retry, circuit breaker on repeated failure.
//   7. Observable  -> structured log of every attempt WITHOUT secrets/PAN.
// Rungs 4/5/6 (concurrency, list reads, multi-step saga) don't apply to a single charge call -> skipped.

/// <summary>Amount carried as integer minor units with its currency. No floats touch money.</summary>
public readonly record struct Money(long MinorUnits, string Currency)
{
    // greybeard: rung 1 - money is integer minor units (e.g. cents); rounding happens upstream, explicitly, not here.
    public static Money Of(long minorUnits, string currency)
    {
        // greybeard: trust-boundary validation - reject nonsense before it reaches the processor.
        if (minorUnits <= 0) throw new ArgumentOutOfRangeException(nameof(minorUnits), "Charge amount must be positive minor units.");
        if (string.IsNullOrWhiteSpace(currency) || currency.Length != 3)
            throw new ArgumentException("Currency must be a 3-letter ISO-4217 code.", nameof(currency));
        return new Money(minorUnits, currency.ToUpperInvariant());
    }
}

public sealed record ChargeRequest(
    Money Amount,
    string CardToken,        // greybeard: a processor token/PAN-surrogate, NEVER a raw card number. Never logged.
    string IdempotencyKey);  // greybeard: rung 2 - caller-supplied stable key; same key => same charge, retried safely.

public enum ChargeOutcome { Approved, Declined, Retryable, PermanentError }

public sealed record ChargeResult(ChargeOutcome Outcome, string? ProcessorChargeId, string? DeclineCode);

/// <summary>Thin client over the upstream processor; assume the SDK enforces idempotency via header.</summary>
public interface ICardProcessor
{
    Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct);
}

public sealed class CardCharger
{
    private const int MaxAttempts = 3;
    private static readonly TimeSpan PerCallTimeout = TimeSpan.FromSeconds(8); // greybeard: rung 3 - external calls ALWAYS bound time.

    private readonly ICardProcessor _processor;
    private readonly ILogger<CardCharger> _logger;
    private readonly ICircuitBreaker _breaker; // greybeard: rung 3 - open after repeated failures so we stop hammering a sick bank.

    public CardCharger(ICardProcessor processor, ILogger<CardCharger> logger, ICircuitBreaker breaker)
    {
        _processor = processor ?? throw new ArgumentNullException(nameof(processor));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _breaker = breaker ?? throw new ArgumentNullException(nameof(breaker));
    }

    public async Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        // greybeard: rung 2 - without an idempotency key a retry could double-charge. Refuse to proceed.
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("IdempotencyKey is required to safely retry a charge.", nameof(request));

        // greybeard: rung 3 - fail fast (and cheaply) when the processor is known-unhealthy.
        if (!_breaker.AllowRequest())
        {
            _logger.LogWarning(
                "Charge short-circuited by open breaker. idem={IdempotencyKey} amount={MinorUnits} {Currency}",
                request.IdempotencyKey, request.Amount.MinorUnits, request.Amount.Currency);
            return new ChargeResult(ChargeOutcome.Retryable, null, "circuit_open");
        }

        Exception? lastError = null;
        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            using var attemptCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            attemptCts.CancelAfter(PerCallTimeout); // greybeard: rung 3 - hard timeout per attempt; a hung bank never hangs us forever.

            try
            {
                var result = await _processor.ChargeAsync(request, attemptCts.Token).ConfigureAwait(false);

                // greybeard: rung 7 - log the attempt with safe fields only. NO card token, NO PAN, NO secrets.
                _logger.LogInformation(
                    "Charge attempt {Attempt}/{Max} outcome={Outcome} idem={IdempotencyKey} amount={MinorUnits} {Currency} chargeId={ChargeId} decline={DeclineCode}",
                    attempt, MaxAttempts, result.Outcome, request.IdempotencyKey,
                    request.Amount.MinorUnits, request.Amount.Currency,
                    result.ProcessorChargeId, result.DeclineCode);

                if (result.Outcome is ChargeOutcome.Approved or ChargeOutcome.Declined or ChargeOutcome.PermanentError)
                {
                    _breaker.RecordSuccess(); // greybeard: a clean processor reply (even a decline) means the dependency is healthy.
                    return result;
                }

                // Retryable -> fall through to backoff.
                _breaker.RecordFailure();
            }
            catch (Exception ex) when (ex is OperationCanceledException or HttpRequestException or TimeoutException)
            {
                lastError = ex;
                _breaker.RecordFailure();
                // greybeard: log the failure CLASS, not the exception's raw payload, to avoid leaking processor secrets/PII.
                _logger.LogWarning(
                    "Charge attempt {Attempt}/{Max} transient failure ({Error}) idem={IdempotencyKey} amount={MinorUnits} {Currency}",
                    attempt, MaxAttempts, ex.GetType().Name, request.IdempotencyKey,
                    request.Amount.MinorUnits, request.Amount.Currency);

                if (ct.IsCancellationRequested) throw; // caller gave up -> respect it.
            }

            if (attempt < MaxAttempts)
            {
                // greybeard: rung 3 - jittered exponential backoff. The SAME idempotency key is reused on retry => exactly-once charge effect.
                var backoff = TimeSpan.FromMilliseconds(Math.Pow(2, attempt) * 100 + Random.Shared.Next(0, 100));
                await Task.Delay(backoff, ct).ConfigureAwait(false);
            }
        }

        _logger.LogError(
            "Charge exhausted {Max} attempts; surfacing retryable. idem={IdempotencyKey} amount={MinorUnits} {Currency}",
            MaxAttempts, request.IdempotencyKey, request.Amount.MinorUnits, request.Amount.Currency);

        // greybeard: ambiguous outcome - we may have charged on the last attempt. Report Retryable so the caller
        // re-drives with the SAME idempotency key rather than assuming failure and double-charging.
        return new ChargeResult(ChargeOutcome.Retryable, null, lastError?.GetType().Name ?? "unknown");
    }
}

public interface ICircuitBreaker
{
    bool AllowRequest();
    void RecordSuccess();
    void RecordFailure();
}

using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Payments;

// greybeard: Money travels as integer minor-units + ISO currency code. No float, ever.
public readonly record struct Money(long MinorUnits, string Currency)
{
    // greybeard: validate at the trust boundary — reject nonsense before it reaches the processor.
    public void Validate()
    {
        if (MinorUnits <= 0)
            throw new ArgumentOutOfRangeException(nameof(MinorUnits), "Charge amount must be positive.");
        if (string.IsNullOrWhiteSpace(Currency) || Currency.Length != 3)
            throw new ArgumentException("Currency must be a 3-letter ISO code.", nameof(Currency));
    }
}

public sealed record ChargeRequest(
    string IdempotencyKey,   // greybeard: caller-supplied; the same key must never charge twice.
    string CardToken,        // greybeard: a vault token, NOT a PAN. Raw card data never enters this method.
    Money Amount);

public enum ChargeOutcome { Succeeded, Declined, Failed }

public sealed record ChargeResult(ChargeOutcome Outcome, string? ProcessorChargeId, string? DeclineReason);

public interface ICardProcessor
{
    // The concrete client is expected to honor the CancellationToken (timeout) we pass it.
    Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct);
}

// greybeard: a place to remember which idempotency keys we've already resolved — survives retries/restarts.
public interface IChargeLedger
{
    Task<ChargeResult?> TryGetAsync(string idempotencyKey, CancellationToken ct);
    Task SaveAsync(string idempotencyKey, ChargeResult result, CancellationToken ct);
}

// greybeard: trips after repeated processor failures so we stop hammering a dead dependency.
public interface ICircuitBreaker
{
    bool IsOpen { get; }
    void RecordSuccess();
    void RecordFailure();
}

public sealed class CardCharger
{
    private static readonly TimeSpan PerAttemptTimeout = TimeSpan.FromSeconds(8);
    private const int MaxAttempts = 3;

    private readonly ICardProcessor _processor;
    private readonly IChargeLedger _ledger;
    private readonly ICircuitBreaker _breaker;
    private readonly ILogger<CardCharger> _logger;

    public CardCharger(
        ICardProcessor processor,
        IChargeLedger ledger,
        ICircuitBreaker breaker,
        ILogger<CardCharger> logger)
    {
        _processor = processor;
        _ledger = ledger;
        _breaker = breaker;
        _logger = logger;
    }

    public async Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        // greybeard: validate everything crossing the boundary before we touch money or the network.
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("Idempotency key is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.CardToken))
            throw new ArgumentException("Card token is required.", nameof(request));
        request.Amount.Validate();

        // greybeard: never log the card token — log a stable, non-reversible scope key instead.
        using var scope = _logger.BeginScope(new
        {
            request.IdempotencyKey,
            request.Amount.MinorUnits,
            request.Amount.Currency
        });

        // greybeard: idempotency — a retried request returns the prior result instead of charging again.
        var existing = await _ledger.TryGetAsync(request.IdempotencyKey, ct).ConfigureAwait(false);
        if (existing is not null)
        {
            _logger.LogInformation(
                "Charge {IdempotencyKey} already resolved as {Outcome}; replaying stored result.",
                request.IdempotencyKey, existing.Outcome);
            return existing;
        }

        // greybeard: circuit breaker — fail fast and degrade gracefully when the processor is down.
        if (_breaker.IsOpen)
        {
            _logger.LogWarning(
                "Circuit open; rejecting charge {IdempotencyKey} without calling processor.",
                request.IdempotencyKey);
            var degraded = new ChargeResult(ChargeOutcome.Failed, null, "processor_unavailable");
            // greybeard: do NOT persist transient infrastructure failures — the key stays retryable later.
            return degraded;
        }

        ChargeResult? lastResult = null;
        for (var attempt = 1; attempt <= MaxAttempts; attempt++)
        {
            // greybeard: half-way path — log the attempt BEFORE the call so an in-flight/hung charge is debuggable.
            _logger.LogInformation(
                "Charge attempt {Attempt}/{Max} for {IdempotencyKey} ({MinorUnits} {Currency}).",
                attempt, MaxAttempts, request.IdempotencyKey,
                request.Amount.MinorUnits, request.Amount.Currency);

            // greybeard: always a timeout. A network call with no deadline is an outage waiting to happen.
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            timeoutCts.CancelAfter(PerAttemptTimeout);

            try
            {
                var result = await _processor.ChargeAsync(request, timeoutCts.Token).ConfigureAwait(false);
                _breaker.RecordSuccess();
                lastResult = result;

                if (result.Outcome == ChargeOutcome.Succeeded)
                {
                    // greybeard: persist the terminal result keyed by idempotency BEFORE returning,
                    // so any future retry replays it instead of double-charging.
                    await _ledger.SaveAsync(request.IdempotencyKey, result, ct).ConfigureAwait(false);
                    _logger.LogInformation(
                        "Charge {IdempotencyKey} succeeded; processorChargeId={ProcessorChargeId}.",
                        request.IdempotencyKey, result.ProcessorChargeId);
                    return result;
                }

                // greybeard: a decline is a deterministic, terminal answer — persist and stop, do not retry.
                if (result.Outcome == ChargeOutcome.Declined)
                {
                    await _ledger.SaveAsync(request.IdempotencyKey, result, ct).ConfigureAwait(false);
                    _logger.LogWarning(
                        "Charge {IdempotencyKey} declined; reason={DeclineReason}.",
                        request.IdempotencyKey, result.DeclineReason);
                    return result;
                }

                // Outcome == Failed: transient processor-side failure, fall through to retry/backoff.
                _logger.LogWarning(
                    "Charge {IdempotencyKey} attempt {Attempt} returned transient failure; reason={DeclineReason}.",
                    request.IdempotencyKey, attempt, result.DeclineReason);
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                // Caller gave up — surface it, don't swallow.
                throw;
            }
            catch (OperationCanceledException)
            {
                // greybeard: our per-attempt timeout fired. The charge MAY have landed — treat as unknown, retryable.
                _breaker.RecordFailure();
                lastResult = new ChargeResult(ChargeOutcome.Failed, null, "timeout");
                _logger.LogError(
                    "Charge {IdempotencyKey} attempt {Attempt} timed out after {TimeoutSeconds}s.",
                    request.IdempotencyKey, attempt, PerAttemptTimeout.TotalSeconds);
            }
            catch (Exception ex)
            {
                // greybeard: log the exception type/message but NEVER the request payload (card token leak risk).
                _breaker.RecordFailure();
                lastResult = new ChargeResult(ChargeOutcome.Failed, null, "processor_error");
                _logger.LogError(ex,
                    "Charge {IdempotencyKey} attempt {Attempt} threw {ExceptionType}.",
                    request.IdempotencyKey, attempt, ex.GetType().Name);
            }

            if (attempt < MaxAttempts)
            {
                // greybeard: jittered exponential backoff so retries don't synchronize into a thundering herd.
                var backoff = ComputeJitteredBackoff(attempt);
                await Task.Delay(backoff, ct).ConfigureAwait(false);
            }
        }

        // greybeard: exhausted retries with an indeterminate outcome. Do NOT persist as terminal —
        // the idempotency key remains unresolved so a later reconciliation/retry can settle it safely.
        var failed = lastResult ?? new ChargeResult(ChargeOutcome.Failed, null, "unknown");
        _logger.LogError(
            "Charge {IdempotencyKey} failed after {MaxAttempts} attempts; final reason={DeclineReason}. " +
            "Left unresolved for reconciliation.",
            request.IdempotencyKey, MaxAttempts, failed.DeclineReason);
        return failed;
    }

    private static TimeSpan ComputeJitteredBackoff(int attempt)
    {
        // 250ms, 500ms, 1s ... capped, plus full jitter.
        var baseMs = Math.Min(250 * Math.Pow(2, attempt - 1), 4000);
        var jittered = Random.Shared.NextDouble() * baseMs;
        return TimeSpan.FromMilliseconds(jittered);
    }
}

using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

// greybeard ladder for "send a webhook when an order ships":
//   3. External call  -> customer URL: timeout always, retry w/ jittered backoff, circuit breaker. (+ SSRF guard on a URL we don't control)
//   2. Mutation/delivery -> stable idempotency/event id so a retried send is exactly-once at the receiver; at-least-once delivery.
//   6. Fail half-way   -> durable outbox + dead-letter; partial failure is a first-class path, never silent loss.
//   7. Observable      -> structured logs, no secrets (signing key / signature / payload bodies stay out of logs).
// Rungs skipped (do not apply): 1 Money (no currency here), 4 Concurrency (single outbox claim, shown), 5 List (single send).

namespace Shipping.Webhooks;

// ----- Domain event we deliver -----------------------------------------------

public sealed record OrderShippedEvent(
    string OrderId,
    string Carrier,
    string TrackingNumber,
    DateTimeOffset ShippedAt);

// ----- Durable outbox record (rung 6: partial failure is first-class) --------

public enum OutboxStatus { Pending, Delivered, DeadLettered }

public sealed class WebhookDelivery
{
    // greybeard: EventId is the idempotency key. It is generated ONCE when the
    // order ships and reused across every retry, so the receiver can dedupe and
    // a retried delivery is exactly-once at their end.
    public required string EventId { get; init; }
    public required string CustomerUrl { get; init; }
    public required string Payload { get; init; }      // canonical JSON, signed verbatim
    public OutboxStatus Status { get; set; } = OutboxStatus.Pending;
    public int Attempts { get; set; }
    public DateTimeOffset? NextAttemptAt { get; set; } = DateTimeOffset.UtcNow;
    public string? LastError { get; set; }             // greybeard: never store secrets/signatures here
}

// greybeard: persistence is an interface so the outbox is actually durable in
// prod (DB row with a status). The in-memory impl is for tests only.
public interface IWebhookOutbox
{
    Task<WebhookDelivery> EnqueueAsync(WebhookDelivery delivery, CancellationToken ct);
    Task SaveAsync(WebhookDelivery delivery, CancellationToken ct);
    Task<IReadOnlyList<WebhookDelivery>> ClaimDueAsync(int max, CancellationToken ct);
}

// ----- SSRF guard: the URL is attacker-controllable input (trust boundary) ---

public static class SsrfGuard
{
    // greybeard: customer-supplied URL crosses a trust boundary. Validate it
    // BEFORE we ever connect: https only, public host only, no link-local /
    // loopback / private / metadata ranges. Re-checked per-connection below to
    // beat DNS-rebinding.
    public static void ValidateUrlSyntax(string url)
    {
        if (string.IsNullOrWhiteSpace(url))
            throw new ArgumentException("Webhook URL is required.");
        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
            throw new ArgumentException("Webhook URL is not a valid absolute URI.");
        if (uri.Scheme != Uri.UriSchemeHttps)
            throw new ArgumentException("Webhook URL must use https.");
        if (uri.IsDefaultPort is false && uri.Port != 443)
            throw new ArgumentException("Webhook URL must target port 443.");
    }

    public static bool IsDisallowedAddress(IPAddress ip)
    {
        if (IPAddress.IsLoopback(ip)) return true;
        if (ip.IsIPv6LinkLocal || ip.IsIPv6SiteLocal || ip.IsIPv6Multicast) return true;

        if (ip.AddressFamily == AddressFamily.InterNetwork)
        {
            Span<byte> b = stackalloc byte[4];
            ip.TryWriteBytes(b, out _);
            uint a = BinaryPrimitives.ReadUInt32BigEndian(b);
            bool InRange(string cidrBase, int bits)
            {
                var baseIp = BinaryPrimitives.ReadUInt32BigEndian(IPAddress.Parse(cidrBase).GetAddressBytes());
                uint mask = bits == 0 ? 0u : 0xFFFFFFFFu << (32 - bits);
                return (a & mask) == (baseIp & mask);
            }
            return InRange("10.0.0.0", 8)        // private
                || InRange("172.16.0.0", 12)     // private
                || InRange("192.168.0.0", 16)    // private
                || InRange("127.0.0.0", 8)       // loopback
                || InRange("169.254.0.0", 16)    // link-local + cloud metadata (169.254.169.254)
                || InRange("0.0.0.0", 8)         // "this network"
                || InRange("100.64.0.0", 10);    // carrier-grade NAT
        }
        // IPv6: block unique-local fc00::/7 and unspecified
        var bytes = ip.GetAddressBytes();
        if ((bytes[0] & 0xFE) == 0xFC) return true;
        if (ip.Equals(IPAddress.IPv6Any)) return true;
        return false;
    }
}

// ----- HMAC signing (security: prove the webhook came from us) ----------------

public static class WebhookSigner
{
    // greybeard: sign the exact bytes we send, with a timestamp in the signed
    // material so the receiver can reject replays. Signature header lets the
    // customer verify authenticity. The key is a secret -> never logged.
    public static (string signatureHeader, string timestamp) Sign(
        ReadOnlySpan<byte> body, byte[] signingKey, DateTimeOffset now)
    {
        var ts = now.ToUnixTimeSeconds().ToString(CultureInfo.InvariantCulture);
        var signedPayload = $"{ts}.";
        var prefix = Encoding.UTF8.GetBytes(signedPayload);
        var toSign = new byte[prefix.Length + body.Length];
        prefix.CopyTo(toSign, 0);
        body.CopyTo(toSign.AsSpan(prefix.Length));

        using var hmac = new HMACSHA256(signingKey);
        var sig = hmac.ComputeHash(toSign);
        return ($"t={ts},v1={Convert.ToHexString(sig).ToLowerInvariant()}", ts);
    }
}

// ----- Circuit breaker (rung 3) ----------------------------------------------

public sealed class CircuitBreaker
{
    private readonly int _threshold;
    private readonly TimeSpan _openFor;
    private int _consecutiveFailures;
    private DateTimeOffset _openedUntil = DateTimeOffset.MinValue;
    private readonly object _gate = new();

    public CircuitBreaker(int threshold = 5, TimeSpan? openFor = null)
    {
        _threshold = threshold;
        _openFor = openFor ?? TimeSpan.FromSeconds(30);
    }

    public bool IsOpen(DateTimeOffset now)
    {
        lock (_gate) return now < _openedUntil;
    }

    public void RecordSuccess()
    {
        lock (_gate) { _consecutiveFailures = 0; _openedUntil = DateTimeOffset.MinValue; }
    }

    public void RecordFailure(DateTimeOffset now)
    {
        lock (_gate)
        {
            // greybeard: stop hammering a downstream that is clearly down.
            if (++_consecutiveFailures >= _threshold)
                _openedUntil = now + _openFor;
        }
    }
}

// ----- The sender ------------------------------------------------------------

public sealed class WebhookSenderOptions
{
    public TimeSpan RequestTimeout { get; init; } = TimeSpan.FromSeconds(5); // greybeard: always a timeout
    public int MaxAttempts { get; init; } = 6;
    public TimeSpan BaseBackoff { get; init; } = TimeSpan.FromSeconds(2);
    public TimeSpan MaxBackoff { get; init; } = TimeSpan.FromMinutes(15);
}

public sealed class WebhookSender
{
    private readonly HttpClient _http;
    private readonly IWebhookOutbox _outbox;
    private readonly byte[] _signingKey;
    private readonly WebhookSenderOptions _opt;
    private readonly ILogger<WebhookSender> _log;
    private readonly CircuitBreaker _breaker;

    public WebhookSender(
        HttpClient http,
        IWebhookOutbox outbox,
        byte[] signingKey,
        WebhookSenderOptions opt,
        ILogger<WebhookSender> log,
        CircuitBreaker? breaker = null)
    {
        _http = http;
        _outbox = outbox;
        _signingKey = signingKey ?? throw new ArgumentNullException(nameof(signingKey));
        if (_signingKey.Length < 32)
            throw new ArgumentException("Signing key must be >= 256 bits.");
        _opt = opt;
        _log = log;
        _breaker = breaker ?? new CircuitBreaker();
    }

    // Call this synchronously in the same DB transaction that marks the order
    // shipped. It only enqueues — it does not block the ship flow on a flaky
    // external call.
    public async Task<string> EnqueueOrderShippedAsync(
        string customerUrl, OrderShippedEvent evt, CancellationToken ct = default)
    {
        SsrfGuard.ValidateUrlSyntax(customerUrl); // greybeard: validate at the boundary, fail fast

        // greybeard: canonical, stable serialization — the exact bytes we sign
        // and resend on every retry, so the signature stays valid.
        var eventId = Guid.NewGuid().ToString("N");
        var envelope = new
        {
            id = eventId,
            type = "order.shipped",
            created = evt.ShippedAt.ToUnixTimeSeconds(),
            data = new
            {
                order_id = evt.OrderId,
                carrier = evt.Carrier,
                tracking_number = evt.TrackingNumber,
                shipped_at = evt.ShippedAt.ToString("O"),
            }
        };
        var payload = JsonSerializer.Serialize(envelope);

        var delivery = await _outbox.EnqueueAsync(new WebhookDelivery
        {
            EventId = eventId,
            CustomerUrl = customerUrl,
            Payload = payload,
        }, ct);

        _log.LogInformation(
            "Webhook enqueued event {EventId} for order {OrderId}",
            delivery.EventId, evt.OrderId); // greybeard: no URL host secrets, no payload body, no key
        return eventId;
    }

    // Background worker pumps the outbox. One delivery attempt:
    public async Task<bool> TryDeliverAsync(WebhookDelivery delivery, CancellationToken ct = default)
    {
        var now = DateTimeOffset.UtcNow;

        if (_breaker.IsOpen(now))
        {
            // greybeard: breaker open -> back off instead of piling on a dead host.
            ScheduleRetry(delivery, now, reason: "circuit_open");
            await _outbox.SaveAsync(delivery, ct);
            return false;
        }

        delivery.Attempts++;
        try
        {
            var body = Encoding.UTF8.GetBytes(delivery.Payload);
            var (signature, _) = WebhookSigner.Sign(body, _signingKey, now);

            using var req = new HttpRequestMessage(HttpMethod.Post, delivery.CustomerUrl);
            req.Content = new ByteArrayContent(body);
            req.Content.Headers.ContentType =
                new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");
            // greybeard: idempotency key on the wire so a retried POST is deduped by the receiver.
            req.Headers.TryAddWithoutValidation("Idempotency-Key", delivery.EventId);
            req.Headers.TryAddWithoutValidation("Webhook-Id", delivery.EventId);
            req.Headers.TryAddWithoutValidation("Webhook-Signature", signature);

            // greybeard: hard per-request timeout — always. Never trust the
            // customer's server to ever respond.
            using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            cts.CancelAfter(_opt.RequestTimeout);

            // greybeard: re-resolve + re-check the host at send time to defeat
            // DNS rebinding (a syntactically-fine URL pointing at 169.254.169.254).
            await AssertHostIsPublicAsync(new Uri(delivery.CustomerUrl), cts.Token);

            using var resp = await _http.SendAsync(
                req, HttpCompletionOption.ResponseHeadersRead, cts.Token);

            if ((int)resp.StatusCode is >= 200 and < 300)
            {
                _breaker.RecordSuccess();
                delivery.Status = OutboxStatus.Delivered;
                delivery.LastError = null;
                await _outbox.SaveAsync(delivery, ct);
                _log.LogInformation("Webhook delivered event {EventId} on attempt {Attempt}",
                    delivery.EventId, delivery.Attempts);
                return true;
            }

            // 4xx (except 408/429) is the customer's bug, not ours — don't retry forever.
            bool retryable = (int)resp.StatusCode is 408 or 429 or (>= 500 and <= 599);
            RecordFailureAndSchedule(delivery, now,
                reason: $"http_{(int)resp.StatusCode}", retryable: retryable);
        }
        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
        {
            RecordFailureAndSchedule(delivery, now, reason: "timeout", retryable: true);
        }
        catch (HttpRequestException ex)
        {
            // greybeard: log the failure CLASS, never the raw exception that may
            // carry URLs / headers / secrets.
            RecordFailureAndSchedule(delivery, now, reason: "transport_error", retryable: true);
            _log.LogWarning("Webhook transport failure for {EventId}: {Kind}",
                delivery.EventId, ex.GetType().Name);
        }
        catch (Exception)
        {
            // SSRF re-check failure or serialization issue: do not retry blindly.
            RecordFailureAndSchedule(delivery, now, reason: "non_retryable", retryable: false);
        }

        await _outbox.SaveAsync(delivery, ct);
        return false;
    }

    private void RecordFailureAndSchedule(
        WebhookDelivery delivery, DateTimeOffset now, string reason, bool retryable)
    {
        _breaker.RecordFailure(now);
        delivery.LastError = reason; // greybeard: bounded reason code, never secrets

        if (!retryable || delivery.Attempts >= _opt.MaxAttempts)
        {
            // greybeard: dead-letter instead of silently dropping. Recoverable:
            // an operator can inspect and replay. Data-loss safety.
            delivery.Status = OutboxStatus.DeadLettered;
            delivery.NextAttemptAt = null;
            _log.LogError(
                "Webhook dead-lettered event {EventId} after {Attempts} attempts: {Reason}",
                delivery.EventId, delivery.Attempts, reason);
            return;
        }
        ScheduleRetry(delivery, now, reason);
    }

    private void ScheduleRetry(WebhookDelivery delivery, DateTimeOffset now, string reason)
    {
        // greybeard: exponential backoff with FULL jitter to avoid retry storms
        // that synchronize across all pending deliveries.
        var exp = Math.Min(delivery.Attempts, 20);
        var ceiling = Math.Min(
            _opt.MaxBackoff.TotalMilliseconds,
            _opt.BaseBackoff.TotalMilliseconds * Math.Pow(2, exp));
        var jittered = Random.Shared.NextDouble() * ceiling;
        delivery.Status = OutboxStatus.Pending;
        delivery.NextAttemptAt = now + TimeSpan.FromMilliseconds(jittered);
    }

    private static async Task AssertHostIsPublicAsync(Uri uri, CancellationToken ct)
    {
        var addrs = await Dns.GetHostAddressesAsync(uri.DnsSafeHost, ct);
        if (addrs.Length == 0)
            throw new InvalidOperationException("Webhook host did not resolve.");
        foreach (var ip in addrs)
            if (SsrfGuard.IsDisallowedAddress(ip))
                throw new InvalidOperationException("Webhook host resolves to a disallowed address.");
    }
}

// ----- Reference in-memory outbox (tests only) -------------------------------

public sealed class InMemoryOutbox : IWebhookOutbox
{
    private readonly object _gate = new();
    private readonly Dictionary<string, WebhookDelivery> _store = new();

    public Task<WebhookDelivery> EnqueueAsync(WebhookDelivery d, CancellationToken ct)
    {
        lock (_gate) _store[d.EventId] = d;
        return Task.FromResult(d);
    }

    public Task SaveAsync(WebhookDelivery d, CancellationToken ct)
    {
        lock (_gate) _store[d.EventId] = d;
        return Task.CompletedTask;
    }

    public Task<IReadOnlyList<WebhookDelivery>> ClaimDueAsync(int max, CancellationToken ct)
    {
        var now = DateTimeOffset.UtcNow;
        lock (_gate)
        {
            // greybeard: in real persistence this is a SELECT ... FOR UPDATE SKIP
            // LOCKED so two workers never claim the same row (rung 4, no lost update).
            var due = _store.Values
                .Where(d => d.Status == OutboxStatus.Pending
                            && d.NextAttemptAt is { } t && t <= now)
                .OrderBy(d => d.NextAttemptAt)
                .Take(max)
                .ToList();
            return Task.FromResult<IReadOnlyList<WebhookDelivery>>(due);
        }
    }
}

// greybeard re-read at 3am: URL is validated at the boundary AND re-checked per
// send (DNS rebinding); every send has a hard timeout; retries use full-jitter
// backoff and trip a circuit breaker; the event id is a stable idempotency key
// so a retried webhook can't double-fire at the receiver; failures dead-letter
// for replay instead of vanishing; the signing key, signature, and payload body
// never reach the logs. Open item to flag: rotate signing keys and send the new
// signature under a second header during the overlap window.

// OrderShippedWebhookSender.cs
//
// greybeard ladder applied to "send a webhook when an order ships":
//   Rung 1 Money?            -> N/A. The shipment notification carries an order id, not a balance we mutate.
//   Rung 2 Mutation?         -> YES. Sending a webhook is a side effect that MUST be exactly-once in effect.
//                               We persist an outbox row keyed by a delivery idempotency key and send a
//                               stable Idempotency-Key header so a retried delivery does not double-fire
//                               the customer's downstream automation.
//   Rung 3 External call?    -> YES. The customer's URL is the most hostile dependency we have. Hard timeout,
//                               retry with jittered exponential backoff, and a circuit breaker per endpoint.
//   Rung 4 Concurrency?      -> YES. Multiple workers drain the outbox. We claim a row with an optimistic
//                               row lock (status + lease) so two workers never deliver the same event.
//   Rung 5 Reads a list?     -> YES. The drainer reads pending deliveries -> bounded batch, no unbounded fan-out.
//   Rung 6 Fail half-way?    -> YES. Persist-then-send (transactional outbox). Exhausted retries land in a
//                               dead-letter state for replay, never silently dropped. Partial failure is a path.
//   Rung 7 Minimum correct + observable -> structured logs/metrics, secrets never logged.
//
// Non-negotiables honored:
//   - Trust-boundary validation: the customer URL is validated + SSRF-guarded before every send.
//   - No secrets in logs/errors/traces: the signing secret and signature are never logged.
//   - Data-loss safety: nothing is dropped; failures dead-letter with a recovery path.

#nullable enable

using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Shipping.Webhooks;

#region Domain + persistence contracts

/// <summary>The business event we deliver.</summary>
public sealed record OrderShippedEvent(
    string OrderId,
    string Carrier,
    string TrackingNumber,
    DateTimeOffset ShippedAt);

public enum DeliveryStatus
{
    Pending = 0,
    InFlight = 1,
    Delivered = 2,
    DeadLettered = 3
}

/// <summary>
/// One row in the transactional outbox. greybeard: the event is committed here in the SAME
/// transaction as the order-ship state change, so we never promise a webhook for a ship that
/// didn't happen, nor lose a webhook for a ship that did.
/// </summary>
public sealed class WebhookDelivery
{
    public required string DeliveryId { get; init; }          // PK, our internal id
    public required string IdempotencyKey { get; init; }      // stable across all retries of THIS delivery
    public required string Endpoint { get; init; }            // customer URL
    public required string Payload { get; init; }             // canonical JSON body (signed verbatim)
    public DeliveryStatus Status { get; set; } = DeliveryStatus.Pending;
    public int Attempts { get; set; }
    public DateTimeOffset NextAttemptAt { get; set; } = DateTimeOffset.UtcNow;
    public DateTimeOffset? LeaseUntil { get; set; }           // row lease for concurrent drainers
    public string? LastError { get; set; }                    // sanitized only
    public long Version { get; set; }                         // optimistic-concurrency token
}

/// <summary>
/// Store abstraction. A real impl is Postgres/SQL Server. greybeard: claim/complete operations are
/// optimistic-concurrency guarded (WHERE Version = @expected) so two workers can't both win a row.
/// </summary>
public interface IWebhookOutbox
{
    /// <summary>Insert in the same DB transaction that flips the order to "shipped". Idempotent on IdempotencyKey.</summary>
    Task EnqueueAsync(WebhookDelivery delivery, CancellationToken ct);

    /// <summary>Atomically claim up to <paramref name="max"/> due rows, taking a time-boxed lease.</summary>
    Task<IReadOnlyList<WebhookDelivery>> ClaimDueAsync(int max, TimeSpan lease, CancellationToken ct);

    /// <summary>Persist a terminal/next-attempt state. Returns false on version conflict (someone else moved it).</summary>
    Task<bool> SaveAsync(WebhookDelivery delivery, CancellationToken ct);
}

#endregion

#region Idempotency + canonical payload

public static class WebhookIdentity
{
    /// <summary>
    /// greybeard: a webhook delivery's idempotency key is derived ONLY from stable business identity
    /// (endpoint + event type + order id), NOT from wall-clock or a fresh GUID. Re-enqueueing the same
    /// shipped event produces the same key, so EnqueueAsync dedupes and the customer never sees a double.
    /// </summary>
    public static string DeliveryKey(string endpoint, OrderShippedEvent e)
    {
        var material = $"order.shipped|{endpoint}|{e.OrderId}";
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(material));
        return "whk_" + Convert.ToHexString(hash).ToLowerInvariant()[..32];
    }

    /// <summary>
    /// Canonical body. greybeard: we sign exactly the bytes we send, so we build the JSON once, store it,
    /// and never re-serialize at send time (re-serialization can reorder keys and break signature verification).
    /// </summary>
    public static string CanonicalPayload(OrderShippedEvent e)
    {
        return JsonSerializer.Serialize(new
        {
            type = "order.shipped",
            data = new
            {
                order_id = e.OrderId,
                carrier = e.Carrier,
                tracking_number = e.TrackingNumber,
                shipped_at = e.ShippedAt.ToUniversalTime().ToString("O", CultureInfo.InvariantCulture)
            }
        });
    }
}

#endregion

#region Signing

/// <summary>
/// HMAC-SHA256 request signing, Stripe-style. greybeard: the customer verifies authenticity AND integrity.
/// The timestamp is inside the signed material so a captured request can't be replayed past a tolerance window.
/// The secret and the resulting signature are treated as secrets -- never logged.
/// </summary>
public sealed class WebhookSigner
{
    private readonly byte[] _secret;

    public WebhookSigner(string signingSecret)
    {
        if (string.IsNullOrWhiteSpace(signingSecret))
            throw new ArgumentException("Signing secret is required.", nameof(signingSecret));
        _secret = Encoding.UTF8.GetBytes(signingSecret);
    }

    public (string signatureHeader, string timestamp) Sign(string payload, DateTimeOffset now)
    {
        var ts = now.ToUnixTimeSeconds().ToString(CultureInfo.InvariantCulture);
        var signed = $"{ts}.{payload}";
        using var hmac = new HMACSHA256(_secret);
        var mac = hmac.ComputeHash(Encoding.UTF8.GetBytes(signed));
        var hex = Convert.ToHexString(mac).ToLowerInvariant();
        // Header format: "t=<unix>,v1=<hex>" -- customer recomputes HMAC over "t.payload".
        return ($"t={ts},v1={hex}", ts);
    }
}

#endregion

#region SSRF guard (trust-boundary validation)

/// <summary>
/// greybeard: a customer-supplied URL is untrusted input crossing a trust boundary. Before we ever open a
/// socket we (1) require https, (2) resolve DNS ourselves, and (3) reject any resolved IP that is private,
/// loopback, link-local, or otherwise internal -- defeating SSRF + DNS-rebinding to our own infrastructure.
/// We connect by the vetted IP and carry the Host header so the resolution we checked is the one we use.
/// </summary>
public static class SsrfGuard
{
    public static async Task<IPAddress> ValidateAndResolveAsync(Uri uri, CancellationToken ct)
    {
        if (uri.Scheme != Uri.UriSchemeHttps)
            throw new WebhookSecurityException("Webhook endpoint must be https.");

        if (uri.IsDefaultPort is false && uri.Port is not (443 or 8443))
            throw new WebhookSecurityException("Webhook endpoint uses a disallowed port.");

        IPAddress[] resolved;
        try
        {
            resolved = await Dns.GetHostAddressesAsync(uri.DnsSafeHost, ct).ConfigureAwait(false);
        }
        catch (SocketException)
        {
            throw new WebhookSecurityException("Webhook endpoint host could not be resolved.");
        }

        var safe = resolved.FirstOrDefault(ip => !IsInternal(ip));
        if (safe is null)
            throw new WebhookSecurityException("Webhook endpoint resolves to a non-public address.");

        return safe;
    }

    private static bool IsInternal(IPAddress ip)
    {
        if (IPAddress.IsLoopback(ip)) return true;
        if (ip.IsIPv6LinkLocal || ip.IsIPv6SiteLocal || ip.IsIPv6Multicast) return true;

        if (ip.AddressFamily == AddressFamily.InterNetwork)
        {
            Span<byte> b = stackalloc byte[4];
            ip.TryWriteBytes(b, out _);
            uint v = BinaryPrimitives.ReadUInt32BigEndian(b);
            // 10/8, 172.16/12, 192.168/16, 169.254/16 (link-local), 127/8, 100.64/10 (CGNAT), 0/8
            if ((v & 0xFF000000) == 0x0A000000) return true;
            if ((v & 0xFFF00000) == 0xAC100000) return true;
            if ((v & 0xFFFF0000) == 0xC0A80000) return true;
            if ((v & 0xFFFF0000) == 0xA9FE0000) return true;
            if ((v & 0xFF000000) == 0x7F000000) return true;
            if ((v & 0xFFC00000) == 0x64400000) return true;
            if ((v & 0xFF000000) == 0x00000000) return true;
        }
        else if (ip.AddressFamily == AddressFamily.InterNetworkV6)
        {
            if (ip.IsIPv4MappedToIPv6) return IsInternal(ip.MapToIPv4());
            var b = ip.GetAddressBytes();
            if ((b[0] & 0xFE) == 0xFC) return true; // fc00::/7 unique-local
        }
        return true; // fail closed on anything we don't positively recognize as public
    }
}

#endregion

#region Circuit breaker (per endpoint)

/// <summary>
/// greybeard: a customer endpoint that is hard-down should not soak up every worker and every retry budget.
/// After N consecutive failures the breaker opens for a cooldown; deliveries short-circuit to a retry
/// schedule instead of hammering a dead host. One half-open probe re-closes it on success.
/// </summary>
public sealed class CircuitBreaker
{
    private enum State { Closed, Open, HalfOpen }

    private readonly int _threshold;
    private readonly TimeSpan _cooldown;
    private readonly object _gate = new();
    private State _state = State.Closed;
    private int _consecutiveFailures;
    private DateTimeOffset _openedAt;

    public CircuitBreaker(int threshold = 5, TimeSpan? cooldown = null)
    {
        _threshold = threshold;
        _cooldown = cooldown ?? TimeSpan.FromSeconds(30);
    }

    public bool TryEnter(DateTimeOffset now)
    {
        lock (_gate)
        {
            switch (_state)
            {
                case State.Closed:
                    return true;
                case State.Open when now - _openedAt >= _cooldown:
                    _state = State.HalfOpen; // allow a single probe
                    return true;
                case State.Open:
                    return false;
                case State.HalfOpen:
                    return false; // a probe is already outstanding
                default:
                    return true;
            }
        }
    }

    public void OnSuccess()
    {
        lock (_gate)
        {
            _consecutiveFailures = 0;
            _state = State.Closed;
        }
    }

    public void OnFailure(DateTimeOffset now)
    {
        lock (_gate)
        {
            _consecutiveFailures++;
            if (_state == State.HalfOpen || _consecutiveFailures >= _threshold)
            {
                _state = State.Open;
                _openedAt = now;
            }
        }
    }

    public bool IsOpen
    {
        get { lock (_gate) { return _state == State.Open; } }
    }
}

public sealed class WebhookSecurityException : Exception
{
    public WebhookSecurityException(string message) : base(message) { }
}

#endregion

#region Sender

public sealed class WebhookOptions
{
    public TimeSpan RequestTimeout { get; init; } = TimeSpan.FromSeconds(10); // greybeard: hard per-attempt timeout, always.
    public int MaxAttempts { get; init; } = 8;                                // then dead-letter, never infinite.
    public TimeSpan BaseBackoff { get; init; } = TimeSpan.FromSeconds(2);
    public TimeSpan MaxBackoff { get; init; } = TimeSpan.FromMinutes(15);
    public int DrainBatchSize { get; init; } = 50;                            // greybeard: bounded fan-out per tick.
    public TimeSpan LeaseDuration { get; init; } = TimeSpan.FromSeconds(60);
}

/// <summary>
/// Sends one delivery attempt. Returns whether the attempt succeeded. greybeard: this is a single, dumb,
/// well-behaved network call -- timeout, validation, signing. Orchestration (retry/breaker/state) lives above it.
/// </summary>
public sealed class WebhookSender
{
    private readonly HttpClient _http;
    private readonly WebhookSigner _signer;
    private readonly WebhookOptions _opts;
    private readonly ILogger<WebhookSender> _log;

    public WebhookSender(HttpClient http, WebhookSigner signer, WebhookOptions opts, ILogger<WebhookSender> log)
    {
        _http = http;
        _signer = signer;
        _opts = opts;
        _log = log;
    }

    /// <returns>true on 2xx; false (with sanitized reason) otherwise. Throws only on a hard security violation.</returns>
    public async Task<(bool ok, string? sanitizedError)> TrySendAsync(WebhookDelivery d, CancellationToken ct)
    {
        if (!Uri.TryCreate(d.Endpoint, UriKind.Absolute, out var uri))
            return (false, "invalid_endpoint_uri");

        // greybeard: re-validate on EVERY attempt -- DNS can rebind between attempts.
        await SsrfGuard.ValidateAndResolveAsync(uri, ct).ConfigureAwait(false);

        var now = DateTimeOffset.UtcNow;
        var (signature, ts) = _signer.Sign(d.Payload, now);

        using var req = new HttpRequestMessage(HttpMethod.Post, uri);
        req.Content = new StringContent(d.Payload, Encoding.UTF8, "application/json");
        // greybeard: Idempotency-Key is stable across retries so the customer can dedupe at-least-once delivery.
        req.Headers.TryAddWithoutValidation("Idempotency-Key", d.IdempotencyKey);
        req.Headers.TryAddWithoutValidation("Webhook-Id", d.DeliveryId);
        req.Headers.TryAddWithoutValidation("Webhook-Signature", signature);
        req.Headers.TryAddWithoutValidation("Webhook-Timestamp", ts);

        using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        timeoutCts.CancelAfter(_opts.RequestTimeout); // greybeard: bound the attempt even if HttpClient default changes.

        try
        {
            using var resp = await _http.SendAsync(req, HttpCompletionOption.ResponseHeadersRead, timeoutCts.Token)
                                        .ConfigureAwait(false);
            if ((int)resp.StatusCode is >= 200 and < 300)
                return (true, null);

            // 4xx (except 429) is the customer's contract problem -- retrying won't help, surface it.
            var retryable = resp.StatusCode == HttpStatusCode.TooManyRequests || (int)resp.StatusCode >= 500;
            // greybeard: log the STATUS only -- never the response body (may echo our headers/secrets).
            return (false, retryable ? $"http_{(int)resp.StatusCode}_retryable" : $"http_{(int)resp.StatusCode}_permanent");
        }
        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
        {
            return (false, "timeout");
        }
        catch (HttpRequestException)
        {
            return (false, "connection_error"); // greybeard: never surface raw exception (may contain host/secret detail).
        }
    }
}

#endregion

#region Service: enqueue + drain

/// <summary>
/// The public entry point. Enqueue from your "order shipped" transaction; run DrainAsync from a background
/// worker. greybeard: separating enqueue (synchronous, transactional, fast) from delivery (async, retried)
/// is what makes the webhook reliable -- the API request that shipped the order never blocks on the customer.
/// </summary>
public sealed class OrderShippedWebhookService
{
    private readonly IWebhookOutbox _outbox;
    private readonly WebhookSender _sender;
    private readonly WebhookOptions _opts;
    private readonly ILogger<OrderShippedWebhookService> _log;
    private readonly Dictionary<string, CircuitBreaker> _breakers = new();
    private readonly object _breakerGate = new();

    public OrderShippedWebhookService(
        IWebhookOutbox outbox,
        WebhookSender sender,
        WebhookOptions opts,
        ILogger<OrderShippedWebhookService> log)
    {
        _outbox = outbox;
        _sender = sender;
        _opts = opts;
        _log = log;
    }

    /// <summary>
    /// Call inside the same DB transaction that marks the order shipped. greybeard: persist-then-send.
    /// Idempotent on the derived key, so a retried ship-handler enqueues at most one delivery.
    /// </summary>
    public Task EnqueueAsync(string customerEndpoint, OrderShippedEvent e, CancellationToken ct)
    {
        if (!Uri.TryCreate(customerEndpoint, UriKind.Absolute, out _))
            throw new WebhookSecurityException("Customer endpoint is not a valid absolute URL.");

        var delivery = new WebhookDelivery
        {
            DeliveryId = Guid.NewGuid().ToString("n"),
            IdempotencyKey = WebhookIdentity.DeliveryKey(customerEndpoint, e),
            Endpoint = customerEndpoint,
            Payload = WebhookIdentity.CanonicalPayload(e),
            Status = DeliveryStatus.Pending,
            NextAttemptAt = DateTimeOffset.UtcNow
        };

        return _outbox.EnqueueAsync(delivery, ct);
    }

    /// <summary>
    /// One drain tick. Run on a timer / hosted service across N workers. greybeard: ClaimDueAsync uses a
    /// leased row lock, so running this concurrently is safe and lost-update-free.
    /// </summary>
    public async Task DrainAsync(CancellationToken ct)
    {
        var batch = await _outbox.ClaimDueAsync(_opts.DrainBatchSize, _opts.LeaseDuration, ct).ConfigureAwait(false);
        foreach (var delivery in batch)
        {
            ct.ThrowIfCancellationRequested();
            await DeliverOnceAsync(delivery, ct).ConfigureAwait(false);
        }
    }

    private async Task DeliverOnceAsync(WebhookDelivery d, CancellationToken ct)
    {
        var breaker = GetBreaker(d.Endpoint);
        var now = DateTimeOffset.UtcNow;

        if (!breaker.TryEnter(now))
        {
            // greybeard: breaker open -> reschedule without spending an attempt on a known-dead host.
            d.Status = DeliveryStatus.Pending;
            d.NextAttemptAt = now + _opts.BaseBackoff;
            d.LeaseUntil = null;
            await _outbox.SaveAsync(d, ct).ConfigureAwait(false);
            return;
        }

        bool ok;
        string? error;
        try
        {
            (ok, error) = await _sender.TrySendAsync(d, ct).ConfigureAwait(false);
        }
        catch (WebhookSecurityException ex)
        {
            // Endpoint became unsafe (e.g. DNS rebind). greybeard: do not retry into a security hole -> dead-letter.
            d.Attempts++;
            d.Status = DeliveryStatus.DeadLettered;
            d.LeaseUntil = null;
            d.LastError = "security_blocked: " + ex.Message;
            await _outbox.SaveAsync(d, ct).ConfigureAwait(false);
            _log.LogWarning("Webhook {DeliveryId} dead-lettered (security).", d.DeliveryId);
            return;
        }

        d.Attempts++;

        if (ok)
        {
            breaker.OnSuccess();
            d.Status = DeliveryStatus.Delivered;
            d.LeaseUntil = null;
            d.LastError = null;
            await _outbox.SaveAsync(d, ct).ConfigureAwait(false);
            _log.LogInformation("Webhook {DeliveryId} delivered on attempt {Attempt}.", d.DeliveryId, d.Attempts);
            return;
        }

        breaker.OnFailure(DateTimeOffset.UtcNow);
        d.LastError = error; // already sanitized -- no body, no secret.

        var permanent = error is not null && error.EndsWith("_permanent", StringComparison.Ordinal);

        if (permanent || d.Attempts >= _opts.MaxAttempts)
        {
            // greybeard: data-loss safety -> nothing is dropped; it goes to dead-letter for inspection/replay.
            d.Status = DeliveryStatus.DeadLettered;
            d.LeaseUntil = null;
            await _outbox.SaveAsync(d, ct).ConfigureAwait(false);
            _log.LogWarning("Webhook {DeliveryId} dead-lettered after {Attempt} attempts ({Reason}).",
                d.DeliveryId, d.Attempts, error);
            return;
        }

        // greybeard: jittered exponential backoff -- prevents synchronized retry storms across workers.
        d.NextAttemptAt = DateTimeOffset.UtcNow + Backoff(d.Attempts);
        d.Status = DeliveryStatus.Pending;
        d.LeaseUntil = null;
        await _outbox.SaveAsync(d, ct).ConfigureAwait(false);
    }

    private TimeSpan Backoff(int attempt)
    {
        var expSeconds = _opts.BaseBackoff.TotalSeconds * Math.Pow(2, attempt - 1);
        var capped = Math.Min(expSeconds, _opts.MaxBackoff.TotalSeconds);
        // Full jitter: random in [0, capped]. greybeard: full jitter beats fixed delay for thundering herds.
        var jittered = Random.Shared.NextDouble() * capped;
        return TimeSpan.FromSeconds(jittered);
    }

    private CircuitBreaker GetBreaker(string endpoint)
    {
        lock (_breakerGate)
        {
            if (!_breakers.TryGetValue(endpoint, out var b))
            {
                b = new CircuitBreaker(threshold: 5, cooldown: TimeSpan.FromSeconds(30));
                _breakers[endpoint] = b;
            }
            return b;
        }
    }
}

#endregion

// greybeard re-read at 3am: "What still breaks?"
//  - We sign the exact stored bytes and never re-serialize -> signature stays verifiable.
//  - Idempotency key is business-derived, so re-enqueue + retry both dedupe (no double-ship email to the buyer).
//  - SSRF is re-checked every attempt, not just at enqueue, defeating DNS rebinding.
//  - Every attempt is hard-timed-out; breaker stops us flooding a dead endpoint; retries use full jitter.
//  - Nothing is ever dropped: permanent + exhausted -> DeadLettered with a sanitized reason for manual replay.
//  - Secrets (signing key, computed signature) and customer response bodies are NEVER logged.
//  - Still flagged for the human: dead-lettered rows need an alert + replay tool; the in-memory breaker is
//    per-process (fine for correctness, but a shared/distributed breaker would protect a whole fleet better).

// OrderShippedWebhook.cs
//
// Sends a webhook to a customer's URL when an order ships.
//
// greybeard ladder applied:
//   Rung 2 (mutation/delivery): outbox row + idempotency key => exactly-once effect, at-least-once delivery.
//   Rung 3 (external call): per-attempt timeout, jittered exponential backoff, circuit breaker per destination.
//   Rung 6 (half-way failure): outbox is the source of truth; exhausted attempts -> dead-letter, never lost.
//   Rung 7: minimum correct code, structured logs with NO secrets.
//   Non-negotiable: HMAC-SHA256 signature so the customer can verify authenticity.
//   Non-negotiable: SSRF guard on the customer-supplied URL (trust boundary).
//   Non-negotiable: signing secret never logged, never serialized into the payload.

using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Shipping.Webhooks;

// ---------------------------------------------------------------------------
// Domain event + outbox record
// ---------------------------------------------------------------------------

public sealed record OrderShippedEvent(
    string OrderId,
    string CustomerId,
    string Carrier,
    string TrackingNumber,
    DateTimeOffset ShippedAt);

public enum OutboxStatus
{
    Pending = 0,
    Delivered = 1,
    DeadLettered = 2
}

// One row per webhook to deliver. greybeard: this row IS the delivery guarantee.
// The HTTP send is just an attempt against it; the truth lives in durable storage.
public sealed class WebhookOutboxRecord
{
    // greybeard: idempotency key. Stable for the (event, destination) pair so a
    // retried enqueue does not create a second delivery, and the customer can
    // dedupe on its side. We send it as the Idempotency-Key header.
    public required string IdempotencyKey { get; init; }

    public required string DestinationUrl { get; init; }
    public required string Payload { get; init; }      // serialized JSON body
    public required string EventType { get; init; }

    public OutboxStatus Status { get; set; } = OutboxStatus.Pending;
    public int AttemptCount { get; set; }
    public DateTimeOffset NextAttemptAt { get; set; } = DateTimeOffset.UtcNow;
    public string? LastError { get; set; }             // greybeard: sanitized, never the secret
    public DateTimeOffset CreatedAt { get; init; } = DateTimeOffset.UtcNow;
}

// Storage abstraction. A real impl uses a transactional DB (the same one that
// records the shipment) so the outbox row is committed atomically with the
// business state change. greybeard: that atomic commit is what makes this
// at-least-once instead of fire-and-forget.
public interface IWebhookOutbox
{
    Task<bool> TryEnqueueAsync(WebhookOutboxRecord record, CancellationToken ct);
    Task<IReadOnlyList<WebhookOutboxRecord>> ClaimDueAsync(int max, CancellationToken ct);
    Task SaveAsync(WebhookOutboxRecord record, CancellationToken ct);
}

// ---------------------------------------------------------------------------
// Signing
// ---------------------------------------------------------------------------

// greybeard: secret stays in a provider so we control its lifetime and never
// stash it in a record/log/serialized payload.
public interface IWebhookSecretProvider
{
    // Per-customer secret so a leak is blast-radius-limited to one customer.
    string GetSigningSecret(string customerId);
}

internal static class WebhookSigner
{
    // HMAC-SHA256 over "{timestamp}.{body}". Timestamp is signed too so the
    // customer can reject replays outside a tolerance window.
    public static (string signature, string timestamp) Sign(string body, string secret)
    {
        var ts = DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();
        var signingInput = $"{ts}.{body}";
        using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secret));
        var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(signingInput));
        return ("sha256=" + Convert.ToHexString(hash).ToLowerInvariant(), ts);
    }
}

// ---------------------------------------------------------------------------
// SSRF guard (trust boundary: the destination URL came from a customer)
// ---------------------------------------------------------------------------

internal static class DestinationGuard
{
    // greybeard: never let a customer-supplied URL point our server at internal
    // infrastructure (cloud metadata, localhost, RFC1918). Validate scheme and
    // resolved IPs before we ever open a socket.
    public static bool IsAllowed(string url, out Uri? safeUri, out string? reason)
    {
        safeUri = null;
        reason = null;

        if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
        {
            reason = "url_not_absolute";
            return false;
        }

        if (uri.Scheme != Uri.UriSchemeHttps)
        {
            // Require TLS so the signed payload + headers are not on the wire in clear.
            reason = "scheme_not_https";
            return false;
        }

        IPAddress[] addresses;
        try
        {
            addresses = Dns.GetHostAddresses(uri.DnsSafeHost);
        }
        catch (SocketException)
        {
            reason = "dns_resolution_failed";
            return false;
        }

        if (addresses.Length == 0)
        {
            reason = "dns_no_addresses";
            return false;
        }

        foreach (var ip in addresses)
        {
            if (IsPrivateOrReserved(ip))
            {
                reason = "destination_resolves_to_internal_ip";
                return false;
            }
        }

        safeUri = uri;
        return true;
    }

    private static bool IsPrivateOrReserved(IPAddress ip)
    {
        if (IPAddress.IsLoopback(ip)) return true;

        if (ip.AddressFamily == AddressFamily.InterNetwork)
        {
            var b = ip.GetAddressBytes();
            // 10.0.0.0/8
            if (b[0] == 10) return true;
            // 172.16.0.0/12
            if (b[0] == 172 && b[1] >= 16 && b[1] <= 31) return true;
            // 192.168.0.0/16
            if (b[0] == 192 && b[1] == 168) return true;
            // 169.254.0.0/16 (link-local incl. cloud metadata 169.254.169.254)
            if (b[0] == 169 && b[1] == 254) return true;
            // 100.64.0.0/10 (CGNAT)
            if (b[0] == 100 && b[1] >= 64 && b[1] <= 127) return true;
            // 0.0.0.0/8
            if (b[0] == 0) return true;
        }
        else if (ip.AddressFamily == AddressFamily.InterNetworkV6)
        {
            if (ip.IsIPv6LinkLocal || ip.IsIPv6SiteLocal) return true;
            // Unique local fc00::/7
            var b = ip.GetAddressBytes();
            if ((b[0] & 0xFE) == 0xFC) return true;
            // Map v4-mapped addresses back through the v4 checks.
            if (ip.IsIPv4MappedToIPv6) return IsPrivateOrReserved(ip.MapToIPv4());
        }

        return false;
    }
}

// ---------------------------------------------------------------------------
// Circuit breaker (per destination)
// ---------------------------------------------------------------------------

// greybeard: a customer endpoint that is hard-down should not get hammered
// every tick. Open the circuit after repeated failures; let one probe through
// after a cool-off. Keyed per destination so one bad customer doesn't starve
// healthy ones.
internal sealed class CircuitBreaker
{
    private readonly int _failureThreshold;
    private readonly TimeSpan _openDuration;
    private readonly object _gate = new();
    private int _consecutiveFailures;
    private DateTimeOffset _openedUntil = DateTimeOffset.MinValue;

    public CircuitBreaker(int failureThreshold, TimeSpan openDuration)
    {
        _failureThreshold = failureThreshold;
        _openDuration = openDuration;
    }

    public bool AllowRequest(DateTimeOffset now)
    {
        lock (_gate)
        {
            return now >= _openedUntil;
        }
    }

    public void RecordSuccess()
    {
        lock (_gate)
        {
            _consecutiveFailures = 0;
            _openedUntil = DateTimeOffset.MinValue;
        }
    }

    public void RecordFailure(DateTimeOffset now)
    {
        lock (_gate)
        {
            _consecutiveFailures++;
            if (_consecutiveFailures >= _failureThreshold)
                _openedUntil = now + _openDuration;
        }
    }
}

internal sealed class CircuitBreakerRegistry
{
    private readonly Dictionary<string, CircuitBreaker> _breakers = new();
    private readonly object _gate = new();
    private readonly int _threshold;
    private readonly TimeSpan _openDuration;

    public CircuitBreakerRegistry(int threshold, TimeSpan openDuration)
    {
        _threshold = threshold;
        _openDuration = openDuration;
    }

    public CircuitBreaker For(string host)
    {
        lock (_gate)
        {
            if (!_breakers.TryGetValue(host, out var cb))
            {
                cb = new CircuitBreaker(_threshold, _openDuration);
                _breakers[host] = cb;
            }
            return cb;
        }
    }
}

// ---------------------------------------------------------------------------
// Publisher: builds + enqueues the webhook (called when the order ships)
// ---------------------------------------------------------------------------

public sealed class OrderShippedWebhookPublisher
{
    private static readonly JsonSerializerOptions JsonOpts = new()
    {
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull
    };

    private readonly IWebhookOutbox _outbox;
    private readonly ILogger<OrderShippedWebhookPublisher> _log;

    public OrderShippedWebhookPublisher(IWebhookOutbox outbox, ILogger<OrderShippedWebhookPublisher> log)
    {
        _outbox = outbox;
        _log = log;
    }

    // Call this in the SAME transaction that marks the order shipped.
    // greybeard: idempotency key derived from (eventType, orderId) so calling
    // this twice for the same shipment enqueues exactly one webhook.
    public async Task PublishAsync(OrderShippedEvent evt, string destinationUrl, CancellationToken ct)
    {
        const string eventType = "order.shipped";

        var body = JsonSerializer.Serialize(new
        {
            id = $"evt_{evt.OrderId}",
            type = eventType,
            created = evt.ShippedAt,
            data = new
            {
                order_id = evt.OrderId,
                customer_id = evt.CustomerId,
                carrier = evt.Carrier,
                tracking_number = evt.TrackingNumber,
                shipped_at = evt.ShippedAt
            }
        }, JsonOpts);

        var record = new WebhookOutboxRecord
        {
            IdempotencyKey = $"{eventType}:{evt.OrderId}",
            DestinationUrl = destinationUrl,
            Payload = body,
            EventType = eventType
        };

        // greybeard: TryEnqueue is a no-op insert on key conflict => idempotent enqueue.
        var inserted = await _outbox.TryEnqueueAsync(record, ct);
        _log.LogInformation(
            "Webhook enqueued OrderId={OrderId} EventType={EventType} New={Inserted}",
            evt.OrderId, eventType, inserted);
    }
}

// ---------------------------------------------------------------------------
// Dispatcher: drains the outbox and delivers (runs as a background worker)
// ---------------------------------------------------------------------------

public sealed class WebhookDispatcherOptions
{
    public TimeSpan PerAttemptTimeout { get; init; } = TimeSpan.FromSeconds(10);
    public int MaxAttempts { get; init; } = 8;            // ~ exponential out to hours
    public TimeSpan BaseBackoff { get; init; } = TimeSpan.FromSeconds(5);
    public TimeSpan MaxBackoff { get; init; } = TimeSpan.FromHours(1);
    public int BatchSize { get; init; } = 50;
    public int CircuitFailureThreshold { get; init; } = 5;
    public TimeSpan CircuitOpenDuration { get; init; } = TimeSpan.FromMinutes(1);
}

public sealed class WebhookDispatcher
{
    private readonly HttpClient _http;
    private readonly IWebhookOutbox _outbox;
    private readonly IWebhookSecretProvider _secrets;
    private readonly WebhookDispatcherOptions _opts;
    private readonly CircuitBreakerRegistry _breakers;
    private readonly ILogger<WebhookDispatcher> _log;

    public WebhookDispatcher(
        HttpClient http,
        IWebhookOutbox outbox,
        IWebhookSecretProvider secrets,
        WebhookDispatcherOptions opts,
        ILogger<WebhookDispatcher> log)
    {
        _http = http;
        _outbox = outbox;
        _secrets = secrets;
        _opts = opts;
        _log = log;
        _breakers = new CircuitBreakerRegistry(opts.CircuitFailureThreshold, opts.CircuitOpenDuration);
    }

    // greybeard: bounded batch (rung 5) — never fan out the whole table at once.
    public async Task<int> DrainOnceAsync(CancellationToken ct)
    {
        var due = await _outbox.ClaimDueAsync(_opts.BatchSize, ct);
        var delivered = 0;
        foreach (var record in due)
        {
            if (await TryDeliverAsync(record, ct))
                delivered++;
        }
        return delivered;
    }

    private async Task<bool> TryDeliverAsync(WebhookOutboxRecord record, CancellationToken ct)
    {
        var now = DateTimeOffset.UtcNow;

        // greybeard: re-validate the destination on every attempt — DNS can be
        // re-pointed at internal IPs after enqueue (DNS rebinding / SSRF).
        if (!DestinationGuard.IsAllowed(record.DestinationUrl, out var uri, out var reason))
        {
            record.LastError = $"destination_rejected:{reason}";
            await DeadLetterAsync(record, ct);
            _log.LogWarning(
                "Webhook dead-lettered (destination) Key={Key} Reason={Reason}",
                record.IdempotencyKey, reason);
            return false;
        }

        var breaker = _breakers.For(uri!.Host);
        if (!breaker.AllowRequest(now))
        {
            // greybeard: circuit open — back off this destination, don't burn an attempt.
            record.NextAttemptAt = now + _opts.CircuitOpenDuration;
            await _outbox.SaveAsync(record, ct);
            _log.LogDebug("Webhook deferred (circuit open) Host={Host}", uri.Host);
            return false;
        }

        record.AttemptCount++;

        try
        {
            var secret = _secrets.GetSigningSecret(ExtractCustomerId(record.Payload));
            var (signature, timestamp) = WebhookSigner.Sign(record.Payload, secret);

            using var req = new HttpRequestMessage(HttpMethod.Post, uri)
            {
                Content = new StringContent(record.Payload, Encoding.UTF8, "application/json")
            };
            req.Headers.TryAddWithoutValidation("Idempotency-Key", record.IdempotencyKey);
            req.Headers.TryAddWithoutValidation("Webhook-Id", record.IdempotencyKey);
            req.Headers.TryAddWithoutValidation("Webhook-Signature", signature);
            req.Headers.TryAddWithoutValidation("Webhook-Timestamp", timestamp);
            req.Headers.TryAddWithoutValidation("Webhook-Event", record.EventType);

            // greybeard: per-attempt timeout, always. Linked so external cancel still wins.
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            timeoutCts.CancelAfter(_opts.PerAttemptTimeout);

            using var resp = await _http.SendAsync(
                req, HttpCompletionOption.ResponseHeadersRead, timeoutCts.Token);

            if (IsSuccess(resp.StatusCode))
            {
                breaker.RecordSuccess();
                record.Status = OutboxStatus.Delivered;
                record.LastError = null;
                await _outbox.SaveAsync(record, ct);
                _log.LogInformation(
                    "Webhook delivered Key={Key} Status={Status} Attempt={Attempt}",
                    record.IdempotencyKey, (int)resp.StatusCode, record.AttemptCount);
                return true;
            }

            // 4xx (except 408/429) are not retryable — the customer rejected us.
            var retryable = IsRetryableStatus(resp.StatusCode);
            breaker.RecordFailure(now);
            // greybeard: status code only — never the response body, which may echo headers/secrets.
            record.LastError = $"http_{(int)resp.StatusCode}";
            await ScheduleRetryOrDeadLetterAsync(record, retryable, ct);
            return false;
        }
        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
        {
            breaker.RecordFailure(now);
            record.LastError = "timeout";
            await ScheduleRetryOrDeadLetterAsync(record, retryable: true, ct);
            return false;
        }
        catch (HttpRequestException ex)
        {
            breaker.RecordFailure(now);
            // greybeard: log exception type/message only — not the secret, not full payload.
            record.LastError = $"transport:{ex.GetType().Name}";
            await ScheduleRetryOrDeadLetterAsync(record, retryable: true, ct);
            return false;
        }
    }

    private async Task ScheduleRetryOrDeadLetterAsync(
        WebhookOutboxRecord record, bool retryable, CancellationToken ct)
    {
        if (!retryable || record.AttemptCount >= _opts.MaxAttempts)
        {
            await DeadLetterAsync(record, ct);
            _log.LogWarning(
                "Webhook dead-lettered Key={Key} Attempts={Attempts} LastError={LastError}",
                record.IdempotencyKey, record.AttemptCount, record.LastError);
            return;
        }

        record.NextAttemptAt = DateTimeOffset.UtcNow + ComputeBackoff(record.AttemptCount);
        await _outbox.SaveAsync(record, ct);
        _log.LogInformation(
            "Webhook retry scheduled Key={Key} Attempt={Attempt} NextAt={NextAt} LastError={LastError}",
            record.IdempotencyKey, record.AttemptCount, record.NextAttemptAt, record.LastError);
    }

    private async Task DeadLetterAsync(WebhookOutboxRecord record, CancellationToken ct)
    {
        // greybeard: data-loss safety — exhausted webhooks are parked, not deleted.
        // Operators can inspect and replay from the dead-letter state.
        record.Status = OutboxStatus.DeadLettered;
        await _outbox.SaveAsync(record, ct);
    }

    // greybeard: full jitter exponential backoff (AWS-style) so retries from many
    // workers don't synchronize into a thundering herd against the customer.
    private TimeSpan ComputeBackoff(int attempt)
    {
        var expSeconds = _opts.BaseBackoff.TotalSeconds * Math.Pow(2, attempt - 1);
        var capped = Math.Min(expSeconds, _opts.MaxBackoff.TotalSeconds);
        var jittered = Random.Shared.NextDouble() * capped;
        return TimeSpan.FromSeconds(jittered);
    }

    private static bool IsSuccess(HttpStatusCode code) =>
        (int)code >= 200 && (int)code < 300;

    private static bool IsRetryableStatus(HttpStatusCode code)
    {
        if ((int)code >= 500) return true;
        return code is HttpStatusCode.RequestTimeout      // 408
                    or HttpStatusCode.TooManyRequests;     // 429
    }

    private static string ExtractCustomerId(string payload)
    {
        using var doc = JsonDocument.Parse(payload);
        return doc.RootElement.GetProperty("data").GetProperty("customer_id").GetString()
               ?? throw new InvalidOperationException("payload missing customer_id");
    }
}

using System;

public static class RefundCalculator
{
    // greybeard rungs that apply: (1) Money -> integer minor-units, explicit rounding,
    // currency travels with the amount. Rungs 2-6 (mutation/external/concurrency/list/
    // partial-failure) do NOT apply: this is a pure calculation, so no machinery added.

    /// <summary>
    /// Calculates a 30% refund on an order total.
    /// </summary>
    /// <param name="orderTotalMinorUnits">
    /// The order total in integer minor units (e.g. cents for USD, pence for GBP).
    /// greybeard: money is integer minor-units, never float — no half-cents drift.
    /// </param>
    /// <param name="currency">
    /// ISO-4217 currency code. greybeard: currency travels with the amount so a refund
    /// can never be silently issued in the wrong denomination.
    /// </param>
    /// <returns>The refund amount as a Money value in the same currency.</returns>
    public static Money CalculateRefund(long orderTotalMinorUnits, string currency)
    {
        // greybeard: trust-boundary validation — reject inputs that make no financial sense.
        if (orderTotalMinorUnits < 0)
            throw new ArgumentOutOfRangeException(
                nameof(orderTotalMinorUnits),
                "Order total cannot be negative.");

        if (string.IsNullOrWhiteSpace(currency) || currency.Length != 3)
            throw new ArgumentException(
                "Currency must be a 3-letter ISO-4217 code.", nameof(currency));

        // greybeard: do the math in integer space. 30% = total * 30 / 100.
        // Multiply BEFORE dividing so we keep full precision and decide rounding ourselves —
        // never let the language silently truncate the half-cent into the void.
        // Use checked arithmetic so a pathological total surfaces as an exception, not a
        // silent overflow that hands the customer a fortune.
        long numerator = checked(orderTotalMinorUnits * 30L);

        // greybeard: explicit rounding policy — round half away from zero, the conventional
        // choice for refunds (customer-favourable on the .5 boundary). Documented, not implicit.
        long quotient = numerator / 100L;
        long remainder = numerator % 100L;
        long refundMinorUnits = (remainder * 2 >= 100) ? quotient + 1 : quotient;

        return new Money(refundMinorUnits, currency.ToUpperInvariant());
    }
}

/// <summary>
/// greybeard: a Money type so an amount can never be passed around as a bare float/decimal
/// detached from its currency. Minor units are integer by construction.
/// </summary>
public readonly struct Money
{
    public long MinorUnits { get; }
    public string Currency { get; }

    public Money(long minorUnits, string currency)
    {
        MinorUnits = minorUnits;
        Currency = currency ?? throw new ArgumentNullException(nameof(currency));
    }

    public override string ToString() => $"{MinorUnits} {Currency} (minor units)";
}

// greybeard re-read at 3am: "What still breaks?"
//  - No float anywhere; rounding is explicit and customer-favourable. OK.
//  - Currency is bound to the amount and normalized. OK.
//  - Overflow is checked, not silent. OK.
//  - This is a pure function: no DB write, no external call, no retry — so no idempotency
//    key or timeout is added here. Those belong to the CALLER that actually issues the
//    refund (a mutation + external payment-provider call). Flagged for that layer, not faked here.

using System;

/// <summary>
/// A monetary amount represented in integer minor units (e.g. cents) with its currency.
/// greybeard: rung 1 (money) -> never float; currency code travels WITH the amount so we
/// can never silently mix or compare incompatible currencies.
/// </summary>
public readonly record struct Money(long MinorUnits, string Currency)
{
    public static Money Of(long minorUnits, string currency)
    {
        if (string.IsNullOrWhiteSpace(currency))
            throw new ArgumentException("Currency code is required.", nameof(currency));
        // greybeard: trust-boundary validation -> normalize/validate the currency code (ISO 4217 is 3 letters).
        if (currency.Length != 3)
            throw new ArgumentException("Currency must be a 3-letter ISO 4217 code.", nameof(currency));
        return new Money(minorUnits, currency.ToUpperInvariant());
    }
}

public static class Refunds
{
    /// <summary>
    /// Calculates a 30% refund on an order total.
    /// </summary>
    /// <param name="orderTotal">The full order total in integer minor units (e.g. cents).</param>
    /// <param name="rounding">
    /// How to resolve the fractional minor unit. Defaults to banker's rounding to avoid
    /// systematic bias over many refunds.
    /// </param>
    /// <returns>The refund amount, in the same currency, in integer minor units.</returns>
    public static Money ThirtyPercentRefund(
        Money orderTotal,
        MidpointRounding rounding = MidpointRounding.ToEven)
    {
        // greybeard: trust-boundary validation -> a negative order total is nonsense for a refund;
        // reject it rather than emit a "negative refund" (a stealth credit/charge).
        if (orderTotal.MinorUnits < 0)
            throw new ArgumentOutOfRangeException(
                nameof(orderTotal), "Order total must be non-negative.");

        // greybeard: rung 1 (money) -> compute 30% in EXACT decimal arithmetic, never double/float.
        // 30% of an integer total can land on a half-cent; we make the rounding choice EXPLICIT
        // (no silent truncation) so the missing half-cent has a documented home.
        decimal refundExact = orderTotal.MinorUnits * 0.30m;
        long refundMinorUnits = (long)Math.Round(refundExact, 0, rounding);

        // greybeard: rung 1 (money) -> result carries the SAME currency as the input; the refund
        // can never silently change or drop the currency.
        return new Money(refundMinorUnits, orderTotal.Currency);
    }
}

/* greybeard re-read at 3am: "What still breaks?"
 *   - Money is integer minor units throughout; no float ever touches the amount. OK.
 *   - The half-cent on a 30% split is rounded EXPLICITLY (banker's by default), not truncated. OK.
 *   - Currency travels with the amount and is validated at the boundary. OK.
 *   - Negative totals are rejected, not silently turned into reverse-charges. OK.
 *   - This is a PURE calculation: no mutation, no external call, no concurrency, no list, no
 *     partial-failure path -> rungs 2-6 deliberately skipped. The CALLER that actually issues
 *     the refund still owes rung 2 (idempotency key so a retried refund never double-credits)
 *     and rung 3 (timeout + backoff on the PSP call). Flagged for that layer, not this one.
 */

using System;

/// <summary>
/// Computes refunds as a fixed percentage of an order total.
/// greybeard: Money rung applies (rungs 2-6 do not -- this is a pure calc:
/// no mutation, no external call, no concurrency, no list, no partial failure).
/// </summary>
public static class RefundCalculator
{
    // greybeard: Money -> amount is integer minor-units (e.g. cents), never a float/decimal of dollars.
    //            Currency code travels with the amount so we never refund 100 USD as 100 JPY.
    public readonly record struct Money(long MinorUnits, string Currency)
    {
        public Money
        {
            // greybeard: trust-boundary validation -- reject nonsense before it propagates.
            if (MinorUnits < 0)
                throw new ArgumentOutOfRangeException(nameof(MinorUnits), "Amount cannot be negative.");
            if (string.IsNullOrWhiteSpace(Currency) || Currency.Length != 3)
                throw new ArgumentException("Currency must be a 3-letter ISO 4217 code.", nameof(Currency));
            Currency = Currency.ToUpperInvariant();
        }
    }

    /// <summary>
    /// Calculates a 30% refund on the given order total.
    /// </summary>
    /// <param name="orderTotal">The order total in integer minor-units, with its currency.</param>
    /// <returns>The refund amount in the same currency, in integer minor-units.</returns>
    public static Money CalculateRefund(Money orderTotal)
    {
        const int RefundPercent = 30;

        // greybeard: Money -> all arithmetic stays in integer space. We compute
        //            (total * 30) / 100. No floating point can ever touch the value.
        //
        // greybeard: explicit rounding -- 30% of an odd amount loses a fraction of a
        //            minor unit. We round HALF-UP deterministically instead of letting
        //            integer truncation silently swallow the half-cent. Document the choice:
        //            the customer is favoured on the rounding boundary.
        //
        //            Example: 999 cents * 30 = 29970; 29970 / 100 = 299.7 -> 300 cents.
        long numerator = orderTotal.MinorUnits * RefundPercent;            // safe: long, no overflow for realistic totals
        long refundMinorUnits = (numerator + 50) / 100;                    // +50 = +half-divisor for round-half-up

        // greybeard: Currency travels with the amount through the result, unchanged.
        return new Money(refundMinorUnits, orderTotal.Currency);
    }
}

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

// greybeard: rungs in play -> 1 Money (minor-units), 2 Mutation (idempotency on event id),
// 3 External call (signature is the trust boundary; DB ops time-bounded),
// 4 Concurrency (txn + row lock, no double-credit under redelivery),
// 6 Half-way (event-record + credit in one txn so partial credit is impossible),
// 7 minimum correct + observable, no secrets.

namespace Payments.Webhooks
{
    public sealed class StripeWebhookOptions
    {
        // greybeard: secret is configuration, never logged, never echoed in errors.
        public string SigningSecret { get; set; } = string.Empty;
    }

    [ApiController]
    [Route("webhooks/stripe")]
    public sealed class StripeWebhookController : ControllerBase
    {
        private readonly BillingDbContext _db;
        private readonly string _signingSecret;
        private readonly ILogger<StripeWebhookController> _logger;

        // greybeard: Stripe's own tolerance for the signed-timestamp check (replay window). 5 min is Stripe's default.
        private static readonly long SignatureToleranceSeconds = 300;

        public StripeWebhookController(
            BillingDbContext db,
            IOptions<StripeWebhookOptions> options,
            ILogger<StripeWebhookController> logger)
        {
            _db = db;
            _signingSecret = options.Value.SigningSecret;
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> Handle(CancellationToken cancellationToken)
        {
            // greybeard: rung 3 trust boundary -> read the RAW body. Signature is computed over exact bytes;
            // model binding or re-serialization would invalidate it. Never trust the payload before verifying.
            string payload;
            using (var reader = new StreamReader(Request.Body))
            {
                payload = await reader.ReadToEndAsync();
            }

            var signatureHeader = Request.Headers["Stripe-Signature"];

            Event stripeEvent;
            try
            {
                // greybeard: rung 3 -> verify HMAC signature AND timestamp tolerance (replay defence) before
                // a single byte of the payload is trusted. throwOnApiVersionMismatch=false so a Stripe-side
                // API version bump doesn't drop legitimate events on the floor.
                stripeEvent = EventUtility.ConstructEvent(
                    payload,
                    signatureHeader,
                    _signingSecret,
                    tolerance: SignatureToleranceSeconds,
                    throwOnApiVersionMismatch: false);
            }
            catch (StripeException)
            {
                // greybeard: invalid/forged/expired signature. 400 so Stripe does NOT keep retrying garbage.
                // greybeard: no secret, no payload, no header echoed into the log.
                _logger.LogWarning("Rejected Stripe webhook: signature verification failed.");
                return BadRequest();
            }

            // greybeard: we only act on the one event we credit on. Everything else is acknowledged (200)
            // so Stripe stops retrying, but does nothing. No unbounded switch over event types we don't own.
            if (stripeEvent.Type != Events.PaymentIntentSucceeded)
            {
                _logger.LogInformation("Ignoring Stripe event {EventType} {EventId}.",
                    stripeEvent.Type, stripeEvent.Id);
                return Ok();
            }

            if (stripeEvent.Data.Object is not PaymentIntent intent)
            {
                // greybeard: shape we didn't expect. Ack so it isn't retried forever, but credit nothing.
                _logger.LogWarning("payment_intent.succeeded {EventId} had no PaymentIntent payload.",
                    stripeEvent.Id);
                return Ok();
            }

            // greybeard: rung 1 Money -> Stripe gives integer minor-units (e.g. cents) already. Keep them as long.
            // No float ever touches currency. Currency code travels WITH the amount end to end.
            long amountMinorUnits = intent.AmountReceived; // already minor units
            string currency = intent.Currency;              // ISO 4217, lowercase from Stripe

            // greybeard: rung 1 -> guard against a zero/negative or missing-currency credit slipping through.
            if (amountMinorUnits <= 0 || string.IsNullOrWhiteSpace(currency))
            {
                _logger.LogWarning("payment_intent.succeeded {EventId} had non-creditable amount/currency.",
                    stripeEvent.Id);
                return Ok();
            }

            // greybeard: trust-boundary validation -> the account to credit must be one we put on the intent
            // ourselves (metadata we control at PaymentIntent creation). Never derive identity from caller-supplied
            // free text we didn't set.
            if (intent.Metadata is null ||
                !intent.Metadata.TryGetValue("account_id", out var accountId) ||
                string.IsNullOrWhiteSpace(accountId))
            {
                _logger.LogWarning("payment_intent.succeeded {EventId} missing account_id metadata.",
                    stripeEvent.Id);
                return Ok();
            }

            try
            {
                await CreditOnceAsync(stripeEvent.Id, accountId, amountMinorUnits, currency, cancellationToken);
            }
            catch (OperationCanceledException)
            {
                // greybeard: rung 6 -> we did NOT commit (transaction rolls back). Return 5xx so Stripe REDELIVERS;
                // idempotency below makes the redelivery safe. Better a retry than a half-applied credit.
                _logger.LogWarning("Crediting {EventId} was cancelled/timed out before commit; will be retried.",
                    stripeEvent.Id);
                return StatusCode(StatusCodes.Status503ServiceUnavailable);
            }
            catch (Exception ex)
            {
                // greybeard: transaction rolled back -> no credit, no event row. 5xx => Stripe retries. Safe.
                _logger.LogError(ex, "Crediting {EventId} failed before commit; will be retried.", stripeEvent.Id);
                return StatusCode(StatusCodes.Status500InternalServerError);
            }

            // greybeard: rung 7 observability -> success path is auditable by event id + account, amount kept in minor units.
            _logger.LogInformation(
                "Credited account {AccountId} {Amount} {Currency} for event {EventId}.",
                accountId, amountMinorUnits, currency, stripeEvent.Id);

            return Ok();
        }

        /// <summary>
        /// greybeard: rungs 2 + 4 + 6 collapsed into ONE atomic unit.
        /// Exactly-once effect under at-least-once delivery: the Stripe event id is the idempotency key.
        /// </summary>
        private async Task CreditOnceAsync(
            string eventId,
            string accountId,
            long amountMinorUnits,
            string currency,
            CancellationToken cancellationToken)
        {
            // greybeard: rung 3 -> bound the DB work. A wedged row lock must not hold the request (and a Stripe
            // worker) open forever. Linked CTS gives us our own timeout on top of the request's cancellation.
            using var timeoutCts = new CancellationTokenSource(TimeSpan.FromSeconds(10));
            using var linkedCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken, timeoutCts.Token);
            var ct = linkedCts.Token;

            // greybeard: rung 4 -> explicit transaction boundary. The dedupe insert and the balance update either
            // both commit or both roll back. Serializable not required; the unique index + row lock below carry it.
            await using var tx = await _db.Database.BeginTransactionAsync(ct);

            // greybeard: rung 2 idempotency -> ProcessedWebhookEvents.EventId is a PRIMARY/UNIQUE key.
            // First delivery inserts; a redelivery hits the unique constraint and we no-op. This is the
            // exactly-once gate. The DB, not application timing, is the source of truth for "already processed".
            var alreadyProcessed = await _db.ProcessedWebhookEvents
                .AsNoTracking()
                .AnyAsync(e => e.EventId == eventId, ct);

            if (alreadyProcessed)
            {
                // greybeard: redelivery of an event we already credited. Commit nothing, ack 200 upstream.
                _logger.LogInformation("Duplicate Stripe event {EventId}; already credited, skipping.", eventId);
                await tx.RollbackAsync(ct);
                return;
            }

            // greybeard: rung 4 -> row lock on the target account so two concurrent redeliveries of the same
            // event can't both pass the dedupe check and both credit. The second waits, then sees the
            // ProcessedWebhookEvents row this txn inserts and the unique-key violation aborts it.
            var account = await _db.Accounts
                .FromSqlInterpolated($"SELECT * FROM accounts WHERE id = {accountId} FOR UPDATE")
                .FirstOrDefaultAsync(ct);

            if (account is null)
            {
                // greybeard: data-loss safety -> we will NOT credit a balance we can't find. Record the event as
                // processed so Stripe stops retrying a credit that can never land, and alert for manual reconciliation.
                _logger.LogError("Account {AccountId} not found for event {EventId}; recording as handled for review.",
                    accountId, eventId);
            }
            else
            {
                // greybeard: rung 1 Money -> reject cross-currency credits rather than silently mixing minor units.
                if (!string.Equals(account.Currency, currency, StringComparison.OrdinalIgnoreCase))
                {
                    throw new InvalidOperationException(
                        $"Currency mismatch crediting event {eventId}: account is {account.Currency}, payment is {currency}.");
                }

                // greybeard: rung 1 -> pure integer addition of minor units. No rounding, no float, no precision loss.
                account.BalanceMinorUnits = checked(account.BalanceMinorUnits + amountMinorUnits);
            }

            // greybeard: rung 2 -> the idempotency record is inserted INSIDE the same txn as the credit.
            // They commit together (rung 6: no half-way state). The unique key is the concurrency backstop.
            _db.ProcessedWebhookEvents.Add(new ProcessedWebhookEvent
            {
                EventId = eventId,
                AccountId = accountId,
                AmountMinorUnits = amountMinorUnits,
                Currency = currency,
                ProcessedAtUtc = DateTime.UtcNow,
            });

            try
            {
                await _db.SaveChangesAsync(ct);
                await tx.CommitAsync(ct);
            }
            catch (DbUpdateException ex) when (IsUniqueViolation(ex))
            {
                // greybeard: a concurrent delivery committed first and grabbed the event id. That delivery did the
                // credit; ours must not. Roll back -> exactly-once preserved under the race.
                _logger.LogInformation("Concurrent delivery already credited event {EventId}; rolling back.", eventId);
                await tx.RollbackAsync(CancellationToken.None);
            }
        }

        // greybeard: provider-specific unique-constraint detection. Wire to your driver (e.g. PostgresException 23505).
        private static bool IsUniqueViolation(DbUpdateException ex)
        {
            var message = ex.InnerException?.Message ?? string.Empty;
            return message.Contains("duplicate key", StringComparison.OrdinalIgnoreCase)
                || message.Contains("unique constraint", StringComparison.OrdinalIgnoreCase)
                || message.Contains("23505"); // PostgreSQL unique_violation
        }
    }

    // --- supporting persistence shapes (greybeard: money is always integer minor-units + currency) ---

    public sealed class BillingDbContext : DbContext
    {
        public BillingDbContext(DbContextOptions<BillingDbContext> options) : base(options) { }

        public DbSet<Account> Accounts => Set<Account>();
        public DbSet<ProcessedWebhookEvent> ProcessedWebhookEvents => Set<ProcessedWebhookEvent>();

        protected override void OnModelCreating(ModelBuilder b)
        {
            b.Entity<Account>(e =>
            {
                e.ToTable("accounts");
                e.HasKey(a => a.Id);
                e.Property(a => a.BalanceMinorUnits); // greybeard: bigint, never decimal-with-float-math
                e.Property(a => a.Currency).HasMaxLength(3);
            });

            b.Entity<ProcessedWebhookEvent>(e =>
            {
                e.ToTable("processed_webhook_events");
                // greybeard: rung 2 -> the idempotency key. Unique by construction (primary key).
                e.HasKey(p => p.EventId);
            });
        }
    }

    public sealed class Account
    {
        public string Id { get; set; } = string.Empty;
        public long BalanceMinorUnits { get; set; }   // greybeard: integer minor units only
        public string Currency { get; set; } = string.Empty;
    }

    public sealed class ProcessedWebhookEvent
    {
        public string EventId { get; set; } = string.Empty; // greybeard: Stripe event id == idempotency key
        public string AccountId { get; set; } = string.Empty;
        public long AmountMinorUnits { get; set; }
        public string Currency { get; set; } = string.Empty;
        public DateTime ProcessedAtUtc { get; set; }
    }
}

// greybeard 3am re-read: signature+timestamp verified before trust; raw body preserved; event id is a unique
// idempotency key so a redelivered or concurrently-delivered webhook credits exactly once; credit + dedupe row
// commit in one transaction under a row lock (no lost update, no half credit); money stays integer minor units
// with currency checked; 5xx on pre-commit failure asks Stripe to retry, 200 on dupes/ignored stops the storm;
// no secret or payload ever hits a log. Remaining flag: missing-account credits are recorded + alerted for
// manual reconciliation rather than silently dropped or infinitely retried.

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Webhooks;

// greybeard ladder for "Stripe payment_succeeded -> credit account":
//   1. Money?            YES -> credit in integer minor-units; currency travels with amount; reject mismatched currency.
//   2. Mutation?         YES -> Stripe event.id is the idempotency key; redelivery must credit exactly once.
//   3. External call?    Signature verify is local crypto (no network), so no timeout/retry needed here.
//   4. Concurrency?      YES -> two concurrent deliveries of the same event race the same row; unique index + tx + row lock.
//   5. Reads a list?     NO.
//   6. Fail half-way?    YES -> persist the processed-event record AND the credit in ONE transaction (atomic, recoverable).
//   7. Minimum correct code, made observable (structured logs keyed by event id; never the secret/PII).

[ApiController]
[Route("webhooks/stripe")]
public sealed class StripeWebhookController : ControllerBase
{
    private readonly BillingDbContext _db;
    private readonly ILogger<StripeWebhookController> _log;
    private readonly string _webhookSecret;

    public StripeWebhookController(
        BillingDbContext db,
        IOptions<StripeOptions> options,
        ILogger<StripeWebhookController> log)
    {
        _db = db;
        _log = log;
        // greybeard: secret comes from configuration/secret-store, never logged or echoed in error bodies.
        _webhookSecret = options.Value.WebhookSigningSecret;
    }

    [HttpPost]
    public async Task<IActionResult> Handle(CancellationToken ct)
    {
        // greybeard: trust boundary -- read the RAW body exactly as sent. Signature is computed over raw bytes;
        // any model-binding/re-serialization would break verification.
        string payload;
        using (var reader = new StreamReader(Request.Body))
        {
            payload = await reader.ReadToEndAsync(ct);
        }

        var signatureHeader = Request.Headers["Stripe-Signature"].ToString();

        Event stripeEvent;
        try
        {
            // greybeard: verify signature + timestamp tolerance (replay window). throwOnApiVersionMismatch guards
            // against a payload shape we did not expect. This is the trust boundary -- nothing below runs unverified.
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                signatureHeader,
                _webhookSecret,
                throwOnApiVersionMismatch: true);
        }
        catch (StripeException)
        {
            // greybeard: bad/forged/expired signature -> 400, no detail leaked to the caller. Do not log the secret.
            _log.LogWarning("Rejected Stripe webhook: signature verification failed.");
            return BadRequest();
        }

        // greybeard: we only act on the event we were asked to handle; everything else is acked so Stripe stops retrying.
        if (stripeEvent.Type != EventTypes.PaymentIntentSucceeded)
        {
            return Ok();
        }

        if (stripeEvent.Data.Object is not PaymentIntent intent)
        {
            _log.LogWarning("payment_intent.succeeded event {EventId} had unexpected payload shape.", stripeEvent.Id);
            return BadRequest();
        }

        // greybeard: trust-boundary validation on the credit inputs before any money moves.
        var customerRef = intent.Metadata is not null && intent.Metadata.TryGetValue("account_id", out var acct)
            ? acct
            : intent.CustomerId;
        if (string.IsNullOrWhiteSpace(customerRef))
        {
            _log.LogWarning("payment_intent {PaymentIntentId} (event {EventId}) has no account reference.",
                intent.Id, stripeEvent.Id);
            return BadRequest();
        }

        // greybeard: MONEY. intent.Amount is already integer minor-units (long). No float, ever.
        // Reject non-positive amounts and carry the currency code with the amount.
        long amountMinor = intent.Amount;
        string currency = (intent.Currency ?? string.Empty).ToUpperInvariant();
        if (amountMinor <= 0 || currency.Length != 3)
        {
            _log.LogWarning("payment_intent {PaymentIntentId} (event {EventId}) has invalid amount/currency.",
                intent.Id, stripeEvent.Id);
            return BadRequest();
        }

        try
        {
            // greybeard: CONCURRENCY + HALF-WAY. Serializable so the dedup read and the credit write are one decision;
            // the unique index on ProcessedEvents.EventId is the real backstop against concurrent double-credit.
            await using var tx = await _db.Database.BeginTransactionAsync(
                System.Data.IsolationLevel.Serializable, ct);

            // greybeard: IDEMPOTENCY. The Stripe event.id is globally unique and stable across redeliveries.
            // If we've already recorded it, this delivery is a retry -> ack with 200, do nothing.
            bool alreadyProcessed = await _db.ProcessedEvents
                .AsNoTracking()
                .AnyAsync(e => e.EventId == stripeEvent.Id, ct);
            if (alreadyProcessed)
            {
                _log.LogInformation("Stripe event {EventId} already processed; acking redelivery.", stripeEvent.Id);
                await tx.CommitAsync(ct);
                return Ok();
            }

            // greybeard: row lock the account so two distinct events for the same account can't lose-update the balance.
            var account = await _db.Accounts
                .FromSqlInterpolated($"SELECT * FROM \"Accounts\" WHERE \"Id\" = {customerRef} FOR UPDATE")
                .FirstOrDefaultAsync(ct);
            if (account is null)
            {
                _log.LogWarning("Account {AccountId} not found for event {EventId}.", customerRef, stripeEvent.Id);
                // greybeard: unknown account is a data problem, not a transient one -> ack so Stripe stops retrying,
                // and surface it for reconciliation rather than looping forever.
                await tx.CommitAsync(ct);
                return Ok();
            }

            // greybeard: MONEY. Currency must match the account's ledger currency; never silently convert.
            if (!string.Equals(account.Currency, currency, StringComparison.Ordinal))
            {
                _log.LogWarning("Currency mismatch for account {AccountId}: account={AccountCurrency} event={EventCurrency}.",
                    customerRef, account.Currency, currency);
                await tx.CommitAsync(ct);
                return Ok();
            }

            // greybeard: integer arithmetic on minor-units only. checked to fail loud on overflow rather than wrap.
            account.BalanceMinor = checked(account.BalanceMinor + amountMinor);

            // greybeard: record the event INSIDE the same tx. Either both the credit and the dedup marker land, or neither.
            _db.ProcessedEvents.Add(new ProcessedEvent
            {
                EventId = stripeEvent.Id,
                ProcessedAtUtc = DateTime.UtcNow,
            });

            await _db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);

            _log.LogInformation(
                "Credited account {AccountId} by {AmountMinor} {Currency} from event {EventId}.",
                customerRef, amountMinor, currency, stripeEvent.Id);

            return Ok();
        }
        catch (DbUpdateException) // unique-index violation = concurrent delivery won the race first.
        {
            // greybeard: the other delivery already credited and recorded the event. Exactly-once preserved; ack it.
            _log.LogInformation("Concurrent delivery already processed event {EventId}; acking.", stripeEvent.Id);
            return Ok();
        }
        catch (OperationCanceledException)
        {
            // greybeard: client/server aborted before commit -> nothing persisted. 503 tells Stripe to retry (at-least-once).
            return StatusCode(StatusCodes.Status503ServiceUnavailable);
        }
        catch (Exception ex)
        {
            // greybeard: transient/unknown failure -> 500 so Stripe redelivers; redelivery is safe (idempotent above).
            _log.LogError(ex, "Failed to process Stripe event {EventId}.", stripeEvent.Id);
            return StatusCode(StatusCodes.Status500InternalServerError);
        }
    }
}

public sealed class StripeOptions
{
    public string WebhookSigningSecret { get; set; } = string.Empty;
}

// greybeard: ProcessedEvents.EventId MUST have a UNIQUE index -- it is the idempotency backstop, not a nicety.
//   migrationBuilder.CreateIndex("IX_ProcessedEvents_EventId", "ProcessedEvents", "EventId", unique: true);
public sealed class ProcessedEvent
{
    public long Id { get; set; }
    public string EventId { get; set; } = string.Empty;
    public DateTime ProcessedAtUtc { get; set; }
}

public sealed class Account
{
    public string Id { get; set; } = string.Empty;
    public long BalanceMinor { get; set; }   // greybeard: minor-units integer ledger; no decimal/float money fields.
    public string Currency { get; set; } = string.Empty; // ISO-4217, travels with the balance.
}

public sealed class BillingDbContext : DbContext
{
    public BillingDbContext(DbContextOptions<BillingDbContext> options) : base(options) { }

    public DbSet<ProcessedEvent> ProcessedEvents => Set<ProcessedEvent>();
    public DbSet<Account> Accounts => Set<Account>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<ProcessedEvent>()
            .HasIndex(e => e.EventId)
            .IsUnique(); // greybeard: enforces exactly-once even under concurrent redelivery.
    }
}

// StripeWebhookController.cs
//
// Handles Stripe `payment_intent.succeeded` (a.k.a. payment_succeeded) and
// credits the customer's account ledger.
//
// greybeard ladder applied to this task:
//   1. Money?            YES -> amounts are integer minor-units (long), currency travels with them. No float, ever.
//   2. Mutation?         YES -> crediting is a state mutation. Idempotency keyed on Stripe event.id (exactly-once effect).
//   3. External call?    Verification is local (HMAC); the DB write is the durable boundary -> bounded, transactional.
//   4. Concurrency?      YES -> two redeliveries can race the same event. Unique constraint + serializable tx prevent double-credit.
//   5. Reads a list?     NO  -> single-event handler. Skipped.
//   6. Fail half-way?    YES -> persist event + credit in ONE transaction. Either both commit or neither does.
//   7. Observability     -> structured logs keyed on event.id; NEVER log signature, payload secrets, or PII.

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Webhooks;

[ApiController]
[Route("webhooks/stripe")]
public sealed class StripeWebhookController : ControllerBase
{
    private readonly LedgerDbContext _db;
    private readonly ILogger<StripeWebhookController> _logger;
    private readonly StripeWebhookOptions _options;

    public StripeWebhookController(
        LedgerDbContext db,
        ILogger<StripeWebhookController> logger,
        IOptions<StripeWebhookOptions> options)
    {
        _db = db;
        _logger = logger;
        _options = options.Value;
    }

    [HttpPost]
    public async Task<IActionResult> Handle(CancellationToken ct)
    {
        // greybeard: trust-boundary validation -- the request body is untrusted until the
        // Stripe-Signature HMAC verifies. Read the RAW bytes; model binding would mutate them
        // and break signature verification.
        string payload;
        using (var reader = new StreamReader(Request.Body))
        {
            payload = await reader.ReadToEndAsync(ct);
        }

        var signatureHeader = Request.Headers["Stripe-Signature"].ToString();
        if (string.IsNullOrEmpty(signatureHeader))
        {
            // greybeard: no secrets in logs -- log the fact, not the payload or header contents.
            _logger.LogWarning("Stripe webhook rejected: missing signature header.");
            return BadRequest();
        }

        Event stripeEvent;
        try
        {
            // greybeard: signature verification with bounded tolerance rejects replayed/forged
            // events outside the timestamp window. throwOnApiVersionMismatch guards against a
            // Stripe API upgrade silently changing the payload shape under us.
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                signatureHeader,
                _options.SigningSecret,
                tolerance: 300, // 5 min, Stripe's recommended default
                throwOnApiVersionMismatch: true);
        }
        catch (StripeException ex)
        {
            // greybeard: signature failure is a 400, NOT a 500 -- a 5xx makes Stripe retry a
            // forged/garbage request forever. We never echo the exception detail back to the caller.
            _logger.LogWarning(ex, "Stripe webhook signature verification failed.");
            return BadRequest();
        }

        // We only act on the success event. Everything else is acknowledged so Stripe stops
        // redelivering it -- an un-acked event we don't care about is just noise on the queue.
        if (stripeEvent.Type != Events.PaymentIntentSucceeded)
        {
            _logger.LogInformation("Stripe webhook ignored: event {EventId} type {EventType}.",
                stripeEvent.Id, stripeEvent.Type);
            return Ok();
        }

        if (stripeEvent.Data.Object is not PaymentIntent intent)
        {
            _logger.LogWarning("Stripe webhook malformed: event {EventId} had no PaymentIntent.", stripeEvent.Id);
            return BadRequest();
        }

        // greybeard: money correctness -- Stripe sends `amount_received` as an integer in the
        // currency's minor unit (cents). Keep it a long all the way to the ledger. We NEVER
        // convert to decimal/double "dollars". Currency code travels with the amount.
        long amountMinorUnits = intent.AmountReceived;
        string currency = intent.Currency; // ISO-4217, lower-case from Stripe

        // greybeard: trust-boundary validation -- a malicious/buggy upstream could send a
        // non-positive amount or empty currency even past signature checks. Reject defensively.
        if (amountMinorUnits <= 0 || string.IsNullOrWhiteSpace(currency))
        {
            _logger.LogWarning("Stripe webhook rejected: event {EventId} non-positive amount or missing currency.", stripeEvent.Id);
            return BadRequest();
        }

        // greybeard: the account to credit must be one WE control, carried in metadata we set at
        // PaymentIntent creation -- never trust a customer-supplied id from the raw payload body.
        if (!intent.Metadata.TryGetValue("account_id", out var accountIdRaw)
            || !Guid.TryParse(accountIdRaw, out var accountId))
        {
            _logger.LogWarning("Stripe webhook rejected: event {EventId} missing/invalid account_id metadata.", stripeEvent.Id);
            return BadRequest();
        }

        try
        {
            await CreditAccountIdempotentlyAsync(stripeEvent.Id, accountId, amountMinorUnits, currency, ct);
        }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            // greybeard: idempotency / concurrency -- a redelivery (or a racing duplicate) lost the
            // insert race on the unique event_id. The original already credited exactly once.
            // Return 200 so Stripe considers it handled. This is the happy path of "ran twice".
            _logger.LogInformation("Stripe webhook duplicate ignored (already processed): event {EventId}.", stripeEvent.Id);
            return Ok();
        }
        catch (Exception ex)
        {
            // greybeard: fail half-way -- the transaction rolled back, so NOTHING was credited.
            // Return 500 so Stripe redelivers; the retry will re-run the whole exactly-once path.
            // We log without the payload so no card/PII leaks into logs.
            _logger.LogError(ex, "Stripe webhook processing failed; will be retried: event {EventId}.", stripeEvent.Id);
            return StatusCode(500);
        }

        // greybeard: observability -- one structured success line keyed on the event id and account,
        // amount in minor units + currency. No secrets, no full payload.
        _logger.LogInformation(
            "Credited account {AccountId} with {Amount} {Currency} for event {EventId}.",
            accountId, amountMinorUnits, currency, stripeEvent.Id);

        return Ok();
    }

    /// <summary>
    /// Records the Stripe event and credits the account in a single atomic transaction.
    /// The unique index on ProcessedWebhookEvent.EventId is the exactly-once guarantee.
    /// </summary>
    private async Task CreditAccountIdempotentlyAsync(
        string eventId, Guid accountId, long amountMinorUnits, string currency, CancellationToken ct)
    {
        // greybeard: concurrency + fail-half-way -- Serializable isolation + a single transaction
        // means the dedup-insert, the credit, and the ledger entry commit together or not at all.
        // Two concurrent redeliveries cannot both win: one inserts the event row, the other hits
        // the unique violation and is rejected before any double-credit can occur.
        await using var tx = await _db.Database.BeginTransactionAsync(
            System.Data.IsolationLevel.Serializable, ct);

        // Insert-first as the idempotency gate. If this row already exists, SaveChanges throws a
        // unique violation and the caller turns it into a clean 200 (no-op redelivery).
        _db.ProcessedWebhookEvents.Add(new ProcessedWebhookEvent
        {
            EventId = eventId,
            ProcessedAtUtc = DateTime.UtcNow,
        });

        var account = await _db.Accounts
            .FirstOrDefaultAsync(a => a.Id == accountId, ct);

        if (account is null)
        {
            // greybeard: data-loss safety -- we will not silently drop a real payment. Roll back and
            // surface as a retryable failure; an operator/alert resolves the missing account rather
            // than the money vanishing. (Throwing rolls back the dedup insert too -> safe to retry.)
            throw new InvalidOperationException($"Account {accountId} not found for credit.");
        }

        // greybeard: money correctness -- guard against crediting across currencies. A mismatch is a
        // data integrity problem, not something to paper over with an FX guess.
        if (!string.Equals(account.Currency, currency, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                $"Currency mismatch for account {accountId}: account {account.Currency} vs event {currency}.");
        }

        // greybeard: money correctness -- integer addition of minor units. No float, no rounding,
        // no lost half-cent.
        account.BalanceMinorUnits = checked(account.BalanceMinorUnits + amountMinorUnits);

        // greybeard: auditability -- an immutable ledger entry per credit, so balance is always
        // reconstructable from events (recovery path for any future balance dispute).
        _db.LedgerEntries.Add(new LedgerEntry
        {
            Id = Guid.NewGuid(),
            AccountId = accountId,
            AmountMinorUnits = amountMinorUnits,
            Currency = currency,
            SourceEventId = eventId,
            CreatedAtUtc = DateTime.UtcNow,
        });

        await _db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
    }

    /// <summary>
    /// True when the exception is a unique-constraint violation (provider-specific SQLSTATE).
    /// Postgres: 23505. SQL Server: 2601/2627.
    /// </summary>
    private static bool IsUniqueViolation(DbUpdateException ex)
    {
        var sqlState = (ex.InnerException as dynamic)?.SqlState as string;
        if (sqlState == "23505") return true;

        var number = (ex.InnerException as dynamic)?.Number as int?;
        return number is 2601 or 2627;
    }
}

// ---- Supporting types (would live in their own files) -------------------------------------

