// OrderShippedWebhook.cs
//
// Sends a webhook to a customer's URL when an order ships.
//
// Reliability: bounded retries with exponential backoff + jitter, per-attempt
// timeout, and retry only on transient failures (5xx / 429 / network errors).
// Security: HMAC-SHA256 signature over the raw body so the customer can verify
// authenticity, a timestamp to limit replay, HTTPS-only enforcement, and a
// capped redirect/response policy.
//
// YAGNI note: this is the minimum that is actually reliable and secure using
// only the BCL. There is intentionally no message broker, no DB outbox, and no
// background service here — add those at the call site only if you need
// durability across process crashes. This class does the HTTP delivery well.

using System;
using System.Net;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Shipping.Webhooks;

/// <summary>Payload sent when an order ships.</summary>
public sealed record OrderShippedEvent(
    string OrderId,
    string Carrier,
    string TrackingNumber,
    DateTimeOffset ShippedAt);

/// <summary>Result of a delivery attempt.</summary>
public sealed record WebhookResult(bool Delivered, int Attempts, string? Error);

public sealed class OrderShippedWebhookSender
{
    private readonly HttpClient _http;
    private readonly byte[] _signingKey;
    private readonly int _maxAttempts;
    private readonly TimeSpan _baseDelay;

    private static readonly JsonSerializerOptions JsonOpts = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    /// <param name="http">
    /// A long-lived HttpClient (inject via IHttpClientFactory). Its Timeout is
    /// used as the per-attempt timeout, so set it to something small (e.g. 10s).
    /// </param>
    /// <param name="signingSecret">
    /// Shared secret used to HMAC-sign the body. Give each customer their own.
    /// </param>
    public OrderShippedWebhookSender(
        HttpClient http,
        string signingSecret,
        int maxAttempts = 5,
        TimeSpan? baseDelay = null)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        if (string.IsNullOrEmpty(signingSecret))
            throw new ArgumentException("A signing secret is required.", nameof(signingSecret));

        _signingKey = Encoding.UTF8.GetBytes(signingSecret);
        _maxAttempts = Math.Max(1, maxAttempts);
        _baseDelay = baseDelay ?? TimeSpan.FromSeconds(1);
    }

    /// <summary>
    /// Delivers the event to the customer's webhook URL, retrying transient
    /// failures. Returns a result instead of throwing for delivery failures so
    /// the caller can decide whether to dead-letter the message.
    /// </summary>
    public async Task<WebhookResult> SendAsync(
        Uri customerUrl,
        OrderShippedEvent evt,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(customerUrl);
        ArgumentNullException.ThrowIfNull(evt);

        // Security: never send a signed secret-bearing request over plaintext.
        if (customerUrl.Scheme != Uri.UriSchemeHttps)
            throw new ArgumentException("Webhook URL must use HTTPS.", nameof(customerUrl));

        // Serialize once so the bytes we sign are exactly the bytes we send.
        byte[] body = JsonSerializer.SerializeToUtf8Bytes(evt, JsonOpts);

        long timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        string signature = Sign(timestamp, body);

        // Idempotency key lets the customer dedupe retries of the same delivery.
        string idempotencyKey = $"{evt.OrderId}:{timestamp}";

        string? lastError = null;

        for (int attempt = 1; attempt <= _maxAttempts; attempt++)
        {
            cancellationToken.ThrowIfCancellationRequested();

            try
            {
                using var request = new HttpRequestMessage(HttpMethod.Post, customerUrl);
                request.Content = new ByteArrayContent(body);
                request.Content.Headers.ContentType =
                    new MediaTypeHeaderValue("application/json") { CharSet = "utf-8" };

                request.Headers.TryAddWithoutValidation("X-Webhook-Timestamp", timestamp.ToString());
                request.Headers.TryAddWithoutValidation("X-Webhook-Signature", $"sha256={signature}");
                request.Headers.TryAddWithoutValidation("X-Idempotency-Key", idempotencyKey);

                using HttpResponseMessage response =
                    await _http.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cancellationToken)
                               .ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                    return new WebhookResult(Delivered: true, Attempts: attempt, Error: null);

                lastError = $"HTTP {(int)response.StatusCode} {response.ReasonPhrase}";

                // 4xx (except 429) means the request is malformed/rejected;
                // retrying won't help, so stop early.
                if (!IsRetryableStatus(response.StatusCode))
                    return new WebhookResult(Delivered: false, Attempts: attempt, Error: lastError);
            }
            catch (HttpRequestException ex)
            {
                lastError = ex.Message; // network/DNS/TLS failure — transient, retry.
            }
            catch (TaskCanceledException) when (!cancellationToken.IsCancellationRequested)
            {
                lastError = "Request timed out."; // per-attempt timeout — retry.
            }

            if (attempt < _maxAttempts)
                await DelayBeforeRetry(attempt, cancellationToken).ConfigureAwait(false);
        }

        return new WebhookResult(Delivered: false, Attempts: _maxAttempts, Error: lastError);
    }

    private string Sign(long timestamp, byte[] body)
    {
        // Sign "timestamp.body" so the signature also authenticates the
        // timestamp, blocking replay with a stale-but-valid signature.
        byte[] prefix = Encoding.UTF8.GetBytes($"{timestamp}.");
        byte[] signed = new byte[prefix.Length + body.Length];
        Buffer.BlockCopy(prefix, 0, signed, 0, prefix.Length);
        Buffer.BlockCopy(body, 0, signed, prefix.Length, body.Length);

        byte[] hash = HMACSHA256.HashData(_signingKey, signed);
        return Convert.ToHexStringLower(hash);
    }

    private static bool IsRetryableStatus(HttpStatusCode status) =>
        status == HttpStatusCode.RequestTimeout ||      // 408
        status == HttpStatusCode.TooManyRequests ||     // 429
        (int)status >= 500;                             // 5xx

    private Task DelayBeforeRetry(int attempt, CancellationToken ct)
    {
        // Exponential backoff with full jitter to avoid thundering herds.
        double maxMs = _baseDelay.TotalMilliseconds * Math.Pow(2, attempt - 1);
        double delayMs = Random.Shared.NextDouble() * maxMs;
        return Task.Delay(TimeSpan.FromMilliseconds(delayMs), ct);
    }
}

// Sends a webhook to a customer's URL when an order ships.
//
// Reliability and security with the laziest correct approach:
//   - Reliability: ASP.NET Core's IHttpClientFactory + Polly's standard resilience
//     handler gives us retries with exponential backoff + jitter, a timeout per
//     attempt, and a circuit breaker. No bespoke retry loop needed.
//   - Security: we HMAC-SHA256 sign the body so the customer can verify it's
//     really from us, send the signature + a timestamp (replay protection), and
//     use HTTPS. We do NOT roll our own crypto.
//
// Register once at startup:
//
//   builder.Services
//       .AddHttpClient<OrderShippedWebhookSender>()
//       .AddStandardResilienceHandler();   // Microsoft.Extensions.Http.Resilience
//
// then inject OrderShippedWebhookSender wherever an order ships and call
// SendAsync(...).

using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Shipping.Webhooks;

/// <summary>The payload we send to the customer when their order ships.</summary>
public sealed record OrderShippedEvent(
    string OrderId,
    string Carrier,
    string TrackingNumber,
    DateTimeOffset ShippedAt);

public sealed class OrderShippedWebhookSender
{
    private readonly HttpClient _http;

    // Per-customer shared secret. In real life this comes from config / a secret
    // store keyed by customer; passed in here to keep the example self-contained.
    public OrderShippedWebhookSender(HttpClient http) => _http = http;

    /// <summary>
    /// POSTs the event to <paramref name="webhookUrl"/>, signed with the
    /// customer's <paramref name="signingSecret"/>. Throws if delivery ultimately
    /// fails (after the resilience handler's retries) so the caller can fall back
    /// to an outbox / dead-letter queue.
    /// </summary>
    public async Task SendAsync(
        Uri webhookUrl,
        string signingSecret,
        OrderShippedEvent @event,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(webhookUrl);
        ArgumentException.ThrowIfNullOrEmpty(signingSecret);
        ArgumentNullException.ThrowIfNull(@event);

        // Refuse to send secrets over plaintext HTTP.
        if (webhookUrl.Scheme != Uri.UriSchemeHttps)
            throw new ArgumentException("Webhook URL must use HTTPS.", nameof(webhookUrl));

        // Serialize once so the bytes we sign are exactly the bytes we send.
        byte[] body = JsonSerializer.SerializeToUtf8Bytes(@event);

        long timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        string signature = Sign(signingSecret, timestamp, body);

        using var content = new ByteArrayContent(body);
        content.Headers.ContentType =
            new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");

        using var request = new HttpRequestMessage(HttpMethod.Post, webhookUrl)
        {
            Content = content,
        };
        request.Headers.TryAddWithoutValidation("X-Webhook-Timestamp", timestamp.ToString());
        request.Headers.TryAddWithoutValidation("X-Webhook-Signature", "sha256=" + signature);
        // Idempotency key lets the customer dedupe our retries.
        request.Headers.TryAddWithoutValidation("X-Webhook-Id", @event.OrderId);

        using HttpResponseMessage response =
            await _http.SendAsync(request, cancellationToken).ConfigureAwait(false);

        // Non-2xx => let it bubble up; the resilience handler has already retried
        // transient failures, so reaching here means the caller should dead-letter.
        response.EnsureSuccessStatusCode();
    }

    // Sign "<timestamp>.<body>" so the timestamp is covered too — this lets the
    // receiver reject stale (replayed) requests. Standard, boring HMAC-SHA256.
    private static string Sign(string secret, long timestamp, byte[] body)
    {
        byte[] key = Encoding.UTF8.GetBytes(secret);
        byte[] prefix = Encoding.UTF8.GetBytes(timestamp + ".");

        using var hmac = new HMACSHA256(key);
        hmac.TransformBlock(prefix, 0, prefix.Length, null, 0);
        hmac.TransformFinalBlock(body, 0, body.Length);
        return Convert.ToHexStringLower(hmac.Hash!);
    }
}

// Sends a webhook to a customer's URL when an order ships.
//
// Reliability + security with the laziest correct approach (YAGNI):
//   - HMAC-SHA256 signature so the customer can verify authenticity (no extra deps).
//   - Timestamp in the signed payload to let the customer reject replays.
//   - Idempotency key so a retried delivery is recognized as the same event.
//   - HTTPS-only + IHttpClientFactory's typed client with a built-in retry/timeout
//     pipeline (Microsoft.Extensions.Http.Resilience -> Polly) instead of a
//     hand-rolled retry loop.
//
// Wiring (Program.cs):
//   builder.Services.Configure<WebhookOptions>(builder.Configuration.GetSection("Webhook"));
//   builder.Services
//       .AddHttpClient<WebhookSender>()
//       .AddStandardResilienceHandler();   // timeout + retry w/ backoff + circuit breaker
//
// Config (appsettings.json):
//   "Webhook": { "SigningSecret": "<from secret store, not source control>" }

using System;
using System.Net.Http;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Options;

public sealed class WebhookOptions
{
    // Pull from a secret store / env var; never commit the real value.
    public string SigningSecret { get; set; } = "";
}

public sealed record OrderShippedEvent(
    string OrderId,
    string TrackingNumber,
    string Carrier,
    DateTimeOffset ShippedAt);

public sealed class WebhookSender
{
    private readonly HttpClient _http;
    private readonly byte[] _secret;

    // HttpClient is configured (and resilience added) by IHttpClientFactory.
    public WebhookSender(HttpClient http, IOptions<WebhookOptions> options)
    {
        _http = http;

        var secret = options.Value.SigningSecret;
        if (string.IsNullOrEmpty(secret))
            throw new InvalidOperationException("Webhook:SigningSecret is not configured.");
        _secret = Encoding.UTF8.GetBytes(secret);
    }

    /// <summary>
    /// Delivers the "order shipped" event to the customer's webhook URL.
    /// Retries/timeouts/backoff are handled by the resilience handler on HttpClient.
    /// </summary>
    public async Task SendOrderShippedAsync(
        Uri customerUrl,
        OrderShippedEvent payload,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(customerUrl);
        ArgumentNullException.ThrowIfNull(payload);

        // Security: only ever POST secrets/signatures over TLS.
        if (customerUrl.Scheme != Uri.UriSchemeHttps)
            throw new ArgumentException("Webhook URL must use HTTPS.", nameof(customerUrl));

        // Serialize once so the bytes we sign are exactly the bytes we send.
        var body = JsonSerializer.SerializeToUtf8Bytes(payload);

        // Stable id for this delivery -> customer can dedupe safe retries.
        var idempotencyKey = $"order-shipped:{payload.OrderId}";
        var timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();

        // Sign timestamp + body; binding the timestamp lets the customer
        // reject stale/replayed deliveries.
        var signature = ComputeSignature(timestamp, body);

        using var request = new HttpRequestMessage(HttpMethod.Post, customerUrl)
        {
            Content = new ByteArrayContent(body),
        };
        request.Content.Headers.ContentType = new("application/json");
        request.Headers.TryAddWithoutValidation("X-Webhook-Timestamp", timestamp);
        request.Headers.TryAddWithoutValidation("X-Webhook-Signature", $"sha256={signature}");
        request.Headers.TryAddWithoutValidation("Idempotency-Key", idempotencyKey);

        using var response = await _http.SendAsync(request, cancellationToken);
        response.EnsureSuccessStatusCode();
    }

    private string ComputeSignature(string timestamp, byte[] body)
    {
        // Signed message = "<timestamp>." + raw JSON body.
        using var hmac = new HMACSHA256(_secret);
        hmac.TransformBlock(Encoding.UTF8.GetBytes(timestamp + "."), 0, timestamp.Length + 1, null, 0);
        hmac.TransformFinalBlock(body, 0, body.Length);
        return Convert.ToHexStringLower(hmac.Hash!);
    }
}

using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Stripe;

namespace Payments.Controllers;

// YAGNI: lean on Stripe.NET for signature verification and on a single DB
// uniqueness constraint for idempotency. No custom crypto, no bespoke queue.
[ApiController]
[Route("webhooks/stripe")]
public class StripeWebhookController : ControllerBase
{
    private readonly IAccountCreditService _credits;
    private readonly ILogger<StripeWebhookController> _logger;
    private readonly string _webhookSecret;

    public StripeWebhookController(
        IAccountCreditService credits,
        ILogger<StripeWebhookController> logger,
        IConfiguration config)
    {
        _credits = credits;
        _logger = logger;
        // The signing secret ("whsec_...") from the Stripe dashboard / CLI.
        _webhookSecret = config["Stripe:WebhookSecret"]
            ?? throw new InvalidOperationException("Stripe:WebhookSecret is not configured.");
    }

    [HttpPost]
    public async Task<IActionResult> Handle()
    {
        // Read the raw body. Signature verification requires the exact bytes
        // Stripe sent, so we must NOT use a model-bound DTO here.
        string payload = await new StreamReader(Request.Body).ReadToEndAsync();

        Event stripeEvent;
        try
        {
            // ConstructEvent verifies the Stripe-Signature header against the
            // signing secret AND enforces the timestamp tolerance (replay guard).
            // Throws StripeException on any mismatch.
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                Request.Headers["Stripe-Signature"],
                _webhookSecret);
        }
        catch (StripeException ex)
        {
            // Bad/forged signature or stale timestamp -> reject. 400 tells Stripe
            // not to keep retrying a request it can never make valid.
            _logger.LogWarning(ex, "Rejected Stripe webhook: signature verification failed.");
            return BadRequest();
        }

        // We only care about successful payments here. Acknowledge everything
        // else with 200 so Stripe stops resending events we intentionally ignore.
        if (stripeEvent.Type != EventTypes.PaymentIntentSucceeded)
        {
            return Ok();
        }

        if (stripeEvent.Data.Object is not PaymentIntent intent)
        {
            _logger.LogWarning("payment_intent.succeeded event {EventId} had an unexpected payload.", stripeEvent.Id);
            return Ok();
        }

        try
        {
            // Idempotency for redeliveries: Stripe may deliver the same event
            // more than once (retries, network hiccups). We pass the event id and
            // let the service apply the credit exactly once. The implementation
            // records the event id under a unique constraint inside the same
            // transaction as the credit, so a duplicate is a no-op.
            await _credits.CreditOnceAsync(
                eventId: stripeEvent.Id,
                customerId: intent.CustomerId,
                amount: intent.AmountReceived,   // smallest currency unit (e.g. cents)
                currency: intent.Currency);
        }
        catch (Exception ex)
        {
            // Transient failure (DB down, etc.): return 500 so Stripe retries
            // later with the same event id, which our idempotency key absorbs.
            _logger.LogError(ex, "Failed to credit account for Stripe event {EventId}.", stripeEvent.Id);
            return StatusCode(StatusCodes.Status500InternalServerError);
        }

        // Acknowledge quickly so Stripe marks the event as delivered.
        return Ok();
    }
}

/// <summary>
/// Credits an account exactly once per Stripe event id.
/// Implementations should persist the event id under a unique constraint in the
/// SAME transaction that applies the credit, treating a duplicate-key violation
/// as a successful no-op (the credit was already applied for this event).
/// </summary>
public interface IAccountCreditService
{
    Task CreditOnceAsync(string eventId, string? customerId, long amount, string currency);
}

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Stripe;

namespace Payments.Controllers;

// Minimal, correct Stripe webhook handler.
// - Verifies the signature using Stripe's official helper (handles timestamp +
//   HMAC tolerance, which guards against replay/forgery). No hand-rolled crypto.
// - Treats delivery as at-least-once: Stripe retries, so the credit operation
//   must be idempotent. We delegate that to the account service keyed by the
//   Stripe event id.
// - Always 200 on events we accept (even if we ignore the type) so Stripe stops
//   retrying; only 400 for genuinely bad/unverifiable payloads.
[ApiController]
[Route("webhooks/stripe")]
public sealed class StripeWebhookController : ControllerBase
{
    private readonly string _webhookSecret;
    private readonly IAccountCreditService _credits;
    private readonly ILogger<StripeWebhookController> _logger;

    public StripeWebhookController(
        IAccountCreditService credits,
        ILogger<StripeWebhookController> logger,
        // Inject the signing secret (whsec_...) from configuration, not a literal.
        IStripeWebhookSecret secret)
    {
        _credits = credits;
        _logger = logger;
        _webhookSecret = secret.Value;
    }

    [HttpPost]
    public async Task<IActionResult> Handle(CancellationToken ct)
    {
        // Read the raw body exactly as sent — signature verification is byte-sensitive.
        string payload;
        using (var reader = new StreamReader(Request.Body))
        {
            payload = await reader.ReadToEndAsync(ct);
        }

        Event stripeEvent;
        try
        {
            // Throws StripeException if the signature is missing/invalid or the
            // timestamp is outside the default tolerance (replay protection).
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                Request.Headers["Stripe-Signature"],
                _webhookSecret);
        }
        catch (StripeException ex)
        {
            _logger.LogWarning(ex, "Rejected Stripe webhook: signature verification failed.");
            return BadRequest();
        }

        // We only care about successful payments here. Acknowledge everything
        // else with 200 so Stripe doesn't keep retrying types we don't handle.
        if (stripeEvent.Type != EventTypes.PaymentIntentSucceeded)
        {
            return Ok();
        }

        var intent = (PaymentIntent)stripeEvent.Data.Object;

        // Idempotency: Stripe delivers at least once. Key the credit on the event
        // id so a redelivery is a no-op. The service is responsible for doing this
        // atomically (e.g. unique constraint on the event id).
        await _credits.CreditAsync(
            eventId: stripeEvent.Id,
            customerId: intent.CustomerId,
            amount: intent.AmountReceived,
            currency: intent.Currency,
            ct);

        return Ok();
    }
}

// Provided elsewhere in the app. Implementations MUST be idempotent on eventId.
public interface IAccountCreditService
{
    Task CreditAsync(
        string eventId,
        string customerId,
        long amount,
        string currency,
        CancellationToken ct);
}

// Thin wrapper so the signing secret is injected rather than read inline.
public interface IStripeWebhookSecret
{
    string Value { get; }
}

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Stripe;

namespace Payments;

// Minimal, lazy-but-correct Stripe webhook handler.
//
// Why this shape:
// - Use Stripe.net's EventUtility.ConstructEvent to verify the signature for us.
//   It checks the HMAC AND the timestamp tolerance (replay window) in one call,
//   so we don't hand-roll crypto.
// - Stripe retries on any non-2xx (or timeout), so the SAME event can arrive
//   multiple times. We make crediting idempotent by recording the Stripe event
//   id and skipping if we've seen it. That's the whole "redelivery" story.
// - Return 200 fast for anything we've already handled or don't care about,
//   so Stripe stops retrying.

[ApiController]
[Route("webhooks/stripe")]
public sealed class StripeWebhookController : ControllerBase
{
    private readonly string _webhookSecret;
    private readonly IAccountCreditStore _credits;
    private readonly ILogger<StripeWebhookController> _logger;

    public StripeWebhookController(
        IStripeWebhookOptions options,
        IAccountCreditStore credits,
        ILogger<StripeWebhookController> logger)
    {
        _webhookSecret = options.WebhookSigningSecret;
        _credits = credits;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> Handle(CancellationToken ct)
    {
        // Read the raw body. The signature is computed over the exact bytes,
        // so we must NOT let model binding reparse/reserialize it.
        string payload;
        using (var reader = new StreamReader(Request.Body))
        {
            payload = await reader.ReadToEndAsync(ct);
        }

        var signature = Request.Headers["Stripe-Signature"];

        Event stripeEvent;
        try
        {
            // Verifies HMAC signature + timestamp tolerance (default 5 min).
            // Throws on a bad/missing signature or a too-old timestamp (replay).
            stripeEvent = EventUtility.ConstructEvent(
                payload,
                signature,
                _webhookSecret);
        }
        catch (StripeException ex)
        {
            // Bad signature => almost certainly not from Stripe. 400 so the
            // sender (and our logs) know it was rejected. Stripe itself won't
            // send a payload that fails its own signing, so this won't loop.
            _logger.LogWarning(ex, "Rejected Stripe webhook: invalid signature.");
            return BadRequest();
        }

        // Idempotency: Stripe may redeliver the same event on retry. Claim the
        // event id atomically; if we've already processed it, ack and stop.
        if (!await _credits.TryClaimEventAsync(stripeEvent.Id, ct))
        {
            _logger.LogInformation(
                "Stripe event {EventId} already processed; acking duplicate.",
                stripeEvent.Id);
            return Ok();
        }

        // We only act on payment_intent.succeeded here. Everything else we
        // acknowledge so Stripe stops retrying it.
        if (stripeEvent.Type == EventTypes.PaymentIntentSucceeded)
        {
            var intent = (PaymentIntent)stripeEvent.Data.Object;

            // Credit using the PaymentIntent id as the unit of work and the
            // amount Stripe actually settled. Customer can be null for guest
            // checkouts; fall back to nothing-to-credit in that case.
            if (string.IsNullOrEmpty(intent.CustomerId))
            {
                _logger.LogWarning(
                    "PaymentIntent {IntentId} succeeded with no customer; nothing to credit.",
                    intent.Id);
            }
            else
            {
                await _credits.CreditAsync(
                    customerId: intent.CustomerId,
                    amountMinorUnits: intent.AmountReceived,
                    currency: intent.Currency,
                    sourcePaymentIntentId: intent.Id,
                    ct: ct);

                _logger.LogInformation(
                    "Credited customer {CustomerId} with {Amount} {Currency} for {IntentId}.",
                    intent.CustomerId, intent.AmountReceived, intent.Currency, intent.Id);
            }
        }

        // 2xx tells Stripe we've durably accepted the event; it won't retry.
        return Ok();
    }
}

/// <summary>Signing secret from config (e.g. "whsec_...").</summary>
public interface IStripeWebhookOptions
{
    string WebhookSigningSecret { get; }
}

/// <summary>
/// Account crediting + dedup. Implementations should make TryClaimEventAsync
/// and CreditAsync durable (and ideally part of the same transaction) so a
/// crash between them doesn't drop or double a credit.
/// </summary>
public interface IAccountCreditStore
{
    /// <summary>
    /// Atomically records that we've seen this Stripe event id. Returns false
    /// if it was already recorded (i.e. this is a redelivery).
    /// </summary>
    Task<bool> TryClaimEventAsync(string eventId, CancellationToken ct);

    Task CreditAsync(
        string customerId,
        long amountMinorUnits,
        string currency,
        string sourcePaymentIntentId,
        CancellationToken ct);
}

