using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace MyApp.Controllers
{
    [ApiController]
    [Route("api/webhooks")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly ILogger<StripeWebhookController> _logger;
        private readonly StripeSettings _stripeSettings;
        private readonly IAccountService _accountService;
        private readonly IIdempotencyService _idempotencyService;

        public StripeWebhookController(
            ILogger<StripeWebhookController> logger,
            IOptions<StripeSettings> stripeSettings,
            IAccountService accountService,
            IIdempotencyService idempotencyService)
        {
            _logger = logger;
            _stripeSettings = stripeSettings.Value;
            _accountService = accountService;
            _idempotencyService = idempotencyService;
        }

        [HttpPost("stripe")]
        public async Task<IActionResult> HandleStripeWebhook()
        {
            string payload;
            using (var reader = new StreamReader(HttpContext.Request.Body))
            {
                payload = await reader.ReadToEndAsync();
            }

            // Retrieve the Stripe-Signature header for verification
            if (!Request.Headers.TryGetValue("Stripe-Signature", out var stripeSignatureHeader))
            {
                _logger.LogWarning("Stripe webhook received without Stripe-Signature header.");
                return BadRequest("Missing Stripe-Signature header.");
            }

            Event stripeEvent;
            try
            {
                // Verify the webhook signature using the endpoint secret
                // This prevents replay attacks and ensures the request came from Stripe
                stripeEvent = EventUtility.ConstructEvent(
                    payload,
                    stripeSignatureHeader,
                    _stripeSettings.WebhookSecret,
                    throwOnApiVersionMismatch: false
                );
            }
            catch (StripeException ex)
            {
                _logger.LogWarning(ex, "Stripe webhook signature verification failed.");
                return BadRequest("Invalid webhook signature.");
            }

            _logger.LogInformation("Received Stripe event: {EventType} with ID: {EventId}", stripeEvent.Type, stripeEvent.Id);

            // Use the event ID for idempotency to handle redeliveries correctly
            // Stripe may deliver the same event multiple times; we must process it only once
            if (await _idempotencyService.HasBeenProcessedAsync(stripeEvent.Id))
            {
                _logger.LogInformation("Stripe event {EventId} has already been processed. Skipping.", stripeEvent.Id);
                return Ok(new { message = "Event already processed." });
            }

            try
            {
                switch (stripeEvent.Type)
                {
                    case Events.PaymentIntentSucceeded:
                        await HandlePaymentIntentSucceededAsync(stripeEvent);
                        break;

                    case Events.ChargeSucceeded:
                        // Handle charge.succeeded if using older Stripe integration
                        await HandleChargeSucceededAsync(stripeEvent);
                        break;

                    default:
                        // Log and ignore unhandled event types; still return 200 to acknowledge receipt
                        _logger.LogInformation("Unhandled Stripe event type: {EventType}", stripeEvent.Type);
                        break;
                }

                // Mark event as processed to prevent duplicate processing on redelivery
                await _idempotencyService.MarkAsProcessedAsync(stripeEvent.Id);

                return Ok(new { message = "Webhook processed successfully." });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing Stripe event {EventId} of type {EventType}.", stripeEvent.Id, stripeEvent.Type);
                // Return 500 so Stripe will retry the webhook delivery
                return StatusCode(500, "Internal server error processing webhook.");
            }
        }

        private async Task HandlePaymentIntentSucceededAsync(Event stripeEvent)
        {
            if (stripeEvent.Data.Object is not PaymentIntent paymentIntent)
            {
                _logger.LogError("Could not deserialize PaymentIntent from event {EventId}.", stripeEvent.Id);
                throw new InvalidOperationException("Invalid PaymentIntent data in event.");
            }

            _logger.LogInformation(
                "PaymentIntent succeeded: {PaymentIntentId}, Amount: {Amount}, Currency: {Currency}, Customer: {CustomerId}",
                paymentIntent.Id,
                paymentIntent.Amount,
                paymentIntent.Currency,
                paymentIntent.CustomerId);

            if (string.IsNullOrEmpty(paymentIntent.CustomerId))
            {
                _logger.LogWarning("PaymentIntent {PaymentIntentId} has no associated customer.", paymentIntent.Id);
                return;
            }

            // Convert amount from smallest currency unit (e.g., cents) to major unit (e.g., dollars)
            decimal creditAmount = paymentIntent.Amount / 100m;

            await _accountService.CreditCustomerAccountAsync(
                customerId: paymentIntent.CustomerId,
                amount: creditAmount,
                currency: paymentIntent.Currency,
                referenceId: paymentIntent.Id,
                description: $"Payment succeeded for PaymentIntent {paymentIntent.Id}"
            );

            _logger.LogInformation(
                "Successfully credited {Amount} {Currency} to customer {CustomerId} for PaymentIntent {PaymentIntentId}.",
                creditAmount,
                paymentIntent.Currency,
                paymentIntent.CustomerId,
                paymentIntent.Id);
        }

        private async Task HandleChargeSucceededAsync(Event stripeEvent)
        {
            if (stripeEvent.Data.Object is not Charge charge)
            {
                _logger.LogError("Could not deserialize Charge from event {EventId}.", stripeEvent.Id);
                throw new InvalidOperationException("Invalid Charge data in event.");
            }

            _logger.LogInformation(
                "Charge succeeded: {ChargeId}, Amount: {Amount}, Currency: {Currency}, Customer: {CustomerId}",
                charge.Id,
                charge.Amount,
                charge.Currency,
                charge.CustomerId);

            if (string.IsNullOrEmpty(charge.CustomerId))
            {
                _logger.LogWarning("Charge {ChargeId} has no associated customer.", charge.Id);
                return;
            }

            decimal creditAmount = charge.Amount / 100m;

            await _accountService.CreditCustomerAccountAsync(
                customerId: charge.CustomerId,
                amount: creditAmount,
                currency: charge.Currency,
                referenceId: charge.Id,
                description: $"Payment succeeded for Charge {charge.Id}"
            );

            _logger.LogInformation(
                "Successfully credited {Amount} {Currency} to customer {CustomerId} for Charge {ChargeId}.",
                creditAmount,
                charge.Currency,
                charge.CustomerId,
                charge.Id);
        }
    }

    // Settings model for Stripe configuration
    public class StripeSettings
    {
        public string SecretKey { get; set; } = string.Empty;
        public string WebhookSecret { get; set; } = string.Empty;
    }

    // Service interfaces (implementations would be in separate files)
    public interface IAccountService
    {
        Task CreditCustomerAccountAsync(
            string customerId,
            decimal amount,
            string currency,
            string referenceId,
            string description);
    }

    public interface IIdempotencyService
    {
        Task<bool> HasBeenProcessedAsync(string eventId);
        Task MarkAsProcessedAsync(string eventId);
    }
}

using System;
using System.IO;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace MyApp.Controllers
{
    [ApiController]
    [Route("api/webhooks")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly ILogger<StripeWebhookController> _logger;
        private readonly IAccountCreditService _accountCreditService;
        private readonly IIdempotencyStore _idempotencyStore;
        private readonly StripeSettings _stripeSettings;

        public StripeWebhookController(
            ILogger<StripeWebhookController> logger,
            IAccountCreditService accountCreditService,
            IIdempotencyStore idempotencyStore,
            IOptions<StripeSettings> stripeSettings)
        {
            _logger = logger;
            _accountCreditService = accountCreditService;
            _idempotencyStore = idempotencyStore;
            _stripeSettings = stripeSettings.Value;
        }

        [HttpPost("stripe")]
        public async Task<IActionResult> HandleStripeWebhook()
        {
            // Read the raw request body for signature verification
            string json;
            using (var reader = new StreamReader(HttpContext.Request.Body))
            {
                json = await reader.ReadToEndAsync();
            }

            // Retrieve the Stripe-Signature header
            if (!Request.Headers.TryGetValue("Stripe-Signature", out var signatureHeader))
            {
                _logger.LogWarning("Missing Stripe-Signature header.");
                return BadRequest("Missing Stripe-Signature header.");
            }

            Event stripeEvent;
            try
            {
                // Verify the webhook signature using the webhook secret
                stripeEvent = EventUtility.ConstructEvent(
                    json,
                    signatureHeader,
                    _stripeSettings.WebhookSecret,
                    throwOnApiVersionMismatch: false
                );
            }
            catch (StripeException ex)
            {
                _logger.LogWarning(ex, "Stripe webhook signature verification failed.");
                return BadRequest("Webhook signature verification failed.");
            }

            _logger.LogInformation("Received Stripe event: {EventType}, ID: {EventId}", stripeEvent.Type, stripeEvent.Id);

            // Idempotency check: ensure we don't process the same event twice (handles redelivery)
            if (await _idempotencyStore.HasBeenProcessedAsync(stripeEvent.Id))
            {
                _logger.LogInformation("Duplicate Stripe event {EventId} — skipping.", stripeEvent.Id);
                return Ok(new { status = "already_processed" });
            }

            try
            {
                switch (stripeEvent.Type)
                {
                    case Events.PaymentIntentSucceeded:
                        await HandlePaymentIntentSucceededAsync(stripeEvent);
                        break;

                    case Events.ChargeSucceeded:
                        // Some integrations use charge.succeeded; handle if needed
                        await HandleChargeSucceededAsync(stripeEvent);
                        break;

                    default:
                        // Unhandled event type — return 200 to acknowledge receipt
                        _logger.LogInformation("Unhandled Stripe event type: {EventType}", stripeEvent.Type);
                        return Ok(new { status = "unhandled_event" });
                }

                // Mark the event as processed after successful handling
                await _idempotencyStore.MarkAsProcessedAsync(stripeEvent.Id);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing Stripe event {EventId}.", stripeEvent.Id);
                // Return 500 so Stripe will retry the webhook
                return StatusCode(500, "Internal error processing webhook.");
            }

            return Ok(new { status = "success" });
        }

        private async Task HandlePaymentIntentSucceededAsync(Event stripeEvent)
        {
            if (stripeEvent.Data.Object is not PaymentIntent paymentIntent)
            {
                _logger.LogWarning("Could not deserialize PaymentIntent from event {EventId}.", stripeEvent.Id);
                throw new InvalidOperationException("Invalid PaymentIntent payload.");
            }

            // Extract the customer ID; this may be a Customer ID or email depending on your setup
            string customerId = paymentIntent.CustomerId
                ?? paymentIntent.Metadata?.GetValueOrDefault("customer_id");

            if (string.IsNullOrEmpty(customerId))
            {
                _logger.LogWarning(
                    "PaymentIntent {PaymentIntentId} has no associated customer — cannot credit account.",
                    paymentIntent.Id);
                throw new InvalidOperationException("No customer ID found on PaymentIntent.");
            }

            // Amount is in the smallest currency unit (e.g., cents for USD)
            long amountReceived = paymentIntent.AmountReceived;
            string currency = paymentIntent.Currency;

            _logger.LogInformation(
                "Crediting customer {CustomerId} with {Amount} {Currency} for PaymentIntent {PaymentIntentId}.",
                customerId, amountReceived, currency.ToUpperInvariant(), paymentIntent.Id);

            await _accountCreditService.CreditAccountAsync(
                customerId: customerId,
                amountInSmallestUnit: amountReceived,
                currency: currency,
                referenceId: paymentIntent.Id,
                description: $"Payment succeeded: {paymentIntent.Id}"
            );
        }

        private async Task HandleChargeSucceededAsync(Event stripeEvent)
        {
            if (stripeEvent.Data.Object is not Charge charge)
            {
                _logger.LogWarning("Could not deserialize Charge from event {EventId}.", stripeEvent.Id);
                throw new InvalidOperationException("Invalid Charge payload.");
            }

            string customerId = charge.CustomerId
                ?? charge.Metadata?.GetValueOrDefault("customer_id");

            if (string.IsNullOrEmpty(customerId))
            {
                _logger.LogWarning(
                    "Charge {ChargeId} has no associated customer — cannot credit account.",
                    charge.Id);
                throw new InvalidOperationException("No customer ID found on Charge.");
            }

            long amountCaptured = charge.AmountCaptured;
            string currency = charge.Currency;

            _logger.LogInformation(
                "Crediting customer {CustomerId} with {Amount} {Currency} for Charge {ChargeId}.",
                customerId, amountCaptured, currency.ToUpperInvariant(), charge.Id);

            await _accountCreditService.CreditAccountAsync(
                customerId: customerId,
                amountInSmallestUnit: amountCaptured,
                currency: currency,
                referenceId: charge.Id,
                description: $"Charge succeeded: {charge.Id}"
            );
        }
    }

