using Microsoft.Extensions.Logging;

public class OrderService
{
    private readonly AppDbContext _db;
    private readonly ILogger<OrderService> _log;

    public OrderService(AppDbContext db, ILogger<OrderService> log)
    {
        _db = db;
        _log = log;
