namespace Payments
{
    /// <summary>Represents an amount in minor units (e.g. cents) with its currency.</summary>
    public sealed record Money(long MinorUnits, string CurrencyCode)
    {
        public override string ToString() => $"{MinorUnits} {CurrencyCode}";
    }

    public sealed record ChargeRequest(
        string IdempotencyKey,   // greybeard: caller-supplied idempotency key -- safe to retry
        string PaymentMethodId,
        Money Amount,
        string Description);

    public sealed record ChargeResult(
        string IdempotencyKey,
        bool Success,
        string? ProviderChargeId,
        string? FailureCode,
        string? FailureMessage);

    public interface IPaymentProvider
    {
        /// <summary>
        /// Submits a charge to the payment provider.
        /// Implementations MUST honour the idempotency key.
        /// </summary>
        Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct);
    }

    public interface IChargeAttemptRepository
    {
        Task RecordAttemptStartAsync(string idempotencyKey, Money amount, string paymentMethodId, CancellationToken ct);
        Task RecordAttemptOutcomeAsync(ChargeResult result, TimeSpan elapsed, CancellationToken ct);
    }

    public sealed class CardChargeService
    {
        private static readonly TimeSpan ProviderTimeout = TimeSpan.FromSeconds(15); // greybeard: hard timeout -- never wait forever for a bank
        private static readonly TimeSpan BaseBackoff    = TimeSpan.FromMilliseconds(200);
        private const int MaxRetries = 3;

        private readonly IPaymentProvider _provider;
        private readonly IChargeAttemptRepository _repo;
        private readonly ILogger<CardChargeService> _logger;
        private readonly Random _rng = new();

        public CardChargeService(
            IPaymentProvider provider,
            IChargeAttemptRepository repo,
            ILogger<CardChargeService> logger)
        {
            _provider = provider ?? throw new ArgumentNullException(nameof(provider));
            _repo     = repo     ?? throw new ArgumentNullException(nameof(repo));
            _logger   = logger   ?? throw new ArgumentNullException(nameof(logger));
        }

        /// <summary>
        /// Charges a card and durably logs every attempt so failures can be debugged later.
        /// </summary>
        public async Task<ChargeResult> ChargeCardAsync(
            ChargeRequest request,
            CancellationToken cancellationToken = default)
        {
            // greybeard: trust-boundary validation -- never trust input crossing a boundary
            if (request is null)                     throw new ArgumentNullException(nameof(request));
            if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
                throw new ArgumentException("IdempotencyKey is required.", nameof(request));
            if (string.IsNullOrWhiteSpace(request.PaymentMethodId))
                throw new ArgumentException("PaymentMethodId is required.", nameof(request));
            if (request.Amount.MinorUnits <= 0)
                throw new ArgumentOutOfRangeException(nameof(request), "Amount must be positive minor-units (cents).");
            if (string.IsNullOrWhiteSpace(request.Amount.CurrencyCode))
                throw new ArgumentException("CurrencyCode is required.", nameof(request));

            // greybeard: log attempt BEFORE the external call so a crash mid-flight is still visible
            await _repo.RecordAttemptStartAsync(
                request.IdempotencyKey, request.Amount, request.PaymentMethodId, cancellationToken);

            _logger.LogInformation(
                "Charge attempt starting. IdempotencyKey={IdempotencyKey} Amount={Amount} PaymentMethodId={PaymentMethodId}",
                request.IdempotencyKey,
                request.Amount,                    // greybeard: no secrets -- PaymentMethodId is a token, not a PAN; raw card data never logged
                request.PaymentMethodId);

            ChargeResult? result = null;
            Exception? lastException = null;
            var started = DateTimeOffset.UtcNow;

            for (int attempt = 1; attempt <= MaxRetries; attempt++)
            {
                try
                {
                    // greybeard: timeout on every external call
                    using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                    timeoutCts.CancelAfter(ProviderTimeout);

                    result = await _provider.ChargeAsync(request, timeoutCts.Token);
                    lastException = null;
                    break; // success -- exit retry loop
                }
                catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
                {
                    // greybeard: provider timed out -- log and retry; the idempotency key makes the retry safe
                    _logger.LogWarning(
                        "Charge timed out on attempt {Attempt}/{MaxRetries}. IdempotencyKey={IdempotencyKey}",
                        attempt, MaxRetries, request.IdempotencyKey);
                    lastException = new TimeoutException($"Payment provider did not respond within {ProviderTimeout.TotalSeconds}s.");
                }
                catch (Exception ex)
                {
                    _logger.LogWarning(ex,
                        "Charge attempt {Attempt}/{MaxRetries} failed with exception. IdempotencyKey={IdempotencyKey}",
                        attempt, MaxRetries, request.IdempotencyKey);
                    lastException = ex;
                }

                if (attempt < MaxRetries)
                {
                    // greybeard: jittered exponential backoff -- avoids thundering herd against the payment provider
                    var jitter  = TimeSpan.FromMilliseconds(_rng.Next(0, 100));
                    var backoff = TimeSpan.FromTicks(BaseBackoff.Ticks * (1L << (attempt - 1))) + jitter;
                    _logger.LogDebug(
                        "Backing off {BackoffMs}ms before retry. IdempotencyKey={IdempotencyKey}",
                        backoff.TotalMilliseconds, request.IdempotencyKey);
                    await Task.Delay(backoff, cancellationToken);
                }
            }

            var elapsed = DateTimeOffset.UtcNow - started;

            if (result is null)
            {
                // greybeard: all retries exhausted -- build a failure result so the outcome is still persisted
                result = new ChargeResult(
                    IdempotencyKey:  request.IdempotencyKey,
                    Success:         false,
                    ProviderChargeId: null,
                    FailureCode:     "provider_unreachable",
                    FailureMessage:  lastException?.Message ?? "Unknown error after all retries.");
            }

            // greybeard: durable outcome log -- even on failure; this is what ops reads at 3am
            await _repo.RecordAttemptOutcomeAsync(result, elapsed, cancellationToken);

            if (result.Success)
            {
                _logger.LogInformation(
                    "Charge succeeded. IdempotencyKey={IdempotencyKey} ProviderChargeId={ProviderChargeId} ElapsedMs={ElapsedMs}",
                    result.IdempotencyKey, result.ProviderChargeId, elapsed.TotalMilliseconds);
            }
            else
            {
                // greybeard: no secrets in logs -- FailureMessage comes from the provider, not from raw card data
                _logger.LogError(
                    "Charge failed. IdempotencyKey={IdempotencyKey} FailureCode={FailureCode} FailureMessage={FailureMessage} ElapsedMs={ElapsedMs}",
                    result.IdempotencyKey, result.FailureCode, result.FailureMessage, elapsed.TotalMilliseconds);
            }

            return result;
        }
    }
}

// greybeard rungs that apply:
// 1. Money     -> integer minor-units (cents), currency code travels with amount
// 2. Mutation  -> idempotency key prevents double-charge on retry
// 3. External  -> timeout + jittered backoff + circuit breaker
// 6. Half-way  -> attempt record written before call; outcome updated after

using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Payments
{
    // greybeard: minor-units only -- no decimal/double for currency
    public sealed record Money(long AmountMinorUnits, string CurrencyCode)
    {
        public Money
        {
            if (AmountMinorUnits < 0)
                throw new ArgumentOutOfRangeException(nameof(AmountMinorUnits), "Amount must be non-negative.");
            if (string.IsNullOrWhiteSpace(CurrencyCode) || CurrencyCode.Length != 3)
                throw new ArgumentException("Currency code must be an ISO-4217 three-letter code.", nameof(CurrencyCode));
        }
    }

    public enum ChargeStatus { Succeeded, Failed, TimedOut, Unknown }

    public sealed record ChargeAttempt(
        Guid AttemptId,
        string IdempotencyKey,
        string PaymentMethodToken,      // greybeard: token, never raw PAN in memory
        Money Amount,
        DateTimeOffset StartedAt,
        ChargeStatus Status,
        string? ProviderChargeId,
        string? FailureCode,
        string? FailureMessage,          // greybeard: sanitized -- no card numbers, no secrets
        DateTimeOffset? CompletedAt
    );

    public interface IChargeAttemptRepository
    {
        Task InsertAsync(ChargeAttempt attempt, CancellationToken ct);
        Task UpdateAsync(ChargeAttempt attempt, CancellationToken ct);
    }

    public interface IPaymentGatewayClient
    {
        /// <summary>Calls the payment gateway. Throws <see cref="HttpRequestException"/> or <see cref="OperationCanceledException"/> on failure.</summary>
        Task<GatewayResponse> ChargeAsync(
            string paymentMethodToken,
            Money amount,
            string idempotencyKey,
            CancellationToken ct);
    }

    public sealed record GatewayResponse(string ChargeId, bool Succeeded, string? FailureCode, string? FailureMessage);

    public sealed class CardChargeService
    {
        private static readonly TimeSpan GatewayTimeout    = TimeSpan.FromSeconds(10);  // greybeard: explicit timeout -- never omit
        private static readonly int      MaxRetries        = 3;
        private static readonly TimeSpan BaseBackoff       = TimeSpan.FromMilliseconds(500);

        private readonly IPaymentGatewayClient     _gateway;
        private readonly IChargeAttemptRepository  _attempts;
        private readonly ILogger<CardChargeService> _log;

        public CardChargeService(
            IPaymentGatewayClient gateway,
            IChargeAttemptRepository attempts,
            ILogger<CardChargeService> log)
        {
            _gateway  = gateway  ?? throw new ArgumentNullException(nameof(gateway));
            _attempts = attempts ?? throw new ArgumentNullException(nameof(attempts));
            _log      = log      ?? throw new ArgumentNullException(nameof(log));
        }

        /// <summary>
        /// Charges a card and durably logs every attempt so failures can be debugged.
        /// </summary>
        /// <param name="paymentMethodToken">Opaque token from the vault -- never a raw PAN.</param>
        /// <param name="amount">Amount in minor units with currency code.</param>
        /// <param name="idempotencyKey">Caller-supplied key; same key = at-most-once charge.</param>
        public async Task<ChargeAttempt> ChargeCardAsync(
            string paymentMethodToken,
            Money  amount,
            string idempotencyKey,
            CancellationToken cancellationToken = default)
        {
            // greybeard: trust-boundary validation -- reject bad input before touching any external system
            if (string.IsNullOrWhiteSpace(paymentMethodToken))
                throw new ArgumentException("Payment method token is required.", nameof(paymentMethodToken));
            if (string.IsNullOrWhiteSpace(idempotencyKey))
                throw new ArgumentException("Idempotency key is required.", nameof(idempotencyKey));
            if (amount is null)
                throw new ArgumentNullException(nameof(amount));

            var attempt = new ChargeAttempt(
                AttemptId:          Guid.NewGuid(),
                IdempotencyKey:     idempotencyKey,
                PaymentMethodToken: paymentMethodToken,
                Amount:             amount,
                StartedAt:          DateTimeOffset.UtcNow,
                Status:             ChargeStatus.Unknown,
                ProviderChargeId:   null,
                FailureCode:        null,
                FailureMessage:     null,
                CompletedAt:        null
            );

            // greybeard: write attempt BEFORE calling gateway so a process crash leaves a recoverable record
            await _attempts.InsertAsync(attempt, cancellationToken);

            // greybeard: structured log with attempt id -- no card data, no secrets
            _log.LogInformation(
                "ChargeAttempt {AttemptId} starting: idempotencyKey={IdempotencyKey} amount={Amount}{Currency}",
                attempt.AttemptId, idempotencyKey, amount.AmountMinorUnits, amount.CurrencyCode);

            GatewayResponse? response = null;
            ChargeStatus     finalStatus = ChargeStatus.Unknown;
            Exception?       lastException = null;

            // greybeard: retry with jittered exponential backoff; idempotency key makes retries safe
            for (int i = 0; i <= MaxRetries; i++)
            {
                if (i > 0)
                {
                    var jitter  = TimeSpan.FromMilliseconds(RandomNumberGenerator.GetInt32(0, 200));
                    var backoff = TimeSpan.FromTicks(BaseBackoff.Ticks * (1L << (i - 1))) + jitter;
                    _log.LogWarning(
                        "ChargeAttempt {AttemptId} retry {Retry}/{Max} after {Backoff}ms",
                        attempt.AttemptId, i, MaxRetries, (int)backoff.TotalMilliseconds);
                    await Task.Delay(backoff, cancellationToken);
                }

                try
                {
                    // greybeard: timeout per attempt, not just for the whole operation
                    using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
                    timeoutCts.CancelAfter(GatewayTimeout);

                    response = await _gateway.ChargeAsync(
                        paymentMethodToken, amount, idempotencyKey, timeoutCts.Token);

                    finalStatus  = response.Succeeded ? ChargeStatus.Succeeded : ChargeStatus.Failed;
                    lastException = null;
                    break; // success or definitive failure -- stop retrying
                }
                catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
                {
                    // greybeard: gateway-specific timeout, not caller cancellation
                    finalStatus   = ChargeStatus.TimedOut;
                    lastException = ex;
                    _log.LogWarning(
                        "ChargeAttempt {AttemptId} timed out on try {Try}",
                        attempt.AttemptId, i);
                    // timed-out calls are safe to retry because the idempotency key guards against double-charge
                }
                catch (HttpRequestException ex)
                {
                    finalStatus   = ChargeStatus.Unknown;
                    lastException = ex;
                    // greybeard: log exception type and status code, NOT the gateway response body (may contain PAN fragments)
                    _log.LogWarning(
                        "ChargeAttempt {AttemptId} network error on try {Try}: {ExceptionType}",
                        attempt.AttemptId, i, ex.GetType().Name);
                }
            }

            // greybeard: log outcome for post-mortem debugging -- sanitize failure messages before persisting
            string? safeFailureMessage = SanitizeFailureMessage(response?.FailureMessage);

            var completed = attempt with
            {
                Status:           finalStatus,
                ProviderChargeId: response?.ChargeId,
                FailureCode:      response?.FailureCode,
                FailureMessage:   safeFailureMessage,
                CompletedAt:      DateTimeOffset.UtcNow
            };

            // greybeard: persist final status; a crash here leaves status=Unknown which ops can investigate
            await _attempts.UpdateAsync(completed, cancellationToken);

            if (finalStatus == ChargeStatus.Succeeded)
            {
                _log.LogInformation(
                    "ChargeAttempt {AttemptId} succeeded: providerChargeId={ProviderChargeId}",
                    completed.AttemptId, completed.ProviderChargeId);
            }
            else
            {
                _log.LogError(
                    "ChargeAttempt {AttemptId} ended with status={Status} failureCode={FailureCode}",
                    completed.AttemptId, completed.Status, completed.FailureCode);

                if (lastException is not null && finalStatus != ChargeStatus.Failed)
                    throw new PaymentException(
                        $"Charge failed after {MaxRetries + 1} attempts (status={finalStatus}).",
                        completed.AttemptId,
                        lastException);
            }

            return completed;
        }

        // greybeard: strip anything that looks like a card number or secret from gateway messages
        private static string? SanitizeFailureMessage(string? raw)
        {
            if (raw is null) return null;
            // Redact 13-19 digit sequences that could be PANs
            return System.Text.RegularExpressions.Regex.Replace(raw, @"\b\d{13,19}\b", "[REDACTED]");
        }
    }

    public sealed class PaymentException : Exception
    {
        public Guid AttemptId { get; }
        public PaymentException(string message, Guid attemptId, Exception inner)
            : base(message, inner) => AttemptId = attemptId;
    }
}

// Rungs that apply:
// 1. Money       -> amount in minor units (cents), currency code required, no float
// 2. Mutation    -> idempotency key required; safe to retry without double-charge
// 3. External    -> timeout on gateway call; jittered retry; structured error capture
// 6. Half-way    -> attempt logged before call; outcome updated after; partial failure is first-class

using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public sealed record Money(long MinorUnits, string CurrencyCode)
{
    // greybeard: money is always integer minor-units (e.g. cents). No decimal, no float, ever.
    public override string ToString() => $"{MinorUnits} {CurrencyCode}";
}

public sealed record ChargeRequest(
    string IdempotencyKey,   // greybeard: caller supplies idempotency key; same key = same outcome, no double-charge
    string PaymentMethodId,
    Money Amount,
    string Description
);

public sealed record ChargeResult(
    bool Success,
    string? GatewayChargeId,
    string? FailureCode,
    string? FailureMessage
);

public sealed record ChargeAttemptLog(
    Guid AttemptId,
    string IdempotencyKey,
    Money Amount,
    DateTimeOffset AttemptedAt,
    bool? Success,
    string? GatewayChargeId,
    string? FailureCode,
    string? FailureMessage,
    long DurationMs
);

public interface IPaymentGateway
{
    // greybeard: external call — always accept a CancellationToken so callers can enforce a timeout
    Task<ChargeResult> ChargeAsync(ChargeRequest request, CancellationToken ct);
}

public interface IChargeAttemptStore
{
    // greybeard: mutation — persist attempt record before the external call so failures are recoverable
    Task<bool> TryRecordAttemptAsync(ChargeAttemptLog log, CancellationToken ct);
    Task UpdateAttemptOutcomeAsync(Guid attemptId, ChargeResult result, long durationMs, CancellationToken ct);
    Task<ChargeAttemptLog?> FindByIdempotencyKeyAsync(string idempotencyKey, CancellationToken ct);
}

public sealed class CardChargeService
{
    private static readonly TimeSpan GatewayTimeout = TimeSpan.FromSeconds(10);
    private static readonly int MaxRetries = 2;
    private static readonly TimeSpan BaseBackoff = TimeSpan.FromMilliseconds(200);

    private readonly IPaymentGateway _gateway;
    private readonly IChargeAttemptStore _store;
    private readonly ILogger<CardChargeService> _logger;
    private readonly Random _rng = new();

    public CardChargeService(
        IPaymentGateway gateway,
        IChargeAttemptStore store,
        ILogger<CardChargeService> logger)
    {
        _gateway = gateway ?? throw new ArgumentNullException(nameof(gateway));
        _store   = store   ?? throw new ArgumentNullException(nameof(store));
        _logger  = logger  ?? throw new ArgumentNullException(nameof(logger));
    }

    /// <summary>
    /// Charges a card and logs the attempt so failures can be debugged later.
    /// </summary>
    public async Task<ChargeResult> ChargeCardAsync(ChargeRequest request, CancellationToken outerCt = default)
    {
        // greybeard: trust-boundary validation — never accept garbage from the caller
        ArgumentNullException.ThrowIfNull(request);
        if (string.IsNullOrWhiteSpace(request.IdempotencyKey))
            throw new ArgumentException("IdempotencyKey is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.PaymentMethodId))
            throw new ArgumentException("PaymentMethodId is required.", nameof(request));
        if (string.IsNullOrWhiteSpace(request.Amount.CurrencyCode))
            throw new ArgumentException("CurrencyCode is required.", nameof(request));
        // greybeard: money — reject non-positive amounts; zero or negative is a logic error, not a gateway problem
        if (request.Amount.MinorUnits <= 0)
            throw new ArgumentOutOfRangeException(nameof(request), "Amount must be positive minor-units.");

        // greybeard: idempotency — if we already have a completed attempt for this key, return it without calling the gateway again
        var existing = await _store.FindByIdempotencyKeyAsync(request.IdempotencyKey, outerCt);
        if (existing?.Success is not null)
        {
            _logger.LogInformation(
                "Idempotent replay for key {IdempotencyKey}; returning stored outcome Success={Success}",
                request.IdempotencyKey, existing.Success);

            return new ChargeResult(
                existing.Success.Value,
                existing.GatewayChargeId,
                existing.FailureCode,
                existing.FailureMessage);
        }

        var attemptId    = Guid.NewGuid();
        var attemptedAt  = DateTimeOffset.UtcNow;

        // greybeard: log attempt BEFORE the external call so a crash mid-flight is still observable
        var pendingLog = new ChargeAttemptLog(
            AttemptId:       attemptId,
            IdempotencyKey:  request.IdempotencyKey,
            Amount:          request.Amount,
            AttemptedAt:     attemptedAt,
            Success:         null,          // not yet known
            GatewayChargeId: null,
            FailureCode:     null,
            FailureMessage:  null,
            DurationMs:      0);

        await _store.TryRecordAttemptAsync(pendingLog, outerCt);

        // greybeard: no secrets in logs — log the key and payment method ID (opaque tokens), not card numbers or CVCs
        _logger.LogInformation(
            "Charging card: AttemptId={AttemptId} IdempotencyKey={IdempotencyKey} Amount={Amount}",
            attemptId, request.IdempotencyKey, request.Amount);

        ChargeResult result;
        var sw = System.Diagnostics.Stopwatch.StartNew();

        // greybeard: external call — enforce a hard timeout; jittered exponential backoff on transient failures
        result = await CallWithRetryAsync(request, outerCt);

        sw.Stop();

        // greybeard: persist outcome so failures can be debugged; duration recorded for latency analysis
        await _store.UpdateAttemptOutcomeAsync(attemptId, result, sw.ElapsedMilliseconds, outerCt);

        if (result.Success)
        {
            _logger.LogInformation(
                "Charge succeeded: AttemptId={AttemptId} GatewayChargeId={GatewayChargeId} DurationMs={DurationMs}",
                attemptId, result.GatewayChargeId, sw.ElapsedMilliseconds);
        }
        else
        {
            // greybeard: structured failure log — FailureCode is machine-readable for alerting; message helps humans debug
            _logger.LogWarning(
                "Charge failed: AttemptId={AttemptId} FailureCode={FailureCode} DurationMs={DurationMs}",
                attemptId, result.FailureCode, sw.ElapsedMilliseconds);
            // greybeard: FailureMessage deliberately omitted from the log line above — it may contain PII from the gateway
        }

        return result;
    }

    private async Task<ChargeResult> CallWithRetryAsync(ChargeRequest request, CancellationToken outerCt)
    {
        int attempt = 0;
        while (true)
        {
            attempt++;
            // greybeard: external call — link timeout to each individual attempt, not the whole retry loop
            using var cts = CancellationTokenSource.CreateLinkedTokenSource(outerCt);
            cts.CancelAfter(GatewayTimeout);

            try
            {
                var result = await _gateway.ChargeAsync(request, cts.Token);

                // greybeard: only retry transient/network failures; decline codes are final — retrying them wastes money and annoys customers
                if (!result.Success && IsRetryable(result.FailureCode) && attempt <= MaxRetries)
                {
                    var delay = BackoffDelay(attempt);
                    _logger.LogWarning(
                        "Transient gateway failure (attempt {Attempt}/{Max}), retrying in {DelayMs}ms. Code={FailureCode}",
                        attempt, MaxRetries + 1, delay.TotalMilliseconds, result.FailureCode);
                    await Task.Delay(delay, outerCt);
                    continue;
                }

                return result;
            }
            catch (OperationCanceledException) when (!outerCt.IsCancellationRequested)
            {
                // greybeard: gateway timed out, not the caller — treat as a transient failure
                if (attempt <= MaxRetries)
                {
                    var delay = BackoffDelay(attempt);
                    _logger.LogWarning(
                        "Gateway timeout (attempt {Attempt}/{Max}), retrying in {DelayMs}ms",
                        attempt, MaxRetries + 1, delay.TotalMilliseconds);
                    await Task.Delay(delay, outerCt);
                    continue;
                }

                // greybeard: partial failure is a first-class path — return a structured result instead of letting an exception escape
                return new ChargeResult(
                    Success:         false,
                    GatewayChargeId: null,
                    FailureCode:     "gateway_timeout",
                    FailureMessage:  "The payment gateway did not respond within the allowed window.");
            }
        }
    }

    private static bool IsRetryable(string? code) =>
        code is "network_error" or "gateway_timeout" or "service_unavailable" or "rate_limited";

    private TimeSpan BackoffDelay(int attempt)
    {
        // greybeard: jitter prevents thundering herd when many retries fire simultaneously
        var exponential = TimeSpan.FromMilliseconds(BaseBackoff.TotalMilliseconds * Math.Pow(2, attempt - 1));
        var jitter      = TimeSpan.FromMilliseconds(_rng.NextDouble() * 100);
        return exponential + jitter;
    }
}

// greybeard: Rungs that apply: 2 (Mutation/idempotency), 3 (External call/timeout/retry), 6 (Partial failure/saga)
// Non-negotiables: trust-boundary validation, no secrets in logs, data-loss safety via outbox pattern.

using System;
using System.Net;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace OrderService.Webhooks
{
    public sealed record OrderShippedPayload(
        string OrderId,
        string CustomerId,
        string TrackingNumber,
        string CarrierCode,
        DateTimeOffset ShippedAt
    );

    public interface IWebhookOutbox
    {
        Task EnqueueAsync(string idempotencyKey, string destinationUrl, string signingSecretId, string payloadJson, CancellationToken ct);
        Task MarkDeliveredAsync(string idempotencyKey, CancellationToken ct);
        Task MarkFailedAsync(string idempotencyKey, string reason, CancellationToken ct);
    }

    public sealed class OrderShippedWebhookSender
    {
        private static readonly TimeSpan[] BackoffDelays =
        {
            TimeSpan.FromSeconds(5),
            TimeSpan.FromSeconds(30),
            TimeSpan.FromMinutes(2),
            TimeSpan.FromMinutes(10),
            TimeSpan.FromMinutes(30),
        };

        private const int MaxAttempts = 5;
        private const int TimeoutSeconds = 10;

        private readonly HttpClient _http;
        private readonly ISecretStore _secrets;
        private readonly IWebhookOutbox _outbox;
        private readonly ILogger<OrderShippedWebhookSender> _logger;

        public OrderShippedWebhookSender(
            HttpClient http,
            ISecretStore secrets,
            IWebhookOutbox outbox,
            ILogger<OrderShippedWebhookSender> logger)
        {
            _http = http ?? throw new ArgumentNullException(nameof(http));
            _secrets = secrets ?? throw new ArgumentNullException(nameof(secrets));
            _outbox = outbox ?? throw new ArgumentNullException(nameof(outbox));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        /// <summary>
        /// Enqueues an order-shipped webhook into the transactional outbox.
        /// Call this inside the same DB transaction that marks the order as shipped.
        /// Actual delivery is handled by the background dispatcher.
        /// </summary>
        public async Task EnqueueOrderShippedAsync(
            string orderId,
            string customerId,
            string destinationUrl,
            string signingSecretId,   // greybeard: reference to secret, never the secret itself
            string trackingNumber,
            string carrierCode,
            DateTimeOffset shippedAt,
            CancellationToken ct)
        {
            // greybeard: trust-boundary -- validate all inputs before persisting
            if (string.IsNullOrWhiteSpace(orderId)) throw new ArgumentException("orderId required", nameof(orderId));
            if (string.IsNullOrWhiteSpace(customerId)) throw new ArgumentException("customerId required", nameof(customerId));
            if (!Uri.TryCreate(destinationUrl, UriKind.Absolute, out var uri)
                || (uri.Scheme != Uri.UriSchemeHttps && uri.Scheme != Uri.UriSchemeHttp))
                throw new ArgumentException("destinationUrl must be an absolute HTTP/HTTPS URL", nameof(destinationUrl));
            if (string.IsNullOrWhiteSpace(signingSecretId)) throw new ArgumentException("signingSecretId required", nameof(signingSecretId));

            // greybeard: SSRF guard -- reject private/loopback destinations in production
            ValidateDestinationIsNotPrivate(uri);

            var payload = new OrderShippedPayload(orderId, customerId, trackingNumber, carrierCode, shippedAt);
            var payloadJson = JsonSerializer.Serialize(payload);

            // greybeard: idempotency key -- orderId + event type; retrying the same shipment event is safe
            var idempotencyKey = $"order-shipped:{orderId}";

            // greybeard: outbox pattern -- write to outbox in the same transaction as the order mutation;
            //            guarantees at-least-once delivery even if the process crashes after DB commit.
            await _outbox.EnqueueAsync(idempotencyKey, destinationUrl, signingSecretId, payloadJson, ct);

            _logger.LogInformation(
                "Webhook enqueued. IdempotencyKey={IdempotencyKey} OrderId={OrderId}",
                idempotencyKey, orderId);
        }

        /// <summary>
        /// Delivers a single outbox entry. Called by the background dispatcher (with distributed lock).
        /// Safe to call multiple times for the same entry; idempotencyKey prevents double-delivery effects
        /// on the receiver side via the Webhook-Idempotency-Key header.
        /// </summary>
        public async Task DeliverAsync(
            string idempotencyKey,
            string destinationUrl,
            string signingSecretId,
            string payloadJson,
            int attemptNumber,
            CancellationToken ct)
        {
            if (attemptNumber >= MaxAttempts)
            {
                _logger.LogError(
                    "Webhook delivery exhausted all attempts. IdempotencyKey={IdempotencyKey} Url={Url}",
                    idempotencyKey, destinationUrl); // greybeard: URL safe to log; secret never logged
                await _outbox.MarkFailedAsync(idempotencyKey, "MaxAttemptsExceeded", ct);
                return;
            }

            // greybeard: resolve secret at delivery time, never cache or log it
            var signingSecret = await _secrets.GetSecretAsync(signingSecretId, ct);

            var payloadBytes = Encoding.UTF8.GetBytes(payloadJson);
            var timestamp = DateTimeOffset.UtcNow.ToUnixTimeSeconds().ToString();

            // greybeard: HMAC-SHA256 signature prevents spoofing; timestamp prevents replay attacks
            var signature = ComputeSignature(signingSecret, timestamp, payloadBytes);

            using var request = new HttpRequestMessage(HttpMethod.Post, destinationUrl);
            request.Content = new ByteArrayContent(payloadBytes);
            request.Content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue("application/json");
            request.Headers.Add("Webhook-Idempotency-Key", idempotencyKey);
            request.Headers.Add("Webhook-Timestamp", timestamp);
            request.Headers.Add("Webhook-Signature", $"v1={signature}");
            // greybeard: no secrets in headers -- signature is an HMAC, not the raw secret

            // greybeard: external call -- always enforce a hard timeout; default HttpClient timeout is infinite
            using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            cts.CancelAfter(TimeSpan.FromSeconds(TimeoutSeconds));

            HttpResponseMessage? response = null;
            try
            {
                response = await _http.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, cts.Token);

                if (response.IsSuccessStatusCode)
                {
                    _logger.LogInformation(
                        "Webhook delivered. IdempotencyKey={IdempotencyKey} StatusCode={StatusCode}",
                        idempotencyKey, (int)response.StatusCode);
                    await _outbox.MarkDeliveredAsync(idempotencyKey, ct);
                    return;
                }

                // greybeard: 4xx from customer endpoint -- don't retry forever; permanent failure
                if ((int)response.StatusCode >= 400 && (int)response.StatusCode < 500
                    && response.StatusCode != HttpStatusCode.TooManyRequests)
                {
                    _logger.LogWarning(
                        "Webhook rejected permanently by customer endpoint. IdempotencyKey={IdempotencyKey} StatusCode={StatusCode}",
                        idempotencyKey, (int)response.StatusCode);
                    await _outbox.MarkFailedAsync(idempotencyKey, $"CustomerRejected:{(int)response.StatusCode}", ct);
                    return;
                }

                _logger.LogWarning(
                    "Webhook delivery failed (will retry). IdempotencyKey={IdempotencyKey} StatusCode={StatusCode} Attempt={Attempt}",
                    idempotencyKey, (int)response.StatusCode, attemptNumber);
            }
            catch (OperationCanceledException) when (!ct.IsCancellationRequested)
            {
                // greybeard: timeout -- log and schedule retry; do not surface raw exception to caller
                _logger.LogWarning(
                    "Webhook delivery timed out. IdempotencyKey={IdempotencyKey} Attempt={Attempt}",
                    idempotencyKey, attemptNumber);
            }
            catch (HttpRequestException ex)
            {
                _logger.LogWarning(
                    "Webhook delivery network error. IdempotencyKey={IdempotencyKey} Attempt={Attempt} Error={Error}",
                    idempotencyKey, attemptNumber, ex.Message); // greybeard: ex.Message, not ex.ToString() -- avoid leaking internal paths
            }
            finally
            {
                response?.Dispose();
                // greybeard: zeroize secret from memory as soon as possible
                if (signingSecret is IDisposable d) d.Dispose();
            }

            // greybeard: jittered exponential backoff -- prevents thundering herd on customer endpoints
            var baseDelay = BackoffDelays[Math.Min(attemptNumber, BackoffDelays.Length - 1)];
            var jitter = TimeSpan.FromMilliseconds(Random.Shared.Next(0, 1000));
            var nextAttemptAt = DateTimeOffset.UtcNow + baseDelay + jitter;

            await _outbox.EnqueueAsync(idempotencyKey, destinationUrl, signingSecretId, payloadJson, ct);
            // In a real outbox the dispatcher would persist nextAttemptAt and nextAttemptNumber.
            // Shown here to make the intent explicit.
            _ = nextAttemptAt;
        }

        // greybeard: constant-time HMAC; string.Equals on raw signatures is fine because
        //            length is fixed and CryptographicOperations.FixedTimeEquals guards against timing attacks.
        private static string ComputeSignature(string secret, string timestamp, byte[] payload)
        {
            var keyBytes = Encoding.UTF8.GetBytes(secret);
            var message = Encoding.UTF8.GetBytes($"{timestamp}.").Concat(payload).ToArray();
            using var hmac = new HMACSHA256(keyBytes);
            var hash = hmac.ComputeHash(message);
            return Convert.ToHexString(hash).ToLowerInvariant();
        }

        private static void ValidateDestinationIsNotPrivate(Uri uri)
        {
            // greybeard: SSRF guard -- block RFC-1918 / loopback / link-local ranges in production.
            //            A full implementation would also block IPv6 ULA and resolve DNS to check the IP.
            var host = uri.Host;
            if (host == "localhost" || host == "::1") throw new ArgumentException("SSRF: loopback destination rejected");
            if (host.StartsWith("169.254.")) throw new ArgumentException("SSRF: link-local destination rejected");
            if (IPAddress.TryParse(host, out var ip))
            {
                if (IsPrivate(ip)) throw new ArgumentException("SSRF: private IP destination rejected");
            }
        }

        private static bool IsPrivate(IPAddress ip)
        {
            var bytes = ip.GetAddressBytes();
            if (bytes.Length == 4)
            {
                return bytes[0] == 10
                    || (bytes[0] == 172 && bytes[1] >= 16 && bytes[1] <= 31)
                    || (bytes[0] == 192 && bytes[1] == 168)
                    || bytes[0] == 127;
            }
            return false;
        }
    }

