     *
     * 3am question: what if the outbox table grows unbounded?
     *   -> Add a separate archival job that moves delivered rows older than N days to cold storage.
     *
     * 3am question: what if signing key rotation breaks in-flight retries?
     *   -> Store the key *version* in the outbox entry and look up by version, not just customerId.
     */
}

// greybeard: Rung 1 (Money) — amount in integer minor-units (e.g. cents), currency code travels with the value, no float arithmetic.
// greybeard: Rung 6 (Partial failure) — returns a typed result; caller decides whether to persist/apply the refund amount.

using System;

public readonly record struct Money(long MinorUnits, string CurrencyCode)
{
    public override string ToString() => $"{MinorUnits} {CurrencyCode}";
}

public readonly record struct RefundResult(
    Money RefundAmount,
    Money OrderTotal,
    long RefundBasisPoints,   // greybeard: store the rate used so the ledger entry is self-describing
    string Note);

public static class RefundCalculator
{
    private const long RefundRateBasisPoints = 3_000; // 30.00 % expressed in basis points — no magic floats
    private const long BasisPointDivisor    = 10_000;

    /// <summary>
    /// Calculates a 30 % refund on <paramref name="orderTotal"/>.
    /// Uses integer arithmetic on minor units (e.g. cents) to avoid floating-point rounding errors.
    /// Truncates sub-cent remainders toward zero and records them in the result note so nothing
    /// disappears silently — the caller must decide what to do with any remainder.
    /// </summary>
    /// <param name="orderTotal">Order total in minor units with its currency code.</param>
    /// <returns>A <see cref="RefundResult"/> describing the refund; throws on invalid input.</returns>
    public static RefundResult Calculate30PctRefund(Money orderTotal)
    {
        // greybeard: Rung 1 — trust-boundary validation; never let a negative or zero order total
        //            silently produce a nonsensical refund.
        if (string.IsNullOrWhiteSpace(orderTotal.CurrencyCode))
            throw new ArgumentException("Currency code must be provided.", nameof(orderTotal));

        if (orderTotal.MinorUnits < 0)
            throw new ArgumentOutOfRangeException(nameof(orderTotal),
                "Order total cannot be negative.");

        if (orderTotal.MinorUnits == 0)
        {
            // greybeard: Rung 6 — zero-total is valid (fully discounted orders exist); return zero refund.
            return new RefundResult(
                RefundAmount     : new Money(0, orderTotal.CurrencyCode),
                OrderTotal       : orderTotal,
                RefundBasisPoints: RefundRateBasisPoints,
                Note             : "Order total is zero; refund is zero.");
        }

        // greybeard: Rung 1 — integer-only arithmetic; no float, no decimal division that could drift.
        //            30 % = 3000 basis points. Multiply first, then divide to preserve precision.
        long rawMinorUnits  = orderTotal.MinorUnits * RefundRateBasisPoints;
        long refundAmount   = rawMinorUnits / BasisPointDivisor;          // truncate toward zero
        long remainderUnits = rawMinorUnits % BasisPointDivisor;          // greybeard: never discard silently

        string note = remainderUnits == 0
            ? "Exact 30 % refund; no sub-unit remainder."
            : $"30 % refund truncated; sub-unit remainder of {remainderUnits} basis-point-units was dropped. Caller should handle remainder per business rules.";

        // greybeard: Rung 1 — currency code propagates with the refund amount so the caller never
        //            has to guess which currency the minor units belong to.
        return new RefundResult(
            RefundAmount     : new Money(refundAmount, orderTotal.CurrencyCode),
            OrderTotal       : orderTotal,
            RefundBasisPoints: RefundRateBasisPoints,
            Note             : note);
    }
}

// greybeard: Rung 1 (Money) -- order total in integer minor-units (cents); currency code travels with amount.
// greybeard: Rung 6 (Can it fail half-way?) -- validation throws before any mutation; caller owns transaction boundary.

using System;

/// <summary>
/// Represents a monetary amount in minor units (e.g. cents) with an explicit currency code.
/// Never use floating-point for money.
/// </summary>
public readonly struct Money
{
    public long AmountMinorUnits { get; }
    public string CurrencyCode { get; }

    public Money(long amountMinorUnits, string currencyCode)
    {
        if (string.IsNullOrWhiteSpace(currencyCode))
            throw new ArgumentException("Currency code must not be empty.", nameof(currencyCode));

        AmountMinorUnits = amountMinorUnits;
        CurrencyCode = currencyCode.ToUpperInvariant();
    }

    public override string ToString() => $"{AmountMinorUnits} {CurrencyCode}";
}

public static class RefundCalculator
{
    // greybeard: Rung 1 (Money) -- 30% expressed as integer ratio (30/100) to avoid float arithmetic.
    // Integer division truncates toward zero; we floor (favour the merchant, not the customer)
    // and document that choice explicitly so it is never a surprise.
    private const long RefundNumerator   = 30L;
    private const long RefundDenominator = 100L;

    /// <summary>
    /// Calculates a 30% refund on <paramref name="orderTotal"/>.
    ///
    /// Rounding: truncating integer division (floor toward zero) -- refund is rounded DOWN
    /// to the nearest minor unit. This means the merchant never refunds more than 30%.
    /// Document this contract in your API spec; change it only deliberately.
    /// </summary>
    /// <param name="orderTotal">
    ///   The original order total in minor units (e.g. cents for USD).
    ///   Must be non-negative; negative totals indicate a data/logic error upstream.
    /// </param>
    /// <returns>
    ///   A <see cref="Money"/> representing the refund amount, in the same currency and minor units.
    /// </returns>
    /// <exception cref="ArgumentException">
    ///   Thrown when <paramref name="orderTotal"/> carries a negative amount, preventing
    ///   a silent negative-refund (i.e. an accidental charge).
    /// </exception>
    public static Money CalculateThirtyPercentRefund(Money orderTotal)
    {
        // greybeard: trust-boundary validation -- reject nonsensical input before touching numbers.
        if (orderTotal.AmountMinorUnits < 0)
            throw new ArgumentException(
                "Order total must not be negative. A negative total would produce a negative refund " +
                "(an implicit charge). Investigate upstream data.",
                nameof(orderTotal));

        // greybeard: Rung 1 (Money) -- pure integer arithmetic; no float, no decimal cast.
        // Multiply first, then divide, to preserve precision within long range.
        // Max safe order total: long.MaxValue / 30 ≈ 307,445,734,561,825,860 minor units (~$3 quadrillion).
        // If amounts can exceed that, switch to BigInteger or validate an upper bound here.
        long refundMinorUnits = (orderTotal.AmountMinorUnits * RefundNumerator) / RefundDenominator;

        return new Money(refundMinorUnits, orderTotal.CurrencyCode);
    }
}

// greybeard: Rungs that apply here:
// 1. Money? YES — order total is currency; must use integer minor-units, never float.
// 6. Can it fail half-way? Flagged — caller is responsible for persisting the refund amount
//    atomically with order state; this method is pure calculation only.

using System;

/// <summary>
/// Calculates a 30% refund amount for an order total.
/// All amounts are in integer minor-units (e.g., cents for USD) to avoid floating-point errors.
/// </summary>
public static class RefundCalculator
{
    private const int RefundBasisPoints = 3000; // 30.00% expressed as basis points (100 bp = 1%)
    private const int BasisPointDivisor = 10000;

    /// <summary>
    /// Calculates a 30% refund on the given order total.
    /// </summary>
    /// <param name="orderTotalMinorUnits">
    /// The order total in integer minor-units (e.g., cents). Must be non-negative.
    /// </param>
    /// <param name="currencyCode">
    /// ISO 4217 currency code (e.g., "USD"). Travels with the amount so the caller
    /// cannot silently mix currencies.
    /// </param>
    /// <returns>
    /// A <see cref="MoneyAmount"/> containing the refund amount in minor-units and the
    /// original currency code. Rounding is floor (truncate toward zero) — the merchant
    /// never refunds more than 30%; any remainder stays with the merchant.
    /// </returns>
    /// <exception cref="ArgumentOutOfRangeException">
    /// Thrown when <paramref name="orderTotalMinorUnits"/> is negative.
    /// </exception>
    /// <exception cref="ArgumentException">
    /// Thrown when <paramref name="currencyCode"/> is null or whitespace.
    /// </exception>
    public static MoneyAmount CalculateThirtyPercentRefund(
        long orderTotalMinorUnits,
        string currencyCode)
    {
        // greybeard: Money — validate inputs at the trust boundary before any arithmetic.
        if (orderTotalMinorUnits < 0)
            throw new ArgumentOutOfRangeException(
                nameof(orderTotalMinorUnits),
                "Order total must be non-negative.");

        if (string.IsNullOrWhiteSpace(currencyCode))
            throw new ArgumentException(
                "Currency code must be provided.", nameof(currencyCode));

        // greybeard: Money — integer arithmetic only; no float, no double, no decimal division
        // that could silently accumulate rounding error.
        // 30% = 3000 basis points. Multiply first, then divide to preserve precision.
        // Floor division: any sub-unit fraction is truncated (merchant keeps the rounding diff).
        long refundMinorUnits = (orderTotalMinorUnits * RefundBasisPoints) / BasisPointDivisor;

        // greybeard: Money — currency code travels with the result so callers cannot
        // accidentally apply a USD refund to a JPY (zero-decimal) order.
        return new MoneyAmount(refundMinorUnits, currencyCode.ToUpperInvariant());
    }
}

/// <summary>
/// Represents a monetary amount in integer minor-units paired with its ISO 4217 currency code.
/// </summary>
public readonly struct MoneyAmount : IEquatable<MoneyAmount>
{
    /// <summary>Amount in minor-units (e.g., cents for USD, yen for JPY).</summary>
    public long MinorUnits { get; }

    /// <summary>ISO 4217 currency code, e.g. "USD", "EUR", "JPY".</summary>
    public string CurrencyCode { get; }

    public MoneyAmount(long minorUnits, string currencyCode)
    {
        MinorUnits = minorUnits;
        CurrencyCode = currencyCode ?? throw new ArgumentNullException(nameof(currencyCode));
    }

    public bool Equals(MoneyAmount other) =>
        MinorUnits == other.MinorUnits &&
        string.Equals(CurrencyCode, other.CurrencyCode, StringComparison.OrdinalIgnoreCase);

    public override bool Equals(object? obj) => obj is MoneyAmount m && Equals(m);
    public override int GetHashCode() => HashCode.Combine(MinorUnits, CurrencyCode.ToUpperInvariant());
    public override string ToString() => $"{MinorUnits} {CurrencyCode}";
}

// greybeard rungs that apply:
// 2. Mutation      -> idempotency key (Stripe event ID). Exactly-once credit, at-least-once delivery.
// 3. External call -> Stripe signature verification (trust-boundary). No outbound call needed here, but DB has timeout.
// 4. Concurrency   -> explicit transaction + row-level lock to prevent double-credit on concurrent redeliveries.
// 6. Partial fail  -> if DB commit fails after acking HTTP 200, Stripe redelivers; idempotency guard makes retry safe.

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Stripe;

namespace Payments.Controllers
{
    [ApiController]
    [Route("webhooks/stripe")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly AppDbContext _db;
        private readonly ILogger<StripeWebhookController> _logger;
        private readonly StripeWebhookOptions _options;

        // greybeard: no secrets in ctor args that end up in DI logs; options object is sealed.
        public StripeWebhookController(
            AppDbContext db,
            ILogger<StripeWebhookController> logger,
            Microsoft.Extensions.Options.IOptions<StripeWebhookOptions> options)
        {
            _db = db;
            _logger = logger;
            _options = options.Value;
        }

        [HttpPost]
        [Consumes("application/json")]
        public async Task<IActionResult> Handle(CancellationToken ct)
        {
            // greybeard: trust-boundary — read raw body before any model binding so HMAC covers bytes-on-wire.
            string json;
            using (var reader = new StreamReader(Request.Body))
            {
                json = await reader.ReadToEndAsync();
            }

            // greybeard: trust-boundary — reject anything that fails Stripe's HMAC signature check.
            //            Never trust the payload until the signature is verified.
            if (!Request.Headers.TryGetValue("Stripe-Signature", out var sigHeader))
            {
                _logger.LogWarning("Stripe webhook received without signature header");
                return Unauthorized();
            }

            Event stripeEvent;
            try
            {
                // greybeard: tolerance window is Stripe's default 300 s; replay attacks outside that window are rejected.
                stripeEvent = EventUtility.ConstructEvent(
                    json,
                    sigHeader,
                    _options.WebhookSecret,   // greybeard: secret from config, never hard-coded or logged.
                    throwOnApiVersionMismatch: false);
            }
            catch (StripeException ex)
            {
                // greybeard: no secret material in log — exception message from Stripe is safe (it's our own key check).
                _logger.LogWarning("Stripe signature validation failed: {Reason}", ex.Message);
                return Unauthorized();
            }

            // Only handle the events we care about; return 200 for others so Stripe stops retrying them.
            if (stripeEvent.Type != Events.PaymentIntentSucceeded)
            {
                return Ok(new { ignored = true });
            }

            if (stripeEvent.Data.Object is not PaymentIntent paymentIntent)
            {
                _logger.LogError("payment_intent.succeeded event {EventId} had unexpected data object type", stripeEvent.Id);
                // greybeard: return 400 so Stripe will retry — we want to see this event again until we can parse it.
                return BadRequest("Unexpected data object type");
            }

            // greybeard: money — amount is in minor units (cents) as an integer; never convert to float.
            long amountMinorUnits = paymentIntent.Amount;         // e.g. 1099 = $10.99 USD
            string currency = paymentIntent.Currency.ToUpperInvariant(); // greybeard: currency code travels with amount.

            string? customerId = paymentIntent.CustomerId;
            if (string.IsNullOrWhiteSpace(customerId))
            {
                _logger.LogError("payment_intent.succeeded event {EventId} has no CustomerId", stripeEvent.Id);
                return UnprocessableEntity("Missing customer");
            }

            // greybeard: idempotency — use Stripe event ID as the idempotency key.
            //            A re-delivered webhook with the same event ID must not double-credit.
            //            We write a ProcessedWebhookEvent row inside the same transaction as the credit.
            await using var tx = await _db.Database.BeginTransactionAsync(
                System.Data.IsolationLevel.ReadCommitted, ct);

            try
            {
                // greybeard: concurrency — check for duplicate inside the transaction; use a unique index
                //            on ProcessedWebhookEvents.EventId (enforced at DB level) as the final guard.
                bool alreadyProcessed = await _db.ProcessedWebhookEvents
                    .AnyAsync(e => e.EventId == stripeEvent.Id, ct);

                if (alreadyProcessed)
                {
                    // greybeard: idempotency — safe no-op for redelivery; return 200 so Stripe stops retrying.
                    _logger.LogInformation(
                        "Stripe event {EventId} already processed — skipping duplicate credit", stripeEvent.Id);
                    await tx.RollbackAsync(ct);
                    return Ok(new { duplicate = true });
                }

                // greybeard: concurrency — row-level lock on the CustomerAccount row prevents two concurrent
                //            redeliveries from both reading balance=0 and each crediting independently.
                var account = await _db.CustomerAccounts
                    .FromSqlRaw(
                        "SELECT * FROM \"CustomerAccounts\" WHERE \"CustomerId\" = {0} FOR UPDATE",
                        customerId)
                    .FirstOrDefaultAsync(ct);

                if (account is null)
                {
                    _logger.LogError(
                        "No CustomerAccount found for CustomerId {CustomerId} (event {EventId})",
                        customerId, stripeEvent.Id);
                    await tx.RollbackAsync(ct);
                    // greybeard: partial fail — returning 422 causes Stripe to stop retrying; alert ops manually.
                    //            If this customer should exist, this is a data-integrity bug that needs human review.
                    return UnprocessableEntity("Customer account not found");
                }

                // greybeard: money — integer arithmetic only; no float, no decimal rounding surprises.
                account.BalanceMinorUnits += amountMinorUnits;
                account.CurrencyCode = currency; // greybeard: validate currency matches account's currency in prod.

                // greybeard: idempotency — record the processed event atomically with the credit.
                //            If the commit fails, both the credit and the event record roll back together;
                //            Stripe redelivers; we re-enter this handler and try again safely.
                _db.ProcessedWebhookEvents.Add(new ProcessedWebhookEvent
                {
                    EventId = stripeEvent.Id,
                    EventType = stripeEvent.Type,
                    CustomerId = customerId,
                    AmountMinorUnits = amountMinorUnits,
                    Currency = currency,
                    ProcessedAt = DateTimeOffset.UtcNow,
                });

                await _db.SaveChangesAsync(ct);
                await tx.CommitAsync(ct);

                // greybeard: observable — structured log with no PII beyond customer ID, no card data, no secrets.
                _logger.LogInformation(
                    "Credited {Amount} {Currency} to customer {CustomerId} for Stripe event {EventId}",
                    amountMinorUnits, currency, customerId, stripeEvent.Id);

                return Ok(new { credited = true });
            }
            catch (DbUpdateException ex) when (IsUniqueConstraintViolation(ex))
            {
                // greybeard: concurrency — two concurrent redeliveries both pass the AnyAsync check (race),
                //            but only one wins the unique-index insert; the loser lands here. Safe no-op.
                await tx.RollbackAsync(ct);
                _logger.LogWarning(
                    "Concurrent duplicate detected for Stripe event {EventId} — unique constraint won", stripeEvent.Id);
                return Ok(new { duplicate = true });
            }
            catch (Exception ex)
            {
                await tx.RollbackAsync(ct);
                // greybeard: no secret/card data in log; exception message from EF is safe here.
                _logger.LogError(ex, "Failed to process Stripe event {EventId}", stripeEvent.Id);
                // greybeard: return 500 so Stripe retries; transaction rolled back so credit never happened.
                return StatusCode(500, "Internal error — will retry");
            }
        }

        // greybeard: unique-constraint detection is DB-driver-specific; centralised here so it's easy to adapt.
        private static bool IsUniqueConstraintViolation(DbUpdateException ex)
        {
            // Works for Npgsql (PostgreSQL). Adapt for SqlException error 2627 on SQL Server, etc.
            return ex.InnerException?.Message.Contains("unique constraint", StringComparison.OrdinalIgnoreCase) == true
                || ex.InnerException?.Message.Contains("duplicate key", StringComparison.OrdinalIgnoreCase) == true;
        }
    }

    // -------------------------------------------------------------------------
    // Supporting types (normally in separate files)
    // -------------------------------------------------------------------------

    public class StripeWebhookOptions
    {
        // greybeard: bound from configuration (e.g. environment variable STRIPE__WEBHOOKSECRET);
        //            never default to a known value; fail fast on startup if missing.
        public string WebhookSecret { get; set; } = string.Empty;
    }

    public class CustomerAccount
    {
        public int Id { get; set; }
        public string CustomerId { get; set; } = string.Empty;

        // greybeard: money — balance stored as integer minor units (e.g. cents). Never float or decimal with silent rounding.
        public long BalanceMinorUnits { get; set; }
        public string CurrencyCode { get; set; } = string.Empty;
    }

    public class ProcessedWebhookEvent
    {
        public int Id { get; set; }

        // greybeard: idempotency — unique index on EventId enforced at DB level (migration not shown).
        public string EventId { get; set; } = string.Empty;
        public string EventType { get; set; } = string.Empty;
        public string CustomerId { get; set; } = string.Empty;
        public long AmountMinorUnits { get; set; }
        public string Currency { get; set; } = string.Empty;
        public DateTimeOffset ProcessedAt { get; set; }
    }

    public class AppDbContext : DbContext
    {
        public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

        public DbSet<CustomerAccount> CustomerAccounts => Set<CustomerAccount>();
        public DbSet<ProcessedWebhookEvent> ProcessedWebhookEvents => Set<ProcessedWebhookEvent>();

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            // greybeard: idempotency — database-enforced uniqueness is the final defence against double-credit.
            modelBuilder.Entity<ProcessedWebhookEvent>()
                .HasIndex(e => e.EventId)
                .IsUnique();

            modelBuilder.Entity<CustomerAccount>()
                .HasIndex(a => a.CustomerId)
                .IsUnique();
        }
    }
}

// greybeard: Rungs that apply here:
//   2. Mutation    -> idempotency key (Stripe event ID). Exactly-once credit, at-least-once delivery.
//   3. External call -> Stripe signature verification; no outbound call needed but we guard the inbound trust boundary.
//   4. Concurrency -> row-level lock + unique constraint on processed event ID to prevent double-credit.
//   6. Half-way failure -> outbox / transactional write so credit and event-log commit together or not at all.
// Non-negotiables: trust-boundary validation on signature; no secrets in logs; money in minor-units (cents).

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Controllers
{
    [ApiController]
    [Route("webhooks/stripe")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly AppDbContext _db;
        private readonly ILogger<StripeWebhookController> _logger;
        private readonly StripeOptions _options;

        public StripeWebhookController(
            AppDbContext db,
            ILogger<StripeWebhookController> logger,
            IOptions<StripeOptions> options)
        {
            _db = db;
            _logger = logger;
            _options = options.Value;
        }

        [HttpPost]
        // greybeard: trust boundary — consume raw body BEFORE any model binding touches it;
        //            signature verification uses the exact bytes Stripe signed.
        [Consumes("application/json")]
        public async Task<IActionResult> Handle(CancellationToken ct)
        {
            string json;
            using (var reader = new StreamReader(HttpContext.Request.Body))
                json = await reader.ReadToEndAsync();

            // greybeard: trust boundary — reject anything that fails HMAC-SHA256 sig check.
            //            ConstructEvent throws StripeException on tampered/replayed payloads.
            Event stripeEvent;
            try
            {
                stripeEvent = EventUtility.ConstructEvent(
                    json,
                    Request.Headers["Stripe-Signature"],
                    _options.WebhookSecret,   // greybeard: secret from config, never logged.
                    throwOnApiVersionMismatch: false);
            }
            catch (StripeException ex)
            {
                // greybeard: no secret material or raw payload in the log.
                _logger.LogWarning("Stripe signature verification failed: {Message}", ex.Message);
                return BadRequest("Invalid signature.");
            }

            // We only process payment_intent.succeeded; ack everything else so Stripe stops retrying.
            if (stripeEvent.Type != Events.PaymentIntentSucceeded)
                return Ok();

            var paymentIntent = stripeEvent.Data.Object as PaymentIntent;
            if (paymentIntent is null)
            {
                _logger.LogError("Event {EventId} type {Type}: data object is not a PaymentIntent.", stripeEvent.Id, stripeEvent.Type);
                return Ok(); // ack so Stripe does not retry an event we cannot parse
            }

            // greybeard: money in minor-units (cents) straight from Stripe — never float.
            //            Amount is already an integer (long) in the Stripe SDK.
            long creditAmountMinorUnits = paymentIntent.Amount; // e.g. 1999 = $19.99 USD
            string currency = paymentIntent.Currency.ToUpperInvariant(); // travels with the amount

            if (string.IsNullOrWhiteSpace(paymentIntent.CustomerId))
            {
                _logger.LogError("Event {EventId}: PaymentIntent has no CustomerId; cannot credit account.", stripeEvent.Id);
                return Ok();
            }

            string customerId = paymentIntent.CustomerId;
            string idempotencyKey = stripeEvent.Id; // greybeard: Stripe event ID is the natural idempotency key for redelivery.

            try
            {
                await CreditAccountExactlyOnceAsync(idempotencyKey, customerId, creditAmountMinorUnits, currency, ct);
            }
            catch (OperationCanceledException)
            {
                // greybeard: request cancelled (client disconnect / shutdown); return 500 so Stripe retries.
                return StatusCode(503);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Unhandled error processing event {EventId}.", stripeEvent.Id);
                // greybeard: return 500 to trigger Stripe retry; do NOT expose internal detail.
                return StatusCode(500);
            }

            return Ok();
        }

        // greybeard: Mutation — the entire credit+event-log write happens in ONE database transaction
        //            so either both commit or neither does (half-way failure protection).
        //            Unique index on ProcessedStripeEvents.EventId is the last line of defense against
        //            a double-credit if two concurrent deliveries race past the SELECT check.
        private async Task CreditAccountExactlyOnceAsync(
            string idempotencyKey,
            string customerId,
            long amountMinorUnits,
            string currency,
            CancellationToken ct)
        {
            // greybeard: concurrency — serializable or RepeatableRead isolation prevents phantom read;
            //            unique DB constraint on event_id is the hard stop.
            await using var tx = await _db.Database.BeginTransactionAsync(
                System.Data.IsolationLevel.RepeatableRead, ct);

            // greybeard: idempotency — check whether we already processed this Stripe event.
            bool alreadyProcessed = await _db.ProcessedStripeEvents
                .AnyAsync(e => e.EventId == idempotencyKey, ct);

            if (alreadyProcessed)
            {
                _logger.LogInformation("Event {EventId} already processed; skipping (idempotent).", idempotencyKey);
                await tx.RollbackAsync(ct);
                return;
            }

            // greybeard: concurrency — lock the customer row to prevent a concurrent webhook
            //            from crediting simultaneously and creating a lost update.
            var account = await _db.CustomerAccounts
                .FromSqlRaw("SELECT * FROM customer_accounts WHERE customer_id = {0} FOR UPDATE", customerId)
                .SingleOrDefaultAsync(ct);

            if (account is null)
            {
                // greybeard: half-way failure — log and ack so Stripe stops retrying an event
                //            we genuinely cannot fulfil; alert on-call instead.
                _logger.LogError("Event {EventId}: no account found for customer {CustomerId}.", idempotencyKey, customerId);
                await tx.RollbackAsync(ct);
                return; // still return 200 to caller so Stripe stops retrying; on-call alert handles it
            }

            // greybeard: money — add integer minor-units; no float arithmetic, no silent rounding.
            if (account.Currency != currency)
            {
                _logger.LogError(
                    "Event {EventId}: currency mismatch; account={AccountCurrency} payment={PaymentCurrency}.",
                    idempotencyKey, account.Currency, currency);
                await tx.RollbackAsync(ct);
                return;
            }

            account.BalanceMinorUnits += amountMinorUnits;

            // greybeard: mutation — record processed event atomically with the balance update.
            _db.ProcessedStripeEvents.Add(new ProcessedStripeEvent
            {
                EventId = idempotencyKey,
                CustomerId = customerId,
                AmountMinorUnits = amountMinorUnits,
                Currency = currency,
                ProcessedAtUtc = DateTime.UtcNow
            });

            // greybeard: observable — structured log with correlation fields; no PII/secrets.
            _logger.LogInformation(
                "Crediting account for customer {CustomerId}: +{Amount} {Currency} (event {EventId}).",
                customerId, amountMinorUnits, currency, idempotencyKey);

            await _db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
            // greybeard: if SaveChanges or Commit throws a unique-constraint violation
            //            (race with a concurrent delivery), EF/Npgsql surfaces a DbUpdateException;
            //            the outer handler returns 500, Stripe retries, the second pass hits the
            //            alreadyProcessed guard and returns 200. Safe.
        }
    }

    // ---- Supporting types (would normally live in separate files) ----

    public class StripeOptions
    {
        // greybeard: loaded from IConfiguration/secrets manager, never hardcoded or logged.
        public string WebhookSecret { get; set; } = string.Empty;
    }

    public class CustomerAccount
    {
        public string CustomerId { get; set; } = string.Empty;
        // greybeard: money — balance stored as integer minor-units (e.g. cents), never decimal/float.
        public long BalanceMinorUnits { get; set; }
        public string Currency { get; set; } = string.Empty; // ISO 4217, e.g. "USD"
        public int RowVersion { get; set; } // for optimistic concurrency on non-PostgreSQL stores
    }

    public class ProcessedStripeEvent
    {
        public int Id { get; set; }
        // greybeard: unique index on EventId is the DB-level idempotency guard (DDL below).
        public string EventId { get; set; } = string.Empty;
        public string CustomerId { get; set; } = string.Empty;
        public long AmountMinorUnits { get; set; }
        public string Currency { get; set; } = string.Empty;
        public DateTime ProcessedAtUtc { get; set; }
    }

    public class AppDbContext : DbContext
    {
        public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

        public DbSet<CustomerAccount> CustomerAccounts => Set<CustomerAccount>();
        public DbSet<ProcessedStripeEvent> ProcessedStripeEvents => Set<ProcessedStripeEvent>();

        protected override void OnModelCreating(ModelBuilder mb)
        {
            mb.Entity<CustomerAccount>(e =>
            {
                e.HasKey(a => a.CustomerId);
                e.ToTable("customer_accounts");
                e.Property(a => a.BalanceMinorUnits).HasColumnName("balance_minor_units");
                e.Property(a => a.Currency).HasMaxLength(3);
                // greybeard: concurrency — row-version token; EF throws DbUpdateConcurrencyException on stale write.
                e.Property(a => a.RowVersion).IsRowVersion();
            });

            mb.Entity<ProcessedStripeEvent>(e =>
            {
                e.HasKey(ev => ev.Id);
                e.ToTable("processed_stripe_events");
                // greybeard: idempotency — unique constraint ensures duplicate event IDs fail at the DB level
                //            even if two processes race past the application-level check.
                e.HasIndex(ev => ev.EventId).IsUnique();
                e.Property(ev => ev.EventId).HasMaxLength(255);
                e.Property(ev => ev.Currency).HasMaxLength(3);
            });
        }
    }
}

/*
greybeard 3am review:

WHAT STILL NEEDS ATTENTION:
1. The SELECT ... FOR UPDATE raw SQL works on PostgreSQL/MySQL but not SQL Server
   (use UPDLOCK hint instead). Make this dialect-aware or use app-level distributed lock.
2. BalanceMinorUnits overflow: long holds ~9.2e18 cents — practically safe, but assert
   account.BalanceMinorUnits + amountMinorUnits does not overflow if paranoia demands it.
3. Alert on the "no account found" and "currency mismatch" branches — returning 200 silences
   Stripe but a human must investigate; hook these log lines to PagerDuty / Sentry.
4. WebhookSecret rotation: Stripe supports two active secrets during rotation; consider
   trying both secrets before rejecting the request.
5. Rate / replay window: Stripe replays for up to 72h. The processed_stripe_events table
   must be retained for at least that window before archiving old rows.
6. Idempotency key alone is not enough if you ever refund and re-process; events have
   distinct IDs so this is fine, but document the assumption.
*/

// greybeard rungs that apply:
// 2. Mutation       -> idempotency key (Stripe event ID). Safe to retry. Exactly-once credit.
// 3. External call  -> Stripe SDK call has timeout; signature verification before any processing.
// 4. Concurrency    -> optimistic concurrency / row-level lock to prevent double-credit on parallel delivery.
// 6. Partial fail   -> compensating transaction; event marked processed only after credit commits.
// Non-negotiables   -> trust-boundary validation (HMAC signature), no secrets in logs, money in integer minor-units.

using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Stripe;

namespace Payments.Controllers
{
    [ApiController]
    [Route("webhooks/stripe")]
    public class StripeWebhookController : ControllerBase
    {
        private readonly AppDbContext _db;
        private readonly StripeOptions _stripeOptions;
        private readonly ILogger<StripeWebhookController> _logger;

        public StripeWebhookController(
            AppDbContext db,
            IOptions<StripeOptions> stripeOptions,
            ILogger<StripeWebhookController> logger)
        {
            _db = db;
            _stripeOptions = stripeOptions.Value;
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> HandleWebhook(CancellationToken cancellationToken)
        {
            // greybeard: trust-boundary -- read raw body before any model binding; signature must be verified first.
            string json;
            using (var reader = new StreamReader(Request.Body))
            {
                json = await reader.ReadToEndAsync();
            }

            // greybeard: trust-boundary -- HMAC verification using Stripe-Signature header; reject anything unsigned.
            Event stripeEvent;
            try
            {
                stripeEvent = EventUtility.ConstructEvent(
                    json,
                    Request.Headers["Stripe-Signature"],
                    _stripeOptions.WebhookSecret,
                    throwOnApiVersionMismatch: false // tolerate minor API version drift; log and continue
                );
            }
            catch (StripeException ex)
            {
                // greybeard: no secret material (webhook secret, raw body) in logs.
                _logger.LogWarning("Stripe webhook signature validation failed: {ErrorMessage}", ex.Message);
                return BadRequest("Invalid signature.");
            }

            if (stripeEvent.Type != Events.PaymentIntentSucceeded &&
                stripeEvent.Type != Events.ChargeSucceeded)
            {
                // Acknowledge unhandled event types so Stripe stops retrying them.
                return Ok(new { received = true });
            }

            // greybeard: idempotency -- use Stripe event ID as idempotency key; check before doing any work.
            var idempotencyKey = stripeEvent.Id;

            // greybeard: concurrency + mutation -- wrap credit + idempotency record in a single serializable transaction.
            await using var transaction = await _db.Database.BeginTransactionAsync(
                System.Data.IsolationLevel.Serializable, cancellationToken);

            try
            {
                var alreadyProcessed = await _db.ProcessedWebhookEvents
                    .AnyAsync(e => e.StripeEventId == idempotencyKey, cancellationToken);

                if (alreadyProcessed)
                {
                    // greybeard: idempotency -- redelivery detected; return 200 so Stripe stops retrying.
                    _logger.LogInformation("Duplicate Stripe event {EventId} ignored.", idempotencyKey);
                    await transaction.RollbackAsync(cancellationToken);
                    return Ok(new { received = true });
                }

                // Extract payment details.
                long amountMinorUnits; // greybeard: money -- always integer minor-units (cents), never float.
                string currency;       // greybeard: money -- currency code travels with the amount.
                string customerId;

                if (stripeEvent.Type == Events.PaymentIntentSucceeded)
                {
                    var paymentIntent = stripeEvent.Data.Object as PaymentIntent
                        ?? throw new InvalidOperationException("Expected PaymentIntent payload.");

                    amountMinorUnits = paymentIntent.AmountReceived; // already in minor units from Stripe
                    currency = paymentIntent.Currency.ToUpperInvariant();
                    customerId = paymentIntent.CustomerId
                        ?? throw new InvalidOperationException("PaymentIntent has no CustomerId.");
                }
                else // ChargeSucceeded
                {
                    var charge = stripeEvent.Data.Object as Charge
                        ?? throw new InvalidOperationException("Expected Charge payload.");

                    amountMinorUnits = charge.Amount;
                    currency = charge.Currency.ToUpperInvariant();
                    customerId = charge.CustomerId
                        ?? throw new InvalidOperationException("Charge has no CustomerId.");
                }

                // greybeard: trust-boundary -- validate extracted fields before touching any account.
                if (amountMinorUnits <= 0)
                    throw new InvalidOperationException($"Non-positive amount {amountMinorUnits} in event {idempotencyKey}.");

                if (string.IsNullOrWhiteSpace(currency))
                    throw new InvalidOperationException($"Missing currency in event {idempotencyKey}.");

                if (string.IsNullOrWhiteSpace(customerId))
                    throw new InvalidOperationException($"Missing customerId in event {idempotencyKey}.");

                // greybeard: concurrency -- pessimistic row lock on the customer account row to prevent lost updates
                // when two Stripe redeliveries arrive simultaneously.
                var account = await _db.CustomerAccounts
                    .FromSqlInterpolated(
                        $"SELECT * FROM customer_accounts WHERE stripe_customer_id = {customerId} FOR UPDATE")
                    .FirstOrDefaultAsync(cancellationToken);

                if (account is null)
                {
                    // greybeard: partial failure -- unknown customer; reject with 422 so Stripe does NOT retry (it is a data bug, not transient).
                    _logger.LogError(
                        "No account found for Stripe customer {CustomerId} (event {EventId}).",
                        customerId, idempotencyKey);
                    await transaction.RollbackAsync(cancellationToken);
                    return UnprocessableEntity("Customer account not found.");
                }

                // greybeard: money -- guard against currency mismatch; never silently convert.
                if (!string.Equals(account.Currency, currency, StringComparison.OrdinalIgnoreCase))
                {
                    _logger.LogError(
                        "Currency mismatch for account {AccountId}: expected {Expected}, got {Got} (event {EventId}).",
                        account.Id, account.Currency, currency, idempotencyKey);
                    await transaction.RollbackAsync(cancellationToken);
                    return UnprocessableEntity("Currency mismatch.");
                }

                // greybeard: money -- integer arithmetic only; no floating-point at any step.
                checked // overflow guard
                {
                    account.BalanceMinorUnits += amountMinorUnits;
                }

                // greybeard: mutation -- record processed event in same transaction; atomically prevents double-credit.
                _db.ProcessedWebhookEvents.Add(new ProcessedWebhookEvent
                {
                    StripeEventId = idempotencyKey,
                    EventType = stripeEvent.Type,
                    AmountMinorUnits = amountMinorUnits,
                    Currency = currency,
                    CustomerId = customerId,
                    ProcessedAt = DateTimeOffset.UtcNow,
                });

                await _db.SaveChangesAsync(cancellationToken);
                await transaction.CommitAsync(cancellationToken);

                // greybeard: observable -- structured log without PII beyond account ID; no card numbers, no secrets.
                _logger.LogInformation(
                    "Credited account {AccountId} with {Amount} {Currency} for event {EventId}.",
                    account.Id, amountMinorUnits, currency, idempotencyKey);

                return Ok(new { received = true });
            }
            catch (OperationCanceledException)
            {
                await transaction.RollbackAsync(CancellationToken.None);
                // greybeard: partial failure -- return 500 so Stripe retries; our idempotency key protects against double-credit.
                return StatusCode(503, "Request cancelled.");
            }
            catch (Exception ex)
            {
                await transaction.RollbackAsync(CancellationToken.None);
                // greybeard: no secrets/PII in error responses returned to Stripe.
                _logger.LogError(ex, "Unhandled error processing Stripe event {EventId}.", idempotencyKey);
                // Return 500 so Stripe retries; idempotency key protects against double-credit on retry.
                return StatusCode(500, "Internal error; will retry.");
            }
        }
    }

    // ---------------------------------------------------------------------------
    // Supporting types (would normally live in their own files)
    // ---------------------------------------------------------------------------

    public class StripeOptions
    {
        public string WebhookSecret { get; set; } = string.Empty; // loaded from secret store, never from appsettings.json plain text
    }

    public class CustomerAccount
    {
        public Guid Id { get; set; }
        public string StripeCustomerId { get; set; } = string.Empty;
        // greybeard: money -- balance stored as integer minor-units (e.g. cents) in DB; never decimal/float column.
        public long BalanceMinorUnits { get; set; }
        public string Currency { get; set; } = string.Empty; // ISO 4217, e.g. "USD"
    }

    public class ProcessedWebhookEvent
    {
        public Guid Id { get; set; } = Guid.NewGuid();
        public string StripeEventId { get; set; } = string.Empty; // unique index in DB
        public string EventType { get; set; } = string.Empty;
        public long AmountMinorUnits { get; set; }
        public string Currency { get; set; } = string.Empty;
        public string CustomerId { get; set; } = string.Empty;
        public DateTimeOffset ProcessedAt { get; set; }
    }

    // Minimal DbContext stub -- real implementation wires up migrations, indexes, etc.
    public class AppDbContext : DbContext
    {
        public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

        public DbSet<CustomerAccount> CustomerAccounts => Set<CustomerAccount>();
        public DbSet<ProcessedWebhookEvent> ProcessedWebhookEvents => Set<ProcessedWebhookEvent>();

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<CustomerAccount>(b =>
            {
                b.ToTable("customer_accounts");
                b.Property(e => e.StripeCustomerId).HasColumnName("stripe_customer_id");
                // greybeard: money -- map to bigint, not numeric/decimal, to make the integer-minor-units contract explicit.
                b.Property(e => e.BalanceMinorUnits).HasColumnName("balance_minor_units").HasColumnType("bigint");
                b.Property(e => e.Currency).HasColumnName("currency").HasMaxLength(3);
            });

            modelBuilder.Entity<ProcessedWebhookEvent>(b =>
            {
                b.ToTable("processed_webhook_events");
                // greybeard: idempotency -- unique index on stripe_event_id; DB enforces exactly-once at storage layer.
                b.HasIndex(e => e.StripeEventId).IsUnique();
            });
        }
    }
}

